// Compiled by bin/build-help.php from help/*.md and assets/help/common/*.md. Do not edit.
export default {"format":"cadcraft-help","version":1,"app":"markupcraft","name":"MarkupCraft","common":"basics","sections":{"start":"Getting started","tasks":"Walkthroughs","switching":"Coming from other software","reference":"Reference","trouble":"Troubleshooting and limits"},"variants":{"os":{"mac":"Mac","windows":"Windows","linux":"Linux"},"browser":{"chromium":"Chrome or Edge","firefox":"Firefox","safari":"Safari"},"shell":{"web":"In the browser","desktop":"Desktop app"},"net":{"online":"Online","offline":"Offline"},"input":{"mouse":"Mouse","touch":"Touch"}},"topics":[{"slug":"whats-new","scope":"markupcraft","title":"What's new in 0.7","summary":"RFIs, submittals and daily logs in a new Field tab, with due dates, overdue in red, CSV and BCF, offline work and Merge; assistants that set statuses, reply and export the list; unit lists that follow Settings; panels that tidy away and dialogs that move.","section":"start","order":5,"keywords":["whats new","what's new","release notes","changelog","changes","0.7","version","new features","field","field records","rfi","request for information","submittal","daily log","site diary","overdue","due date","assigned to me","pin","merge","offline","tablet","bcf","csv","assistant","mcp","markup status","reply","export","units","unit lists","star","calibrate","compact","panels","dialogs","portuguese"],"headings":[{"id":"new","text":"New","level":2},{"id":"rfis-submittals-and-daily-logs","text":"RFIs, submittals and daily logs","level":3},{"id":"ai-assistants","text":"AI assistants","level":3},{"id":"in-every-app","text":"In every app","level":2},{"id":"not-in-this-version-yet","text":"Not in this version yet","level":2}],"html":"\u003Cp\u003EThis is what changed in MarkupCraft 0.7, compared with 0.6. The big new thing is field records: RFIs, submittals and daily logs kept inside the PDF beside your markups.\u003C/p\u003E\n\u003Ch2 id=\"new\"\u003ENew\u003C/h2\u003E\n\u003Ch3 id=\"rfis-submittals-and-daily-logs\"\u003ERFIs, submittals and daily logs\u003C/h3\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EThe Field tab.\u003C/strong\u003E Open the \u003Cspan class=\"hui\"\u003EField\u003C/span\u003E tab and choose \u003Cspan class=\"hui\"\u003ERFI\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESubmittal\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EDaily log\u003C/span\u003E. Tap or click the sheet where an RFI or a submittal belongs and a pin marks the place; a daily log goes on the open sheet without a pin (\u003Cspan class=\"hui\"\u003EPlace pin\u003C/span\u003E adds one later, \u003Cspan class=\"hui\"\u003EMove pin\u003C/span\u003E moves any pin). Each record has its own number (RFI-0001, SUB-0001, LOG-0001), a title, text, a status, an assignee, a due date, a thread of replies and a list of attachment names. See \u003Ca href=\"/tutorials/markupcraft/field-records\" data-topic=\"markupcraft/field-records\"\u003ETrack RFIs, submittals and daily logs\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESee what is late.\u003C/strong\u003E Filter the list by type, status, due date (overdue, due in 7 days, has or has no due date), this sheet or all sheets, a text search, or \u003Cspan class=\"hui\"\u003EAssigned to me\u003C/span\u003E. A record past its due date that is still waiting is marked \u003Cstrong\u003EOverdue\u003C/strong\u003E, in red, on the list and on its pin. See \u003Ca href=\"/tutorials/markupcraft/field-records#find-what-matters\" data-topic=\"markupcraft/field-records\" data-hash=\"find-what-matters\"\u003EFind what matters\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECSV and BCF.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ECSV\u003C/span\u003E writes the listed records as a spreadsheet; \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E writes them as BCF topics, each with a snapshot of its place on the sheet. Both follow the filters. See \u003Ca href=\"/tutorials/markupcraft/field-records#export\" data-topic=\"markupcraft/field-records\" data-hash=\"export\"\u003EExport\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EOffline, and two copies made one.\u003C/strong\u003E Records are saved inside the PDF and need no network, so a tablet on site can add, answer and save them. Back at the office, \u003Cspan class=\"hui\"\u003EMerge\u003C/span\u003E joins the records of another copy of the same PDF by their ids, as one undo step. See \u003Ca href=\"/tutorials/markupcraft/field-records#save-offline-and-merging-copies\" data-topic=\"markupcraft/field-records\" data-hash=\"save-offline-and-merging-copies\"\u003ESave, offline and merging copies\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch3 id=\"ai-assistants\"\u003EAI assistants\u003C/h3\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EMore an assistant can do.\u003C/strong\u003E Your own assistant, connected through CadCraft Studio, can now set a markup&#039;s status (\u003Ccode\u003Emarkup_status\u003C/code\u003E, logged in its thread), reply in a thread (\u003Ccode\u003Emarkup_reply\u003C/code\u003E) and export the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list as CSV or BCF (\u003Ccode\u003Emarkups_export\u003C/code\u003E, what the list shows with its filters). Each change is one undo step, signed with the assistant&#039;s name. See \u003Ca href=\"/tutorials/markupcraft/use-with-ai-assistants#what-an-assistant-can-ask-for\" data-topic=\"markupcraft/use-with-ai-assistants\" data-hash=\"what-an-assistant-can-ask-for\"\u003EWhat an assistant can ask for\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"in-every-app\"\u003EIn every app\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EUnits.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EUnits\u003C/span\u003E has one list each for length, area, volume, angle and slope, with the exact sizes the units&#039; definitions give (the US survey foot is its own unit). Switch off the units you never use and they leave the unit lists; star one and new work starts in it. A file always keeps its own unit. In MarkupCraft, the measuring and position units in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E and the unit in the calibrate dialog follow the switches, the star sets the measuring unit until you save MarkupCraft&#039;s own settings, and the real distance you type when you calibrate can carry any unit&#039;s mark, such as \u003Ccode\u003E3 yd\u003C/code\u003E or \u003Ccode\u003E1.5 km\u003C/code\u003E. See \u003Ca href=\"/tutorials/basics/unit-lists\" data-topic=\"basics/unit-lists\"\u003EUnits, typed values and the unit lists\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EA denser layout and panels that tidy away.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003ELayout density\u003C/span\u003E › \u003Cspan class=\"hui\"\u003ECompact\u003C/span\u003E fits more on the screen (touch screens and phones keep their large buttons). Each side panel has a slim title bar: drag it to dock or float the panel, drop it on another panel&#039;s bar to share one frame as tabs, pin it to slide away to the edge, or hide it and bring it back from the edge. See \u003Ca href=\"/tutorials/basics/arrange-panels#make-the-layout-denser\" data-topic=\"basics/arrange-panels\" data-hash=\"make-the-layout-denser\"\u003EArrange the panels\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EDialogs move.\u003C/strong\u003E Drag a dialog by its title bar out of the way of the drawing; it comes back where you left it. Double-click the title bar to centre it again. See \u003Ca href=\"/tutorials/basics/arrange-panels#move-a-dialog\" data-topic=\"basics/arrange-panels\" data-hash=\"move-a-dialog\"\u003EMove a dialog\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ERecipes for AI assistants.\u003C/strong\u003E Ten worked requests for your own assistant (tidy a drawing, plot a set, check drawings, ask a model questions, total a takeoff, try a part variant…), each with the tools it calls and the permissions it needs, and each replayed by our tests. The apps contain no AI. See \u003Ca href=\"/tutorials/basics/assistants-recipes\" data-topic=\"basics/assistants-recipes\"\u003ERecipes for AI assistants\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ELanguages.\u003C/strong\u003E \u003Cstrong\u003EPortuguês (Portugal)\u003C/strong\u003E is new in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003ELanguage\u003C/span\u003E. It, \u003Cstrong\u003EPortuguês (Brasil)\u003C/strong\u003E, \u003Cstrong\u003EEspañol (México)\u003C/strong\u003E and \u003Cstrong\u003EBahasa Indonesia\u003C/strong\u003E now have every word of the apps, as drafts not yet reviewed by a native speaker. Help topics are in English.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECadCraft Studio\u003C/strong\u003E says why an update check failed (no file for your system yet, no network, a bad signature) instead of just &quot;Done&quot;, and stops bringing back a What&#039;s new card you closed until there is a newer release.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"not-in-this-version-yet\"\u003ENot in this version yet\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003E0.7 is not code-signed.\u003C/strong\u003E Signing, and the Microsoft Store package, moved to 0.8 because the certificate validation has not come through yet. Check the SHA-256 beside each file on getcadcraft.com/download. On Windows, if SmartScreen stops the installer, choose \u003Cspan class=\"hui\"\u003EMore info\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003ERun anyway\u003C/span\u003E. On a Mac, the first time, right-click CadCraft Studio and choose \u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E. CadCraft Studio is not in an app store yet, and there is no iPad or iPhone build yet.\u003C/li\u003E\u003Cli\u003EThe angle and slope lists in \u003Cspan class=\"hui\"\u003EUnits\u003C/span\u003E are saved, but no box reads them yet.\u003C/li\u003E\u003Cli\u003EField records are not shared in a CadCraft Studio live session (live sessions carry markups only); bring copies together with \u003Cspan class=\"hui\"\u003EMerge\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EMerge takes a record as a whole from the copy changed last: if two people changed different fields of one record, the later copy&#039;s fields win. Threads and attachment names are joined.\u003C/li\u003E\u003Cli\u003EAttachments are names only; the files stay where they are. There are no teams, notifications or cloud projects for records, and assistants have no tools for records yet.\u003C/li\u003E\u003Cli\u003EField records were tested in a browser at phone and tablet sizes with the network cut, but not yet by hand on a real tablet.\u003C/li\u003E\u003Cli\u003EStill from 0.6: turning page objects to any angle, drawing new shapes straight into the page, changing a line&#039;s font or size, and text that flows over several lines. A saved copy with page edits has not been opened in Acrobat yet.\u003C/li\u003E\u003Cli\u003EStill from 0.5: undoing a page change (such as adding a blank page), reading text from scanned sheets, and live sessions beyond your own network.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EEverything else is in \u003Ca href=\"/tutorials/markupcraft/not-built-yet\" data-topic=\"markupcraft/not-built-yet\"\u003EWhat is not built yet\u003C/a\u003E.\u003C/p\u003E","text":"This is what changed in MarkupCraft 0.7, compared with 0.6. The big new thing is field records: RFIs, submittals and daily logs kept inside the PDF beside your markups. New RFIs, submittals and daily logs The Field tab. Open the Field tab and choose RFI, Submittal or Daily log. Tap or click the sheet where an RFI or a submittal belongs and a pin marks the place; a daily log goes on the open sheet without a pin (Place pin adds one later, Move pin moves any pin). Each record has its own number (RFI-0001, SUB-0001, LOG-0001), a title, text, a status, an assignee, a due date, a thread of replies and a list of attachment names. See Track RFIs, submittals and daily logs. See what is late. Filter the list by type, status, due date (overdue, due in 7 days, has or has no due date), this sheet or all sheets, a text search, or Assigned to me. A record past its due date that is still waiting is marked Overdue, in red, on the list and on its pin. See Find what matters. CSV and BCF. CSV writes the listed records as a spreadsheet; BCF writes them as BCF topics, each with a snapshot of its place on the sheet. Both follow the filters. See Export. Offline, and two copies made one. Records are saved inside the PDF and need no network, so a tablet on site can add, answer and save them. Back at the office, Merge joins the records of another copy of the same PDF by their ids, as one undo step. See Save, offline and merging copies. AI assistants More an assistant can do. Your own assistant, connected through CadCraft Studio, can now set a markup's status (markup_status, logged in its thread), reply in a thread (markup_reply) and export the Markups list as CSV or BCF (markups_export, what the list shows with its filters). Each change is one undo step, signed with the assistant's name. See What an assistant can ask for. In every app Units. Settings › General › Units has one list each for length, area, volume, angle and slope, with the exact sizes the units' definitions give (the US survey foot is its own unit). Switch off the units you never use and they leave the unit lists; star one and new work starts in it. A file always keeps its own unit. In MarkupCraft, the measuring and position units in Settings › MarkupCraft and the unit in the calibrate dialog follow the switches, the star sets the measuring unit until you save MarkupCraft's own settings, and the real distance you type when you calibrate can carry any unit's mark, such as 3 yd or 1.5 km. See Units, typed values and the unit lists. A denser layout and panels that tidy away. Settings › General › Layout density › Compact fits more on the screen (touch screens and phones keep their large buttons). Each side panel has a slim title bar: drag it to dock or float the panel, drop it on another panel's bar to share one frame as tabs, pin it to slide away to the edge, or hide it and bring it back from the edge. See Arrange the panels. Dialogs move. Drag a dialog by its title bar out of the way of the drawing; it comes back where you left it. Double-click the title bar to centre it again. See Move a dialog. Recipes for AI assistants. Ten worked requests for your own assistant (tidy a drawing, plot a set, check drawings, ask a model questions, total a takeoff, try a part variant…), each with the tools it calls and the permissions it needs, and each replayed by our tests. The apps contain no AI. See Recipes for AI assistants. Languages. Português (Portugal) is new in Settings › General › Language. It, Português (Brasil), Español (México) and Bahasa Indonesia now have every word of the apps, as drafts not yet reviewed by a native speaker. Help topics are in English. CadCraft Studio says why an update check failed (no file for your system yet, no network, a bad signature) instead of just \"Done\", and stops bringing back a What's new card you closed until there is a newer release. Not in this version yet 0.7 is not code-signed. Signing, and the Microsoft Store package, moved to 0.8 because the certificate validation has not come through yet. Check the SHA-256 beside each file on getcadcraft.com/download. On Windows, if SmartScreen stops the installer, choose More info, then Run anyway. On a Mac, the first time, right-click CadCraft Studio and choose Open. CadCraft Studio is not in an app store yet, and there is no iPad or iPhone build yet. The angle and slope lists in Units are saved, but no box reads them yet. Field records are not shared in a CadCraft Studio live session (live sessions carry markups only); bring copies together with Merge. Merge takes a record as a whole from the copy changed last: if two people changed different fields of one record, the later copy's fields win. Threads and attachment names are joined. Attachments are names only; the files stay where they are. There are no teams, notifications or cloud projects for records, and assistants have no tools for records yet. Field records were tested in a browser at phone and tablet sizes with the network cut, but not yet by hand on a real tablet. Still from 0.6: turning page objects to any angle, drawing new shapes straight into the page, changing a line's font or size, and text that flows over several lines. A saved copy with page edits has not been opened in Acrobat yet. Still from 0.5: undoing a page change (such as adding a blank page), reading text from scanned sheets, and live sessions beyond your own network. Everything else is in What is not built yet.","lang":"en"},{"slug":"getting-started","scope":"markupcraft","title":"Getting started with MarkupCraft","summary":"Open a plan set, put your first cloud and callout on a sheet, and save a marked-up copy.","section":"start","order":10,"keywords":["start","first steps","open pdf","review","markup","redline","red pen","plan set","tutorial","quick start"],"headings":[{"id":"what-you-need","text":"What you need","level":2},{"id":"your-first-review-in-ten-steps","text":"Your first review in ten steps","level":2},{"id":"online-and-offline","text":"Online and offline","level":2},{"id":"what-the-app-remembers-and-what-it-does-not","text":"What the app remembers, and what it does not","level":2},{"id":"where-to-go-next","text":"Where to go next","level":2}],"html":"\u003Cp\u003EMarkupCraft is for reviewing drawings: you open PDF plan sets, mark them up with clouds, callouts, text, stamps and measurements, track each comment&#039;s status, and save a copy of the PDF that any PDF viewer can show.\u003C/p\u003E\n\u003Cp\u003EIt runs in your web browser. Your PDFs are opened on your own computer and are \u003Cstrong\u003Enever uploaded\u003C/strong\u003E. Saving downloads a new copy; your original file is not changed.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EMarkupCraft is in development. The help describes the build you are running. Things it does not do yet are listed in \u003Ca href=\"/tutorials/markupcraft/not-built-yet\" data-topic=\"markupcraft/not-built-yet\"\u003EWhat is not built yet\u003C/a\u003E.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"what-you-need\"\u003EWhat you need\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EA recent Chrome, Edge, Firefox or Safari on a Mac, Windows or Linux computer, or Safari or Chrome on an iPad. See \u003Ca href=\"/tutorials/basics/browsers\" data-topic=\"basics/browsers\"\u003EBrowsers and computers\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003EOne or more PDF files. A whole plan set can be one PDF or many.\u003C/li\u003E\u003Cli\u003EA mouse with a wheel is the most comfortable. A trackpad works, and so does a touch screen (see \u003Ca href=\"/tutorials/markupcraft/review-on-a-tablet\" data-topic=\"markupcraft/review-on-a-tablet\"\u003EReview on an iPad or touch screen\u003C/a\u003E).\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"your-first-review-in-ten-steps\"\u003EYour first review in ten steps\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen MarkupCraft in your browser. The middle of the screen says &quot;Open a plan set&quot;.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EOpen PDFs\u003C/span\u003E (or \u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E at the left end of the toolbar, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E), pick one or more PDFs, and confirm. You can also drag PDFs from \u003Cspan class=\"hp\"\u003E\u003Cspan class=\"hpv\" data-v=\"os:mac\" title=\"Mac\"\u003EFinder\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:windows\" title=\"Windows\"\u003EFile Explorer\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:linux\" title=\"Linux\"\u003Eyour file manager\u003C/span\u003E\u003C/span\u003E and drop them on the sheet area. The first time, the status bar at the bottom says &quot;Loading the PDF reader…&quot;. Then every page becomes a sheet in the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E list on the left, and the first sheet fills the middle.\u003C/li\u003E\u003Cli\u003EClick a sheet in the list to show it. Turn the mouse wheel over the sheet to zoom in where the pointer is.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003ERevise\u003C/span\u003E group of the toolbar (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E). The first time you pick a drawing tool, MarkupCraft asks for your name. Type it and choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E. Every markup records it. (More in \u003Ca href=\"/tutorials/markupcraft/set-your-name\" data-topic=\"markupcraft/set-your-name\"\u003ESet your author name\u003C/a\u003E.)\u003C/li\u003E\u003Cli\u003EDrag a box around the area you want to flag. A red revision cloud appears and is selected.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EAnnotate\u003C/span\u003E group (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E). Press on the thing you are pointing at, drag to where the text should go, and let go.\u003C/li\u003E\u003Cli\u003EType your comment in the box that appears. Click anywhere outside the box (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E) to finish.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E twice: once to clear the selection, once to go back to the \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E tool. Click the cloud. The \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E tab on the right shows who made it, when, and its \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E in the toolbar (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E). Your browser downloads a copy named like &quot;A-Plans (marked up).pdf&quot;. The status bar lists how many markups were written.\u003C/li\u003E\u003Cli\u003EOpen that copy in any PDF viewer to check: the cloud and the callout are there, as normal PDF comments with your name on them.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ETo keep working later, open the &quot;(marked up)&quot; copy in MarkupCraft. Your markups come back editable, with their statuses, replies and punch numbers.\u003C/p\u003E\n\u003Ch2 id=\"online-and-offline\"\u003EOnline and offline\u003C/h2\u003E\n\u003Cdiv class=\"hv\" data-v=\"net:online\"\u003E\u003Cp class=\"hv-label\"\u003EOnline\u003C/p\u003E\n\u003Cp\u003EYou are online. MarkupCraft loads its PDF reader the first time you open a PDF, and its PDF writer the first time you save. To work with no connection later (on a site visit, on a plane), choose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E in the bar at the top now and wait for &quot;Offline ready&quot;. The copy includes the PDF reader and writer, so opening and saving PDFs then work offline. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"net:offline\"\u003E\u003Cp class=\"hv-label\"\u003EOffline\u003C/p\u003E\n\u003Cp\u003EYou are offline. If the bar at the top says &quot;Offline ready&quot;, MarkupCraft was saved for offline use in this browser and everything works: opening, marking up, measuring, saving. If it was not, use what has already loaded in this tab and don&#039;t reload the page until you are back online. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"what-the-app-remembers-and-what-it-does-not\"\u003EWhat the app remembers, and what it does not\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EYour markups live in the PDF you save.\u003C/strong\u003E Nothing is kept on a server. The app does not save the PDF on its own, but keeps a recovery copy in this browser until you do. Save before you close the tab; the browser asks first if you try to leave with unsaved markups (except on an iPad, see \u003Ca href=\"/tutorials/markupcraft/review-on-a-tablet\" data-topic=\"markupcraft/review-on-a-tablet\"\u003EReview on an iPad or touch screen\u003C/a\u003E).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EYour name, your tool styles and your tool chest\u003C/strong\u003E stay in this browser on this computer. Another browser or computer starts fresh, and clearing the browser&#039;s site data removes them. See \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003ECloud saving and review sessions shared between people are not available yet.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"where-to-go-next\"\u003EWhere to go next\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/workspace\" data-topic=\"markupcraft/workspace\"\u003EA tour of the screen\u003C/a\u003E\u003C/li\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/mark-up-a-sheet\" data-topic=\"markupcraft/mark-up-a-sheet\"\u003EMark up a sheet\u003C/a\u003E\u003C/li\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure\" data-topic=\"markupcraft/calibrate-and-measure\"\u003ECalibrate a sheet and measure\u003C/a\u003E\u003C/li\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/coming-from\" data-topic=\"markupcraft/coming-from\"\u003EComing from other markup software\u003C/a\u003E if you already review drawings in another program.\u003C/li\u003E\u003C/ul\u003E","text":"MarkupCraft is for reviewing drawings: you open PDF plan sets, mark them up with clouds, callouts, text, stamps and measurements, track each comment's status, and save a copy of the PDF that any PDF viewer can show. It runs in your web browser. Your PDFs are opened on your own computer and are never uploaded. Saving downloads a new copy; your original file is not changed. MarkupCraft is in development. The help describes the build you are running. Things it does not do yet are listed in What is not built yet. What you need A recent Chrome, Edge, Firefox or Safari on a Mac, Windows or Linux computer, or Safari or Chrome on an iPad. See Browsers and computers. One or more PDF files. A whole plan set can be one PDF or many. A mouse with a wheel is the most comfortable. A trackpad works, and so does a touch screen (see Review on an iPad or touch screen). Your first review in ten steps Open MarkupCraft in your browser. The middle of the screen says \"Open a plan set\". Choose Open PDFs (or Open at the left end of the toolbar, or press Ctrl+O), pick one or more PDFs, and confirm. You can also drag PDFs from Finder / File Explorer / your file manager and drop them on the sheet area. The first time, the status bar at the bottom says \"Loading the PDF reader…\". Then every page becomes a sheet in the Sheets list on the left, and the first sheet fills the middle. Click a sheet in the list to show it. Turn the mouse wheel over the sheet to zoom in where the pointer is. Choose Cloud in the Revise group of the toolbar (or press C). The first time you pick a drawing tool, MarkupCraft asks for your name. Type it and choose Save. Every markup records it. (More in Set your author name.) Drag a box around the area you want to flag. A red revision cloud appears and is selected. Choose Callout in the Annotate group (or press K). Press on the thing you are pointing at, drag to where the text should go, and let go. Type your comment in the box that appears. Click anywhere outside the box (or press Ctrl+Enter) to finish. Press Esc twice: once to clear the selection, once to go back to the Select tool. Click the cloud. The Properties tab on the right shows who made it, when, and its Status. Choose Save in the toolbar (or press Ctrl+S). Your browser downloads a copy named like \"A-Plans (marked up).pdf\". The status bar lists how many markups were written. Open that copy in any PDF viewer to check: the cloud and the callout are there, as normal PDF comments with your name on them. To keep working later, open the \"(marked up)\" copy in MarkupCraft. Your markups come back editable, with their statuses, replies and punch numbers. Online and offline You are online. MarkupCraft loads its PDF reader the first time you open a PDF, and its PDF writer the first time you save. To work with no connection later (on a site visit, on a plane), choose Save for offline in the bar at the top now and wait for \"Offline ready\". The copy includes the PDF reader and writer, so opening and saving PDFs then work offline. See Working offline. You are offline. If the bar at the top says \"Offline ready\", MarkupCraft was saved for offline use in this browser and everything works: opening, marking up, measuring, saving. If it was not, use what has already loaded in this tab and don't reload the page until you are back online. See Working offline. What the app remembers, and what it does not Your markups live in the PDF you save. Nothing is kept on a server. The app does not save the PDF on its own, but keeps a recovery copy in this browser until you do. Save before you close the tab; the browser asks first if you try to leave with unsaved markups (except on an iPad, see Review on an iPad or touch screen). Your name, your tool styles and your tool chest stay in this browser on this computer. Another browser or computer starts fresh, and clearing the browser's site data removes them. See What stays in this browser. Cloud saving and review sessions shared between people are not available yet. Where to go next A tour of the screen Mark up a sheet Calibrate a sheet and measure Coming from other markup software if you already review drawings in another program.","lang":"en"},{"slug":"workspace","scope":"markupcraft","title":"A tour of the screen","summary":"The toolbar, the sheets list, the sheet area, the five panels on the right and the status bar, by their on-screen names.","section":"start","order":20,"keywords":["screen","layout","toolbar","panels","sidebar","thumbnails","properties","status bar","interface","full screen","theme","dark mode"],"headings":[{"id":"the-bar-at-the-very-top","text":"The bar at the very top","level":2},{"id":"the-toolbar","text":"The toolbar","level":2},{"id":"the-sheets-list-left","text":"The sheets list (left)","level":2},{"id":"the-sheet-area-middle","text":"The sheet area (middle)","level":2},{"id":"the-panels-right","text":"The panels (right)","level":2},{"id":"the-status-bar-bottom","text":"The status bar (bottom)","level":2},{"id":"on-a-small-screen","text":"On a small screen","level":2}],"html":"\u003Cp\u003EMarkupCraft fills the browser window. From top to bottom and left to right:\u003C/p\u003E\n\u003Ch2 id=\"the-bar-at-the-very-top\"\u003EThe bar at the very top\u003C/h2\u003E\n\u003Cp\u003EThe thin bar above everything belongs to the CadCraft family, not to MarkupCraft itself. It has:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003Ethe app name and which version you are running,\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EAbout MarkupCraft\u003C/span\u003E, which opens the app&#039;s page on the website,\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E, which opens this help in a side panel (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E),\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E, which keeps MarkupCraft, its PDF reader and writer, and this help in this browser so it opens with no connection; it then says &quot;Offline ready&quot; (see \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E),\u003C/li\u003E\u003Cli\u003Ethe screen-mode button (\u003Cspan class=\"hui\"\u003EFull screen\u003C/span\u003E), and\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E (or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E), with a \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E tab for this app&#039;s own settings and \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E for the ones every CadCraft app shares (see \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003EMarkupCraft settings\u003C/a\u003E), and\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPaper\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EModel\u003C/span\u003E, the light and dark themes. In \u003Cspan class=\"hui\"\u003EModel\u003C/span\u003E the sheets are drawn light-on-dark; your markups keep their own colors.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe screen-mode button, or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E, steps through three modes: normal, full screen, and full screen with the bars hidden. With the bars hidden, move the pointer to the top edge of the screen (or tap there) and they slide back. This shortcut uses the Control key on every computer, Mac included.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EIn full screen, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E also makes the browser leave full screen. If you only meant to cancel a drawing, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E again to go back to full screen.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"the-toolbar\"\u003EThe toolbar\u003C/h2\u003E\n\u003Cp\u003EUnder the top bar, the tools are grouped and labeled:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EGroup\u003C/th\u003E\u003Cth scope=\"col\"\u003EButtons\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EFile\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESelect\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDraw\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPen\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ERevise\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EAnnotate\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EText\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMeasure\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEdit\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ERedo\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E, and \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E: \u003Cspan class=\"hui\"\u003ECut\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPaste in place\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDuplicate\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDelete\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESelect all\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESelect none\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EThe tool you are using looks pressed. Hold the pointer over a button to see its key (for example &quot;Rectangle (R)&quot;); the \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E menu lists each command&#039;s key beside it. Buttons that cannot act right now are dimmed: \u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E until you select a markup, \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E until something is copied. A small dot after \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E means some markups are not saved yet. The full key list is in \u003Ca href=\"/tutorials/markupcraft/keyboard\" data-topic=\"markupcraft/keyboard\"\u003EKeyboard and mouse\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EA tool stays on after you draw with it, so you can draw several clouds in a row. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E (twice if the new markup is still selected) or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"V\"\u003EV\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EV\u003C/span\u003E\u003C/kbd\u003E to go back to \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"the-sheets-list-left\"\u003EThe sheets list (left)\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E lists every page of every open PDF. Each row shows a small picture of the sheet, its name, its sheet number or file and page, and how many markups it has. The count after the heading is the number of sheets.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EClick a row to show that sheet.\u003C/li\u003E\u003Cli\u003EType in \u003Cspan class=\"hui\"\u003ESearch sheets\u003C/span\u003E to filter by sheet name, sheet number or file name. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E to open the first match.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ESheet names come from the PDF when it has them. See \u003Ca href=\"/tutorials/markupcraft/open-a-plan-set\" data-topic=\"markupcraft/open-a-plan-set\"\u003EOpen a plan set and move between sheets\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"the-sheet-area-middle\"\u003EThe sheet area (middle)\u003C/h2\u003E\n\u003Cp\u003EThe sheet you are working on. Before anything is open it shows &quot;Open a plan set&quot; with an \u003Cspan class=\"hui\"\u003EOpen PDFs\u003C/span\u003E button. Drop PDFs anywhere here to open them.\u003C/p\u003E\n\u003Cp\u003EUnder the sheet, a narrow bar has:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003Ethe previous and next sheet arrows, and &quot;3 of 12: A-101 — Floor plan&quot; (hold the pointer over it to see the file and page),\u003C/li\u003E\u003Cli\u003Ezoom out, the zoom box (type a percentage and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E; 100% is actual size on a typical screen), zoom in,\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EFit page\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EFit width\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EEach sheet remembers its own zoom while the set is open.\u003C/p\u003E\n\u003Cp\u003EWhen you compare two sheets, a legend appears here: &quot;Only on the old sheet&quot;, &quot;Only on the new sheet&quot; and &quot;On both&quot;. See \u003Ca href=\"/tutorials/markupcraft/compare-revisions\" data-topic=\"markupcraft/compare-revisions\"\u003ECompare two revisions\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"the-panels-right\"\u003EThe panels (right)\u003C/h2\u003E\n\u003Cp\u003EFive tabs:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ETab\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it shows\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EThe selected markup: author, dates, measured values, status, subject, text, comment, style, its replies and its punch item. With a drawing tool on and nothing selected, the settings new markups will use. With nothing selected and \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E on, the sheet: number, title, where the name was read from, paper size, scale, and \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EEvery markup in the open set, with filters, and \u003Cspan class=\"hui\"\u003ECSV\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E exports. See \u003Ca href=\"/tutorials/markupcraft/markups-list-and-export\" data-topic=\"markupcraft/markups-list-and-export\"\u003EThe markups list\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003ENumbered punch items with assignee, due date and status. See \u003Ca href=\"/tutorials/markupcraft/punch-list\" data-topic=\"markupcraft/punch-list\"\u003EMake a punch list\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EThe tool chest: saved, styled tools. See \u003Ca href=\"/tutorials/markupcraft/tool-chest\" data-topic=\"markupcraft/tool-chest\"\u003EThe tool chest\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECompare\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EOverlay two sheets. See \u003Ca href=\"/tutorials/markupcraft/compare-revisions\" data-topic=\"markupcraft/compare-revisions\"\u003ECompare two revisions\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"the-status-bar-bottom\"\u003EThe status bar (bottom)\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EOn the left, where the pointer is on the sheet, in inches (or millimeters, in \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003ESettings\u003C/a\u003E) on the paper.\u003C/li\u003E\u003Cli\u003EIn the middle, messages: what a tool expects next, what was just saved, why something was refused. \u003Cstrong\u003ERead it when something does not happen.\u003C/strong\u003E\u003C/li\u003E\u003Cli\u003EThe sheet&#039;s scale button (&quot;Not calibrated&quot;, or the scale). Click it to set the scale. See \u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure\" data-topic=\"markupcraft/calibrate-and-measure\"\u003ECalibrate a sheet and measure\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003EYour name (&quot;Set your name&quot; until you give one). Click it to change it.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"on-a-small-screen\"\u003EOn a small screen\u003C/h2\u003E\n\u003Cp\u003EBelow about 1180 pixels wide the panels get narrower and the sheet pictures shrink. On a phone-sized screen the parts stack: toolbar (scroll it sideways), the sheet, the status bar, the panels, then the sheets list at the bottom. A tablet in landscape keeps the full layout.\u003C/p\u003E","text":"MarkupCraft fills the browser window. From top to bottom and left to right: The bar at the very top The thin bar above everything belongs to the CadCraft family, not to MarkupCraft itself. It has: the app name and which version you are running, About MarkupCraft, which opens the app's page on the website, Help, which opens this help in a side panel (or press F1), Save for offline, which keeps MarkupCraft, its PDF reader and writer, and this help in this browser so it opens with no connection; it then says \"Offline ready\" (see Working offline), the screen-mode button (Full screen), and Settings (or Ctrl+,), with a MarkupCraft tab for this app's own settings and General for the ones every CadCraft app shares (see MarkupCraft settings), and Paper and Model, the light and dark themes. In Model the sheets are drawn light-on-dark; your markups keep their own colors. The screen-mode button, or Ctrl+Shift+F, steps through three modes: normal, full screen, and full screen with the bars hidden. With the bars hidden, move the pointer to the top edge of the screen (or tap there) and they slide back. This shortcut uses the Control key on every computer, Mac included. In full screen, Esc also makes the browser leave full screen. If you only meant to cancel a drawing, press Ctrl+Shift+F again to go back to full screen. The toolbar Under the top bar, the tools are grouped and labeled: Group Buttons File Open, Save, Close Select Select, Pan Draw Pen, Highlight, Line, Arrow, Rectangle, Ellipse, Polyline, Polygon Revise Cloud, Free cloud Annotate Callout, Text, Note, Stamp Measure Calibrate, Length, Area, Count Edit Undo, Redo, Copy, Paste, and More: Cut, Copy, Paste, Paste in place, Duplicate, Delete, Select all, Select none The tool you are using looks pressed. Hold the pointer over a button to see its key (for example \"Rectangle (R)\"); the More menu lists each command's key beside it. Buttons that cannot act right now are dimmed: Copy until you select a markup, Paste until something is copied. A small dot after Save means some markups are not saved yet. The full key list is in Keyboard and mouse. A tool stays on after you draw with it, so you can draw several clouds in a row. Press Esc (twice if the new markup is still selected) or V to go back to Select. The sheets list (left) Sheets lists every page of every open PDF. Each row shows a small picture of the sheet, its name, its sheet number or file and page, and how many markups it has. The count after the heading is the number of sheets. Click a row to show that sheet. Type in Search sheets to filter by sheet name, sheet number or file name. Press Enter to open the first match. Sheet names come from the PDF when it has them. See Open a plan set and move between sheets. The sheet area (middle) The sheet you are working on. Before anything is open it shows \"Open a plan set\" with an Open PDFs button. Drop PDFs anywhere here to open them. Under the sheet, a narrow bar has: the previous and next sheet arrows, and \"3 of 12: A-101 — Floor plan\" (hold the pointer over it to see the file and page), zoom out, the zoom box (type a percentage and press Enter; 100% is actual size on a typical screen), zoom in, Fit page and Fit width. Each sheet remembers its own zoom while the set is open. When you compare two sheets, a legend appears here: \"Only on the old sheet\", \"Only on the new sheet\" and \"On both\". See Compare two revisions. The panels (right) Five tabs: Tab What it shows Properties The selected markup: author, dates, measured values, status, subject, text, comment, style, its replies and its punch item. With a drawing tool on and nothing selected, the settings new markups will use. With nothing selected and Select on, the sheet: number, title, where the name was read from, paper size, scale, and Rename sheet. Markups Every markup in the open set, with filters, and CSV and BCF exports. See The markups list. Punch list Numbered punch items with assignee, due date and status. See Make a punch list. Tools The tool chest: saved, styled tools. See The tool chest. Compare Overlay two sheets. See Compare two revisions. The status bar (bottom) On the left, where the pointer is on the sheet, in inches (or millimeters, in Settings) on the paper. In the middle, messages: what a tool expects next, what was just saved, why something was refused. Read it when something does not happen. The sheet's scale button (\"Not calibrated\", or the scale). Click it to set the scale. See Calibrate a sheet and measure. Your name (\"Set your name\" until you give one). Click it to change it. On a small screen Below about 1180 pixels wide the panels get narrower and the sheet pictures shrink. On a phone-sized screen the parts stack: toolbar (scroll it sideways), the sheet, the status bar, the panels, then the sheets list at the bottom. A tablet in landscape keeps the full layout.","lang":"en"},{"slug":"files","scope":"markupcraft","title":"Files MarkupCraft opens and saves","summary":"PDFs in, a marked-up PDF copy out, plus CSV, BCF and tool chest files; where each goes, online and offline.","section":"start","order":30,"keywords":["pdf","open","save","export","download","csv","bcf","bcfzip","json","tool chest","file types","formats","upload","password","encrypted"],"headings":[{"id":"what-markupcraft-opens","text":"What MarkupCraft opens","level":2},{"id":"markups-already-in-a-pdf","text":"Markups already in a PDF","level":3},{"id":"files-that-do-not-open","text":"Files that do not open","level":3},{"id":"what-markupcraft-saves","text":"What MarkupCraft saves","level":2},{"id":"where-downloads-go","text":"Where downloads go","level":2},{"id":"online-and-offline","text":"Online and offline","level":2},{"id":"things-to-know","text":"Things to know","level":2}],"html":"\u003Ch2 id=\"what-markupcraft-opens\"\u003EWhat MarkupCraft opens\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EFile\u003C/th\u003E\u003Cth scope=\"col\"\u003EHow\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat happens\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EPDF (\u003Ccode\u003E.pdf\u003C/code\u003E)\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E, or drop on the sheet area. Several at once is fine.\u003C/td\u003E\u003Ctd\u003EEvery page becomes a sheet. Markups already in the file are read back (below).\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETool chest (\u003Ccode\u003E.json\u003C/code\u003E)\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab, then \u003Cspan class=\"hui\"\u003EImport\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003ETools are added to your chest. See \u003Ca href=\"/tutorials/markupcraft/tool-chest\" data-topic=\"markupcraft/tool-chest\"\u003EThe tool chest\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EAnything else is refused with &quot;MarkupCraft opens PDF files.&quot; in the status bar. If you drop a mix, the PDFs open and the status bar says how many files were not PDF.\u003C/p\u003E\n\u003Ch3 id=\"markups-already-in-a-pdf\"\u003EMarkups already in a PDF\u003C/h3\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EMarkups MarkupCraft saved\u003C/strong\u003E come back exactly: type, style, author, dates, status, replies, punch number, the sheet&#039;s scale and any sheet names you typed.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EComments from other PDF programs\u003C/strong\u003E are read too. Rectangles, ellipses, lines and arrows, polylines, polygons, ink (pen) strokes, text boxes and sticky notes become normal, editable MarkupCraft markups. Their replies and review statuses come along.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EEverything else\u003C/strong\u003E (text highlights made by selecting text, other programs&#039; stamps, and other kinds) is shown as it is, marked read-only. You can select it, see it in the markups list and reply to it, but not move, change or delete it.\u003C/li\u003E\u003Cli\u003ELinks and form fields are left alone and are not listed.\u003C/li\u003E\u003Cli\u003EA scale saved by another program (a measurement viewport) is used as the sheet&#039;s scale when MarkupCraft understands its unit.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch3 id=\"files-that-do-not-open\"\u003EFiles that do not open\u003C/h3\u003E\n\u003Cul\u003E\u003Cli\u003EA PDF that needs a password: &#039;&quot;name&quot; needs a password to open. Open an unprotected copy.&#039;\u003C/li\u003E\u003Cli\u003EA damaged file or one that is not really a PDF: &#039;&quot;name&quot; could not be read as a PDF (…)&#039;.\u003C/li\u003E\u003Cli\u003EA PDF that opens but is protected against changes opens fine. Saving it is refused (see below).\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EWhen several files are opened at once, the ones that work open and a box called &quot;Some files did not open&quot; lists the others.\u003C/p\u003E\n\u003Ch2 id=\"what-markupcraft-saves\"\u003EWhat MarkupCraft saves\u003C/h2\u003E\n\u003Cp\u003ESaving is always a \u003Cstrong\u003Edownload\u003C/strong\u003E of a new file. A web page cannot overwrite a file on your computer, and MarkupCraft never changes your original.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EYou choose\u003C/th\u003E\u003Cth scope=\"col\"\u003EYou get\u003C/th\u003E\u003Cth scope=\"col\"\u003ENotes\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E)\u003C/td\u003E\u003Ctd\u003E&quot;&lt;name&gt; (marked up).pdf&quot;\u003C/td\u003E\u003Ctd\u003EA copy of the original PDF with every markup written in as a real PDF comment. Saving a &quot;(marked up)&quot; file again keeps the same name; it never becomes &quot;(marked up) (marked up)&quot;. See \u003Ca href=\"/tutorials/markupcraft/save-the-marked-up-pdf\" data-topic=\"markupcraft/save-the-marked-up-pdf\"\u003ESave the marked-up PDF\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab, then \u003Cspan class=\"hui\"\u003ECSV\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E&quot;&lt;name&gt; markups.csv&quot;\u003C/td\u003E\u003Ctd\u003EThe markups as listed (filters apply).\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab, then \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E&quot;&lt;name&gt; markups.bcfzip&quot;\u003C/td\u003E\u003Ctd\u003EBCF 2.1 for BIM coordination tools, a snapshot per markup. See \u003Ca href=\"/tutorials/markupcraft/bcf-basics\" data-topic=\"markupcraft/bcf-basics\"\u003EBCF basics\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab, then \u003Cspan class=\"hui\"\u003EExport CSV\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E&quot;&lt;name&gt; punch list.csv&quot;\u003C/td\u003E\u003Ctd\u003EThe punch items in number order.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab, then \u003Cspan class=\"hui\"\u003EExport\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E&quot;MarkupCraft tool chest.json&quot;\u003C/td\u003E\u003Ctd\u003EYour tool chest, to share or keep.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003E&quot;&lt;name&gt;&quot; is the first open PDF&#039;s file name without &quot;.pdf&quot;.\u003C/p\u003E\n\u003Cp\u003EThe CSV files open in any spreadsheet. They are UTF-8 with the marker spreadsheets look for, so accented names come out right. A cell that starts with =, +, - or @ gets a leading apostrophe so a spreadsheet never runs it as a formula.\u003C/p\u003E\n\u003Ch2 id=\"where-downloads-go\"\u003EWhere downloads go\u003C/h2\u003E\n\u003Cp\u003EYour browser decides: usually your Downloads folder, or it asks each time if you set it to. See \u003Ca href=\"/tutorials/basics/browsers#what-differs-between-browsers\" data-topic=\"basics/browsers\" data-hash=\"what-differs-between-browsers\"\u003EBrowsers and computers\u003C/a\u003E.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:chromium\"\u003E\u003Cp class=\"hv-label\"\u003EChrome or Edge\u003C/p\u003E\n\u003Cp\u003EWhen you save every changed file of a set at once, Chrome and Edge may ask whether this site may download multiple files. Choose \u003Cspan class=\"hui\"\u003EAllow\u003C/span\u003E, or you get only the first copy.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003EOn an iPad, Safari asks before each download and puts the file in the Files app, under Downloads. On a Mac it goes to the folder set in Safari&#039;s settings.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"online-and-offline\"\u003EOnline and offline\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EYour PDFs never leave this computer\u003C/strong\u003E, online or offline. There is no upload anywhere.\u003C/li\u003E\u003Cli\u003EThe PDF reader is loaded the first time you open a PDF (&quot;Loading the PDF reader…&quot;), and the PDF writer the first time you save (&quot;Loading the PDF writer…&quot;) or open a file that already has comments in it.\u003C/li\u003E\u003Cli\u003EWith a connection, both load from the website.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ETo work with no connection,\u003C/strong\u003E choose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E in the bar at the top while you are online. The button counts &quot;Saving N of M&quot; and then says &quot;Offline ready&quot;. That copy includes the PDF reader and the PDF writer (about 6 MB in all) and this help, so afterwards opening, marking up and saving PDFs all work offline in this browser.\u003C/li\u003E\u003Cli\u003EIf the button says &quot;Could not save&quot;, some files did not download: check the connection and click it again. If it says &quot;Offline not available&quot;, this browser window cannot keep an offline copy (private windows and some managed computers); use a normal window.\u003C/li\u003E\u003Cli\u003ETo update or drop the copy, click &quot;Offline ready&quot; and choose &quot;Save again (get the newest version)&quot; or &quot;Remove the offline copy&quot;. More in \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"net:offline\"\u003E\u003Cp class=\"hv-label\"\u003EOffline\u003C/p\u003E\n\u003Cp\u003EYou are offline. If the bar at the top says &quot;Offline ready&quot;, everything works, saving included. If it does not and you have not saved yet in this tab, \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E can fail with &quot;The PDF writer could not load&quot;. Your markups are still in the tab: keep it open, get back online, and choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E again.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"things-to-know\"\u003EThings to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003ELarge plan sets take a while to open: MarkupCraft reads every page&#039;s text to find sheet numbers. The status bar counts the sheets as it goes.\u003C/li\u003E\u003Cli\u003EOpening the same PDF twice adds its sheets twice. Close the set and open it again if that happens.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E closes every open file at once. If any have unsaved markups it asks: \u003Cspan class=\"hui\"\u003ECancel\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EClose without saving\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ESave copies first\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003ECloud saving is not available yet, and there are no desktop builds yet. Keep your PDFs with your other project files and back them up as usual. See \u003Ca href=\"/tutorials/basics/your-files\" data-topic=\"basics/your-files\"\u003EWhere your files go\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E","text":"What MarkupCraft opens File How What happens PDF (.pdf) Open, Ctrl+O, or drop on the sheet area. Several at once is fine. Every page becomes a sheet. Markups already in the file are read back (below). Tool chest (.json) Tools tab, then Import Tools are added to your chest. See The tool chest. Anything else is refused with \"MarkupCraft opens PDF files.\" in the status bar. If you drop a mix, the PDFs open and the status bar says how many files were not PDF. Markups already in a PDF Markups MarkupCraft saved come back exactly: type, style, author, dates, status, replies, punch number, the sheet's scale and any sheet names you typed. Comments from other PDF programs are read too. Rectangles, ellipses, lines and arrows, polylines, polygons, ink (pen) strokes, text boxes and sticky notes become normal, editable MarkupCraft markups. Their replies and review statuses come along. Everything else (text highlights made by selecting text, other programs' stamps, and other kinds) is shown as it is, marked read-only. You can select it, see it in the markups list and reply to it, but not move, change or delete it. Links and form fields are left alone and are not listed. A scale saved by another program (a measurement viewport) is used as the sheet's scale when MarkupCraft understands its unit. Files that do not open A PDF that needs a password: '\"name\" needs a password to open. Open an unprotected copy.' A damaged file or one that is not really a PDF: '\"name\" could not be read as a PDF (…)'. A PDF that opens but is protected against changes opens fine. Saving it is refused (see below). When several files are opened at once, the ones that work open and a box called \"Some files did not open\" lists the others. What MarkupCraft saves Saving is always a download of a new file. A web page cannot overwrite a file on your computer, and MarkupCraft never changes your original. You choose You get Notes Save (Ctrl+S) \"\u003Cname\u003E (marked up).pdf\" A copy of the original PDF with every markup written in as a real PDF comment. Saving a \"(marked up)\" file again keeps the same name; it never becomes \"(marked up) (marked up)\". See Save the marked-up PDF. Markups tab, then CSV \"\u003Cname\u003E markups.csv\" The markups as listed (filters apply). Markups tab, then BCF \"\u003Cname\u003E markups.bcfzip\" BCF 2.1 for BIM coordination tools, a snapshot per markup. See BCF basics. Punch list tab, then Export CSV \"\u003Cname\u003E punch list.csv\" The punch items in number order. Tools tab, then Export \"MarkupCraft tool chest.json\" Your tool chest, to share or keep. \"\u003Cname\u003E\" is the first open PDF's file name without \".pdf\". The CSV files open in any spreadsheet. They are UTF-8 with the marker spreadsheets look for, so accented names come out right. A cell that starts with =, +, - or @ gets a leading apostrophe so a spreadsheet never runs it as a formula. Where downloads go Your browser decides: usually your Downloads folder, or it asks each time if you set it to. See Browsers and computers. When you save every changed file of a set at once, Chrome and Edge may ask whether this site may download multiple files. Choose Allow, or you get only the first copy. On an iPad, Safari asks before each download and puts the file in the Files app, under Downloads. On a Mac it goes to the folder set in Safari's settings. Online and offline Your PDFs never leave this computer, online or offline. There is no upload anywhere. The PDF reader is loaded the first time you open a PDF (\"Loading the PDF reader…\"), and the PDF writer the first time you save (\"Loading the PDF writer…\") or open a file that already has comments in it. With a connection, both load from the website. To work with no connection, choose Save for offline in the bar at the top while you are online. The button counts \"Saving N of M\" and then says \"Offline ready\". That copy includes the PDF reader and the PDF writer (about 6 MB in all) and this help, so afterwards opening, marking up and saving PDFs all work offline in this browser. If the button says \"Could not save\", some files did not download: check the connection and click it again. If it says \"Offline not available\", this browser window cannot keep an offline copy (private windows and some managed computers); use a normal window. To update or drop the copy, click \"Offline ready\" and choose \"Save again (get the newest version)\" or \"Remove the offline copy\". More in Working offline. You are offline. If the bar at the top says \"Offline ready\", everything works, saving included. If it does not and you have not saved yet in this tab, Save can fail with \"The PDF writer could not load\". Your markups are still in the tab: keep it open, get back online, and choose Save again. Things to know Large plan sets take a while to open: MarkupCraft reads every page's text to find sheet numbers. The status bar counts the sheets as it goes. Opening the same PDF twice adds its sheets twice. Close the set and open it again if that happens. Close closes every open file at once. If any have unsaved markups it asks: Cancel, Close without saving or Save copies first. Cloud saving is not available yet, and there are no desktop builds yet. Keep your PDFs with your other project files and back them up as usual. See Where your files go.","lang":"en"},{"slug":"open-a-plan-set","scope":"markupcraft","title":"Open a plan set and move between sheets","summary":"Open one PDF or many, or start with blank pages, find sheets by number or name, zoom and pan, and rename a sheet when the file gets it wrong.","section":"tasks","order":10,"keywords":["open","new","blank page","blank sheet","sketch","grid","untitled","plan set","sheets","pages","thumbnails","page labels","sheet number","title block","rename","navigate","zoom","pan","fit","search sheets"],"headings":[{"id":"open-the-set","text":"Open the set","level":2},{"id":"start-with-blank-pages","text":"Start with blank pages","level":2},{"id":"how-sheets-get-their-names","text":"How sheets get their names","level":2},{"id":"move-between-sheets","text":"Move between sheets","level":2},{"id":"zoom-and-pan","text":"Zoom and pan","level":2},{"id":"bookmarks","text":"Bookmarks","level":2},{"id":"turn-the-view","text":"Turn the view","level":2},{"id":"rename-a-sheet","text":"Rename a sheet","level":2},{"id":"take-the-pdf-to-takeoffcraft-or-bring-it-here","text":"Take the PDF to TakeoffCraft, or bring it here","level":2}],"html":"\u003Ch2 id=\"open-the-set\"\u003EOpen the set\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E in the toolbar, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003Cli\u003EIn the file picker, select every PDF of the set (\u003Cspan class=\"hp\"\u003E\u003Cspan class=\"hpv\" data-v=\"os:mac\" title=\"Mac\"\u003Ehold ⌘ and click each file\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:windows,linux\" title=\"Windows or Linux\"\u003Ehold Ctrl and click each file\u003C/span\u003E\u003C/span\u003E, or select a range with Shift), then confirm. Or drag the files from \u003Cspan class=\"hp\"\u003E\u003Cspan class=\"hpv\" data-v=\"os:mac\" title=\"Mac\"\u003EFinder\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:windows\" title=\"Windows\"\u003EFile Explorer\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:linux\" title=\"Linux\"\u003Eyour file manager\u003C/span\u003E\u003C/span\u003E onto the sheet area. &quot;Drop PDFs to open them&quot; appears while you drag.\u003C/li\u003E\u003Cli\u003EWait while the status bar says &quot;Opening &lt;file&gt;…&quot;. For big files it counts: &quot;(10 of 60 sheets)&quot;.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E list shows every page of every file, in the order you opened them, and the status bar says something like &quot;Opened 3 files (42 sheets in the set).&quot; If the files already had comments, it adds how many were read.\u003C/p\u003E\n\u003Cp\u003ETo add more files to the set later, open them the same way. They join the end of the list.\u003C/p\u003E\n\u003Ch2 id=\"start-with-blank-pages\"\u003EStart with blank pages\u003C/h2\u003E\n\u003Cp\u003ETo sketch or take notes without a drawing, make blank pages instead of opening a PDF:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ENew\u003C/span\u003E in the toolbar, or \u003Cspan class=\"hui\"\u003EStart with a blank page\u003C/span\u003E on the start screen, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command N\"\u003E⌘N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+N\u003C/span\u003E\u003C/kbd\u003E where your browser lets the page have it (the desktop app and Studio always do).\u003C/li\u003E\u003Cli\u003EPick the \u003Cspan class=\"hui\"\u003EPaper size\u003C/span\u003E: Letter, Tabloid or ANSI B, ARCH D, ARCH E, A4, A3 or A1, and \u003Cspan class=\"hui\"\u003EPortrait\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ELandscape\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EPick a \u003Cspan class=\"hui\"\u003EGrid\u003C/span\u003E: \u003Cspan class=\"hui\"\u003ENone\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDots\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ESquares\u003C/span\u003E. The grid is every 1/4 in with a heavier line each inch on inch paper, and every 5 mm with a heavier line each 10 mm on metric paper. It is printed on the page.\u003C/li\u003E\u003Cli\u003EType how many \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E you want, from 1 to 20, then choose \u003Cspan class=\"hui\"\u003ECreate\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: a new PDF named &quot;Untitled-1.pdf&quot; (then &quot;Untitled-2.pdf&quot;, and so on) opens like any other file, made here on this computer. Every tool works on it, and \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E downloads &quot;Untitled-1 (marked up).pdf&quot;. MarkupCraft remembers your choices for next time.\u003C/p\u003E\n\u003Cp\u003EThe pages have no scale: the status bar says &quot;Not calibrated&quot;. The grid is not a scale. To measure, calibrate the sheet or pick a scale first; see \u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure\" data-topic=\"markupcraft/calibrate-and-measure\"\u003ECalibrate and measure\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003ETo add a page to a blank set, open one of its sheets and choose \u003Cspan class=\"hui\"\u003EAdd a blank page\u003C/span\u003E under the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E list. The new page has the same paper and grid and goes at the end. Like every page change, it cannot be undone; see \u003Ca href=\"/tutorials/markupcraft/pages-and-printing\" data-topic=\"markupcraft/pages-and-printing\"\u003EPrint, and change the pages\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"how-sheets-get-their-names\"\u003EHow sheets get their names\u003C/h2\u003E\n\u003Cp\u003EMarkupCraft names each sheet &quot;&lt;sheet number&gt; — &lt;title&gt;&quot;, for example &quot;A-101 — Floor plan&quot;, from the first of these it finds:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EA name you typed with \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E (below).\u003C/li\u003E\u003Cli\u003EThe PDF&#039;s own page labels, when the person who made the PDF set them (for example &quot;A-101&quot;).\u003C/li\u003E\u003Cli\u003EThe title block: MarkupCraft reads the page&#039;s text and looks for something shaped like a sheet number (A-101, A1.01, M-201A, KA1-1), favoring the lower-right corner, the right-hand strip and the bottom band, and takes the largest wording near it as the title.\u003C/li\u003E\u003Cli\u003EOtherwise, the file name and page: &quot;Plans — page 3&quot;.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ETo see which one was used, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E until nothing is selected and \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E is on, then look at \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E: &quot;Read from&quot; says &quot;The page label&quot;, &quot;The title block&quot;, &quot;The file name&quot; or &quot;Typed by hand&quot;.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EScanned sheets, and PDFs whose lettering was exported as lines, have no text to read. They are named by file and page until you rename them. MarkupCraft cannot read text from images yet.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"move-between-sheets\"\u003EMove between sheets\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EClick a sheet in \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↓\"\u003Efn ↓\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Down\u003C/span\u003E\u003C/kbd\u003E for the next sheet and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↑\"\u003Efn ↑\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Up\u003C/span\u003E\u003C/kbd\u003E for the previous one, or use the arrows in the bar under the sheet.\u003C/li\u003E\u003Cli\u003EType in \u003Cspan class=\"hui\"\u003ESearch sheets\u003C/span\u003E: part of a number (&quot;A-2&quot;), a word of the title (&quot;roof&quot;), or a file name. The list narrows as you type (&quot;4 of 42&quot;). Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E to open the first match. Clear the box to see every sheet again.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EEach sheet keeps its own zoom and position until you close the set.\u003C/p\u003E\n\u003Ch2 id=\"zoom-and-pan\"\u003EZoom and pan\u003C/h2\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:mouse\"\u003E\u003Cp class=\"hv-label\"\u003EMouse\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EZoom:\u003C/strong\u003E turn the wheel over the sheet. It zooms around the pointer. Or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"+\"\u003E+\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E+\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"−\"\u003E−\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E−\u003C/span\u003E\u003C/kbd\u003E (also with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E), or use the zoom buttons. Type an exact percentage in the zoom box.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EFit:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EFit page\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 0\"\u003E⌘0\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+0\u003C/span\u003E\u003C/kbd\u003E) shows the whole sheet; \u003Cspan class=\"hui\"\u003EFit width\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 9\"\u003E⌘9\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+9\u003C/span\u003E\u003C/kbd\u003E) fills the width.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPan:\u003C/strong\u003E drag with the middle button (the wheel), or drag with the right button, or hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and drag, or choose \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E) and drag. With nothing selected, the arrow keys move the sheet too.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:mac;input:mouse\"\u003E\u003Cp class=\"hv-label\"\u003EMac, Mouse\u003C/p\u003E\n\u003Cp\u003EOn a Mac trackpad, two-finger scrolling zooms (it does not scroll the sheet). To pan, hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and drag with one finger, or switch to \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E. A pinch zooms in Chrome, Edge and Firefox.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EZoom and pan:\u003C/strong\u003E put two fingers on the sheet. Spread or pinch them to zoom around the point between them, and move them together to pan. Both happen at once.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPan with one finger:\u003C/strong\u003E choose \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E first. With any other tool, one finger draws or selects.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EFit page\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EFit width\u003C/span\u003E are in the bar under the sheet.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Cp\u003EYou can zoom out well past the whole sheet and in up to 6400%. The sheet is redrawn sharp a moment after you stop moving.\u003C/p\u003E\n\u003Ch2 id=\"bookmarks\"\u003EBookmarks\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EBookmarks\u003C/span\u003E, at the top of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E panel, shows the bookmarks (outline) of the PDF the open sheet belongs to. Choose one to go to its page. The pencil renames a bookmark and the cross removes it. \u003Cspan class=\"hui\"\u003EBuild from sheets\u003C/span\u003E makes one bookmark per sheet, named as the sheets list shows them (sheet number and title), and \u003Cspan class=\"hui\"\u003EAdd for this sheet\u003C/span\u003E adds one for the sheet you are on. Changes are part of the file&#039;s unsaved work: \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E writes them into the copy, where every PDF viewer shows them.\u003C/p\u003E\n\u003Ch2 id=\"turn-the-view\"\u003ETurn the view\u003C/h2\u003E\n\u003Cp\u003EThe two turn buttons at the right of the bar under the sheet turn the view a quarter turn either way, for a sheet drawn sideways. Only the view turns: the PDF and its markups stay as they are, and the next sheet opens the way its PDF is (each sheet remembers its own turn while the set is open). Text you add on a turned view reads upright as you see it. To turn the page itself in the saved PDF, use \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003ERotate page clockwise\u003C/span\u003E; see \u003Ca href=\"/tutorials/markupcraft/pages-and-printing\" data-topic=\"markupcraft/pages-and-printing\"\u003EPrint, and change the pages\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"rename-a-sheet\"\u003ERename a sheet\u003C/h2\u003E\n\u003Cp\u003EWhen a sheet&#039;s name is wrong or missing:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EShow the sheet.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E until nothing is selected and the \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E tool is on. \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E now shows the sheet.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EType the \u003Cspan class=\"hui\"\u003ESheet number\u003C/span\u003E and the \u003Cspan class=\"hui\"\u003ETitle\u003C/span\u003E, then choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the sheets list, the bar under the sheet and the markups list all use the new name, and &quot;Read from&quot; says &quot;Typed by hand&quot;. Renaming can be undone with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E.\u003C/p\u003E\n\u003Cp\u003ETo go back to what the file says, open \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E again, clear both boxes, and choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003EWhen you save, a typed sheet number becomes the page&#039;s label in the PDF, so other PDF viewers show &quot;A-101&quot; in their page box too. If you give any page of a file a number, every page of that file gets a label in the copy (its typed number, else its old label, else its page number). A typed title is kept for MarkupCraft but other viewers do not show it.\u003C/p\u003E\n\u003Ch2 id=\"take-the-pdf-to-takeoffcraft-or-bring-it-here\"\u003ETake the PDF to TakeoffCraft, or bring it here\u003C/h2\u003E\n\u003Cp\u003EWhen TakeoffCraft is open in the same place (the lab, Try or the online apps), the bar under the sheet has \u003Cspan class=\"hui\"\u003EOpen in TakeoffCraft\u003C/span\u003E. It opens the sheet&#039;s PDF in TakeoffCraft in a new tab, as it was opened here, so you can measure quantities on it. Your markups stay here; save them as usual.\u003C/p\u003E\n\u003Cp\u003ETakeoffCraft&#039;s \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E button does the same the other way: the PDF opens here as if you had chosen \u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E. If the browser blocks the new tab, allow pop-ups for this site and choose the button again.\u003C/p\u003E","text":"Open the set Choose Open in the toolbar, or press Ctrl+O. In the file picker, select every PDF of the set (hold ⌘ and click each file / hold Ctrl and click each file, or select a range with Shift), then confirm. Or drag the files from Finder / File Explorer / your file manager onto the sheet area. \"Drop PDFs to open them\" appears while you drag. Wait while the status bar says \"Opening \u003Cfile\u003E…\". For big files it counts: \"(10 of 60 sheets)\". Result: the Sheets list shows every page of every file, in the order you opened them, and the status bar says something like \"Opened 3 files (42 sheets in the set).\" If the files already had comments, it adds how many were read. To add more files to the set later, open them the same way. They join the end of the list. Start with blank pages To sketch or take notes without a drawing, make blank pages instead of opening a PDF: Choose New in the toolbar, or Start with a blank page on the start screen, or press Ctrl+N where your browser lets the page have it (the desktop app and Studio always do). Pick the Paper size: Letter, Tabloid or ANSI B, ARCH D, ARCH E, A4, A3 or A1, and Portrait or Landscape. Pick a Grid: None, Dots or Squares. The grid is every 1/4 in with a heavier line each inch on inch paper, and every 5 mm with a heavier line each 10 mm on metric paper. It is printed on the page. Type how many Pages you want, from 1 to 20, then choose Create. Result: a new PDF named \"Untitled-1.pdf\" (then \"Untitled-2.pdf\", and so on) opens like any other file, made here on this computer. Every tool works on it, and Save downloads \"Untitled-1 (marked up).pdf\". MarkupCraft remembers your choices for next time. The pages have no scale: the status bar says \"Not calibrated\". The grid is not a scale. To measure, calibrate the sheet or pick a scale first; see Calibrate and measure. To add a page to a blank set, open one of its sheets and choose Add a blank page under the Sheets list. The new page has the same paper and grid and goes at the end. Like every page change, it cannot be undone; see Print, and change the pages. How sheets get their names MarkupCraft names each sheet \"\u003Csheet number\u003E — \u003Ctitle\u003E\", for example \"A-101 — Floor plan\", from the first of these it finds: A name you typed with Rename sheet (below). The PDF's own page labels, when the person who made the PDF set them (for example \"A-101\"). The title block: MarkupCraft reads the page's text and looks for something shaped like a sheet number (A-101, A1.01, M-201A, KA1-1), favoring the lower-right corner, the right-hand strip and the bottom band, and takes the largest wording near it as the title. Otherwise, the file name and page: \"Plans — page 3\". To see which one was used, press Esc until nothing is selected and Select is on, then look at Properties: \"Read from\" says \"The page label\", \"The title block\", \"The file name\" or \"Typed by hand\". Scanned sheets, and PDFs whose lettering was exported as lines, have no text to read. They are named by file and page until you rename them. MarkupCraft cannot read text from images yet. Move between sheets Click a sheet in Sheets. Press Page Down for the next sheet and Page Up for the previous one, or use the arrows in the bar under the sheet. Type in Search sheets: part of a number (\"A-2\"), a word of the title (\"roof\"), or a file name. The list narrows as you type (\"4 of 42\"). Press Enter to open the first match. Clear the box to see every sheet again. Each sheet keeps its own zoom and position until you close the set. Zoom and pan Zoom: turn the wheel over the sheet. It zooms around the pointer. Or press + and − (also with Ctrl), or use the zoom buttons. Type an exact percentage in the zoom box. Fit: Fit page (Ctrl+0) shows the whole sheet; Fit width (Ctrl+9) fills the width. Pan: drag with the middle button (the wheel), or drag with the right button, or hold Space and drag, or choose Pan (H) and drag. With nothing selected, the arrow keys move the sheet too. On a Mac trackpad, two-finger scrolling zooms (it does not scroll the sheet). To pan, hold Space and drag with one finger, or switch to Pan with H. A pinch zooms in Chrome, Edge and Firefox. Zoom and pan: put two fingers on the sheet. Spread or pinch them to zoom around the point between them, and move them together to pan. Both happen at once. Pan with one finger: choose Pan first. With any other tool, one finger draws or selects. Fit page and Fit width are in the bar under the sheet. You can zoom out well past the whole sheet and in up to 6400%. The sheet is redrawn sharp a moment after you stop moving. Bookmarks Bookmarks, at the top of the Sheets panel, shows the bookmarks (outline) of the PDF the open sheet belongs to. Choose one to go to its page. The pencil renames a bookmark and the cross removes it. Build from sheets makes one bookmark per sheet, named as the sheets list shows them (sheet number and title), and Add for this sheet adds one for the sheet you are on. Changes are part of the file's unsaved work: Save writes them into the copy, where every PDF viewer shows them. Turn the view The two turn buttons at the right of the bar under the sheet turn the view a quarter turn either way, for a sheet drawn sideways. Only the view turns: the PDF and its markups stay as they are, and the next sheet opens the way its PDF is (each sheet remembers its own turn while the set is open). Text you add on a turned view reads upright as you see it. To turn the page itself in the saved PDF, use Pages, then Rotate page clockwise; see Print, and change the pages. Rename a sheet When a sheet's name is wrong or missing: Show the sheet. Press Esc until nothing is selected and the Select tool is on. Properties now shows the sheet. Choose Rename sheet. Type the Sheet number and the Title, then choose Save. Result: the sheets list, the bar under the sheet and the markups list all use the new name, and \"Read from\" says \"Typed by hand\". Renaming can be undone with Ctrl+Z. To go back to what the file says, open Rename sheet again, clear both boxes, and choose Save. When you save, a typed sheet number becomes the page's label in the PDF, so other PDF viewers show \"A-101\" in their page box too. If you give any page of a file a number, every page of that file gets a label in the copy (its typed number, else its old label, else its page number). A typed title is kept for MarkupCraft but other viewers do not show it. Take the PDF to TakeoffCraft, or bring it here When TakeoffCraft is open in the same place (the lab, Try or the online apps), the bar under the sheet has Open in TakeoffCraft. It opens the sheet's PDF in TakeoffCraft in a new tab, as it was opened here, so you can measure quantities on it. Your markups stay here; save them as usual. TakeoffCraft's MarkupCraft button does the same the other way: the PDF opens here as if you had chosen Open. If the browser blocks the new tab, allow pop-ups for this site and choose the button again.","lang":"en"},{"slug":"set-your-name","scope":"markupcraft","title":"Set your author name","summary":"Give the name that goes on every markup, reply and stamp, or use your account's name, and know where it is kept.","section":"tasks","order":20,"keywords":["author","name","account name","signed in","user name","initials","identity","who made it","stamp name","reviewer"],"headings":[{"id":"signed-in-your-account-s-name","text":"Signed in: your account's name","level":2},{"id":"the-first-time-signed-out","text":"The first time (signed out)","level":2},{"id":"change-it","text":"Change it","level":2},{"id":"where-the-name-is-kept","text":"Where the name is kept","level":2}],"html":"\u003Cp\u003EEvery markup records who made it and when. Stamps print the name (&quot;By Ana Ruiz, Oct 10, 2026&quot;), replies show it, the markups list can filter by it, and other PDF viewers show it as the comment&#039;s author.\u003C/p\u003E\n\u003Ch2 id=\"signed-in-your-account-s-name\"\u003ESigned in: your account&#039;s name\u003C/h2\u003E\n\u003Cp\u003EIf you are signed in to your CadCraft account, MarkupCraft uses your account&#039;s name and never asks. Markups, replies, stamps and the status bar show it. In \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EYour name\u003C/span\u003E it reads &quot;From your account (your name)&quot;.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003ETo use another name, choose \u003Cspan class=\"hui\"\u003EUse another name\u003C/span\u003E and type it. A name you type wins from then on.\u003C/li\u003E\u003Cli\u003ETo go back to your account&#039;s name, choose \u003Cspan class=\"hui\"\u003EUse my account name\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EOnly the name is used, never your email address. If you change your name on the site, MarkupCraft shows it the next time it opens.\u003C/p\u003E\n\u003Ch2 id=\"the-first-time-signed-out\"\u003EThe first time (signed out)\u003C/h2\u003E\n\u003Cp\u003EWhen you are not signed in, the first time you pick a drawing tool, a box called &quot;Your name on markups&quot; opens.\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EType your name the way you want reviewers to see it (up to 80 characters).\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: your name appears at the right end of the status bar, and every new markup carries it.\u003C/p\u003E\n\u003Cp\u003EIf you choose \u003Cspan class=\"hui\"\u003ENot now\u003C/span\u003E, markups are made with no author (&quot;Not recorded&quot; in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E) and stamps show only the date. MarkupCraft asks again the next time you open it.\u003C/p\u003E\n\u003Ch2 id=\"change-it\"\u003EChange it\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EClick your name (or &quot;Set your name&quot;) at the right end of the status bar.\u003C/li\u003E\u003Cli\u003EType the new name and choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EOr open \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E), stay on the \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E tab and type it under \u003Cspan class=\"hui\"\u003EYour name\u003C/span\u003E. See \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003EMarkupCraft settings\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EOnly markups you make from now on get the new name. Markups already drawn keep the name they were made with; there is no way to change the author of an existing markup.\u003C/p\u003E\n\u003Ch2 id=\"where-the-name-is-kept\"\u003EWhere the name is kept\u003C/h2\u003E\n\u003Cp\u003EYour name is stored \u003Cstrong\u003Ein this browser, on this computer\u003C/strong\u003E (the browser&#039;s local storage for this website). That means:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EAnother browser on the same computer, or the same browser on another computer, asks again.\u003C/li\u003E\u003Cli\u003EA private or incognito window asks every time, and forgets when it closes.\u003C/li\u003E\u003Cli\u003EClearing this site&#039;s data (cookies and site data) in the browser&#039;s settings forgets it.\u003C/li\u003E\u003Cli\u003ENothing is sent anywhere. The name only leaves this computer inside the PDFs you save.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003ESafari may clear a website&#039;s stored data if you have not visited it for a while. If MarkupCraft asks for your name again, that is why.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cp\u003EIf several people share one computer and one browser login, each should check the name in the status bar before starting, since it is shared.\u003C/p\u003E\n\u003Cp\u003ESee also \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/p\u003E","text":"Every markup records who made it and when. Stamps print the name (\"By Ana Ruiz, Oct 10, 2026\"), replies show it, the markups list can filter by it, and other PDF viewers show it as the comment's author. Signed in: your account's name If you are signed in to your CadCraft account, MarkupCraft uses your account's name and never asks. Markups, replies, stamps and the status bar show it. In Settings › MarkupCraft › Your name it reads \"From your account (your name)\". To use another name, choose Use another name and type it. A name you type wins from then on. To go back to your account's name, choose Use my account name. Only the name is used, never your email address. If you change your name on the site, MarkupCraft shows it the next time it opens. The first time (signed out) When you are not signed in, the first time you pick a drawing tool, a box called \"Your name on markups\" opens. Type your name the way you want reviewers to see it (up to 80 characters). Choose Save. Result: your name appears at the right end of the status bar, and every new markup carries it. If you choose Not now, markups are made with no author (\"Not recorded\" in Properties) and stamps show only the date. MarkupCraft asks again the next time you open it. Change it Click your name (or \"Set your name\") at the right end of the status bar. Type the new name and choose Save. Or open Settings (Ctrl+,), stay on the MarkupCraft tab and type it under Your name. See MarkupCraft settings. Only markups you make from now on get the new name. Markups already drawn keep the name they were made with; there is no way to change the author of an existing markup. Where the name is kept Your name is stored in this browser, on this computer (the browser's local storage for this website). That means: Another browser on the same computer, or the same browser on another computer, asks again. A private or incognito window asks every time, and forgets when it closes. Clearing this site's data (cookies and site data) in the browser's settings forgets it. Nothing is sent anywhere. The name only leaves this computer inside the PDFs you save. Safari may clear a website's stored data if you have not visited it for a while. If MarkupCraft asks for your name again, that is why. If several people share one computer and one browser login, each should check the name in the status bar before starting, since it is shared. See also What stays in this browser.","lang":"en"},{"slug":"mark-up-a-sheet","scope":"markupcraft","title":"Mark up a sheet","summary":"Draw revision clouds, callouts, text boxes, arrows, shapes, pen strokes and highlights, and set their color and line before or after.","section":"tasks","order":30,"keywords":["markup","redline","cloud","revision cloud","callout","leader","text box","arrow","line","rectangle","ellipse","circle","polyline","polygon","pen","freehand","ink","highlighter","color","line width"],"headings":[{"id":"revision-clouds","text":"Revision clouds","level":2},{"id":"callouts","text":"Callouts","level":2},{"id":"text-boxes","text":"Text boxes","level":2},{"id":"arrows-and-lines","text":"Arrows and lines","level":2},{"id":"rectangles-ellipses-polylines-and-polygons","text":"Rectangles, ellipses, polylines and polygons","level":2},{"id":"pen-and-highlighter","text":"Pen and highlighter","level":2},{"id":"color-line-and-fill","text":"Color, line and fill","level":2},{"id":"subject-and-comment","text":"Subject and comment","level":2},{"id":"next","text":"Next","level":2}],"html":"\u003Cp\u003EEvery tool works the same way: pick it, draw on the sheet, and the new markup is selected so you can see it in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. The tool stays on for the next one. The status bar always says what the tool expects next.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Cp\u003EOn a touch screen, use one finger to draw. A second finger cancels what the first one started and pinches or pans instead, so you never leave a mark by accident while zooming. More in \u003Ca href=\"/tutorials/markupcraft/review-on-a-tablet\" data-topic=\"markupcraft/review-on-a-tablet\"\u003EReview on an iPad or touch screen\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"revision-clouds\"\u003ERevision clouds\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003EBox cloud:\u003C/strong\u003E choose \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E) and drag a box. Hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E to make it square.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EFree cloud\u003C/strong\u003E around an odd shape:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift C\"\u003E⇧C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+C\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick each corner of the area.\u003C/li\u003E\u003Cli\u003EFinish with a double-click, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or a right-click. On touch, double-tap.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EWhile you click points, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E removes the last point and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E cancels the whole shape. Hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E to keep the next side at a multiple of 45°. A free cloud needs at least three points.\u003C/p\u003E\n\u003Cp\u003EThe scallops always bulge outward and their size follows the line width: a thicker line gives bigger arcs.\u003C/p\u003E\n\u003Ch2 id=\"callouts\"\u003ECallouts\u003C/h2\u003E\n\u003Cp\u003EA callout is a text box with a leader pointing at something.\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EPress on the point you want to call out and drag to where the text should go. Let go. If you just click without dragging, the box is placed up and to the right of the point.\u003C/li\u003E\u003Cli\u003EType the text. The box grows downward as the lines wrap.\u003C/li\u003E\u003Cli\u003EClick anywhere outside the box, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E, to finish. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E throws the callout away.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EIf you finish without typing anything, no callout is added (&quot;Nothing typed, so no callout was added.&quot;).\u003C/p\u003E\n\u003Cp\u003EAfter it is drawn, select it to move the box, drag the leader&#039;s tip or its bend (the two diamond handles), or resize the box.\u003C/p\u003E\n\u003Ch2 id=\"text-boxes\"\u003EText boxes\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EText\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"T\"\u003ET\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ET\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick where the text starts (you get a box of a sensible width), or drag a box of the size you want.\u003C/li\u003E\u003Cli\u003EType, then click outside or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EText has no border by default. To give it one, raise \u003Cspan class=\"hui\"\u003ELine width\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. To give it a background, tick \u003Cspan class=\"hui\"\u003EFill\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003ETo change the words later: with \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E on, double-click the text, or select it and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EEdit on the sheet\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. You can also edit it in the \u003Cspan class=\"hui\"\u003EText\u003C/span\u003E box in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"arrows-and-lines\"\u003EArrows and lines\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"A\"\u003EA\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EA\u003C/span\u003E\u003C/kbd\u003E) or \u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"L\"\u003EL\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EL\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EDrag from the start to the end. Or click the start, let go, and click the end.\u003C/li\u003E\u003Cli\u003EHold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E to keep it at a multiple of 45°.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EThe arrowhead is at the end where you finished.\u003C/p\u003E\n\u003Ch2 id=\"rectangles-ellipses-polylines-and-polygons\"\u003ERectangles, ellipses, polylines and polygons\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"R\"\u003ER\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ER\u003C/span\u003E\u003C/kbd\u003E) and \u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"E\"\u003EE\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EE\u003C/span\u003E\u003C/kbd\u003E): drag a box. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E makes a square or a circle. A click without dragging draws nothing and the status bar says to drag.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Y\"\u003EY\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EY\u003C/span\u003E\u003C/kbd\u003E) and \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"G\"\u003EG\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EG\u003C/span\u003E\u003C/kbd\u003E): click points; finish with a double-click, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or a right-click (double-tap on touch). \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E removes the last point. A polygon closes itself and needs three points; a polyline needs two.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"pen-and-highlighter\"\u003EPen and highlighter\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPen\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"P\"\u003EP\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EP\u003C/span\u003E\u003C/kbd\u003E): drag to draw freehand. The stroke is smoothed a little when you let go.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"I\"\u003EI\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EI\u003C/span\u003E\u003C/kbd\u003E): the same, with a wide, see-through yellow stroke that tints the drawing under it instead of covering it.\u003C/li\u003E\u003Cli\u003EHold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E while you draw to get one straight stroke from where you started.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe highlighter is a freehand stroke. It does not snap to text in the PDF.\u003C/p\u003E\n\u003Ch2 id=\"color-line-and-fill\"\u003EColor, line and fill\u003C/h2\u003E\n\u003Cp\u003ETwo ways:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EBefore drawing:\u003C/strong\u003E pick the tool. With nothing selected, \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows &quot;&lt;tool&gt; tool&quot; settings: \u003Cspan class=\"hui\"\u003EColor\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELine width\u003C/span\u003E (in points), \u003Cspan class=\"hui\"\u003EFill\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EFill opacity\u003C/span\u003E for closed shapes, \u003Cspan class=\"hui\"\u003EOpacity\u003C/span\u003E, and \u003Cspan class=\"hui\"\u003EText size\u003C/span\u003E for text. Every new markup of that kind uses them, and MarkupCraft remembers them in this browser.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EAfter drawing:\u003C/strong\u003E select one or more markups and change the same controls under &quot;Style&quot;. With several selected, the change applies to all of them in one step.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe defaults: red markups, a yellow highlighter, blue measurements, orange counts, and stamps colored by meaning.\u003C/p\u003E\n\u003Cp\u003ESaved looks you reuse every day belong in the tool chest: see \u003Ca href=\"/tutorials/markupcraft/tool-chest\" data-topic=\"markupcraft/tool-chest\"\u003EThe tool chest\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"subject-and-comment\"\u003ESubject and comment\u003C/h2\u003E\n\u003Cp\u003EEvery markup also has a \u003Cspan class=\"hui\"\u003ESubject\u003C/span\u003E (a short label such as &quot;Cloud&quot; or &quot;RFI&quot;, shown in the markups list and in other PDF viewers) and a \u003Cspan class=\"hui\"\u003EComment\u003C/span\u003E (longer notes). Fill them in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. For a conversation about a markup, use replies: see \u003Ca href=\"/tutorials/markupcraft/statuses-and-replies\" data-topic=\"markupcraft/statuses-and-replies\"\u003EStatuses and replies\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"next\"\u003ENext\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/select-and-edit\" data-topic=\"markupcraft/select-and-edit\"\u003ESelect, move and change markups\u003C/a\u003E\u003C/li\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/stamps-and-notes\" data-topic=\"markupcraft/stamps-and-notes\"\u003EStamps and notes\u003C/a\u003E\u003C/li\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/markupcraft/markup-types\" data-topic=\"markupcraft/markup-types\"\u003EEvery markup type\u003C/a\u003E\u003C/li\u003E\u003C/ul\u003E","text":"Every tool works the same way: pick it, draw on the sheet, and the new markup is selected so you can see it in Properties. The tool stays on for the next one. The status bar always says what the tool expects next. On a touch screen, use one finger to draw. A second finger cancels what the first one started and pinches or pans instead, so you never leave a mark by accident while zooming. More in Review on an iPad or touch screen. Revision clouds Box cloud: choose Cloud (C) and drag a box. Hold Shift to make it square. Free cloud around an odd shape: Choose Free cloud (Shift+C). Click each corner of the area. Finish with a double-click, Enter or a right-click. On touch, double-tap. While you click points, Backspace removes the last point and Esc cancels the whole shape. Hold Shift to keep the next side at a multiple of 45°. A free cloud needs at least three points. The scallops always bulge outward and their size follows the line width: a thicker line gives bigger arcs. Callouts A callout is a text box with a leader pointing at something. Choose Callout (K). Press on the point you want to call out and drag to where the text should go. Let go. If you just click without dragging, the box is placed up and to the right of the point. Type the text. The box grows downward as the lines wrap. Click anywhere outside the box, or press Ctrl+Enter, to finish. Esc throws the callout away. If you finish without typing anything, no callout is added (\"Nothing typed, so no callout was added.\"). After it is drawn, select it to move the box, drag the leader's tip or its bend (the two diamond handles), or resize the box. Text boxes Choose Text (T). Click where the text starts (you get a box of a sensible width), or drag a box of the size you want. Type, then click outside or press Ctrl+Enter. Text has no border by default. To give it one, raise Line width in Properties. To give it a background, tick Fill. To change the words later: with Select on, double-click the text, or select it and press Enter, or choose Edit on the sheet in Properties. You can also edit it in the Text box in Properties. Arrows and lines Choose Arrow (A) or Line (L). Drag from the start to the end. Or click the start, let go, and click the end. Hold Shift to keep it at a multiple of 45°. The arrowhead is at the end where you finished. Rectangles, ellipses, polylines and polygons Rectangle (R) and Ellipse (E): drag a box. Shift makes a square or a circle. A click without dragging draws nothing and the status bar says to drag. Polyline (Y) and Polygon (G): click points; finish with a double-click, Enter or a right-click (double-tap on touch). Backspace removes the last point. A polygon closes itself and needs three points; a polyline needs two. Pen and highlighter Pen (P): drag to draw freehand. The stroke is smoothed a little when you let go. Highlight (I): the same, with a wide, see-through yellow stroke that tints the drawing under it instead of covering it. Hold Shift while you draw to get one straight stroke from where you started. The highlighter is a freehand stroke. It does not snap to text in the PDF. Color, line and fill Two ways: Before drawing: pick the tool. With nothing selected, Properties shows \"\u003Ctool\u003E tool\" settings: Color, Line width (in points), Fill and Fill opacity for closed shapes, Opacity, and Text size for text. Every new markup of that kind uses them, and MarkupCraft remembers them in this browser. After drawing: select one or more markups and change the same controls under \"Style\". With several selected, the change applies to all of them in one step. The defaults: red markups, a yellow highlighter, blue measurements, orange counts, and stamps colored by meaning. Saved looks you reuse every day belong in the tool chest: see The tool chest. Subject and comment Every markup also has a Subject (a short label such as \"Cloud\" or \"RFI\", shown in the markups list and in other PDF viewers) and a Comment (longer notes). Fill them in Properties. For a conversation about a markup, use replies: see Statuses and replies. Next Select, move and change markups Stamps and notes Every markup type","lang":"en"},{"slug":"select-and-edit","scope":"markupcraft","title":"Select, move and change markups","summary":"Pick markups by clicking or with a window, move, resize, nudge, cut, copy, paste, paste in place, duplicate, delete and undo.","section":"tasks","order":40,"keywords":["select","selection","select all","select none","window","crossing","move","resize","grips","handles","nudge","cut","copy","paste","paste in place","duplicate","clipboard","another tab","delete","undo","redo","edit"],"headings":[{"id":"pick-markups","text":"Pick markups","level":2},{"id":"move-and-resize","text":"Move and resize","level":2},{"id":"change-what-it-says-or-how-it-looks","text":"Change what it says or how it looks","level":2},{"id":"copy-paste-and-duplicate","text":"Copy, paste and duplicate","level":2},{"id":"delete","text":"Delete","level":2},{"id":"undo-and-redo","text":"Undo and redo","level":2},{"id":"copy-markups-to-other-sheets","text":"Copy markups to other sheets","level":2}],"html":"\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"V\"\u003EV\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EV\u003C/span\u003E\u003C/kbd\u003E) first. Pressing \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E also gets you there: the first press clears the selection, the next one switches back to \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"pick-markups\"\u003EPick markups\u003C/h2\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:mouse\"\u003E\u003Cp class=\"hv-label\"\u003EMouse\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EOne markup:\u003C/strong\u003E click it. A dashed box and handles appear, and \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows it.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EAdd or remove one:\u003C/strong\u003E hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E and click.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EFully inside a window:\u003C/strong\u003E drag from left to right on an empty part of the sheet. Only markups entirely inside the box are picked (solid outline).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ETouching a window:\u003C/strong\u003E drag from right to left. Anything the box touches is picked (green, dashed outline).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EEverything on this sheet:\u003C/strong\u003E \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command A\"\u003E⌘A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+A\u003C/span\u003E\u003C/kbd\u003E, or \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E then \u003Cspan class=\"hui\"\u003ESelect all\u003C/span\u003E in the toolbar&#039;s \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E group.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ENothing:\u003C/strong\u003E click an empty spot, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E, or \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E then \u003Cspan class=\"hui\"\u003ESelect none\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EOne markup:\u003C/strong\u003E tap it.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESeveral:\u003C/strong\u003E drag one finger across an empty part of the sheet to draw a window. Left to right picks what is fully inside; right to left picks what it touches.\u003C/li\u003E\u003Cli\u003ETapping with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E held only works with a keyboard attached. Without one, use a window.\u003C/li\u003E\u003Cli\u003EOne finger never pans in \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E; use two fingers, or the \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E tool.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Cp\u003ERead-only comments that came with the file show a gray dashed box and no handles. They can be selected and replied to, not changed.\u003C/p\u003E\n\u003Ch2 id=\"move-and-resize\"\u003EMove and resize\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EMove:\u003C/strong\u003E drag a selected markup. Hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E to move only along multiples of 45°. Several selected markups move together.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EResize:\u003C/strong\u003E with one markup selected, drag a handle. Square handles resize the box (hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E to keep its proportions); round handles move one corner point of a line, polyline, polygon, cloud or measurement (hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E for 45°); diamond handles move a callout&#039;s tip and bend. Pen strokes scale from their box.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ENudge:\u003C/strong\u003E press the arrow keys to move the selection one screen pixel; hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E for ten. Each press is one undo step.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"change-what-it-says-or-how-it-looks\"\u003EChange what it says or how it looks\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EText, callouts and notes:\u003C/strong\u003E double-click the markup, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EEdit on the sheet\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. Type, then click outside or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E cancels the edit.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EStamps:\u003C/strong\u003E pick a different stamp in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E (double-click opens \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E for you).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EStyle:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EColor\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELine width\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFill\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EOpacity\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EText size\u003C/span\u003E under &quot;Style&quot; in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. With several selected, \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows the kinds you picked and changes them all at once.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"copy-paste-and-duplicate\"\u003ECopy, paste and duplicate\u003C/h2\u003E\n\u003Cp\u003EThe toolbar&#039;s \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E group has \u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E; its \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E menu has all of these, each with its key.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ECommand\u003C/th\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECut\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command X\"\u003E⌘X\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+X\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECopies the selected markups and deletes them\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECopies the selected markups\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPuts a copy on the sheet you are on (where, below)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPaste in place\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command V\"\u003E⇧⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+V\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPuts the copy at exactly the spot it was copied from: on the same sheet, on top of the original; on another sheet, at the same place on the paper\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EDuplicate\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command D\"\u003E⌘D\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+D\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EMakes a copy of the selection a little down and to the right, without touching what you copied before\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003E\u003Cstrong\u003EWhere Paste puts the copy:\u003C/strong\u003E\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E with the pointer on the sheet puts the copy centered where the pointer is. Move the pointer, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E again, and you place another.\u003C/li\u003E\u003Cli\u003EThe \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E button (the pointer is on the toolbar then), or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E with the pointer off the sheet, puts it a little down and to the right of the original. Each paste of the same copy steps a little further, so copies never hide one another. On another sheet the first paste lands where the original was on its sheet. If that spot is out of view, the copy lands in the middle of the view.\u003C/li\u003E\u003Cli\u003ETo make \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E always paste beside the original, choose \u003Cspan class=\"hui\"\u003EBeside the copy\u003C/span\u003E under \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E in \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003EMarkupCraft settings\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe pasted markups are selected, so you can drag them straight away. Each cut, paste or duplicate is one undo step: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes the whole paste away.\u003C/p\u003E\n\u003Cp\u003EPasted copies are new markups: they get your name, today&#039;s date, the status Open, no punch number and an empty thread. Their kind, shape, style, text and comment come along. Read-only comments that came with the file cannot be copied or cut.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EBetween tabs:\u003C/strong\u003E what you copy is also kept in this browser, so another MarkupCraft tab in the same browser can paste it. Copying markups does not use the computer&#039;s clipboard: you cannot paste them into another program, and text you copied elsewhere does not paste as a markup.\u003C/p\u003E\n\u003Ch2 id=\"delete\"\u003EDelete\u003C/h2\u003E\n\u003Cp\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E, choose \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E then \u003Cspan class=\"hui\"\u003EDelete\u003C/span\u003E in the toolbar, or \u003Cspan class=\"hui\"\u003EDelete\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. The status bar says how many were deleted. Read-only comments from the file are never deleted (&quot;kept as in the file&quot;).\u003C/p\u003E\n\u003Ch2 id=\"undo-and-redo\"\u003EUndo and redo\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E undoes, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Y\"\u003E⌘Y\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Y\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command Z\"\u003E⇧⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+Z\u003C/span\u003E\u003C/kbd\u003E redoes. The toolbar has \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ERedo\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EThe status bar says what was undone (&quot;Undid move markup.&quot;).\u003C/li\u003E\u003Cli\u003EUndo covers every change to markups, statuses, replies, punch items, sheet scales and sheet names, up to 500 steps.\u003C/li\u003E\u003Cli\u003EHistory is cleared when you close the set.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"copy-markups-to-other-sheets\"\u003ECopy markups to other sheets\u003C/h2\u003E\n\u003Cp\u003ETo put the same stamp, note or cloud on several sheets, select it (or several markups) and choose \u003Cspan class=\"hui\"\u003ECopy to other sheets…\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. Tick the sheets, or \u003Cspan class=\"hui\"\u003EAll sheets\u003C/span\u003E, and choose \u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E. Each sheet gets a copy in the same place on the page, signed with your name. One \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E removes them all.\u003C/p\u003E","text":"Choose Select (V) first. Pressing Esc also gets you there: the first press clears the selection, the next one switches back to Select. Pick markups One markup: click it. A dashed box and handles appear, and Properties shows it. Add or remove one: hold Shift and click. Fully inside a window: drag from left to right on an empty part of the sheet. Only markups entirely inside the box are picked (solid outline). Touching a window: drag from right to left. Anything the box touches is picked (green, dashed outline). Everything on this sheet: Ctrl+A, or More then Select all in the toolbar's Edit group. Nothing: click an empty spot, press Esc, or More then Select none. One markup: tap it. Several: drag one finger across an empty part of the sheet to draw a window. Left to right picks what is fully inside; right to left picks what it touches. Tapping with Shift held only works with a keyboard attached. Without one, use a window. One finger never pans in Select; use two fingers, or the Pan tool. Read-only comments that came with the file show a gray dashed box and no handles. They can be selected and replied to, not changed. Move and resize Move: drag a selected markup. Hold Shift to move only along multiples of 45°. Several selected markups move together. Resize: with one markup selected, drag a handle. Square handles resize the box (hold Shift to keep its proportions); round handles move one corner point of a line, polyline, polygon, cloud or measurement (hold Shift for 45°); diamond handles move a callout's tip and bend. Pen strokes scale from their box. Nudge: press the arrow keys to move the selection one screen pixel; hold Shift for ten. Each press is one undo step. Change what it says or how it looks Text, callouts and notes: double-click the markup, or press Enter, or choose Edit on the sheet in Properties. Type, then click outside or press Ctrl+Enter. Esc cancels the edit. Stamps: pick a different stamp in Properties (double-click opens Properties for you). Style: Color, Line width, Fill, Opacity and Text size under \"Style\" in Properties. With several selected, Properties shows the kinds you picked and changes them all at once. Copy, paste and duplicate The toolbar's Edit group has Copy and Paste; its More menu has all of these, each with its key. Command Key What it does Cut Ctrl+X Copies the selected markups and deletes them Copy Ctrl+C Copies the selected markups Paste Ctrl+V Puts a copy on the sheet you are on (where, below) Paste in place Ctrl+Shift+V Puts the copy at exactly the spot it was copied from: on the same sheet, on top of the original; on another sheet, at the same place on the paper Duplicate Ctrl+D Makes a copy of the selection a little down and to the right, without touching what you copied before Where Paste puts the copy: Ctrl+V with the pointer on the sheet puts the copy centered where the pointer is. Move the pointer, press Ctrl+V again, and you place another. The Paste button (the pointer is on the toolbar then), or Ctrl+V with the pointer off the sheet, puts it a little down and to the right of the original. Each paste of the same copy steps a little further, so copies never hide one another. On another sheet the first paste lands where the original was on its sheet. If that spot is out of view, the copy lands in the middle of the view. To make Ctrl+V always paste beside the original, choose Beside the copy under Paste in MarkupCraft settings. The pasted markups are selected, so you can drag them straight away. Each cut, paste or duplicate is one undo step: Ctrl+Z takes the whole paste away. Pasted copies are new markups: they get your name, today's date, the status Open, no punch number and an empty thread. Their kind, shape, style, text and comment come along. Read-only comments that came with the file cannot be copied or cut. Between tabs: what you copy is also kept in this browser, so another MarkupCraft tab in the same browser can paste it. Copying markups does not use the computer's clipboard: you cannot paste them into another program, and text you copied elsewhere does not paste as a markup. Delete Press Delete or Backspace, choose More then Delete in the toolbar, or Delete in Properties. The status bar says how many were deleted. Read-only comments from the file are never deleted (\"kept as in the file\"). Undo and redo Ctrl+Z undoes, Ctrl+Y or Ctrl+Shift+Z redoes. The toolbar has Undo and Redo. The status bar says what was undone (\"Undid move markup.\"). Undo covers every change to markups, statuses, replies, punch items, sheet scales and sheet names, up to 500 steps. History is cleared when you close the set. Copy markups to other sheets To put the same stamp, note or cloud on several sheets, select it (or several markups) and choose Copy to other sheets… in Properties. Tick the sheets, or All sheets, and choose Copy. Each sheet gets a copy in the same place on the page, signed with your name. One Ctrl+Z removes them all.","lang":"en"},{"slug":"stamps-and-notes","scope":"markupcraft","title":"Stamps and sticky notes","summary":"Stamp a sheet Approved, Revise and resubmit or your own wording, and leave sticky notes that open as pop-up comments.","section":"tasks","order":50,"keywords":["stamp","picture","image","paste picture","screenshot","clipboard","logo","photo stamp","signature","sign","approved","approved as noted","revise and resubmit","rejected","reviewed","void","custom stamp","sticky note","note","comment","pop-up"],"headings":[{"id":"stamp-a-sheet","text":"Stamp a sheet","level":2},{"id":"change-a-stamp-later","text":"Change a stamp later","level":3},{"id":"stamps-you-use-often","text":"Stamps you use often","level":3},{"id":"stamp-a-picture-or-your-signature","text":"Stamp a picture or your signature","level":2},{"id":"paste-a-picture-from-the-clipboard","text":"Paste a picture from the clipboard","level":2},{"id":"sticky-notes","text":"Sticky notes","level":2}],"html":"\u003Ch2 id=\"stamp-a-sheet\"\u003EStamp a sheet\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"S\"\u003ES\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ES\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E on the right, pick the stamp under \u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E:\u003Cul\u003E\u003Cli\u003EApproved\u003C/li\u003E\u003Cli\u003EApproved as noted\u003C/li\u003E\u003Cli\u003ERevise and resubmit\u003C/li\u003E\u003Cli\u003ERejected\u003C/li\u003E\u003Cli\u003EReviewed\u003C/li\u003E\u003Cli\u003EVoid\u003C/li\u003E\u003Cli\u003ECustom text… (type up to 60 characters in the box that appears, then press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or click elsewhere)\u003C/li\u003E\u003C/ul\u003E\u003C/li\u003E\u003Cli\u003EClick on the sheet where the stamp goes. Or drag a box to choose its size.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: a framed stamp in capitals with a second line &quot;By &lt;your name&gt;, &lt;date&gt;&quot;. A clicked stamp is sized for the screen at your zoom, kept between half an inch and an inch and a quarter tall on the printed sheet.\u003C/p\u003E\n\u003Cp\u003EThe stamp you picked stays chosen for the next one, also after you reopen MarkupCraft in this browser.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EColors follow the meaning:\u003C/strong\u003E the Approved stamps are green, Revise and resubmit orange, Rejected and Void red, Reviewed blue, and custom stamps purple. If you choose another color in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, that color is kept.\u003C/p\u003E\n\u003Ch3 id=\"change-a-stamp-later\"\u003EChange a stamp later\u003C/h3\u003E\n\u003Cp\u003ESelect it and pick another stamp in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. If it still had its automatic color, the color changes with the meaning.\u003C/p\u003E\n\u003Cp\u003EThe name and date on the stamp are the stamp&#039;s author and the day it was made. They do not change when you edit it, and a stamp&#039;s author cannot be changed. To stamp in someone else&#039;s name, they set their name and stamp it themselves.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EThe date on a stamp is the date in Coordinated Universal Time (UTC). Late in the evening in the Americas, or early in the morning in Asia and Australia, it can show the next or the previous day compared with your clock. The created time in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E is in your own time zone.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch3 id=\"stamps-you-use-often\"\u003EStamps you use often\u003C/h3\u003E\n\u003Cp\u003EThe tool chest comes with an &quot;Approved as noted&quot; stamp tool, and you can save any stamp (its wording and color) as a tool of its own. See \u003Ca href=\"/tutorials/markupcraft/tool-chest\" data-topic=\"markupcraft/tool-chest\"\u003EThe tool chest\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EImage stamps, signature stamps and stamps with filled-in fields (date received, project number) are not built yet.\u003C/p\u003E\n\u003Ch2 id=\"stamp-a-picture-or-your-signature\"\u003EStamp a picture or your signature\u003C/h2\u003E\n\u003Cp\u003EThe stamp list in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E ends with two more choices:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPicture…\u003C/span\u003E asks for a PNG or JPEG on this computer, such as a company seal or a logo. Large pictures are scaled down to 1600 pixels on their longer side.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EMy signature…\u003C/span\u003E opens a signature box: sign with a mouse, a pen or a finger, and choose \u003Cspan class=\"hui\"\u003EUse this signature\u003C/span\u003E. \u003Cspan class=\"hui\"\u003EClear\u003C/span\u003E starts again.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThen click the sheet to place it (a picture 3 in wide, a signature 2 in wide), or drag a box to fit it inside; the proportions are kept. Resize it with its handles like any markup (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E keeps the proportions).\u003C/p\u003E\n\u003Cp\u003EThe last picture and your signature are kept in this browser, so they are ready next time; \u003Cspan class=\"hui\"\u003EChoose another picture…\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ESign again…\u003C/span\u003E replace them. See \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EIn the saved PDF a picture is a stamp comment showing the image, so any PDF viewer shows and prints it. A signature drawn here is a picture of your signature, not a certified digital signature.\u003C/p\u003E\n\u003Ch2 id=\"paste-a-picture-from-the-clipboard\"\u003EPaste a picture from the clipboard\u003C/h2\u003E\n\u003Cp\u003ECopy a picture in another program, or take a screenshot to the clipboard, then press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E over the sheet. It lands where the pointer is, at most 3 in wide or tall with its proportions kept, as a picture markup you can move and resize. In the saved PDF it is a stamp comment showing the image, like the pictures above.\u003C/p\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EPaste a picture\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E group does the same from the menu; the browser may ask first. When the clipboard holds no picture, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E pastes copied markups as before.\u003C/p\u003E\n\u003Ch2 id=\"sticky-notes\"\u003ESticky notes\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick where the note goes. A small note icon appears with a box beside it.\u003C/li\u003E\u003Cli\u003EType the note. Click outside or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E to keep it; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E throws it away.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EUnlike text and callouts, a note is kept even if you type nothing, so you can place the icon now and write later.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EThe note&#039;s words are its \u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E field in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. Double-click the icon (or select it and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E) to edit them on the sheet.\u003C/li\u003E\u003Cli\u003EOn the sheet you see only the icon. Other PDF viewers show a standard sticky note that opens to the text when clicked.\u003C/li\u003E\u003Cli\u003EChange the icon&#039;s color with \u003Cspan class=\"hui\"\u003EColor\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EFor back-and-forth discussion, use the reply thread on any markup instead: see \u003Ca href=\"/tutorials/markupcraft/statuses-and-replies\" data-topic=\"markupcraft/statuses-and-replies\"\u003EStatuses and replies\u003C/a\u003E.\u003C/p\u003E","text":"Stamp a sheet Choose Stamp (S). In Properties on the right, pick the stamp under Stamp: Approved Approved as noted Revise and resubmit Rejected Reviewed Void Custom text… (type up to 60 characters in the box that appears, then press Enter or click elsewhere) Click on the sheet where the stamp goes. Or drag a box to choose its size. Result: a framed stamp in capitals with a second line \"By \u003Cyour name\u003E, \u003Cdate\u003E\". A clicked stamp is sized for the screen at your zoom, kept between half an inch and an inch and a quarter tall on the printed sheet. The stamp you picked stays chosen for the next one, also after you reopen MarkupCraft in this browser. Colors follow the meaning: the Approved stamps are green, Revise and resubmit orange, Rejected and Void red, Reviewed blue, and custom stamps purple. If you choose another color in Properties, that color is kept. Change a stamp later Select it and pick another stamp in Properties. If it still had its automatic color, the color changes with the meaning. The name and date on the stamp are the stamp's author and the day it was made. They do not change when you edit it, and a stamp's author cannot be changed. To stamp in someone else's name, they set their name and stamp it themselves. The date on a stamp is the date in Coordinated Universal Time (UTC). Late in the evening in the Americas, or early in the morning in Asia and Australia, it can show the next or the previous day compared with your clock. The created time in Properties is in your own time zone. Stamps you use often The tool chest comes with an \"Approved as noted\" stamp tool, and you can save any stamp (its wording and color) as a tool of its own. See The tool chest. Image stamps, signature stamps and stamps with filled-in fields (date received, project number) are not built yet. Stamp a picture or your signature The stamp list in Properties ends with two more choices: Picture… asks for a PNG or JPEG on this computer, such as a company seal or a logo. Large pictures are scaled down to 1600 pixels on their longer side. My signature… opens a signature box: sign with a mouse, a pen or a finger, and choose Use this signature. Clear starts again. Then click the sheet to place it (a picture 3 in wide, a signature 2 in wide), or drag a box to fit it inside; the proportions are kept. Resize it with its handles like any markup (Shift keeps the proportions). The last picture and your signature are kept in this browser, so they are ready next time; Choose another picture… and Sign again… replace them. See What stays in this browser. In the saved PDF a picture is a stamp comment showing the image, so any PDF viewer shows and prints it. A signature drawn here is a picture of your signature, not a certified digital signature. Paste a picture from the clipboard Copy a picture in another program, or take a screenshot to the clipboard, then press Ctrl+V over the sheet. It lands where the pointer is, at most 3 in wide or tall with its proportions kept, as a picture markup you can move and resize. In the saved PDF it is a stamp comment showing the image, like the pictures above. More › Paste a picture in the Edit group does the same from the menu; the browser may ask first. When the clipboard holds no picture, Ctrl+V pastes copied markups as before. Sticky notes Choose Note (N). Click where the note goes. A small note icon appears with a box beside it. Type the note. Click outside or press Ctrl+Enter to keep it; Esc throws it away. Unlike text and callouts, a note is kept even if you type nothing, so you can place the icon now and write later. The note's words are its Note field in Properties. Double-click the icon (or select it and press Enter) to edit them on the sheet. On the sheet you see only the icon. Other PDF viewers show a standard sticky note that opens to the text when clicked. Change the icon's color with Color in Properties. For back-and-forth discussion, use the reply thread on any markup instead: see Statuses and replies.","lang":"en"},{"slug":"calibrate-and-measure","scope":"markupcraft","title":"Calibrate a sheet and measure","summary":"Set each sheet's scale from a preset or a known dimension, then measure lengths, areas with perimeters, and counts.","section":"tasks","order":60,"keywords":["calibrate","scale","set scale","measure","length","distance","dimension","area","square feet","perimeter","count","takeoff","quantity","ruler","arithmetic","calculation","plus","fraction"],"headings":[{"id":"choose-a-scale-from-the-list","text":"Choose a scale from the list","level":2},{"id":"calibrate-from-a-known-dimension","text":"Calibrate from a known dimension","level":2},{"id":"measure-a-length","text":"Measure a length","level":2},{"id":"sketch-to-scale","text":"Sketch to scale","level":2},{"id":"measure-an-angle","text":"Measure an angle","level":2},{"id":"measure-an-area-and-its-perimeter","text":"Measure an area and its perimeter","level":2},{"id":"cut-outs","text":"Cut-outs","level":3},{"id":"count-things","text":"Count things","level":2},{"id":"change-or-remove-a-scale","text":"Change or remove a scale","level":2},{"id":"where-the-numbers-go","text":"Where the numbers go","level":2}],"html":"\u003Cp\u003ELengths and areas need to know the sheet&#039;s scale. MarkupCraft keeps a scale \u003Cstrong\u003Eper sheet\u003C/strong\u003E: calibrate each sheet you measure on. Counts need no scale.\u003C/p\u003E\n\u003Cp\u003EThe status bar shows the current sheet&#039;s scale, or &quot;Not calibrated&quot;.\u003C/p\u003E\n\u003Ch2 id=\"choose-a-scale-from-the-list\"\u003EChoose a scale from the list\u003C/h2\u003E\n\u003Cp\u003EUse this when the PDF is at full size (a 24 × 36 sheet that prints at 24 × 36) and the drawing states its scale.\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EClick the scale button in the status bar (&quot;Not calibrated&quot;). The &quot;Sheet scale&quot; box opens.\u003C/li\u003E\u003Cli\u003EUnder \u003Cspan class=\"hui\"\u003EScale\u003C/span\u003E, pick the scale: architectural (1/32&quot; = 1&#039;-0&quot; to 3&quot; = 1&#039;-0&quot;), engineering (1&quot; = 10&#039; to 1&quot; = 100&#039;) or metric (1:1 to 1:1000).\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESet scale\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the status bar shows the scale, for example \u003Ccode\u003E1/4&quot; = 1&#039;-0&quot;\u003C/code\u003E. Architectural scales show lengths in feet and inches, engineering scales in decimal feet, metric scales up to 1:50 in millimeters and from 1:100 in meters.\u003C/p\u003E\n\u003Caside class=\"hc hc-warning\"\u003E\u003Cp class=\"hc-label\"\u003EWarning\u003C/p\u003E\n\u003Cp\u003EA preset is only right if the PDF has not been shrunk. A half-size set, or a sheet that was &quot;fit to page&quot; when it was made, measures wrong with a preset. Calibrate from a known dimension instead, and check one dimension either way.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"calibrate-from-a-known-dimension\"\u003ECalibrate from a known dimension\u003C/h2\u003E\n\u003Cp\u003EUse this for half-size sets, scanned sheets, details at odd scales, or to check a preset.\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EFind a long dimension you trust, or a graphic scale bar.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EMeasure\u003C/span\u003E group (or choose \u003Cspan class=\"hui\"\u003EPick two points\u003C/span\u003E in the &quot;Sheet scale&quot; box).\u003C/li\u003E\u003Cli\u003EClick one end of the dimension, then the other. (Or drag from one end to the other.) Zoom in first for accuracy; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E keeps the line at 45° steps.\u003C/li\u003E\u003Cli\u003EThe box says how far apart the points are on the paper and asks &quot;How far apart are they really?&quot;. Type the \u003Cspan class=\"hui\"\u003EReal distance\u003C/span\u003E, for example \u003Ccode\u003E24&#039;-0&quot;\u003C/code\u003E, \u003Ccode\u003E12&#039; 6 1/2&quot;\u003C/code\u003E, \u003Ccode\u003E7.2 m\u003C/code\u003E or \u003Ccode\u003E900 mm\u003C/code\u003E.\u003C/li\u003E\u003Cli\u003EPick how lengths are shown under \u003Cspan class=\"hui\"\u003EShow lengths in\u003C/span\u003E: \u003Cspan class=\"hui\"\u003EFeet and inches\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDecimal feet\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EInches\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EMeters\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EMillimeters\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESet scale\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the status bar shows &quot;Calibrated: 24&#039;-0&quot; over 1.00 in&quot; (the real length and the paper length), and the tool you were going to measure with comes back on. Every way of typing a length is in \u003Ca href=\"/tutorials/markupcraft/units-and-scales\" data-topic=\"markupcraft/units-and-scales\"\u003EUnits and lengths\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EThe real distance can also be a small calculation: \u003Ccode\u003E12&#039;6&quot;+3/4&quot;\u003C/code\u003E, \u003Ccode\u003E(24&#039;-0&quot;)/3\u003C/code\u003E or \u003Ccode\u003E2*450mm\u003C/code\u003E. Use \u003Ccode\u003E+ - * /\u003C/code\u003E and brackets; a number with no unit counts in the unit under \u003Cspan class=\"hui\"\u003EShow lengths in\u003C/span\u003E (feet for \u003Cspan class=\"hui\"\u003EFeet and inches\u003C/span\u003E). \u003Cspan class=\"hui\"\u003ESet scale\u003C/span\u003E uses the result.\u003C/p\u003E\n\u003Cp\u003EIf MarkupCraft cannot read what you typed, the box says so: &#039;That is not a length MarkupCraft understands. Try 24&#039;-0&quot;, 12&#039; 6 1/2&quot;, 7.2 m or 900 mm.&#039; A calculation it cannot work out says why and where, for example &quot;A bracket is not closed (character 5).&quot;\u003C/p\u003E\n\u003Ch2 id=\"measure-a-length\"\u003EMeasure a length\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick the start, then the end. Or drag from start to end. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E keeps it at 45° steps.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: a dimension line with ticks and the length written on it. The status bar repeats it (&quot;Length: 12&#039;-6 1/2&quot; (1/4&quot; = 1&#039;-0&quot;).&quot;), and \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows it under \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E. Feet and inches are rounded to the nearest 1/16&quot;.\u003C/p\u003E\n\u003Cp\u003EIf the sheet has no scale yet, choosing \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E switches to \u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E and the status bar explains: &quot;Calibrate this sheet first: pick two points a known distance apart, or choose its scale. Then measure.&quot; After you set the scale, \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E comes back.\u003C/p\u003E\n\u003Ch2 id=\"sketch-to-scale\"\u003ESketch to scale\u003C/h2\u003E\n\u003Cp\u003EOn a calibrated sheet you can type real lengths while you draw a \u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E or a space:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EClick the first point.\u003C/li\u003E\u003Cli\u003EPoint the way the next segment goes and type its length, such as \u003Ccode\u003E16\u003C/code\u003E (in the sheet&#039;s unit), \u003Ccode\u003E12&#039;6&quot;\u003C/code\u003E or \u003Ccode\u003E3.5 m\u003C/code\u003E. A box opens by the pointer as you type.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E. The point lands that far away, in the pointer&#039;s direction.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ETo set the direction exactly, add \u003Ccode\u003E&lt;\u003C/code\u003E and an angle in degrees: \u003Ccode\u003E8 &lt; 90\u003C/code\u003E goes 8 feet straight up, \u003Ccode\u003E4&lt;0\u003C/code\u003E to the right, \u003Ccode\u003E10 &lt; 225\u003C/code\u003E down and to the left, as the sheet is seen (turned pages included). Keep typing lengths for the next corners, and finish the shape as usual. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E closes the box without placing a point.\u003C/p\u003E\n\u003Ch2 id=\"measure-an-angle\"\u003EMeasure an angle\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EAngle\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"X\"\u003EX\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EX\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick the end of one arm, then the corner, then the end of the other arm.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the two arms, a small arc at the corner and the angle in degrees, to a tenth (0° to 180°). An angle needs no scale. \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows it under \u003Cspan class=\"hui\"\u003EAngle\u003C/span\u003E, and the list, CSV and BCF carry it.\u003C/p\u003E\n\u003Cp\u003EAn \u003Cspan class=\"hui\"\u003EArc\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"O\"\u003EO\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EO\u003C/span\u003E\u003C/kbd\u003E) on a calibrated sheet also shows its length along the curve in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"measure-an-area-and-its-perimeter\"\u003EMeasure an area and its perimeter\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EClick each corner of the room or region.\u003C/li\u003E\u003Cli\u003EFinish with a double-click, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or a right-click (double-tap on touch). \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E removes the last corner.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: a shaded outline with the area and &quot;P&quot; with the perimeter in the middle, for example &quot;128.00 sq ft&quot; and &quot;P 48&#039;-0&quot;&quot;. Feet scales give square feet, inches square inches, meters square meters, millimeters square millimeters. An area needs at least three corners.\u003C/p\u003E\n\u003Ch3 id=\"cut-outs\"\u003ECut-outs\u003C/h3\u003E\n\u003Cp\u003ETo leave out a column, a shaft or a courtyard, select the area and choose \u003Cspan class=\"hui\"\u003EAdd a cut-out\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. Click the cut-out&#039;s corners inside the area and finish as for an area. The cut-out stays open (unshaded), its area comes off, and its edges are added to the perimeter: a 16&#039; × 8&#039; room with a 4&#039; × 4&#039; cut-out reads &quot;112.00 sq ft&quot; and &quot;P 64&#039;-0&quot;&quot;. Add as many as you need; they cannot overlap each other or cross the area&#039;s outline. \u003Cspan class=\"hui\"\u003ERemove cut-outs\u003C/span\u003E takes them all out, and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E undoes one.\u003C/p\u003E\n\u003Ch2 id=\"count-things\"\u003ECount things\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, type a \u003Cspan class=\"hui\"\u003EGroup name\u003C/span\u003E, for example &quot;Floor drains&quot;. (It stays for next time.)\u003C/li\u003E\u003Cli\u003EClick each item on the sheet.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: each click adds a numbered dot, the first dot carries a tag like &quot;Floor drains: 7&quot;, and the status bar keeps the running total.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EStart another group:\u003C/strong\u003E press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E once (it clears the selection), change the \u003Cspan class=\"hui\"\u003EGroup name\u003C/span\u003E, and click again.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EAdd to an existing group:\u003C/strong\u003E select the group first, then choose \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E and click.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ERemove a mark:\u003C/strong\u003E with the group selected, hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E and click the dot. Removing the last dot removes the group. On a touch screen without a keyboard, use \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E or \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E instead.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ERename a group:\u003C/strong\u003E select it and edit \u003Cspan class=\"hui\"\u003EGroup name\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EA count group belongs to one sheet. Counts on several sheets show as separate groups in the markups list.\u003C/p\u003E\n\u003Ch2 id=\"change-or-remove-a-scale\"\u003EChange or remove a scale\u003C/h2\u003E\n\u003Cp\u003EClick the scale button in the status bar. The box shows the current scale; pick another, choose \u003Cspan class=\"hui\"\u003EPick two points\u003C/span\u003E, or choose \u003Cspan class=\"hui\"\u003ERemove scale\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003ELengths and areas already drawn are \u003Cstrong\u003Ere-measured\u003C/strong\u003E with the new scale at once. Undo brings the old scale back.\u003C/p\u003E\n\u003Ch2 id=\"where-the-numbers-go\"\u003EWhere the numbers go\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows the selected measurement&#039;s values.\u003C/li\u003E\u003Cli\u003EThe \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab lists each value, and its CSV has a &quot;Measurement&quot; column. See \u003Ca href=\"/tutorials/markupcraft/markups-list-and-export\" data-topic=\"markupcraft/markups-list-and-export\"\u003EThe markups list\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003EThe saved PDF keeps the scale on the page and writes lengths and areas as measurement comments, so other PDF programs that understand measurements can show them. See \u003Ca href=\"/tutorials/markupcraft/what-the-pdf-keeps\" data-topic=\"markupcraft/what-the-pdf-keeps\"\u003EWhat is saved in the PDF\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EFor a full quantity takeoff with items, assemblies and prices, use TakeoffCraft: MarkupCraft measures for review, not for estimating.\u003C/p\u003E","text":"Lengths and areas need to know the sheet's scale. MarkupCraft keeps a scale per sheet: calibrate each sheet you measure on. Counts need no scale. The status bar shows the current sheet's scale, or \"Not calibrated\". Choose a scale from the list Use this when the PDF is at full size (a 24 × 36 sheet that prints at 24 × 36) and the drawing states its scale. Click the scale button in the status bar (\"Not calibrated\"). The \"Sheet scale\" box opens. Under Scale, pick the scale: architectural (1/32\" = 1'-0\" to 3\" = 1'-0\"), engineering (1\" = 10' to 1\" = 100') or metric (1:1 to 1:1000). Choose Set scale. Result: the status bar shows the scale, for example 1/4\" = 1'-0\". Architectural scales show lengths in feet and inches, engineering scales in decimal feet, metric scales up to 1:50 in millimeters and from 1:100 in meters. A preset is only right if the PDF has not been shrunk. A half-size set, or a sheet that was \"fit to page\" when it was made, measures wrong with a preset. Calibrate from a known dimension instead, and check one dimension either way. Calibrate from a known dimension Use this for half-size sets, scanned sheets, details at odd scales, or to check a preset. Find a long dimension you trust, or a graphic scale bar. Choose Calibrate in the Measure group (or choose Pick two points in the \"Sheet scale\" box). Click one end of the dimension, then the other. (Or drag from one end to the other.) Zoom in first for accuracy; Shift keeps the line at 45° steps. The box says how far apart the points are on the paper and asks \"How far apart are they really?\". Type the Real distance, for example 24'-0\", 12' 6 1/2\", 7.2 m or 900 mm. Pick how lengths are shown under Show lengths in: Feet and inches, Decimal feet, Inches, Meters or Millimeters. Choose Set scale. Result: the status bar shows \"Calibrated: 24'-0\" over 1.00 in\" (the real length and the paper length), and the tool you were going to measure with comes back on. Every way of typing a length is in Units and lengths. The real distance can also be a small calculation: 12'6\"+3/4\", (24'-0\")/3 or 2*450mm. Use + - * / and brackets; a number with no unit counts in the unit under Show lengths in (feet for Feet and inches). Set scale uses the result. If MarkupCraft cannot read what you typed, the box says so: 'That is not a length MarkupCraft understands. Try 24'-0\", 12' 6 1/2\", 7.2 m or 900 mm.' A calculation it cannot work out says why and where, for example \"A bracket is not closed (character 5).\" Measure a length Choose Length (M). Click the start, then the end. Or drag from start to end. Shift keeps it at 45° steps. Result: a dimension line with ticks and the length written on it. The status bar repeats it (\"Length: 12'-6 1/2\" (1/4\" = 1'-0\").\"), and Properties shows it under Length. Feet and inches are rounded to the nearest 1/16\". If the sheet has no scale yet, choosing Length switches to Calibrate and the status bar explains: \"Calibrate this sheet first: pick two points a known distance apart, or choose its scale. Then measure.\" After you set the scale, Length comes back. Sketch to scale On a calibrated sheet you can type real lengths while you draw a Line, Arrow, Length, Polyline, Polygon, Free cloud, Area or a space: Click the first point. Point the way the next segment goes and type its length, such as 16 (in the sheet's unit), 12'6\" or 3.5 m. A box opens by the pointer as you type. Press Enter. The point lands that far away, in the pointer's direction. To set the direction exactly, add \u003C and an angle in degrees: 8 \u003C 90 goes 8 feet straight up, 4\u003C0 to the right, 10 \u003C 225 down and to the left, as the sheet is seen (turned pages included). Keep typing lengths for the next corners, and finish the shape as usual. Esc closes the box without placing a point. Measure an angle Choose Angle (X). Click the end of one arm, then the corner, then the end of the other arm. Result: the two arms, a small arc at the corner and the angle in degrees, to a tenth (0° to 180°). An angle needs no scale. Properties shows it under Angle, and the list, CSV and BCF carry it. An Arc (O) on a calibrated sheet also shows its length along the curve in Properties. Measure an area and its perimeter Choose Area (Q). Click each corner of the room or region. Finish with a double-click, Enter or a right-click (double-tap on touch). Backspace removes the last corner. Result: a shaded outline with the area and \"P\" with the perimeter in the middle, for example \"128.00 sq ft\" and \"P 48'-0\"\". Feet scales give square feet, inches square inches, meters square meters, millimeters square millimeters. An area needs at least three corners. Cut-outs To leave out a column, a shaft or a courtyard, select the area and choose Add a cut-out in Properties. Click the cut-out's corners inside the area and finish as for an area. The cut-out stays open (unshaded), its area comes off, and its edges are added to the perimeter: a 16' × 8' room with a 4' × 4' cut-out reads \"112.00 sq ft\" and \"P 64'-0\"\". Add as many as you need; they cannot overlap each other or cross the area's outline. Remove cut-outs takes them all out, and Ctrl+Z undoes one. Count things Choose Count (U). In Properties, type a Group name, for example \"Floor drains\". (It stays for next time.) Click each item on the sheet. Result: each click adds a numbered dot, the first dot carries a tag like \"Floor drains: 7\", and the status bar keeps the running total. Start another group: press Esc once (it clears the selection), change the Group name, and click again. Add to an existing group: select the group first, then choose Count and click. Remove a mark: with the group selected, hold Shift and click the dot. Removing the last dot removes the group. On a touch screen without a keyboard, use Ctrl+Z or Undo instead. Rename a group: select it and edit Group name in Properties. A count group belongs to one sheet. Counts on several sheets show as separate groups in the markups list. Change or remove a scale Click the scale button in the status bar. The box shows the current scale; pick another, choose Pick two points, or choose Remove scale. Lengths and areas already drawn are re-measured with the new scale at once. Undo brings the old scale back. Where the numbers go Properties shows the selected measurement's values. The Markups tab lists each value, and its CSV has a \"Measurement\" column. See The markups list. The saved PDF keeps the scale on the page and writes lengths and areas as measurement comments, so other PDF programs that understand measurements can show them. See What is saved in the PDF. For a full quantity takeoff with items, assemblies and prices, use TakeoffCraft: MarkupCraft measures for review, not for estimating.","lang":"en"},{"slug":"statuses-and-replies","scope":"markupcraft","title":"Statuses and replies","summary":"Mark each comment Open, Accepted, Rejected or Completed, discuss it in a reply thread, and pass the thread on in the PDF.","section":"tasks","order":70,"keywords":["status","review status","accepted","rejected","completed","open","reply","replies","thread","comment","conversation","discussion","respond","back-check"],"headings":[{"id":"set-a-status","text":"Set a status","level":2},{"id":"reply","text":"Reply","level":2},{"id":"add-a-photo","text":"Add a photo","level":2},{"id":"passing-the-review-on","text":"Passing the review on","level":2},{"id":"find-what-is-still-open","text":"Find what is still open","level":2}],"html":"\u003Cp\u003EEvery markup has a \u003Cstrong\u003Estatus\u003C/strong\u003E and a \u003Cstrong\u003Ereply thread\u003C/strong\u003E. Together they carry a review round: the reviewer marks up, the designer replies and sets statuses, the reviewer back-checks.\u003C/p\u003E\n\u003Ch2 id=\"set-a-status\"\u003ESet a status\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003ESelect the markup (or several).\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, pick a \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E: Open, Accepted, Rejected or Completed.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the status shows as a chip in the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list, and a line is added to the thread: &quot;Status set to Accepted by Ana Ruiz.&quot; With several markups selected, the status box says &quot;Mixed&quot; until you pick one, and then it changes all of them.\u003C/p\u003E\n\u003Cp\u003ENew markups start as Open. Pasted or duplicated markups also start as Open.\u003C/p\u003E\n\u003Ch2 id=\"reply\"\u003EReply\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003ESelect the markup.\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, find &quot;Replies&quot; below the style settings.\u003C/li\u003E\u003Cli\u003EType in \u003Cspan class=\"hui\"\u003EWrite a reply\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EReply\u003C/span\u003E, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the reply is listed with your name and the date and time, and the heading counts it: &quot;Replies (3)&quot;. The \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list shows a reply count on the row.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EStatus changes are listed in the same thread and marked as status entries, so the history reads in order.\u003C/li\u003E\u003Cli\u003EIf you start typing a reply and click something else, your draft is kept until you come back to that markup (until you close the set).\u003C/li\u003E\u003Cli\u003EIf your name is not set, MarkupCraft asks for it before sending.\u003C/li\u003E\u003Cli\u003EYou can reply to read-only comments that came with the file, too.\u003C/li\u003E\u003C/ul\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EA reply cannot be edited or deleted once sent. Right after sending, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes it back; after that, add a new reply that corrects it.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"add-a-photo\"\u003EAdd a photo\u003C/h2\u003E\n\u003Cp\u003EBelow the reply box, \u003Cspan class=\"hui\"\u003EAdd photo\u003C/span\u003E adds a picture to the thread: a PNG or JPEG from this computer, or, on a tablet or phone, a photo you take there and then. Whatever you typed in the reply box becomes its caption. The thread shows a thumbnail; choose it to see the photo full size. Large photos are scaled down to 1600 pixels on their longer side.\u003C/p\u003E\n\u003Cp\u003EIn the saved PDF each photo also travels as an attached file beside the markup (a paperclip), so other PDF viewers can open it.\u003C/p\u003E\n\u003Ch2 id=\"passing-the-review-on\"\u003EPassing the review on\u003C/h2\u003E\n\u003Cp\u003EThere is no shared online session yet: the review travels in the PDF.\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E. The copy holds every markup with its status and its replies.\u003C/li\u003E\u003Cli\u003ESend that copy the way you send drawings today.\u003C/li\u003E\u003Cli\u003EThe next person opens it in MarkupCraft, replies, sets statuses and saves again.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EOther PDF programs see the replies as replies to the comment, and the statuses as review states (Accepted, Rejected, Completed; Open shows as no state). Their own replies and review states come back into MarkupCraft when you open the file: the newest status wins.\u003C/p\u003E\n\u003Cp\u003EIf two people mark up separate copies at the same time, there is no merge. You can open both copies in one set and copy a few markups across with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E, but a pasted copy is a new markup: it carries your name, a new date and the status Open, and lands slightly offset. Agree who marks up which sheets to avoid this.\u003C/p\u003E\n\u003Ch2 id=\"find-what-is-still-open\"\u003EFind what is still open\u003C/h2\u003E\n\u003Cp\u003EIn the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab, set \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E to &quot;Open&quot; to list only open items, and \u003Cspan class=\"hui\"\u003EAuthor\u003C/span\u003E to one reviewer. See \u003Ca href=\"/tutorials/markupcraft/markups-list-and-export\" data-topic=\"markupcraft/markups-list-and-export\"\u003EThe markups list\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EStatus (Open, Accepted, Rejected, Completed) is about the comment. A punch item has its own separate status for the work in the field; see \u003Ca href=\"/tutorials/markupcraft/punch-list\" data-topic=\"markupcraft/punch-list\"\u003EMake a punch list\u003C/a\u003E.\u003C/p\u003E","text":"Every markup has a status and a reply thread. Together they carry a review round: the reviewer marks up, the designer replies and sets statuses, the reviewer back-checks. Set a status Select the markup (or several). In Properties, pick a Status: Open, Accepted, Rejected or Completed. Result: the status shows as a chip in the Markups list, and a line is added to the thread: \"Status set to Accepted by Ana Ruiz.\" With several markups selected, the status box says \"Mixed\" until you pick one, and then it changes all of them. New markups start as Open. Pasted or duplicated markups also start as Open. Reply Select the markup. In Properties, find \"Replies\" below the style settings. Type in Write a reply. Choose Reply, or press Ctrl+Enter. Result: the reply is listed with your name and the date and time, and the heading counts it: \"Replies (3)\". The Markups list shows a reply count on the row. Status changes are listed in the same thread and marked as status entries, so the history reads in order. If you start typing a reply and click something else, your draft is kept until you come back to that markup (until you close the set). If your name is not set, MarkupCraft asks for it before sending. You can reply to read-only comments that came with the file, too. A reply cannot be edited or deleted once sent. Right after sending, Ctrl+Z takes it back; after that, add a new reply that corrects it. Add a photo Below the reply box, Add photo adds a picture to the thread: a PNG or JPEG from this computer, or, on a tablet or phone, a photo you take there and then. Whatever you typed in the reply box becomes its caption. The thread shows a thumbnail; choose it to see the photo full size. Large photos are scaled down to 1600 pixels on their longer side. In the saved PDF each photo also travels as an attached file beside the markup (a paperclip), so other PDF viewers can open it. Passing the review on There is no shared online session yet: the review travels in the PDF. Choose Save. The copy holds every markup with its status and its replies. Send that copy the way you send drawings today. The next person opens it in MarkupCraft, replies, sets statuses and saves again. Other PDF programs see the replies as replies to the comment, and the statuses as review states (Accepted, Rejected, Completed; Open shows as no state). Their own replies and review states come back into MarkupCraft when you open the file: the newest status wins. If two people mark up separate copies at the same time, there is no merge. You can open both copies in one set and copy a few markups across with Ctrl+C and Ctrl+V, but a pasted copy is a new markup: it carries your name, a new date and the status Open, and lands slightly offset. Agree who marks up which sheets to avoid this. Find what is still open In the Markups tab, set Status to \"Open\" to list only open items, and Author to one reviewer. See The markups list. Status (Open, Accepted, Rejected, Completed) is about the comment. A punch item has its own separate status for the work in the field; see Make a punch list.","lang":"en"},{"slug":"punch-list","scope":"markupcraft","title":"Make a punch list","summary":"Turn markups into numbered punch items with an assignee, a due date and a status, and export the list.","section":"tasks","order":80,"keywords":["punch list","punch","snag list","deficiency","field issues","observation","assign","assignee","due date","closeout","walkthrough","number"],"headings":[{"id":"add-items","text":"Add items","level":2},{"id":"fill-in-the-details","text":"Fill in the details","level":2},{"id":"take-an-item-off","text":"Take an item off","level":2},{"id":"export-the-list","text":"Export the list","level":2},{"id":"on-site-with-a-tablet","text":"On site with a tablet","level":2}],"html":"\u003Cp\u003EA punch item is a markup with a number, an assignee, a due date and an item status. The number is drawn on the sheet next to the markup, so the printed sheet and the list match.\u003C/p\u003E\n\u003Ch2 id=\"add-items\"\u003EAdd items\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EMark up each issue on the sheets: a cloud, a callout, a note, anything.\u003C/li\u003E\u003Cli\u003ESelect one or more of them (see \u003Ca href=\"/tutorials/markupcraft/select-and-edit\" data-topic=\"markupcraft/select-and-edit\"\u003ESelect, move and change markups\u003C/a\u003E).\u003C/li\u003E\u003Cli\u003EEither open the \u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab and choose \u003Cspan class=\"hui\"\u003EAdd selected to the punch list\u003C/span\u003E, or choose \u003Cspan class=\"hui\"\u003EAdd to the punch list\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: each markup gets the next number (1, 2, 3…), in sheet order and then in the order they were drawn. A numbered badge appears on the sheet, and the status bar says &quot;Added 3 items to the punch list.&quot; Markups that already have a number, and read-only comments, are skipped.\u003C/p\u003E\n\u003Ch2 id=\"fill-in-the-details\"\u003EFill in the details\u003C/h2\u003E\n\u003Cp\u003EIn the \u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab, each item shows its number, subject, text, sheet and status, with three fields under it. The same fields are in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E under &quot;Punch list&quot; when the markup is selected:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EAssignee\u003C/span\u003E: a name or trade, as free text.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EDue\u003C/span\u003E: a date, from the date picker.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EItem status\u003C/span\u003E: Open, In progress, Ready for review or Closed.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EClick an item&#039;s heading to jump to it on its sheet.\u003C/p\u003E\n\u003Cp\u003EThe item status is separate from the markup&#039;s review status (Open, Accepted, Rejected, Completed). Use the item status for the work, and the review status for the comment.\u003C/p\u003E\n\u003Ch2 id=\"take-an-item-off\"\u003ETake an item off\u003C/h2\u003E\n\u003Cp\u003ESelect the markup and choose \u003Cspan class=\"hui\"\u003ETake off the punch list\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. The markup stays; only the number goes. While the set is open, numbers are not reused: the next item still gets the next new number, so a gap means an item was taken off. When a file is opened again, numbering carries on after the highest number in it.\u003C/p\u003E\n\u003Ch2 id=\"export-the-list\"\u003EExport the list\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EExport CSV\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab. You get &quot;&lt;name&gt; punch list.csv&quot; with the columns No., Sheet, File, Page, Item, Comment, Assignee, Due, Status, Markup status, Author and Created, in number order. Open it in any spreadsheet.\u003C/p\u003E\n\u003Cp\u003EThe punch numbers, assignees, due dates and item statuses are also saved inside the marked-up PDF, so they come back when you reopen it. Other PDF viewers show the number badge as part of the markup. The markups list&#039;s BCF export carries the assignee and due date too (see \u003Ca href=\"/tutorials/markupcraft/bcf-basics\" data-topic=\"markupcraft/bcf-basics\"\u003EBCF basics\u003C/a\u003E).\u003C/p\u003E\n\u003Ch2 id=\"on-site-with-a-tablet\"\u003EOn site with a tablet\u003C/h2\u003E\n\u003Cp\u003EOpen the set on an iPad, walk the job, and drop a \u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E or draw a \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E at each issue. Add them to the punch list as you go, and save before you leave. See \u003Ca href=\"/tutorials/markupcraft/review-on-a-tablet\" data-topic=\"markupcraft/review-on-a-tablet\"\u003EReview on an iPad or touch screen\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003EA punch list as a formatted PDF or spreadsheet report, and photos attached to items, are not built yet.\u003C/p\u003E","text":"A punch item is a markup with a number, an assignee, a due date and an item status. The number is drawn on the sheet next to the markup, so the printed sheet and the list match. Add items Mark up each issue on the sheets: a cloud, a callout, a note, anything. Select one or more of them (see Select, move and change markups). Either open the Punch list tab and choose Add selected to the punch list, or choose Add to the punch list in Properties. Result: each markup gets the next number (1, 2, 3…), in sheet order and then in the order they were drawn. A numbered badge appears on the sheet, and the status bar says \"Added 3 items to the punch list.\" Markups that already have a number, and read-only comments, are skipped. Fill in the details In the Punch list tab, each item shows its number, subject, text, sheet and status, with three fields under it. The same fields are in Properties under \"Punch list\" when the markup is selected: Assignee: a name or trade, as free text. Due: a date, from the date picker. Item status: Open, In progress, Ready for review or Closed. Click an item's heading to jump to it on its sheet. The item status is separate from the markup's review status (Open, Accepted, Rejected, Completed). Use the item status for the work, and the review status for the comment. Take an item off Select the markup and choose Take off the punch list in Properties. The markup stays; only the number goes. While the set is open, numbers are not reused: the next item still gets the next new number, so a gap means an item was taken off. When a file is opened again, numbering carries on after the highest number in it. Export the list Choose Export CSV in the Punch list tab. You get \"\u003Cname\u003E punch list.csv\" with the columns No., Sheet, File, Page, Item, Comment, Assignee, Due, Status, Markup status, Author and Created, in number order. Open it in any spreadsheet. The punch numbers, assignees, due dates and item statuses are also saved inside the marked-up PDF, so they come back when you reopen it. Other PDF viewers show the number badge as part of the markup. The markups list's BCF export carries the assignee and due date too (see BCF basics). On site with a tablet Open the set on an iPad, walk the job, and drop a Note or draw a Cloud at each issue. Add them to the punch list as you go, and save before you leave. See Review on an iPad or touch screen. A punch list as a formatted PDF or spreadsheet report, and photos attached to items, are not built yet.","lang":"en"},{"slug":"field-records","scope":"markupcraft","title":"Track RFIs, submittals and daily logs","summary":"Put RFIs, submittals and daily logs on the sheets, with numbers, assignees, due dates and threads; filter what is overdue; export CSV or BCF; work offline and merge copies.","section":"tasks","order":85,"keywords":["rfi","request for information","submittal","daily log","field report","site diary","construction","overdue","due date","assigned to me","thread","attachment","merge","offline","tablet","bcf","csv","field"],"headings":[{"id":"add-one","text":"Add one","level":2},{"id":"answer-and-track","text":"Answer and track","level":2},{"id":"find-what-matters","text":"Find what matters","level":2},{"id":"export","text":"Export","level":2},{"id":"save-offline-and-merging-copies","text":"Save, offline and merging copies","level":2},{"id":"limits","text":"Limits","level":2}],"html":"\u003Cp\u003EThe \u003Cspan class=\"hui\"\u003EField\u003C/span\u003E tab keeps three kinds of record beside your markups. Each is tied to a sheet; an RFI or a submittal also has a pin at the place on the sheet it is about.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ERFI\u003C/strong\u003E: a question for the design team. Statuses: Open, Answered, Closed.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESubmittal\u003C/strong\u003E: something to be reviewed before work goes ahead. Statuses: Open, In review, Approved, Approved as noted, Revise and resubmit, Closed.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EDaily log\u003C/strong\u003E: the day&#039;s weather, the number of people on site and the work done. Statuses: Draft, Final.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EEvery record has a number of its own kind (RFI-0001, SUB-0001, LOG-0001), a title, text, an assignee, a due date, a thread of replies and a list of attachment names.\u003C/p\u003E\n\u003Ch2 id=\"add-one\"\u003EAdd one\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the \u003Cspan class=\"hui\"\u003EField\u003C/span\u003E tab and choose \u003Cspan class=\"hui\"\u003ERFI\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ESubmittal\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003ETap or click the sheet where it belongs. A pin appears and the record opens in the tab.\u003C/li\u003E\u003Cli\u003EFill in the title, the question or description, who it is assigned to and when it is due.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EA daily log is added to the open sheet without a pin. \u003Cspan class=\"hui\"\u003EPlace pin\u003C/span\u003E puts one on it later; \u003Cspan class=\"hui\"\u003EMove pin\u003C/span\u003E moves any pin. Tapping a pin on the sheet opens its record.\u003C/p\u003E\n\u003Ch2 id=\"answer-and-track\"\u003EAnswer and track\u003C/h2\u003E\n\u003Cp\u003EChange the \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E and the change is logged in the thread. Write a reply and choose \u003Cspan class=\"hui\"\u003ESend reply\u003C/span\u003E (Ctrl+Enter also sends). Attachments are names only: type one or choose files, and the list tells the team what goes with the record. The files themselves stay where they are.\u003C/p\u003E\n\u003Cp\u003EA record whose due date has passed and that is still waiting (an RFI that is not Answered or Closed, a submittal that is not decided) is marked \u003Cstrong\u003EOverdue\u003C/strong\u003E, in red, on the list and on its pin.\u003C/p\u003E\n\u003Ch2 id=\"find-what-matters\"\u003EFind what matters\u003C/h2\u003E\n\u003Cp\u003EThe filters sit above the list: type, status, due date (overdue, due in 7 days, has or has no due date), this sheet or all sheets, a text search, and \u003Cspan class=\"hui\"\u003EAssigned to me\u003C/span\u003E, which compares the assignee with the name MarkupCraft knows you by (see \u003Ca href=\"/tutorials/markupcraft/set-your-name\" data-topic=\"markupcraft/set-your-name\"\u003ESet your name\u003C/a\u003E). The line under the filters counts what is shown and what is overdue.\u003C/p\u003E\n\u003Ch2 id=\"export\"\u003EExport\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ECSV\u003C/span\u003E writes the listed records as a spreadsheet. \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E writes them as BCF topics, each with a snapshot of its place on the sheet, so other BCF tools can list them. Both follow the filters.\u003C/p\u003E\n\u003Ch2 id=\"save-offline-and-merging-copies\"\u003ESave, offline and merging copies\u003C/h2\u003E\n\u003Cp\u003ERecords are saved inside the PDF when you save it, and they come back when you open it. Nothing needs a network: add, edit, reply and save on a tablet in a basement, then bring the PDF back. Older PDFs, and PDFs from other programs, open as they always did.\u003C/p\u003E\n\u003Cp\u003ETo bring two copies together, open one and choose \u003Cspan class=\"hui\"\u003EMerge\u003C/span\u003E, then pick the other copy of the same PDF. Records are joined by their ids:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003Ea record only one copy has is added;\u003C/li\u003E\u003Cli\u003Ea record in both takes its fields (title, text, status, assignee, due date) from the copy changed last, as a whole, so if two people changed different fields of the same record, the later copy&#039;s version wins; threads and attachment names from both copies are joined;\u003C/li\u003E\u003Cli\u003Eif both copies numbered a new record the same, the one that arrives gets the next free number;\u003C/li\u003E\u003Cli\u003Ea record removed in one copy stays removed unless it was edited after.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EA merge is one undo step.\u003C/p\u003E\n\u003Ch2 id=\"limits\"\u003ELimits\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003ERecords are not shared by Studio Live co-editing yet; use Merge.\u003C/li\u003E\u003Cli\u003EThere are no teams, notifications or cloud projects for records in this version.\u003C/li\u003E\u003Cli\u003EPages deleted from the PDF take their records with them (the page confirmation counts them).\u003C/li\u003E\u003C/ul\u003E","text":"The Field tab keeps three kinds of record beside your markups. Each is tied to a sheet; an RFI or a submittal also has a pin at the place on the sheet it is about. RFI: a question for the design team. Statuses: Open, Answered, Closed. Submittal: something to be reviewed before work goes ahead. Statuses: Open, In review, Approved, Approved as noted, Revise and resubmit, Closed. Daily log: the day's weather, the number of people on site and the work done. Statuses: Draft, Final. Every record has a number of its own kind (RFI-0001, SUB-0001, LOG-0001), a title, text, an assignee, a due date, a thread of replies and a list of attachment names. Add one Open the Field tab and choose RFI or Submittal. Tap or click the sheet where it belongs. A pin appears and the record opens in the tab. Fill in the title, the question or description, who it is assigned to and when it is due. A daily log is added to the open sheet without a pin. Place pin puts one on it later; Move pin moves any pin. Tapping a pin on the sheet opens its record. Answer and track Change the Status and the change is logged in the thread. Write a reply and choose Send reply (Ctrl+Enter also sends). Attachments are names only: type one or choose files, and the list tells the team what goes with the record. The files themselves stay where they are. A record whose due date has passed and that is still waiting (an RFI that is not Answered or Closed, a submittal that is not decided) is marked Overdue, in red, on the list and on its pin. Find what matters The filters sit above the list: type, status, due date (overdue, due in 7 days, has or has no due date), this sheet or all sheets, a text search, and Assigned to me, which compares the assignee with the name MarkupCraft knows you by (see Set your name). The line under the filters counts what is shown and what is overdue. Export CSV writes the listed records as a spreadsheet. BCF writes them as BCF topics, each with a snapshot of its place on the sheet, so other BCF tools can list them. Both follow the filters. Save, offline and merging copies Records are saved inside the PDF when you save it, and they come back when you open it. Nothing needs a network: add, edit, reply and save on a tablet in a basement, then bring the PDF back. Older PDFs, and PDFs from other programs, open as they always did. To bring two copies together, open one and choose Merge, then pick the other copy of the same PDF. Records are joined by their ids: a record only one copy has is added; a record in both takes its fields (title, text, status, assignee, due date) from the copy changed last, as a whole, so if two people changed different fields of the same record, the later copy's version wins; threads and attachment names from both copies are joined; if both copies numbered a new record the same, the one that arrives gets the next free number; a record removed in one copy stays removed unless it was edited after. A merge is one undo step. Limits Records are not shared by Studio Live co-editing yet; use Merge. There are no teams, notifications or cloud projects for records in this version. Pages deleted from the PDF take their records with them (the page confirmation counts them).","lang":"en"},{"slug":"markups-list-and-export","scope":"markupcraft","title":"The markups list, filters and exports","summary":"See every markup in the set, filter by sheet, author, status and type, jump to one, and export the list as CSV or BCF.","section":"tasks","order":90,"keywords":["markups list","list","summary","xlsx","spreadsheet workbook","workbook","pdf report","import bcf","filter","sort","report","export","csv","spreadsheet","bcf","bcfzip","issues","comments list","jump"],"headings":[{"id":"open-the-list","text":"Open the list","level":2},{"id":"jump-to-a-markup","text":"Jump to a markup","level":2},{"id":"filter","text":"Filter","level":2},{"id":"export-to-csv","text":"Export to CSV","level":2},{"id":"a-legend-on-the-sheet","text":"A legend on the sheet","level":2},{"id":"your-own-columns-and-sorting","text":"Your own columns, and sorting","level":2},{"id":"export-a-summary-workbook-or-pdf","text":"Export a summary: workbook or PDF","level":2},{"id":"export-to-bcf","text":"Export to BCF","level":2},{"id":"import-bcf","text":"Import BCF","level":2},{"id":"what-the-list-does-not-do-yet","text":"What the list does not do yet","level":2}],"html":"\u003Ch2 id=\"open-the-list\"\u003EOpen the list\u003C/h2\u003E\n\u003Cp\u003EChoose the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab on the right. Every markup of every open file is listed, in sheet order and then in the order they were made. Each row shows:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003Ean icon in the markup&#039;s color, its punch number if it has one (&quot;#4&quot;), and its subject,\u003C/li\u003E\u003Cli\u003Eits text, stamp wording or measured value, and its comment,\u003C/li\u003E\u003Cli\u003Ethe sheet, the author and the date,\u003C/li\u003E\u003Cli\u003Eits status (or &quot;Read-only&quot; for comments that came with the file), and a reply count when it has replies.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe line above the list counts them: &quot;38 markups&quot;, or &quot;12 of 38 markups&quot; when filtered.\u003C/p\u003E\n\u003Ch2 id=\"jump-to-a-markup\"\u003EJump to a markup\u003C/h2\u003E\n\u003Cp\u003EClick a row. MarkupCraft shows that sheet, selects the markup, and zooms to it when it is off-screen or too small to see. \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E has its details and thread when you switch back to that tab.\u003C/p\u003E\n\u003Ch2 id=\"filter\"\u003EFilter\u003C/h2\u003E\n\u003Cp\u003EFour menus above the list. They combine.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EMenu\u003C/th\u003E\u003Cth scope=\"col\"\u003EChoices\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESheet\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EAll sheets, This sheet (follows you as you change sheets), or any sheet that has markups\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EAuthor\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EAnyone, or each author in the set\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EAny status, Open, Accepted, Rejected, Completed\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EType\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EAny type, or each kind of markup in the set\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EExamples:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EWhat is still open on this sheet: \u003Cspan class=\"hui\"\u003ESheet\u003C/span\u003E &quot;This sheet&quot;, \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E &quot;Open&quot;.\u003C/li\u003E\u003Cli\u003EOne consultant&#039;s comments: \u003Cspan class=\"hui\"\u003EAuthor\u003C/span\u003E their name.\u003C/li\u003E\u003Cli\u003EAll measurements: \u003Cspan class=\"hui\"\u003EType\u003C/span\u003E &quot;Length&quot; or &quot;Area&quot;.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe list shows up to 2000 rows; narrow it with a filter in very large sets.\u003C/p\u003E\n\u003Ch2 id=\"export-to-csv\"\u003EExport to CSV\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003ECSV\u003C/span\u003E at the top of the tab. You get &quot;&lt;name&gt; markups.csv&quot; with \u003Cstrong\u003Ethe markups as currently filtered\u003C/strong\u003E, one per row, with these columns:\u003C/p\u003E\n\u003Cp\u003EPunch no., Sheet, File, Page, Type, Subject, Text, Comment, Measurement, Author, Created, Modified, Status, Replies, Last reply, Color, Read-only.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E&quot;Text&quot; holds the words of text boxes and callouts, a stamp&#039;s wording, or a count group&#039;s name.\u003C/li\u003E\u003Cli\u003E&quot;Measurement&quot; holds lengths, &quot;area, perimeter&quot; for areas, and &quot;group: n&quot; for counts.\u003C/li\u003E\u003Cli\u003EDates are full timestamps in UTC.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ETo export everything, set every filter back to its first choice first.\u003C/p\u003E\n\u003Ch2 id=\"a-legend-on-the-sheet\"\u003EA legend on the sheet\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ELegend\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab puts a legend at the top right of what you see: a box listing each kind of markup on the sheet (by subject and color, such as &quot;Cloud&quot;, &quot;Question&quot; or &quot;Outlets&quot;) with how many there are. A count group counts its marks. The legend keeps counting as you draw, move or delete markups, and it prints and saves with the counts of that moment.\u003C/p\u003E\n\u003Cp\u003EMove and resize it like any markup. In its \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, change its \u003Cspan class=\"hui\"\u003ETitle\u003C/span\u003E, or set \u003Cspan class=\"hui\"\u003ECounts\u003C/span\u003E to \u003Cspan class=\"hui\"\u003EThe whole set\u003C/span\u003E to count every sheet. Spaces, other legends and comments from other programs are not counted.\u003C/p\u003E\n\u003Ch2 id=\"your-own-columns-and-sorting\"\u003EYour own columns, and sorting\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EColumns\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab adds columns of your own to every markup: a \u003Cstrong\u003Etext\u003C/strong\u003E, a \u003Cstrong\u003Echoice\u003C/strong\u003E (such as Trade: Mechanical, Electrical, Plumbing), a \u003Cstrong\u003Enumber\u003C/strong\u003E (such as Cost) or a \u003Cstrong\u003Edate\u003C/strong\u003E. Give each a name, pick its kind, list the choices for a choice column, and choose \u003Cspan class=\"hui\"\u003ESave columns\u003C/span\u003E.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EFill them in under \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E: each column has a field there. A number column takes numbers only, a date column a date.\u003C/li\u003E\u003Cli\u003EThe list shows the values under each markup, the \u003Cspan class=\"hui\"\u003EColumn\u003C/span\u003E filter picks one value (or the markups where it is empty), and \u003Cspan class=\"hui\"\u003ESort\u003C/span\u003E orders the list by a column, by author, status, kind or date, instead of by sheet.\u003C/li\u003E\u003Cli\u003ECSV and XLSX exports carry the columns after the usual ones. The columns are saved with the PDF and come back when you reopen it.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"export-a-summary-workbook-or-pdf\"\u003EExport a summary: workbook or PDF\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EXLSX\u003C/span\u003E downloads &quot;&lt;name&gt; markup summary.xlsx&quot; with three sheets: \u003Cstrong\u003EMarkups\u003C/strong\u003E (one row per listed markup, the same columns as the CSV), \u003Cstrong\u003EBy sheet\u003C/strong\u003E (how many markups each sheet has, open and closed, and how many of each kind, with totals) and \u003Cstrong\u003EPunch list\u003C/strong\u003E (when there are punch items).\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPDF\u003C/span\u003E downloads &quot;&lt;name&gt; markup summary.pdf&quot;: a report to print or send, with the set&#039;s name, the date and a table of the listed markups (number, sheet, kind, subject, text or comment, measured value, author, status and the latest reply). Long text wraps; the table header repeats on each page.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EBoth take the list as it is filtered, so filter first to report one sheet, one author or the open items only.\u003C/p\u003E\n\u003Ch2 id=\"export-to-bcf\"\u003EExport to BCF\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E. MarkupCraft makes a picture of each listed markup on its sheet (&quot;Making snapshots for BCF (3 of 12)…&quot;), then downloads &quot;&lt;name&gt; markups.bcfzip&quot;. Each markup becomes one BCF topic with its status, author, dates, replies as comments, assignee and due date from its punch item, and the snapshot.\u003C/p\u003E\n\u003Cp\u003EUse it to bring drawing review comments into BIM coordination tools that read BCF. What carries over, and what does not, is in \u003Ca href=\"/tutorials/markupcraft/bcf-basics\" data-topic=\"markupcraft/bcf-basics\"\u003EBCF basics\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"import-bcf\"\u003EImport BCF\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EImport BCF\u003C/span\u003E reads a .bcfzip (or .bcf) file from a BIM tool:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EIssues that came from MarkupCraft&#039;s own BCF export find their markups again: new replies are added to the thread, and a new status (Closed counts as Completed) is set. Replies already there are not added twice.\u003C/li\u003E\u003Cli\u003EOther issues become notes, with their title, description, author and comments. A note goes on the sheet whose number or name the issue&#039;s labels give, else on the open sheet; a BIM camera has no place on paper, so such notes are stacked at the top left of the sheet for you to move.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe whole import is one step: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes it back. See \u003Ca href=\"/tutorials/markupcraft/bcf-basics\" data-topic=\"markupcraft/bcf-basics\"\u003EBCF basics\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"what-the-list-does-not-do-yet\"\u003EWhat the list does not do yet\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EGrouping the list (sort, then filter, instead).\u003C/li\u003E\u003Cli\u003EEditing values in the list (edit in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E; punch fields are editable in the \u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab).\u003C/li\u003E\u003C/ul\u003E","text":"Open the list Choose the Markups tab on the right. Every markup of every open file is listed, in sheet order and then in the order they were made. Each row shows: an icon in the markup's color, its punch number if it has one (\"#4\"), and its subject, its text, stamp wording or measured value, and its comment, the sheet, the author and the date, its status (or \"Read-only\" for comments that came with the file), and a reply count when it has replies. The line above the list counts them: \"38 markups\", or \"12 of 38 markups\" when filtered. Jump to a markup Click a row. MarkupCraft shows that sheet, selects the markup, and zooms to it when it is off-screen or too small to see. Properties has its details and thread when you switch back to that tab. Filter Four menus above the list. They combine. Menu Choices Sheet All sheets, This sheet (follows you as you change sheets), or any sheet that has markups Author Anyone, or each author in the set Status Any status, Open, Accepted, Rejected, Completed Type Any type, or each kind of markup in the set Examples: What is still open on this sheet: Sheet \"This sheet\", Status \"Open\". One consultant's comments: Author their name. All measurements: Type \"Length\" or \"Area\". The list shows up to 2000 rows; narrow it with a filter in very large sets. Export to CSV Choose CSV at the top of the tab. You get \"\u003Cname\u003E markups.csv\" with the markups as currently filtered, one per row, with these columns: Punch no., Sheet, File, Page, Type, Subject, Text, Comment, Measurement, Author, Created, Modified, Status, Replies, Last reply, Color, Read-only. \"Text\" holds the words of text boxes and callouts, a stamp's wording, or a count group's name. \"Measurement\" holds lengths, \"area, perimeter\" for areas, and \"group: n\" for counts. Dates are full timestamps in UTC. To export everything, set every filter back to its first choice first. A legend on the sheet Legend in the Markups tab puts a legend at the top right of what you see: a box listing each kind of markup on the sheet (by subject and color, such as \"Cloud\", \"Question\" or \"Outlets\") with how many there are. A count group counts its marks. The legend keeps counting as you draw, move or delete markups, and it prints and saves with the counts of that moment. Move and resize it like any markup. In its Properties, change its Title, or set Counts to The whole set to count every sheet. Spaces, other legends and comments from other programs are not counted. Your own columns, and sorting Columns in the Markups tab adds columns of your own to every markup: a text, a choice (such as Trade: Mechanical, Electrical, Plumbing), a number (such as Cost) or a date. Give each a name, pick its kind, list the choices for a choice column, and choose Save columns. Fill them in under Properties: each column has a field there. A number column takes numbers only, a date column a date. The list shows the values under each markup, the Column filter picks one value (or the markups where it is empty), and Sort orders the list by a column, by author, status, kind or date, instead of by sheet. CSV and XLSX exports carry the columns after the usual ones. The columns are saved with the PDF and come back when you reopen it. Export a summary: workbook or PDF XLSX downloads \"\u003Cname\u003E markup summary.xlsx\" with three sheets: Markups (one row per listed markup, the same columns as the CSV), By sheet (how many markups each sheet has, open and closed, and how many of each kind, with totals) and Punch list (when there are punch items). PDF downloads \"\u003Cname\u003E markup summary.pdf\": a report to print or send, with the set's name, the date and a table of the listed markups (number, sheet, kind, subject, text or comment, measured value, author, status and the latest reply). Long text wraps; the table header repeats on each page. Both take the list as it is filtered, so filter first to report one sheet, one author or the open items only. Export to BCF Choose BCF. MarkupCraft makes a picture of each listed markup on its sheet (\"Making snapshots for BCF (3 of 12)…\"), then downloads \"\u003Cname\u003E markups.bcfzip\". Each markup becomes one BCF topic with its status, author, dates, replies as comments, assignee and due date from its punch item, and the snapshot. Use it to bring drawing review comments into BIM coordination tools that read BCF. What carries over, and what does not, is in BCF basics. Import BCF Import BCF reads a .bcfzip (or .bcf) file from a BIM tool: Issues that came from MarkupCraft's own BCF export find their markups again: new replies are added to the thread, and a new status (Closed counts as Completed) is set. Replies already there are not added twice. Other issues become notes, with their title, description, author and comments. A note goes on the sheet whose number or name the issue's labels give, else on the open sheet; a BIM camera has no place on paper, so such notes are stacked at the top left of the sheet for you to move. The whole import is one step: Ctrl+Z takes it back. See BCF basics. What the list does not do yet Grouping the list (sort, then filter, instead). Editing values in the list (edit in Properties; punch fields are editable in the Punch list tab).","lang":"en"},{"slug":"layers","scope":"markupcraft","title":"Markup layers","summary":"Put markups on named layers, then show, hide or lock each layer; other PDF viewers can switch them too.","section":"tasks","order":95,"keywords":["layers","layer","hide","show","lock","group markups","discipline","mechanical","electrical","optional content","ocg","visibility"],"headings":[{"id":"make-a-layer-and-draw-on-it","text":"Make a layer and draw on it","level":2},{"id":"show-hide-and-lock","text":"Show, hide and lock","level":2},{"id":"in-the-saved-pdf","text":"In the saved PDF","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003ELayers group markups, for example by discipline or by reviewer. Hide a layer to see the drawing under it, or lock it so its markups cannot be moved by accident.\u003C/p\u003E\n\u003Ch2 id=\"make-a-layer-and-draw-on-it\"\u003EMake a layer and draw on it\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen \u003Cspan class=\"hui\"\u003ELayers\u003C/span\u003E, at the top of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E panel.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ENew layer\u003C/span\u003E, type a name such as \u003Ccode\u003EMechanical\u003C/code\u003E, and choose \u003Cspan class=\"hui\"\u003EAdd layer\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EThe new layer becomes the current layer: every markup you draw from now on goes on it. Choose another layer&#039;s name, or \u003Cspan class=\"hui\"\u003ENo layer\u003C/span\u003E, to change where new markups go.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ETo move a markup to another layer, select it and pick the layer under \u003Cspan class=\"hui\"\u003ELayer\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. \u003Cspan class=\"hui\"\u003ENew layer…\u003C/span\u003E at the end of that list makes one on the spot. Moving can be undone with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E.\u003C/p\u003E\n\u003Ch2 id=\"show-hide-and-lock\"\u003EShow, hide and lock\u003C/h2\u003E\n\u003Cp\u003EEach layer&#039;s row has two buttons:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EThe \u003Cstrong\u003Eeye\u003C/strong\u003E shows or hides the layer. Hidden markups are not drawn and cannot be picked; they still count in the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list.\u003C/li\u003E\u003Cli\u003EThe \u003Cstrong\u003Elock\u003C/strong\u003E keeps the layer&#039;s markups on the sheet but stops them from being picked, moved or deleted.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe pencil button renames a layer and moves its markups along. Filter the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list by \u003Cspan class=\"hui\"\u003ELayer\u003C/span\u003E to see one layer&#039;s markups.\u003C/p\u003E\n\u003Ch2 id=\"in-the-saved-pdf\"\u003EIn the saved PDF\u003C/h2\u003E\n\u003Cp\u003EEach layer becomes a PDF layer (optional content). Other PDF viewers list the layers in their layers panel and can switch them; a layer you hid starts hidden there too. Layers the drawing already had, such as CAD layers, stay as they were. When you reopen the copy in MarkupCraft, the markups come back on their layers, hidden and locked as you left them.\u003C/p\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EHiding and locking are not edits: they are not undone with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E, but they are saved with the PDF.\u003C/li\u003E\u003Cli\u003ECopy and paste keep a markup&#039;s layer.\u003C/li\u003E\u003Cli\u003EA flattened copy draws every markup into the page, whatever its layer. See \u003Ca href=\"/tutorials/markupcraft/flatten\" data-topic=\"markupcraft/flatten\"\u003ESave a flattened copy\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E","text":"Layers group markups, for example by discipline or by reviewer. Hide a layer to see the drawing under it, or lock it so its markups cannot be moved by accident. Make a layer and draw on it Open Layers, at the top of the Sheets panel. Choose New layer, type a name such as Mechanical, and choose Add layer. The new layer becomes the current layer: every markup you draw from now on goes on it. Choose another layer's name, or No layer, to change where new markups go. To move a markup to another layer, select it and pick the layer under Layer in Properties. New layer… at the end of that list makes one on the spot. Moving can be undone with Ctrl+Z. Show, hide and lock Each layer's row has two buttons: The eye shows or hides the layer. Hidden markups are not drawn and cannot be picked; they still count in the Markups list. The lock keeps the layer's markups on the sheet but stops them from being picked, moved or deleted. The pencil button renames a layer and moves its markups along. Filter the Markups list by Layer to see one layer's markups. In the saved PDF Each layer becomes a PDF layer (optional content). Other PDF viewers list the layers in their layers panel and can switch them; a layer you hid starts hidden there too. Layers the drawing already had, such as CAD layers, stay as they were. When you reopen the copy in MarkupCraft, the markups come back on their layers, hidden and locked as you left them. Good to know Hiding and locking are not edits: they are not undone with Ctrl+Z, but they are saved with the PDF. Copy and paste keep a markup's layer. A flattened copy draws every markup into the page, whatever its layer. See Save a flattened copy.","lang":"en"},{"slug":"spaces","scope":"markupcraft","title":"Spaces","summary":"Name the rooms or zones of a sheet, then filter, count and export markups by the space they are in.","section":"tasks","order":96,"keywords":["spaces","space","room","zone","wing","area of work","location","filter by room","group by room","export by space"],"headings":[{"id":"make-a-space","text":"Make a space","level":2},{"id":"what-is-in-a-space","text":"What is in a space","level":2},{"id":"in-the-saved-pdf","text":"In the saved PDF","level":2}],"html":"\u003Cp\u003EA space is a named zone on a sheet: a room, a wing, a phase of work. Every markup inside it belongs to it, so you can list, filter and export the markups of one room.\u003C/p\u003E\n\u003Ch2 id=\"make-a-space\"\u003EMake a space\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen \u003Cspan class=\"hui\"\u003ESpaces\u003C/span\u003E, at the top of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E panel, and choose \u003Cspan class=\"hui\"\u003ENew space\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EClick the corners of the zone, then double-click or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003Cli\u003EType its name, such as \u003Ccode\u003EKitchen\u003C/code\u003E or \u003Ccode\u003ELevel 2 east\u003C/code\u003E, and choose \u003Cspan class=\"hui\"\u003EAdd space\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EThe space shows as a light green zone with a dashed outline and its name. The status bar says how many markups are in it.\u003C/p\u003E\n\u003Ch2 id=\"what-is-in-a-space\"\u003EWhat is in a space\u003C/h2\u003E\n\u003Cp\u003EA markup is in the space that holds the middle of the markup. When spaces sit inside each other (a room in a wing), the smaller one wins. Move a markup and it moves between spaces. Select a space to change its outline with its handles, or its name under \u003Cspan class=\"hui\"\u003EName\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows a markup&#039;s space.\u003C/li\u003E\u003Cli\u003EThe \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list filters by \u003Cspan class=\"hui\"\u003ESpace\u003C/span\u003E, including \u003Cspan class=\"hui\"\u003ENo space\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003ECSV and XLSX exports get a \u003Cspan class=\"hui\"\u003ESpace\u003C/span\u003E column once the set has spaces.\u003C/li\u003E\u003Cli\u003EThe \u003Cspan class=\"hui\"\u003ESpaces\u003C/span\u003E panel lists every space with how many markups are in it; choose one to go to it.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"in-the-saved-pdf\"\u003EIn the saved PDF\u003C/h2\u003E\n\u003Cp\u003EA space is a polygon comment with its name as its text, drawn with a dashed border, so other viewers show it too. It reopens in MarkupCraft as a space.\u003C/p\u003E","text":"A space is a named zone on a sheet: a room, a wing, a phase of work. Every markup inside it belongs to it, so you can list, filter and export the markups of one room. Make a space Open Spaces, at the top of the Sheets panel, and choose New space. Click the corners of the zone, then double-click or press Enter. Type its name, such as Kitchen or Level 2 east, and choose Add space. The space shows as a light green zone with a dashed outline and its name. The status bar says how many markups are in it. What is in a space A markup is in the space that holds the middle of the markup. When spaces sit inside each other (a room in a wing), the smaller one wins. Move a markup and it moves between spaces. Select a space to change its outline with its handles, or its name under Name in Properties. Properties shows a markup's space. The Markups list filters by Space, including No space. CSV and XLSX exports get a Space column once the set has spaces. The Spaces panel lists every space with how many markups are in it; choose one to go to it. In the saved PDF A space is a polygon comment with its name as its text, drawn with a dashed border, so other viewers show it too. It reopens in MarkupCraft as a space.","lang":"en"},{"slug":"tool-chest","scope":"markupcraft","title":"The tool chest","summary":"Save a styled markup as a reusable tool, draw with it, and share your chest with the office as a file.","section":"tasks","order":100,"keywords":["tool chest","tools","tool set","custom tools","saved markups","favorites","office standard","import","export","share","json"],"headings":[{"id":"the-tools-you-start-with","text":"The tools you start with","level":2},{"id":"draw-with-a-tool","text":"Draw with a tool","level":2},{"id":"save-your-own","text":"Save your own","level":2},{"id":"remove-a-tool","text":"Remove a tool","level":2},{"id":"where-the-chest-is-kept","text":"Where the chest is kept","level":2},{"id":"share-a-chest-with-your-office","text":"Share a chest with your office","level":2}],"html":"\u003Cp\u003EThe \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab holds your \u003Cstrong\u003Etool chest\u003C/strong\u003E: markups saved with their look, ready to draw again. A tool keeps the markup&#039;s kind, color, line width, fill, opacity, text size and subject, plus a stamp&#039;s wording, a count&#039;s group name, or the starting text of a text box or callout.\u003C/p\u003E\n\u003Ch2 id=\"the-tools-you-start-with\"\u003EThe tools you start with\u003C/h2\u003E\n\u003Cp\u003EA new chest has six: &quot;Revision cloud&quot; (red), &quot;Question cloud&quot; (blue), &quot;Yellow highlighter&quot;, &quot;RFI callout&quot; (blue, starts with &quot;RFI: &quot;), &quot;Field verify&quot; (an orange callout that says &quot;Field verify.&quot;) and &quot;Approved as noted&quot; (a stamp).\u003C/p\u003E\n\u003Ch2 id=\"draw-with-a-tool\"\u003EDraw with a tool\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab.\u003C/li\u003E\u003Cli\u003EClick a tool. It looks pressed, and the matching toolbar tool turns on.\u003C/li\u003E\u003Cli\u003EDraw as usual. \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E says &#039;Drawing with &quot;&lt;tool&gt;&quot; from the tool chest.&#039;\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EWhile a chest tool is on, changes you make in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E before drawing apply to that tool for now, without changing the saved tool or your normal tool settings. Choosing a toolbar button, or pressing a tool&#039;s key, goes back to the plain tool.\u003C/p\u003E\n\u003Ch2 id=\"save-your-own\"\u003ESave your own\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EDraw a markup and style it the way you want: color, line, fill, subject, stamp wording.\u003C/li\u003E\u003Cli\u003ESelect it.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave selected as a tool\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab, or \u003Cspan class=\"hui\"\u003ESave as a tool\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EType a \u003Cspan class=\"hui\"\u003ETool name\u003C/span\u003E and choose \u003Cspan class=\"hui\"\u003ESave tool\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the tool is added at the end of the chest, and the \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab opens to show it.\u003C/p\u003E\n\u003Ch2 id=\"remove-a-tool\"\u003ERemove a tool\u003C/h2\u003E\n\u003Cp\u003EChoose the × at the end of the tool&#039;s row, then \u003Cspan class=\"hui\"\u003ERemove\u003C/span\u003E. Markups already drawn with it stay as they are.\u003C/p\u003E\n\u003Ch2 id=\"where-the-chest-is-kept\"\u003EWhere the chest is kept\u003C/h2\u003E\n\u003Cp\u003EThe chest is stored \u003Cstrong\u003Ein this browser, on this computer\u003C/strong\u003E. Another browser or computer has its own chest (starting with the six defaults), a private window forgets it when it closes, and clearing this site&#039;s data in the browser&#039;s settings erases it.\u003C/p\u003E\n\u003Cp\u003EIf the browser will not store it (storage turned off, or full), the status bar says: &quot;The tool chest could not be kept in this browser (storage is off or full). Export it to keep it.&quot;\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003ESafari can clear a website&#039;s stored data when you have not used the site for a while. Export your chest now and then so you can import it again.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cp\u003E\u003Cstrong\u003EExport your chest as a backup\u003C/strong\u003E, especially after building tools you rely on.\u003C/p\u003E\n\u003Ch2 id=\"share-a-chest-with-your-office\"\u003EShare a chest with your office\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003ESet up the tools once.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EExport\u003C/span\u003E. You get &quot;MarkupCraft tool chest.json&quot;.\u003C/li\u003E\u003Cli\u003EPut that file where the office keeps its standards, or send it around.\u003C/li\u003E\u003Cli\u003EEveryone else chooses \u003Cspan class=\"hui\"\u003EImport\u003C/span\u003E in their \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab and picks the file.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: &quot;Imported 12 tools from &quot;MarkupCraft tool chest.json&quot;.&quot; Tools that came from the same chest replace their older copies, so importing an updated office chest refreshes those tools instead of doubling them; new tools are added. A chest holds up to 500 tools.\u003C/p\u003E\n\u003Cp\u003EMarkupCraft checks every value in an imported file and skips what it cannot use (&quot;2 skipped (not usable)&quot;). Files that are not a chest are refused: &quot;This file is not a MarkupCraft tool chest.&quot; or &quot;This file is not a tool chest (it is not JSON).&quot;\u003C/p\u003E\n\u003Cp\u003ETool chest files from other markup programs cannot be imported.\u003C/p\u003E","text":"The Tools tab holds your tool chest: markups saved with their look, ready to draw again. A tool keeps the markup's kind, color, line width, fill, opacity, text size and subject, plus a stamp's wording, a count's group name, or the starting text of a text box or callout. The tools you start with A new chest has six: \"Revision cloud\" (red), \"Question cloud\" (blue), \"Yellow highlighter\", \"RFI callout\" (blue, starts with \"RFI: \"), \"Field verify\" (an orange callout that says \"Field verify.\") and \"Approved as noted\" (a stamp). Draw with a tool Open the Tools tab. Click a tool. It looks pressed, and the matching toolbar tool turns on. Draw as usual. Properties says 'Drawing with \"\u003Ctool\u003E\" from the tool chest.' While a chest tool is on, changes you make in Properties before drawing apply to that tool for now, without changing the saved tool or your normal tool settings. Choosing a toolbar button, or pressing a tool's key, goes back to the plain tool. Save your own Draw a markup and style it the way you want: color, line, fill, subject, stamp wording. Select it. Choose Save selected as a tool in the Tools tab, or Save as a tool in Properties. Type a Tool name and choose Save tool. Result: the tool is added at the end of the chest, and the Tools tab opens to show it. Remove a tool Choose the × at the end of the tool's row, then Remove. Markups already drawn with it stay as they are. Where the chest is kept The chest is stored in this browser, on this computer. Another browser or computer has its own chest (starting with the six defaults), a private window forgets it when it closes, and clearing this site's data in the browser's settings erases it. If the browser will not store it (storage turned off, or full), the status bar says: \"The tool chest could not be kept in this browser (storage is off or full). Export it to keep it.\" Safari can clear a website's stored data when you have not used the site for a while. Export your chest now and then so you can import it again. Export your chest as a backup, especially after building tools you rely on. Share a chest with your office Set up the tools once. Choose Export. You get \"MarkupCraft tool chest.json\". Put that file where the office keeps its standards, or send it around. Everyone else chooses Import in their Tools tab and picks the file. Result: \"Imported 12 tools from \"MarkupCraft tool chest.json\".\" Tools that came from the same chest replace their older copies, so importing an updated office chest refreshes those tools instead of doubling them; new tools are added. A chest holds up to 500 tools. MarkupCraft checks every value in an imported file and skips what it cannot use (\"2 skipped (not usable)\"). Files that are not a chest are refused: \"This file is not a MarkupCraft tool chest.\" or \"This file is not a tool chest (it is not JSON).\" Tool chest files from other markup programs cannot be imported.","lang":"en"},{"slug":"compare-revisions","scope":"markupcraft","title":"Compare two revisions","summary":"Overlay an old and a new issue of a sheet in two colors, line them up by two points, and cloud what changed.","section":"tasks","order":110,"keywords":["compare","overlay","overlay pages","revision","diff","differences","changes","old new","align","backcheck","issue","bulletin"],"headings":[{"id":"compare-two-sheets","text":"Compare two sheets","level":2},{"id":"fade-between-old-and-new","text":"Fade between old and new","level":2},{"id":"line-the-sheets-up","text":"Line the sheets up","level":2},{"id":"changed-lines-only","text":"Changed lines only","level":2},{"id":"mark-the-changes","text":"Mark the changes","level":2},{"id":"compare-a-whole-set","text":"Compare a whole set","level":2},{"id":"stop-comparing","text":"Stop comparing","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003ECompare lays two sheets over each other. Lines only on the old sheet show in red, lines only on the new sheet in blue, and lines on both in a muted gray. The colors are named in the legend under the sheet: &quot;Only on the old sheet&quot;, &quot;Only on the new sheet&quot;, &quot;On both&quot;.\u003C/p\u003E\n\u003Ch2 id=\"compare-two-sheets\"\u003ECompare two sheets\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen both issues. They can be pages of the same PDF or of different PDFs; open them together as one set (see \u003Ca href=\"/tutorials/markupcraft/several-files\" data-topic=\"markupcraft/several-files\"\u003EWork with several files at once\u003C/a\u003E).\u003C/li\u003E\u003Cli\u003EChoose the \u003Cspan class=\"hui\"\u003ECompare\u003C/span\u003E tab on the right.\u003C/li\u003E\u003Cli\u003EPick the \u003Cspan class=\"hui\"\u003EOld sheet\u003C/span\u003E and the \u003Cspan class=\"hui\"\u003ENew sheet\u003C/span\u003E. The new sheet starts as the one you are on. When several files are open, each sheet&#039;s file name is shown after its name.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECompare\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: MarkupCraft shows the new sheet with the old one mixed in, the legend appears, and the tab says &quot;Comparing &lt;old&gt; (old) with &lt;new&gt; (new). Markups on the new sheet stay editable.&quot;\u003C/p\u003E\n\u003Ch2 id=\"fade-between-old-and-new\"\u003EFade between old and new\u003C/h2\u003E\n\u003Cp\u003EDrag the \u003Cspan class=\"hui\"\u003EOld and new\u003C/span\u003E slider. All the way left shows only the old sheet, all the way right only the new one, the middle shows both. Sliding back and forth is often the quickest way to see a small change.\u003C/p\u003E\n\u003Ch2 id=\"line-the-sheets-up\"\u003ELine the sheets up\u003C/h2\u003E\n\u003Cp\u003EIf the two issues were plotted with a different margin, size or rotation, everything looks changed. Fix it:\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EBy two points (best):\u003C/strong\u003E\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EAlign by two points\u003C/span\u003E. The view shows only the old sheet.\u003C/li\u003E\u003Cli\u003EClick a sharp feature you can find on both sheets, such as a column grid intersection. The tab counts the steps (&quot;1 of 4&quot;).\u003C/li\u003E\u003Cli\u003EClick a second feature, far from the first, such as the opposite grid corner.\u003C/li\u003E\u003Cli\u003EThe view switches to the new sheet. Click the first feature again.\u003C/li\u003E\u003Cli\u003EClick the second feature again.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: &quot;Lined up: old sheet scaled 100.00%, turned 0.00°. Nudge to fine-tune.&quot; The old sheet is moved, scaled and turned to fit. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E cancels while you are picking. Zoom in on each feature before clicking for a precise fit.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EBy nudging:\u003C/strong\u003E use the four arrow buttons under &quot;Line up&quot; to move the old sheet. Choose the step (0.25, 1, 5 or 20 pt; 72 pt is one inch on the paper). The tab says how far it has moved.\u003C/p\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EReset\u003C/span\u003E removes the alignment and the nudges.\u003C/p\u003E\n\u003Ch2 id=\"changed-lines-only\"\u003EChanged lines only\u003C/h2\u003E\n\u003Cp\u003EUnder the alignment buttons, pick \u003Cspan class=\"hui\"\u003EChanged lines\u003C/span\u003E instead of \u003Cspan class=\"hui\"\u003EPicture overlay\u003C/span\u003E. MarkupCraft then compares the two sheets&#039; own lines, not their pictures: the new sheet shows as it is, with the lines that are only on the old sheet in red and the lines only on the new one in blue. A line that only got shorter shows just the missing part. Line the sheets up first (see above): the comparison uses the alignment, so a sheet that was only shifted shows no changes. The status line says how much changed.\u003C/p\u003E\n\u003Cp\u003EThis works for PDFs plotted from CAD, where the drawing is made of lines. Scanned sheets have no lines to compare: use the picture overlay for them. Text set in a font (not drawn as strokes) is not compared.\u003C/p\u003E\n\u003Ch2 id=\"mark-the-changes\"\u003EMark the changes\u003C/h2\u003E\n\u003Cp\u003EWhile comparing, you are on the new sheet and every tool works. Draw clouds around the changes as you find them; they belong to the new sheet and stay when you stop comparing.\u003C/p\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ECloud the changes\u003C/span\u003E does it for you: it groups the changed lines that sit close together and draws a revision cloud round each group on the new sheet, with &quot;Changed since &lt;old sheet&gt;&quot; as its comment. One \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E removes them all; delete the ones you do not need.\u003C/p\u003E\n\u003Ch2 id=\"compare-a-whole-set\"\u003ECompare a whole set\u003C/h2\u003E\n\u003Cp\u003EWhen the new issue arrives as its own PDF, open both PDFs and open \u003Cspan class=\"hui\"\u003ECompare two sets\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003ECompare\u003C/span\u003E tab. Pick the old file and the new file, then choose \u003Cspan class=\"hui\"\u003ECompare the sets\u003C/span\u003E. Sheets are paired by their number (as in \u003Ca href=\"/tutorials/markupcraft/slip-sheet-a-revised-set\" data-topic=\"markupcraft/slip-sheet-a-revised-set\"\u003Eslip-sheeting\u003C/a\u003E), compared by their lines, and listed with the most changed first. Choose a sheet in the list to compare that pair with \u003Cspan class=\"hui\"\u003EChanged lines\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ECloud all changes\u003C/span\u003E clouds every group of changed lines on every changed sheet, in one step you can undo. The set comparison does not line sheets up first, so a sheet that was shifted on the page shows as changed: compare that pair on its own and use \u003Cspan class=\"hui\"\u003EAlign by two points\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"stop-comparing\"\u003EStop comparing\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EStop comparing\u003C/span\u003E, or go to another sheet. The alignment is remembered for the same pair of sheets until you close the set.\u003C/p\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003ECompare works on what is drawn, pixel by pixel. It does not know that a line moved; it shows the old position in one color and the new position in the other.\u003C/li\u003E\u003Cli\u003EText that reflowed, a changed title block date or a different plot style shows up as changes too.\u003C/li\u003E\u003Cli\u003EA scanned sheet compared with a plotted one is noisy: scanning blurs and shifts lines.\u003C/li\u003E\u003Cli\u003EComparing text written in a font, and a list of what changed, are not built yet.\u003C/li\u003E\u003C/ul\u003E","text":"Compare lays two sheets over each other. Lines only on the old sheet show in red, lines only on the new sheet in blue, and lines on both in a muted gray. The colors are named in the legend under the sheet: \"Only on the old sheet\", \"Only on the new sheet\", \"On both\". Compare two sheets Open both issues. They can be pages of the same PDF or of different PDFs; open them together as one set (see Work with several files at once). Choose the Compare tab on the right. Pick the Old sheet and the New sheet. The new sheet starts as the one you are on. When several files are open, each sheet's file name is shown after its name. Choose Compare. Result: MarkupCraft shows the new sheet with the old one mixed in, the legend appears, and the tab says \"Comparing \u003Cold\u003E (old) with \u003Cnew\u003E (new). Markups on the new sheet stay editable.\" Fade between old and new Drag the Old and new slider. All the way left shows only the old sheet, all the way right only the new one, the middle shows both. Sliding back and forth is often the quickest way to see a small change. Line the sheets up If the two issues were plotted with a different margin, size or rotation, everything looks changed. Fix it: By two points (best): Choose Align by two points. The view shows only the old sheet. Click a sharp feature you can find on both sheets, such as a column grid intersection. The tab counts the steps (\"1 of 4\"). Click a second feature, far from the first, such as the opposite grid corner. The view switches to the new sheet. Click the first feature again. Click the second feature again. Result: \"Lined up: old sheet scaled 100.00%, turned 0.00°. Nudge to fine-tune.\" The old sheet is moved, scaled and turned to fit. Esc cancels while you are picking. Zoom in on each feature before clicking for a precise fit. By nudging: use the four arrow buttons under \"Line up\" to move the old sheet. Choose the step (0.25, 1, 5 or 20 pt; 72 pt is one inch on the paper). The tab says how far it has moved. Reset removes the alignment and the nudges. Changed lines only Under the alignment buttons, pick Changed lines instead of Picture overlay. MarkupCraft then compares the two sheets' own lines, not their pictures: the new sheet shows as it is, with the lines that are only on the old sheet in red and the lines only on the new one in blue. A line that only got shorter shows just the missing part. Line the sheets up first (see above): the comparison uses the alignment, so a sheet that was only shifted shows no changes. The status line says how much changed. This works for PDFs plotted from CAD, where the drawing is made of lines. Scanned sheets have no lines to compare: use the picture overlay for them. Text set in a font (not drawn as strokes) is not compared. Mark the changes While comparing, you are on the new sheet and every tool works. Draw clouds around the changes as you find them; they belong to the new sheet and stay when you stop comparing. Cloud the changes does it for you: it groups the changed lines that sit close together and draws a revision cloud round each group on the new sheet, with \"Changed since \u003Cold sheet\u003E\" as its comment. One Ctrl+Z removes them all; delete the ones you do not need. Compare a whole set When the new issue arrives as its own PDF, open both PDFs and open Compare two sets in the Compare tab. Pick the old file and the new file, then choose Compare the sets. Sheets are paired by their number (as in slip-sheeting), compared by their lines, and listed with the most changed first. Choose a sheet in the list to compare that pair with Changed lines. Cloud all changes clouds every group of changed lines on every changed sheet, in one step you can undo. The set comparison does not line sheets up first, so a sheet that was shifted on the page shows as changed: compare that pair on its own and use Align by two points. Stop comparing Choose Stop comparing, or go to another sheet. The alignment is remembered for the same pair of sheets until you close the set. Good to know Compare works on what is drawn, pixel by pixel. It does not know that a line moved; it shows the old position in one color and the new position in the other. Text that reflowed, a changed title block date or a different plot style shows up as changes too. A scanned sheet compared with a plotted one is noisy: scanning blurs and shifts lines. Comparing text written in a font, and a list of what changed, are not built yet.","lang":"en"},{"slug":"slip-sheet-a-revised-set","scope":"markupcraft","title":"Slip-sheet a revised set","summary":"Open the new issue of a plan set beside the old one and carry every open markup onto the sheet with the same number.","section":"tasks","order":112,"keywords":["slip sheet","slip-sheet","revised set","new issue","revision","supersede","superseded","carry forward","replace sheets","reissue","addendum","bulletin"],"headings":[{"id":"slip-sheet","text":"Slip-sheet","level":2},{"id":"how-sheets-are-matched","text":"How sheets are matched","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003EWhen a new issue of the drawings arrives, slip-sheeting moves your review onto it: each new sheet takes the markups of the old sheet with the same number, and the old sheet is stamped &quot;Superseded&quot;.\u003C/p\u003E\n\u003Ch2 id=\"slip-sheet\"\u003ESlip-sheet\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the current set, with your markups.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003ESlip-sheet a revised set…\u003C/span\u003E, and pick the new PDFs. They open beside the old set.\u003C/li\u003E\u003Cli\u003EThe dialog lists each new sheet and the old sheet it replaces. Untick a row to leave that sheet&#039;s markups where they are. Sheets with a new number have nothing to carry.\u003C/li\u003E\u003Cli\u003EChoose whether to leave closed markups (Accepted, Rejected, Completed) on the old sheets, and whether to stamp the old sheets.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ECarry markups forward\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: the markups appear on the new sheets in the same place, with their replies, statuses and authors. A punch item moves to the new sheet and keeps its number. The old sheets keep their markups as a record, under a red &quot;Superseded&quot; stamp. The status bar sums up what moved.\u003C/p\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EJust open the files\u003C/span\u003E opens the new set without carrying anything, for example to compare first. See \u003Ca href=\"/tutorials/markupcraft/compare-revisions\" data-topic=\"markupcraft/compare-revisions\"\u003ECompare two revisions\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"how-sheets-are-matched\"\u003EHow sheets are matched\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EBy sheet number\u003C/strong\u003E, read as the sheets list shows it: a number you typed with \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E, the PDF&#039;s page label, or the title block. Case, spaces, dots and dashes do not matter: &quot;A-101&quot; matches &quot;a101&quot;.\u003C/li\u003E\u003Cli\u003EIf two open files have a sheet with that number, the newest one is replaced, so you can slip-sheet issue after issue.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EScanned sets\u003C/strong\u003E have no numbers to read. When a new file has none, its pages are matched in page order to an open file with the same number of pages. Check those rows before you carry.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EOne \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes the whole slip-sheet back: the copies, the stamps and the moved punch items. The new files stay open.\u003C/li\u003E\u003Cli\u003EIf a new sheet is a different size, the markups are scaled with the page, and the status bar says how many to check.\u003C/li\u003E\u003Cli\u003EThe scale of an old sheet comes along when the new sheet is the same size and has none.\u003C/li\u003E\u003Cli\u003EComments other programs made stay on the old sheets: they are read-only here.\u003C/li\u003E\u003Cli\u003ESave the new files to keep the carried markups. See \u003Ca href=\"/tutorials/markupcraft/save-the-marked-up-pdf\" data-topic=\"markupcraft/save-the-marked-up-pdf\"\u003ESave the marked-up PDF\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E","text":"When a new issue of the drawings arrives, slip-sheeting moves your review onto it: each new sheet takes the markups of the old sheet with the same number, and the old sheet is stamped \"Superseded\". Slip-sheet Open the current set, with your markups. Choose Pages, then Slip-sheet a revised set…, and pick the new PDFs. They open beside the old set. The dialog lists each new sheet and the old sheet it replaces. Untick a row to leave that sheet's markups where they are. Sheets with a new number have nothing to carry. Choose whether to leave closed markups (Accepted, Rejected, Completed) on the old sheets, and whether to stamp the old sheets. Choose Carry markups forward. Result: the markups appear on the new sheets in the same place, with their replies, statuses and authors. A punch item moves to the new sheet and keeps its number. The old sheets keep their markups as a record, under a red \"Superseded\" stamp. The status bar sums up what moved. Just open the files opens the new set without carrying anything, for example to compare first. See Compare two revisions. How sheets are matched By sheet number, read as the sheets list shows it: a number you typed with Rename sheet, the PDF's page label, or the title block. Case, spaces, dots and dashes do not matter: \"A-101\" matches \"a101\". If two open files have a sheet with that number, the newest one is replaced, so you can slip-sheet issue after issue. Scanned sets have no numbers to read. When a new file has none, its pages are matched in page order to an open file with the same number of pages. Check those rows before you carry. Good to know One Ctrl+Z takes the whole slip-sheet back: the copies, the stamps and the moved punch items. The new files stay open. If a new sheet is a different size, the markups are scaled with the page, and the status bar says how many to check. The scale of an old sheet comes along when the new sheet is the same size and has none. Comments other programs made stay on the old sheets: they are read-only here. Save the new files to keep the carried markups. See Save the marked-up PDF.","lang":"en"},{"slug":"find-text","scope":"markupcraft","title":"Find text in the drawings","summary":"Search the words on every sheet, jump to each hit, and cloud them all in one step.","section":"tasks","order":115,"keywords":["find","search","text","word","words","ctrl f","look for","note","keynote","callout","cloud all","highlight hits"],"headings":[{"id":"find","text":"Find","level":2},{"id":"cloud-every-hit","text":"Cloud every hit","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003E\u003Cspan class=\"hui\"\u003EFind text\u003C/span\u003E, at the top of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E panel, searches the words drawn on the sheets themselves. \u003Cspan class=\"hui\"\u003ESearch sheets\u003C/span\u003E below it only searches sheet names.\u003C/p\u003E\n\u003Ch2 id=\"find\"\u003EFind\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command F\"\u003E⌘F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+F\u003C/span\u003E\u003C/kbd\u003E, or open \u003Cspan class=\"hui\"\u003EFind text\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EType the words, such as \u003Ccode\u003Ehood\u003C/code\u003E or \u003Ccode\u003Everify in field\u003C/code\u003E.\u003C/li\u003E\u003Cli\u003EPick \u003Cspan class=\"hui\"\u003EAll sheets\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EThis sheet\u003C/span\u003E, and tick \u003Cspan class=\"hui\"\u003EMatch case\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EWhole words\u003C/span\u003E if you need them.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or choose \u003Cspan class=\"hui\"\u003EFind\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: every hit is listed with its sheet number and the words around it, and is marked in yellow on its sheet. Choose a hit to open its sheet and zoom to it.\u003C/p\u003E\n\u003Cp\u003EA phrase is found even when the drawing splits it over two pieces of text or two lines.\u003C/p\u003E\n\u003Ch2 id=\"cloud-every-hit\"\u003ECloud every hit\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003ECloud all\u003C/span\u003E. A revision cloud goes round each hit in the list, on every sheet, with &quot;Found: &lt;your words&gt;&quot; as its comment. One \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E removes them all.\u003C/p\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EOnly sheets with real text can be searched. Scanned sheets, and drawings whose letters are drawn as lines, have none: the count says how many sheets were skipped. See \u003Ca href=\"/tutorials/markupcraft/not-built-yet\" data-topic=\"markupcraft/not-built-yet\"\u003EWhat is not built yet\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003EThe list shows the first 500 hits; Cloud all clouds up to 2,000.\u003C/li\u003E\u003Cli\u003EThe hits are cleared when you close the set, and for one file when you change its pages.\u003C/li\u003E\u003C/ul\u003E","text":"Find text, at the top of the Sheets panel, searches the words drawn on the sheets themselves. Search sheets below it only searches sheet names. Find Press Ctrl+F, or open Find text. Type the words, such as hood or verify in field. Pick All sheets or This sheet, and tick Match case or Whole words if you need them. Press Enter or choose Find. Result: every hit is listed with its sheet number and the words around it, and is marked in yellow on its sheet. Choose a hit to open its sheet and zoom to it. A phrase is found even when the drawing splits it over two pieces of text or two lines. Cloud every hit Choose Cloud all. A revision cloud goes round each hit in the list, on every sheet, with \"Found: \u003Cyour words\u003E\" as its comment. One Ctrl+Z removes them all. Good to know Only sheets with real text can be searched. Scanned sheets, and drawings whose letters are drawn as lines, have none: the count says how many sheets were skipped. See What is not built yet. The list shows the first 500 hits; Cloud all clouds up to 2,000. The hits are cleared when you close the set, and for one file when you change its pages.","lang":"en"},{"slug":"sheet-links","scope":"markupcraft","title":"Sheet links","summary":"Make a markup jump to another sheet, and turn every sheet callout like 3/A-501 into a link in one pass.","section":"tasks","order":117,"keywords":["hyperlink","link","links","jump","sheet callout","detail callout","section callout","3/A-501","go to sheet","back","auto link","batch link"],"headings":[{"id":"link-a-markup-to-a-sheet","text":"Link a markup to a sheet","level":2},{"id":"link-every-sheet-callout-at-once","text":"Link every sheet callout at once","level":2},{"id":"in-the-saved-pdf","text":"In the saved PDF","level":2}],"html":"\u003Cp\u003EA sheet link takes you from a markup to another sheet of the set: from a detail bubble to the detail, from a note to the sheet it refers to.\u003C/p\u003E\n\u003Ch2 id=\"link-a-markup-to-a-sheet\"\u003ELink a markup to a sheet\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003ESelect the markup.\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, pick the sheet under \u003Cspan class=\"hui\"\u003ELink to sheet\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EA small arrow appears at the markup&#039;s top right. To follow it, hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E and click the markup, or select it and choose \u003Cspan class=\"hui\"\u003EGo to …\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option ←\"\u003E⌥←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+←\u003C/span\u003E\u003C/kbd\u003E goes back to the sheet you came from.\u003C/p\u003E\n\u003Cp\u003EA link names the sheet by its number, so it still works after you reopen the set or slip-sheet a new issue: it opens the newest sheet with that number. If that sheet is not open, the status bar says so.\u003C/p\u003E\n\u003Ch2 id=\"link-every-sheet-callout-at-once\"\u003ELink every sheet callout at once\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen \u003Cspan class=\"hui\"\u003EFind text\u003C/span\u003E at the top of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E panel and choose \u003Cspan class=\"hui\"\u003ELink sheet callouts…\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EMarkupCraft reads the text of every sheet and lists each callout that names another open sheet, such as &quot;3/A-501&quot;, &quot;A-501&quot; or &quot;2 / A501&quot;. Callouts already linked, and a sheet&#039;s own number in its title block, are left out.\u003C/li\u003E\u003Cli\u003EUntick any you do not want, then choose \u003Cspan class=\"hui\"\u003ECreate the links\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EEach callout gets a thin blue box that is a sheet link. One \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E removes them all.\u003C/p\u003E\n\u003Cp\u003ESheets need numbers for this: from their title block, their page label, or \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E. Scanned sheets have no text to read; link their callouts one by one.\u003C/p\u003E\n\u003Ch2 id=\"in-the-saved-pdf\"\u003EIn the saved PDF\u003C/h2\u003E\n\u003Cp\u003EA link to a sheet in the same PDF is also written as a PDF link, so other viewers jump there on a click too. Links to a sheet in another file of the set work in MarkupCraft only.\u003C/p\u003E","text":"A sheet link takes you from a markup to another sheet of the set: from a detail bubble to the detail, from a note to the sheet it refers to. Link a markup to a sheet Select the markup. In Properties, pick the sheet under Link to sheet. A small arrow appears at the markup's top right. To follow it, hold Ctrl and click the markup, or select it and choose Go to … in Properties. Alt+← goes back to the sheet you came from. A link names the sheet by its number, so it still works after you reopen the set or slip-sheet a new issue: it opens the newest sheet with that number. If that sheet is not open, the status bar says so. Link every sheet callout at once Open Find text at the top of the Sheets panel and choose Link sheet callouts…. MarkupCraft reads the text of every sheet and lists each callout that names another open sheet, such as \"3/A-501\", \"A-501\" or \"2 / A501\". Callouts already linked, and a sheet's own number in its title block, are left out. Untick any you do not want, then choose Create the links. Each callout gets a thin blue box that is a sheet link. One Ctrl+Z removes them all. Sheets need numbers for this: from their title block, their page label, or Rename sheet. Scanned sheets have no text to read; link their callouts one by one. In the saved PDF A link to a sheet in the same PDF is also written as a PDF link, so other viewers jump there on a click too. Links to a sheet in another file of the set work in MarkupCraft only.","lang":"en"},{"slug":"save-the-marked-up-pdf","scope":"markupcraft","title":"Save the marked-up PDF","summary":"Download a copy with every markup written in as standard PDF comments, check what other PDF readers see, and keep working on it later.","section":"tasks","order":120,"keywords":["save","download","export pdf","marked up","annotations","comments","share","send","issue","keep working","reopen","round trip","print"],"headings":[{"id":"save","text":"Save","level":2},{"id":"keep-working-on-it-later","text":"Keep working on it later","level":2},{"id":"what-other-pdf-readers-see","text":"What other PDF readers see","level":2},{"id":"characters-that-print-as","text":"Characters that print as \"?\"","level":2},{"id":"files-that-cannot-be-saved","text":"Files that cannot be saved","level":2},{"id":"flattening-and-printing","text":"Flattening and printing","level":2}],"html":"\u003Ch2 id=\"save\"\u003ESave\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E in the toolbar, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003Cli\u003EIf several files are open, choose \u003Cspan class=\"hui\"\u003EThis file\u003C/span\u003E (the file of the sheet you are on) or \u003Cspan class=\"hui\"\u003EEvery changed file\u003C/span\u003E. Each copy downloads separately.\u003C/li\u003E\u003Cli\u003EWait for &quot;Saving &lt;file&gt;…&quot; to finish. The first save in a session also loads the PDF writer.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: your browser downloads &quot;&lt;name&gt; (marked up).pdf&quot;, and the status bar reports it: &#039;Saved A-Plans (marked up).pdf (24 markups, 18.2 MB). The original file is unchanged.&#039; The dot after \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E goes away.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EYour original PDF is never changed.\u003C/strong\u003E MarkupCraft writes a new file. Where it lands depends on your browser&#039;s download settings (see \u003Ca href=\"/tutorials/markupcraft/files#where-downloads-go\" data-topic=\"markupcraft/files\" data-hash=\"where-downloads-go\"\u003EFiles MarkupCraft opens and saves\u003C/a\u003E).\u003C/p\u003E\n\u003Ch2 id=\"keep-working-on-it-later\"\u003EKeep working on it later\u003C/h2\u003E\n\u003Cp\u003EOpen the &quot;(marked up)&quot; copy next time, not the original. Everything comes back editable: markups, statuses, replies, punch items, each sheet&#039;s scale and any sheet names you typed. Saving it again downloads a file with the same &quot;(marked up)&quot; name; your browser may add a number such as &quot;(1)&quot; if the old download is still in the folder. Replace or tidy old copies yourself.\u003C/p\u003E\n\u003Cp\u003EMarkupCraft does not save the PDF on its own. While you work it keeps a recovery copy in this browser, so a crash or a closed tab does not lose your markups: the next time you open MarkupCraft it asks &quot;Recover your work?&quot;. See \u003Ca href=\"/tutorials/basics/recover\" data-topic=\"basics/recover\"\u003ERecover your work\u003C/a\u003E. Still save before closing; if you try to leave with unsaved markups, the browser asks &quot;Leave site?&quot; first (iPad Safari does not).\u003C/p\u003E\n\u003Ch2 id=\"what-other-pdf-readers-see\"\u003EWhat other PDF readers see\u003C/h2\u003E\n\u003Cp\u003EEvery markup is written as a standard PDF comment (annotation) with its own drawing, so any PDF viewer shows it, prints it, and lists it in its comments panel:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EThe look is the same\u003C/strong\u003E as in MarkupCraft: clouds with their scallops, arrowheads, stamps, count dots, punch number badges, measurement labels.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EThe details are standard:\u003C/strong\u003E author, date, subject, the comment text, and colors.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EClouds\u003C/strong\u003E are rectangle or polygon comments with a cloudy border; \u003Cstrong\u003Etext boxes\u003C/strong\u003E and \u003Cstrong\u003Ecallouts\u003C/strong\u003E are text box comments; \u003Cstrong\u003Enotes\u003C/strong\u003E are sticky notes; \u003Cstrong\u003Epen\u003C/strong\u003E and \u003Cstrong\u003Ehighlighter\u003C/strong\u003E strokes are ink; \u003Cstrong\u003Estamps\u003C/strong\u003E are stamp comments.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ELengths and areas\u003C/strong\u003E are measurement comments, and each calibrated sheet carries its scale, so viewers that understand measurements can show the values.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EReplies\u003C/strong\u003E are replies to the comment, and \u003Cstrong\u003Estatuses\u003C/strong\u003E are review states (Open shows as no state).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESheet numbers\u003C/strong\u003E you typed become the page labels other viewers show.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EA few things only MarkupCraft reads back: the punch item&#039;s assignee and due date, item status, and some style details. Other programs keep them unless they rewrite the comment.\u003C/p\u003E\n\u003Cp\u003EIn another program, comments can be moved or edited like any other. If someone does that and sends the file back, MarkupCraft uses the comment&#039;s new position when it opens the file.\u003C/p\u003E\n\u003Cp\u003EFull detail: \u003Ca href=\"/tutorials/markupcraft/what-the-pdf-keeps\" data-topic=\"markupcraft/what-the-pdf-keeps\"\u003EWhat is saved in the PDF\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"characters-that-print-as\"\u003ECharacters that print as &quot;?&quot;\u003C/h2\u003E\n\u003Cp\u003EMarkup text is written with the standard Helvetica font that every PDF viewer has. It covers English and Western European letters (é, ñ, ü, ø, and the like), but not other scripts, symbols outside that set, or emoji. Those characters show fine in MarkupCraft but print as &quot;?&quot; in the saved copy, and the save message counts them: &quot;3 characters outside the Western European set print as &quot;?&quot; in the copy.&quot; Spell such words out, or use a plain substitute (for example &quot;dia.&quot; for the diameter sign).\u003C/p\u003E\n\u003Ch2 id=\"files-that-cannot-be-saved\"\u003EFiles that cannot be saved\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EProtected PDFs:\u003C/strong\u003E &quot;This PDF is protected (encrypted), so a marked-up copy cannot be written. Ask for an unprotected copy.&quot; You can still review it on screen, export the CSV and the BCF.\u003C/li\u003E\u003Cli\u003EIf saving fails for another reason, a box called &quot;Could not save &lt;file&gt;&quot; shows the reason. Your markups are still in the tab; nothing is lost until you close it.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"flattening-and-printing\"\u003EFlattening and printing\u003C/h2\u003E\n\u003Cp\u003EThere is no flatten (burning markups into the page) and no print command yet. To print, open the saved copy in any PDF viewer and print with comments shown.\u003C/p\u003E","text":"Save Choose Save in the toolbar, or press Ctrl+S. If several files are open, choose This file (the file of the sheet you are on) or Every changed file. Each copy downloads separately. Wait for \"Saving \u003Cfile\u003E…\" to finish. The first save in a session also loads the PDF writer. Result: your browser downloads \"\u003Cname\u003E (marked up).pdf\", and the status bar reports it: 'Saved A-Plans (marked up).pdf (24 markups, 18.2 MB). The original file is unchanged.' The dot after Save goes away. Your original PDF is never changed. MarkupCraft writes a new file. Where it lands depends on your browser's download settings (see Files MarkupCraft opens and saves). Keep working on it later Open the \"(marked up)\" copy next time, not the original. Everything comes back editable: markups, statuses, replies, punch items, each sheet's scale and any sheet names you typed. Saving it again downloads a file with the same \"(marked up)\" name; your browser may add a number such as \"(1)\" if the old download is still in the folder. Replace or tidy old copies yourself. MarkupCraft does not save the PDF on its own. While you work it keeps a recovery copy in this browser, so a crash or a closed tab does not lose your markups: the next time you open MarkupCraft it asks \"Recover your work?\". See Recover your work. Still save before closing; if you try to leave with unsaved markups, the browser asks \"Leave site?\" first (iPad Safari does not). What other PDF readers see Every markup is written as a standard PDF comment (annotation) with its own drawing, so any PDF viewer shows it, prints it, and lists it in its comments panel: The look is the same as in MarkupCraft: clouds with their scallops, arrowheads, stamps, count dots, punch number badges, measurement labels. The details are standard: author, date, subject, the comment text, and colors. Clouds are rectangle or polygon comments with a cloudy border; text boxes and callouts are text box comments; notes are sticky notes; pen and highlighter strokes are ink; stamps are stamp comments. Lengths and areas are measurement comments, and each calibrated sheet carries its scale, so viewers that understand measurements can show the values. Replies are replies to the comment, and statuses are review states (Open shows as no state). Sheet numbers you typed become the page labels other viewers show. A few things only MarkupCraft reads back: the punch item's assignee and due date, item status, and some style details. Other programs keep them unless they rewrite the comment. In another program, comments can be moved or edited like any other. If someone does that and sends the file back, MarkupCraft uses the comment's new position when it opens the file. Full detail: What is saved in the PDF. Characters that print as \"?\" Markup text is written with the standard Helvetica font that every PDF viewer has. It covers English and Western European letters (é, ñ, ü, ø, and the like), but not other scripts, symbols outside that set, or emoji. Those characters show fine in MarkupCraft but print as \"?\" in the saved copy, and the save message counts them: \"3 characters outside the Western European set print as \"?\" in the copy.\" Spell such words out, or use a plain substitute (for example \"dia.\" for the diameter sign). Files that cannot be saved Protected PDFs: \"This PDF is protected (encrypted), so a marked-up copy cannot be written. Ask for an unprotected copy.\" You can still review it on screen, export the CSV and the BCF. If saving fails for another reason, a box called \"Could not save \u003Cfile\u003E\" shows the reason. Your markups are still in the tab; nothing is lost until you close it. Flattening and printing There is no flatten (burning markups into the page) and no print command yet. To print, open the saved copy in any PDF viewer and print with comments shown.","lang":"en"},{"slug":"flatten","scope":"markupcraft","title":"Save a flattened copy","summary":"Draw your markups into the pages of a separate copy, so nobody can move or change them.","section":"tasks","order":122,"keywords":["flatten","flattened","lock","burn in","merge markups","final","issue","permanent","cannot edit","print ready"],"headings":[{"id":"save-a-flattened-copy","text":"Save a flattened copy","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003EA flattened copy carries the markups as part of the drawing, not as comments. Every viewer and printer shows them exactly, and nobody can move, edit or delete them. Use it for a final issue; keep the normal marked-up copy for review.\u003C/p\u003E\n\u003Ch2 id=\"save-a-flattened-copy\"\u003ESave a flattened copy\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen a sheet of the file you want to flatten.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003ESave a flattened copy…\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EEvery markup in this file\u003C/span\u003E, or, with markups selected, only those. The others stay comments in the copy.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave the copy\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: your browser downloads &quot;&lt;name&gt; (flattened).pdf&quot;. The markups in MarkupCraft stay editable, and your original PDF is unchanged.\u003C/p\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EReplies, statuses and punch items of a flattened markup are not kept in the copy: it is a picture of the markup now.\u003C/li\u003E\u003Cli\u003EComments that came with the file from other programs stay comments.\u003C/li\u003E\u003Cli\u003EPrinting flattens a copy for you each time. See \u003Ca href=\"/tutorials/markupcraft/pages-and-printing\" data-topic=\"markupcraft/pages-and-printing\"\u003EPrint, and change the pages\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E","text":"A flattened copy carries the markups as part of the drawing, not as comments. Every viewer and printer shows them exactly, and nobody can move, edit or delete them. Use it for a final issue; keep the normal marked-up copy for review. Save a flattened copy Open a sheet of the file you want to flatten. Choose Pages, then Save a flattened copy…. Choose Every markup in this file, or, with markups selected, only those. The others stay comments in the copy. Choose Save the copy. Result: your browser downloads \"\u003Cname\u003E (flattened).pdf\". The markups in MarkupCraft stay editable, and your original PDF is unchanged. Good to know Replies, statuses and punch items of a flattened markup are not kept in the copy: it is a picture of the markup now. Comments that came with the file from other programs stay comments. Printing flattens a copy for you each time. See Print, and change the pages.","lang":"en"},{"slug":"pages-and-printing","scope":"markupcraft","title":"Print, and change the pages of a PDF","summary":"Print sheets with their markups, and rotate, move, insert, delete or extract pages of an open PDF.","section":"tasks","order":125,"keywords":["print","printer","paper","pages","page","rotate","turn","reorder","move page","insert","add page","blank page","delete page","remove page","extract","split","page operations"],"headings":[{"id":"print","text":"Print","level":2},{"id":"turn-a-page","text":"Turn a page","level":2},{"id":"move-a-page","text":"Move a page","level":2},{"id":"insert-pages","text":"Insert pages","level":2},{"id":"delete-pages","text":"Delete pages","level":2},{"id":"extract-pages","text":"Extract pages","level":2},{"id":"good-to-know","text":"Good to know","level":2}],"html":"\u003Cp\u003EThe \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E menu in the \u003Cspan class=\"hui\"\u003EFile\u003C/span\u003E group works on the PDF that the open sheet belongs to. Your PDF on this computer is never changed: the changes are part of the copy you save.\u003C/p\u003E\n\u003Ch2 id=\"print\"\u003EPrint\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command P\"\u003E⌘P\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+P\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EPrint…\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EWhen more than one sheet is open, pick what to print: \u003Cspan class=\"hui\"\u003EThis sheet\u003C/span\u003E, every page of this file, the whole set, or the pages you type (such as \u003Ccode\u003E1-3, 5\u003C/code\u003E).\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EPrint\u003C/span\u003E. Your browser&#039;s printer dialog opens: pick the printer, the paper and the scale there.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EThe markups print as they look on the sheet: they are drawn into the pages of the copy that goes to the printer. Comments other programs made print the way their PDF says.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari,firefox\"\u003E\u003Cp class=\"hv-label\"\u003ESafari or Firefox\u003C/p\u003E\n\u003Cp\u003EIf your browser cannot print from inside the page, the sheets open as a PDF in a new tab. Print from there.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"turn-a-page\"\u003ETurn a page\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003ERotate page clockwise\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ERotate page counterclockwise\u003C/span\u003E. The open sheet turns a quarter turn. Its markups stay where they were on the drawing, and text you typed turns with the page so it still reads upright.\u003C/p\u003E\n\u003Ch2 id=\"move-a-page\"\u003EMove a page\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EMove page earlier\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EMove page later\u003C/span\u003E. The open sheet swaps places with its neighbor in its own PDF. Its markups, its scale and its sheet number go with it.\u003C/p\u003E\n\u003Ch2 id=\"insert-pages\"\u003EInsert pages\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EInsert pages from a PDF…\u003C/span\u003E puts every page of another PDF after the open sheet.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EInsert a blank page\u003C/span\u003E adds an empty page of the same size after the open sheet, for sketches and notes. In a set made with \u003Cspan class=\"hui\"\u003ENew\u003C/span\u003E, it has the set&#039;s grid too.\u003C/li\u003E\u003Cli\u003EIn a set made with \u003Cspan class=\"hui\"\u003ENew\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EAdd a blank page\u003C/span\u003E under the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E list adds one more page like the others at the end. See \u003Ca href=\"/tutorials/markupcraft/open-a-plan-set#start-with-blank-pages\" data-topic=\"markupcraft/open-a-plan-set\" data-hash=\"start-with-blank-pages\"\u003EStart with blank pages\u003C/a\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EInserted pages get their page number as their label until you rename them. See \u003Ca href=\"/tutorials/markupcraft/open-a-plan-set#rename-a-sheet\" data-topic=\"markupcraft/open-a-plan-set\" data-hash=\"rename-a-sheet\"\u003ERename a sheet\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"delete-pages\"\u003EDelete pages\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EDelete pages…\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EType the page numbers of this PDF, such as \u003Ccode\u003E3\u003C/code\u003E or \u003Ccode\u003E2-4\u003C/code\u003E. The open sheet&#039;s page is filled in.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EDelete pages\u003C/span\u003E. If those pages hold markups, MarkupCraft says how many and asks again.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EA PDF keeps at least one page. To drop a whole file, close the set and open the files you still need.\u003C/p\u003E\n\u003Ch2 id=\"extract-pages\"\u003EExtract pages\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EExtract pages…\u003C/span\u003E, and type the pages. They download as a new PDF named &quot;&lt;file&gt; (pages 1-3).pdf&quot;, with their markups as comments you can keep editing. The open file stays as it is.\u003C/p\u003E\n\u003Ch2 id=\"good-to-know\"\u003EGood to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EUndo stops at a page change.\u003C/strong\u003E \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E undoes markups drawn after it, but not the page change itself or anything before it. Close without saving to start over from your original PDF.\u003C/li\u003E\u003Cli\u003EPage numbers count the pages of one PDF, not the whole set. Moving a page keeps it inside its own file.\u003C/li\u003E\u003Cli\u003EThe changed pages are unsaved work: \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E downloads the reorganized copy, and leaving asks first.\u003C/li\u003E\u003C/ul\u003E","text":"The Pages menu in the File group works on the PDF that the open sheet belongs to. Your PDF on this computer is never changed: the changes are part of the copy you save. Print Press Ctrl+P, or choose Pages, then Print…. When more than one sheet is open, pick what to print: This sheet, every page of this file, the whole set, or the pages you type (such as 1-3, 5). Choose Print. Your browser's printer dialog opens: pick the printer, the paper and the scale there. The markups print as they look on the sheet: they are drawn into the pages of the copy that goes to the printer. Comments other programs made print the way their PDF says. If your browser cannot print from inside the page, the sheets open as a PDF in a new tab. Print from there. Turn a page Choose Pages, then Rotate page clockwise or Rotate page counterclockwise. The open sheet turns a quarter turn. Its markups stay where they were on the drawing, and text you typed turns with the page so it still reads upright. Move a page Choose Pages, then Move page earlier or Move page later. The open sheet swaps places with its neighbor in its own PDF. Its markups, its scale and its sheet number go with it. Insert pages Insert pages from a PDF… puts every page of another PDF after the open sheet. Insert a blank page adds an empty page of the same size after the open sheet, for sketches and notes. In a set made with New, it has the set's grid too. In a set made with New, Add a blank page under the Sheets list adds one more page like the others at the end. See Start with blank pages. Inserted pages get their page number as their label until you rename them. See Rename a sheet. Delete pages Choose Pages, then Delete pages…. Type the page numbers of this PDF, such as 3 or 2-4. The open sheet's page is filled in. Choose Delete pages. If those pages hold markups, MarkupCraft says how many and asks again. A PDF keeps at least one page. To drop a whole file, close the set and open the files you still need. Extract pages Choose Pages, then Extract pages…, and type the pages. They download as a new PDF named \"\u003Cfile\u003E (pages 1-3).pdf\", with their markups as comments you can keep editing. The open file stays as it is. Good to know Undo stops at a page change. Ctrl+Z undoes markups drawn after it, but not the page change itself or anything before it. Close without saving to start over from your original PDF. Page numbers count the pages of one PDF, not the whole set. Moving a page keeps it inside its own file. The changed pages are unsaved work: Save downloads the reorganized copy, and leaving asks first.","lang":"en"},{"slug":"page-content","scope":"markupcraft","title":"Change the page's own lines, pictures and text","summary":"Move, resize, recolor or delete what the PDF itself draws, move a line's points, replace a picture, and change the words of a line of text.","section":"tasks","order":128,"keywords":["page content","base content","edit pdf","edit drawing","vector","path","shape","line","picture","image","replace image","text","words","font","points","nodes","move","resize","recolor","delete","content tool"],"headings":[{"id":"pick-what-to-change","text":"Pick what to change","level":2},{"id":"move-resize-recolor-delete","text":"Move, resize, recolor, delete","level":2},{"id":"move-a-line-s-points","text":"Move a line's points","level":2},{"id":"replace-a-picture","text":"Replace a picture","level":2},{"id":"change-the-words-of-a-line-of-text","text":"Change the words of a line of text","level":2},{"id":"what-markupcraft-leaves-as-it-is","text":"What MarkupCraft leaves as it is","level":2},{"id":"put-markups-into-the-page","text":"Put markups into the page","level":2}],"html":"\u003Cp\u003EMarkups sit on top of a sheet. The \u003Cspan class=\"hui\"\u003EContent\u003C/span\u003E tool works on the sheet itself: the lines, pictures and lines of text the PDF draws. Your PDF on this computer is never changed: the edits are part of the copy you save.\u003C/p\u003E\n\u003Ch2 id=\"pick-what-to-change\"\u003EPick what to change\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EContent\u003C/span\u003E in the \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E group, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"B\"\u003EB\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EB\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003Cli\u003EUnder \u003Cspan class=\"hui\"\u003EPick\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, turn \u003Cspan class=\"hui\"\u003EShapes\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPictures\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EText\u003C/span\u003E on or off. Only the kinds that are on can be picked, so you can pick the text of a busy drawing without catching its lines.\u003C/li\u003E\u003Cli\u003EClick something to select it. Shift+click adds or removes. Drag a box over empty paper to select several: dragging to the right takes what is fully inside the box, dragging to the left takes what it touches.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EA shape inside a clipped area is picked only where it shows.\u003C/p\u003E\n\u003Ch2 id=\"move-resize-recolor-delete\"\u003EMove, resize, recolor, delete\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EMove:\u003C/strong\u003E drag a selected object, or press the arrow keys (hold Shift for bigger steps). Hold Shift while dragging to move straight across or straight up.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EResize:\u003C/strong\u003E drag one of the eight squares around the selection. It grows or shrinks from the opposite side. Hold Shift to keep the proportions.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ERecolor:\u003C/strong\u003E for lines and shapes, set \u003Cspan class=\"hui\"\u003ELine color\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFill color\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ELine width (pt)\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EDelete:\u003C/strong\u003E press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EDelete from the page\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EUndo:\u003C/strong\u003E each change is one step: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes it back, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Y\"\u003E⌘Y\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Y\u003C/span\u003E\u003C/kbd\u003E puts it back.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EPut back as it was\u003C/span\u003E undoes every change to the selected objects at once; \u003Cspan class=\"hui\"\u003EPut this page back as it was\u003C/span\u003E does it for the whole page.\u003C/p\u003E\n\u003Ch2 id=\"move-a-line-s-points\"\u003EMove a line&#039;s points\u003C/h2\u003E\n\u003Cp\u003EDouble-click a line or curve (or select it and choose \u003Cspan class=\"hui\"\u003EEdit points\u003C/span\u003E). Its points show as squares and its curve handles as circles. Drag a point or a handle; a point brings the handles next to it along, so the curve keeps its shape around it. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E, or click away from the line, when you are done.\u003C/p\u003E\n\u003Cp\u003ERectangles have no points to drag: resize them with the squares around them.\u003C/p\u003E\n\u003Ch2 id=\"replace-a-picture\"\u003EReplace a picture\u003C/h2\u003E\n\u003Cp\u003ESelect a picture and choose \u003Cspan class=\"hui\"\u003EReplace picture…\u003C/span\u003E, then pick a PNG or JPEG file. The new picture fills the old one&#039;s place, keeping its own proportions.\u003C/p\u003E\n\u003Ch2 id=\"change-the-words-of-a-line-of-text\"\u003EChange the words of a line of text\u003C/h2\u003E\n\u003Cp\u003EDouble-click a line of text, type the new words in \u003Cspan class=\"hui\"\u003EWords\u003C/span\u003E and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E. The words are written in the line&#039;s own font and size, and the line keeps its length, so the text after it does not move.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EMost PDFs carry only the letters they use from each font. When you type a letter the file&#039;s copy of the font does not have, MarkupCraft prints that letter in Helvetica and says so. \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E shows which letters the font in the file has.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003EText is changed one line at a time; it does not flow into the next line.\u003C/p\u003E\n\u003Ch2 id=\"what-markupcraft-leaves-as-it-is\"\u003EWhat MarkupCraft leaves as it is\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EScanned pages\u003C/strong\u003E are one picture: you can move, resize, replace or delete the picture, but what is in it can&#039;t be edited.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EEncrypted and signed PDFs:\u003C/strong\u003E changing the page would break a signature, so the \u003Cspan class=\"hui\"\u003EContent\u003C/span\u003E tool says so and changes nothing. Markups still work.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EClipping areas\u003C/strong\u003E, objects split between two parts of the page&#039;s content, and color blends that fill a whole area stay as they are; MarkupCraft says why when you try.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EWords in a standard font the PDF does not describe\u003C/strong\u003E (such as a Times font with no letter widths in the file) can&#039;t be changed, because MarkupCraft could not keep the line&#039;s spacing. The line can still be moved.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"put-markups-into-the-page\"\u003EPut markups into the page\u003C/h2\u003E\n\u003Cp\u003ELines, rectangles, ellipses, polylines, clouds and pen strokes you drew as markups can become part of the page itself: select them and choose \u003Cspan class=\"hui\"\u003EPut into the page\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E. Text, stamps, pictures and see-through colors stay markups.\u003C/p\u003E","text":"Markups sit on top of a sheet. The Content tool works on the sheet itself: the lines, pictures and lines of text the PDF draws. Your PDF on this computer is never changed: the edits are part of the copy you save. Pick what to change Choose Content in the Select group, or press B. Under Pick in Properties, turn Shapes, Pictures and Text on or off. Only the kinds that are on can be picked, so you can pick the text of a busy drawing without catching its lines. Click something to select it. Shift+click adds or removes. Drag a box over empty paper to select several: dragging to the right takes what is fully inside the box, dragging to the left takes what it touches. A shape inside a clipped area is picked only where it shows. Move, resize, recolor, delete Move: drag a selected object, or press the arrow keys (hold Shift for bigger steps). Hold Shift while dragging to move straight across or straight up. Resize: drag one of the eight squares around the selection. It grows or shrinks from the opposite side. Hold Shift to keep the proportions. Recolor: for lines and shapes, set Line color, Fill color and Line width (pt) in Properties. Delete: press Delete, or choose Delete from the page. Undo: each change is one step: Ctrl+Z takes it back, Ctrl+Y puts it back. Put back as it was undoes every change to the selected objects at once; Put this page back as it was does it for the whole page. Move a line's points Double-click a line or curve (or select it and choose Edit points). Its points show as squares and its curve handles as circles. Drag a point or a handle; a point brings the handles next to it along, so the curve keeps its shape around it. Press Esc, or click away from the line, when you are done. Rectangles have no points to drag: resize them with the squares around them. Replace a picture Select a picture and choose Replace picture…, then pick a PNG or JPEG file. The new picture fills the old one's place, keeping its own proportions. Change the words of a line of text Double-click a line of text, type the new words in Words and press Enter. The words are written in the line's own font and size, and the line keeps its length, so the text after it does not move. Most PDFs carry only the letters they use from each font. When you type a letter the file's copy of the font does not have, MarkupCraft prints that letter in Helvetica and says so. Properties shows which letters the font in the file has. Text is changed one line at a time; it does not flow into the next line. What MarkupCraft leaves as it is Scanned pages are one picture: you can move, resize, replace or delete the picture, but what is in it can't be edited. Encrypted and signed PDFs: changing the page would break a signature, so the Content tool says so and changes nothing. Markups still work. Clipping areas, objects split between two parts of the page's content, and color blends that fill a whole area stay as they are; MarkupCraft says why when you try. Words in a standard font the PDF does not describe (such as a Times font with no letter widths in the file) can't be changed, because MarkupCraft could not keep the line's spacing. The line can still be moved. Put markups into the page Lines, rectangles, ellipses, polylines, clouds and pen strokes you drew as markups can become part of the page itself: select them and choose Put into the page in Properties. Text, stamps, pictures and see-through colors stay markups.","lang":"en"},{"slug":"work-live","scope":"markupcraft","title":"Review one plan set together, live","summary":"What changes in MarkupCraft while you are in a CadCraft Studio live session: everyone's markups, replies and statuses on the same set, your own undo, and joining from a browser on the same network.","section":"tasks","order":128,"keywords":["live","studio live","together","collaborate","review together","session","share live","join","replies","status","punch","undo","host"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"everyone-marks-up-at-once","text":"Everyone marks up at once","level":2},{"id":"when-a-change-is-taken-back","text":"When a change is taken back","level":2},{"id":"undo-undoes-your-own-work","text":"Undo undoes your own work","level":2},{"id":"join-from-a-browser","text":"Join from a browser","level":2},{"id":"when-the-session-ends","text":"When the session ends","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EWhat happens to markups while several people review one plan set at the same time. CadCraft Studio starts and joins the session (Share live, Join); this page is about the set itself.\u003C/p\u003E\n\u003Ch2 id=\"everyone-marks-up-at-once\"\u003EEveryone marks up at once\u003C/h2\u003E\n\u003Cp\u003EThe host&#039;s PDFs come to everyone who joins, so all of you look at the same sheets. Draw, move, restyle and delete markups as usual. Your own changes show at once; other people&#039;s appear a moment after they make them.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ETwo people change one markup:\u003C/strong\u003E different things (one the colour, the other the line weight) are both kept. The same thing goes to the later change.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EReplies:\u003C/strong\u003E everyone&#039;s replies stay on the thread, in the order they were written. Statuses travel the same way.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EScales and sheet names\u003C/strong\u003E set by anyone apply for everyone.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPunch numbers\u003C/strong\u003E never repeat: if two people add a punch item at the same moment, one of them is taken back and can add it again.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EWhat stays yours alone: layers you hide or lock, custom columns, the view, your tool and your name as the author.\u003C/p\u003E\n\u003Ch2 id=\"when-a-change-is-taken-back\"\u003EWhen a change is taken back\u003C/h2\u003E\n\u003Cp\u003EThe host&#039;s copy checks every change. One that can&#039;t go in is taken back on your screen, and the status bar says why, for example when someone deleted that markup just before you.\u003C/p\u003E\n\u003Ch2 id=\"undo-undoes-your-own-work\"\u003EUndo undoes your own work\u003C/h2\u003E\n\u003Cp\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E undoes your own last change and leaves everyone else&#039;s alone. When someone changed the same thing since, nothing is undone and the status bar says who.\u003C/p\u003E\n\u003Ch2 id=\"join-from-a-browser\"\u003EJoin from a browser\u003C/h2\u003E\n\u003Cp\u003EA teammate without Studio can scan the picture under the host&#039;s code with a phone, tablet or computer on the same network. MarkupCraft opens in the browser and fills with the host&#039;s plan set once the host lets you in. Invite links, for joining from another network, are not open yet.\u003C/p\u003E\n\u003Ch2 id=\"when-the-session-ends\"\u003EWhen the session ends\u003C/h2\u003E\n\u003Cp\u003EOnly the host saves the marked-up PDFs. Everyone else keeps an unsaved copy: save it if you want to keep it.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EPDFs you open after joining stay on your own screen: the others don&#039;t get them.\u003C/p\u003E\n\u003C/aside\u003E","text":"What you will learn What happens to markups while several people review one plan set at the same time. CadCraft Studio starts and joins the session (Share live, Join); this page is about the set itself. Everyone marks up at once The host's PDFs come to everyone who joins, so all of you look at the same sheets. Draw, move, restyle and delete markups as usual. Your own changes show at once; other people's appear a moment after they make them. Two people change one markup: different things (one the colour, the other the line weight) are both kept. The same thing goes to the later change. Replies: everyone's replies stay on the thread, in the order they were written. Statuses travel the same way. Scales and sheet names set by anyone apply for everyone. Punch numbers never repeat: if two people add a punch item at the same moment, one of them is taken back and can add it again. What stays yours alone: layers you hide or lock, custom columns, the view, your tool and your name as the author. When a change is taken back The host's copy checks every change. One that can't go in is taken back on your screen, and the status bar says why, for example when someone deleted that markup just before you. Undo undoes your own work Ctrl+Z undoes your own last change and leaves everyone else's alone. When someone changed the same thing since, nothing is undone and the status bar says who. Join from a browser A teammate without Studio can scan the picture under the host's code with a phone, tablet or computer on the same network. MarkupCraft opens in the browser and fills with the host's plan set once the host lets you in. Invite links, for joining from another network, are not open yet. When the session ends Only the host saves the marked-up PDFs. Everyone else keeps an unsaved copy: save it if you want to keep it. PDFs you open after joining stay on your own screen: the others don't get them.","lang":"en"},{"slug":"several-files","scope":"markupcraft","title":"Work with several files at once","summary":"Open many PDFs as one set, find sheets across files, copy markups between them, and save each file's copy.","section":"tasks","order":130,"keywords":["several files","multiple pdfs","plan set","set","batch","many files","combine","disciplines","architectural structural mechanical","save all","close"],"headings":[{"id":"open-them-together","text":"Open them together","level":2},{"id":"across-the-whole-set","text":"Across the whole set","level":2},{"id":"save","text":"Save","level":2},{"id":"close","text":"Close","level":2},{"id":"big-sets","text":"Big sets","level":2}],"html":"\u003Cp\u003EA plan set often arrives as one PDF per discipline, or one PDF per sheet. MarkupCraft treats everything you open as \u003Cstrong\u003Eone set\u003C/strong\u003E.\u003C/p\u003E\n\u003Ch2 id=\"open-them-together\"\u003EOpen them together\u003C/h2\u003E\n\u003Cp\u003ESelect all the PDFs in the file picker at once, or drop them all on the sheet area. To add more later, open them the same way; they join the end of the \u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E list in the order you open them.\u003C/p\u003E\n\u003Cp\u003EResult: &quot;Opened 6 files (84 sheets in the set).&quot; Every page is a sheet. Sheets with a sheet number show &quot;Sheet A-101&quot; under their name; others show the file and page.\u003C/p\u003E\n\u003Cp\u003EThere is no saved &quot;set&quot; file: next time, open the same PDFs again (the &quot;(marked up)&quot; copies, if you saved).\u003C/p\u003E\n\u003Ch2 id=\"across-the-whole-set\"\u003EAcross the whole set\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EFind a sheet:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ESearch sheets\u003C/span\u003E looks in sheet numbers, sheet names and file names of every file. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↑\"\u003Efn ↑\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Up\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↓\"\u003Efn ↓\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Down\u003C/span\u003E\u003C/kbd\u003E walk through all sheets of all files in order.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMarkups list:\u003C/strong\u003E the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab lists markups from every file. Filter by \u003Cspan class=\"hui\"\u003ESheet\u003C/span\u003E to narrow it. The CSV has a File column.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPunch list:\u003C/strong\u003E one numbering for the whole set.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECompare:\u003C/strong\u003E the old and the new sheet can come from different files.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECopy and paste:\u003C/strong\u003E \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E on one sheet and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E on another, in any file. The copy lands at the same place on the page, slightly offset.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"save\"\u003ESave\u003C/h2\u003E\n\u003Cp\u003EChoose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E. With more than one file open, MarkupCraft asks:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EThis file\u003C/span\u003E: a marked-up copy of the file of the sheet you are on.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EEvery changed file\u003C/span\u003E: a copy of each file that has unsaved changes. Each downloads separately, as &quot;&lt;file name&gt; (marked up).pdf&quot;.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ECancel\u003C/span\u003E\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:chromium\"\u003E\u003Cp class=\"hv-label\"\u003EChrome or Edge\u003C/p\u003E\n\u003Cp\u003EThe first time you save several files at once, Chrome and Edge may ask whether this site may download multiple files. Choose \u003Cspan class=\"hui\"\u003EAllow\u003C/span\u003E; otherwise only the first copy arrives.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003ESafari may ask once for each file. On an iPad each copy goes to the Files app.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cp\u003EA file whose markups were saved stops counting as changed; the others still do.\u003C/p\u003E\n\u003Cp\u003ECSV, BCF and punch list exports are named after the \u003Cstrong\u003Efirst\u003C/strong\u003E file you opened.\u003C/p\u003E\n\u003Ch2 id=\"close\"\u003EClose\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E closes the whole set; there is no way to close just one file yet. If anything is unsaved, it asks:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ECancel\u003C/span\u003E: nothing happens.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EClose without saving\u003C/span\u003E: unsaved markups are lost.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ESave copies first\u003C/span\u003E: saves every changed file, then closes.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EClosing also clears undo history.\u003C/p\u003E\n\u003Ch2 id=\"big-sets\"\u003EBig sets\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EEvery page&#039;s text is read on open to find sheet numbers, so a 100-sheet set takes a while. The status bar counts sheets as it goes.\u003C/li\u003E\u003Cli\u003ESheet pictures in the list are drawn as you scroll to them.\u003C/li\u003E\u003Cli\u003EEach open PDF is held in the browser tab&#039;s memory. If the tab slows down, close other heavy tabs, or review one discipline at a time.\u003C/li\u003E\u003Cli\u003EOpening the same file twice gives you two copies of its sheets. If that happens, choose \u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E and open the set again.\u003C/li\u003E\u003C/ul\u003E","text":"A plan set often arrives as one PDF per discipline, or one PDF per sheet. MarkupCraft treats everything you open as one set. Open them together Select all the PDFs in the file picker at once, or drop them all on the sheet area. To add more later, open them the same way; they join the end of the Sheets list in the order you open them. Result: \"Opened 6 files (84 sheets in the set).\" Every page is a sheet. Sheets with a sheet number show \"Sheet A-101\" under their name; others show the file and page. There is no saved \"set\" file: next time, open the same PDFs again (the \"(marked up)\" copies, if you saved). Across the whole set Find a sheet: Search sheets looks in sheet numbers, sheet names and file names of every file. Page Up and Page Down walk through all sheets of all files in order. Markups list: the Markups tab lists markups from every file. Filter by Sheet to narrow it. The CSV has a File column. Punch list: one numbering for the whole set. Compare: the old and the new sheet can come from different files. Copy and paste: Ctrl+C on one sheet and Ctrl+V on another, in any file. The copy lands at the same place on the page, slightly offset. Save Choose Save. With more than one file open, MarkupCraft asks: This file: a marked-up copy of the file of the sheet you are on. Every changed file: a copy of each file that has unsaved changes. Each downloads separately, as \"\u003Cfile name\u003E (marked up).pdf\". Cancel The first time you save several files at once, Chrome and Edge may ask whether this site may download multiple files. Choose Allow; otherwise only the first copy arrives. Safari may ask once for each file. On an iPad each copy goes to the Files app. A file whose markups were saved stops counting as changed; the others still do. CSV, BCF and punch list exports are named after the first file you opened. Close Close closes the whole set; there is no way to close just one file yet. If anything is unsaved, it asks: Cancel: nothing happens. Close without saving: unsaved markups are lost. Save copies first: saves every changed file, then closes. Closing also clears undo history. Big sets Every page's text is read on open to find sheet numbers, so a 100-sheet set takes a while. The status bar counts sheets as it goes. Sheet pictures in the list are drawn as you scroll to them. Each open PDF is held in the browser tab's memory. If the tab slows down, close other heavy tabs, or review one discipline at a time. Opening the same file twice gives you two copies of its sheets. If that happens, choose Close and open the set again.","lang":"en"},{"slug":"use-with-ai-assistants","scope":"markupcraft","title":"Use MarkupCraft with an AI assistant","summary":"Let your own AI assistant or script list the markups of a set, add simple ones, set their status, reply and export the list: permissions, connecting through CadCraft Studio, and the activity log.","section":"tasks","order":135,"keywords":["ai","assistant","agent","mcp","model context protocol","script","automation","markups","review","permissions","disconnect","activity"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"turn-it-on","text":"Turn it on","level":2},{"id":"connect-your-assistant","text":"Connect your assistant","level":2},{"id":"you-stay-in-charge","text":"You stay in charge","level":2},{"id":"what-an-assistant-can-ask-for","text":"What an assistant can ask for","level":2},{"id":"if-something-doesn-t-work","text":"If something doesn't work","level":2},{"id":"see-also","text":"See also","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EHow to let an AI assistant (or a script you wrote) work with MarkupCraft, and how to decide what it is allowed to touch.\u003C/p\u003E\n\u003Cp\u003EMarkupCraft has \u003Cstrong\u003Eno AI of its own\u003C/strong\u003E and sends nothing anywhere. You bring the assistant: any program that speaks the Model Context Protocol (MCP). MarkupCraft only gives it tools, and you choose which.\u003C/p\u003E\n\u003Ch2 id=\"turn-it-on\"\u003ETurn it on\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E (the gear in the app bar, or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E) and go to the \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E tab.\u003C/li\u003E\u003Cli\u003EUnder \u003Cspan class=\"hui\"\u003EAssistants\u003C/span\u003E, tick \u003Cstrong\u003ELet AI assistants and scripts use MarkupCraft\u003C/strong\u003E. It is off until you do.\u003C/li\u003E\u003Cli\u003EChoose what it may do: \u003Cstrong\u003ERead\u003C/strong\u003E is ticked to start with; tick \u003Cstrong\u003EEdit\u003C/strong\u003E, \u003Cstrong\u003ESave\u003C/strong\u003E or \u003Cstrong\u003EExport\u003C/strong\u003E only when you need them.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ETools outside the permissions you ticked are not offered to the assistant, and if it asks for one anyway, MarkupCraft refuses and writes it in the activity log. Turning the switch off ends every connection at once; \u003Cspan class=\"hui\"\u003EReset MarkupCraft settings\u003C/span\u003E turns it off too.\u003C/p\u003E\n\u003Ch2 id=\"connect-your-assistant\"\u003EConnect your assistant\u003C/h2\u003E\n\u003Cp\u003EAssistants connect through \u003Cstrong\u003ECadCraft Studio\u003C/strong\u003E on your computer: Studio runs a small server only this computer can reach, protected by a token it makes each time it starts. In Studio, choose \u003Cspan class=\"hui\"\u003EConnect an assistant\u003C/span\u003E and copy the address and the token into your assistant (Studio shows the exact settings to paste). Never share the token.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EA browser tab can&#039;t open a connection for an assistant: in the browser apps the switch has no effect until you use CadCraft Studio on your computer.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"you-stay-in-charge\"\u003EYou stay in charge\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EEvery change is one undo step\u003C/strong\u003E, labelled with the assistant&#039;s name for it (for example &quot;Assistant: add cloudrect&quot;). \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E takes back the assistant&#039;s last change as a whole.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EYou know when one is connected.\u003C/strong\u003E A button in the app bar names the assistant while it is connected; click it to see what it may do, or to \u003Cstrong\u003EDisconnect\u003C/strong\u003E it.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EActivity.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EAssistants\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EActivity\u003C/span\u003E lists every call: when, which tool, done or refused. \u003Cspan class=\"hui\"\u003ESave the log\u003C/span\u003E keeps a copy.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"what-an-assistant-can-ask-for\"\u003EWhat an assistant can ask for\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ETool\u003C/th\u003E\u003Cth scope=\"col\"\u003EPermission\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003Eapp_info\u003C/code\u003E, \u003Ccode\u003Esheets_list\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003ERead\u003C/td\u003E\u003Ctd\u003EThe sets open, their sheets and how many markups each has\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003Emarkups_list\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003ERead\u003C/td\u003E\u003Ctd\u003EThe markups with type, sheet, text, comment, measurement, status, author and replies, filtered by sheet, status, type or author\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003Emarkup_add\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003EEdit\u003C/td\u003E\u003Ctd\u003EAdds a rectangle, cloud, ellipse, text box, note, line or arrow to a sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003Emarkup_status\u003C/code\u003E, \u003Ccode\u003Emarkup_reply\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003EEdit\u003C/td\u003E\u003Ctd\u003ESets a markup&#039;s status (logged in its thread, signed by the assistant); adds a comment to a thread\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003Emarkups_export\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003EExport\u003C/td\u003E\u003Ctd\u003EThe \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E list&#039;s own CSV or BCF of what the list shows (its filters as you set them); in Studio it can write the file to a folder you allowed\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EA markup an assistant adds names it as the author: the name the assistant program gives itself, followed by &quot;(assistant)&quot;, or by &quot;(assistant for &lt;your name&gt;)&quot; once you have set your reviewer name. Its status changes and replies are signed the same way. Each is one undo step. Saving the marked-up PDF stays with you: use \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E as usual.\u003C/p\u003E\n\u003Cp\u003EWithout opening MarkupCraft, the CadCraft MCP server lists the markups of a PDF in a folder you name (\u003Ccode\u003Emarkups_list\u003C/code\u003E), and \u003Ccode\u003Ecadcraft info Set.pdf\u003C/code\u003E prints them on the command line.\u003C/p\u003E\n\u003Ch2 id=\"if-something-doesn-t-work\"\u003EIf something doesn&#039;t work\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EThe assistant sees no MarkupCraft tools:\u003C/strong\u003E check that the switch is on in this window, and that the window is open in Studio.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003E&quot;needs the edit permission&quot;:\u003C/strong\u003E tick \u003Cstrong\u003EEdit\u003C/strong\u003E under \u003Cspan class=\"hui\"\u003EAssistants\u003C/span\u003E, then ask again.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003E&quot;401&quot; or &quot;token&quot; errors:\u003C/strong\u003E the token changed (Studio restarted, or \u003Cspan class=\"hui\"\u003ENew token\u003C/span\u003E). Copy the new one into the assistant&#039;s settings.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"see-also\"\u003ESee also\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ca href=\"/tutorials/basics/assistants-recipes\" data-topic=\"basics/assistants-recipes\"\u003ERecipes for AI assistants\u003C/a\u003E: worked examples, each with the tools it calls.\u003C/li\u003E\u003C/ul\u003E","text":"What you will learn How to let an AI assistant (or a script you wrote) work with MarkupCraft, and how to decide what it is allowed to touch. MarkupCraft has no AI of its own and sends nothing anywhere. You bring the assistant: any program that speaks the Model Context Protocol (MCP). MarkupCraft only gives it tools, and you choose which. Turn it on Open Settings (the gear in the app bar, or Ctrl+,) and go to the MarkupCraft tab. Under Assistants, tick Let AI assistants and scripts use MarkupCraft. It is off until you do. Choose what it may do: Read is ticked to start with; tick Edit, Save or Export only when you need them. Tools outside the permissions you ticked are not offered to the assistant, and if it asks for one anyway, MarkupCraft refuses and writes it in the activity log. Turning the switch off ends every connection at once; Reset MarkupCraft settings turns it off too. Connect your assistant Assistants connect through CadCraft Studio on your computer: Studio runs a small server only this computer can reach, protected by a token it makes each time it starts. In Studio, choose Connect an assistant and copy the address and the token into your assistant (Studio shows the exact settings to paste). Never share the token. A browser tab can't open a connection for an assistant: in the browser apps the switch has no effect until you use CadCraft Studio on your computer. You stay in charge Every change is one undo step, labelled with the assistant's name for it (for example \"Assistant: add cloudrect\"). Ctrl+Z takes back the assistant's last change as a whole. You know when one is connected. A button in the app bar names the assistant while it is connected; click it to see what it may do, or to Disconnect it. Activity. Settings › MarkupCraft › Assistants › Activity lists every call: when, which tool, done or refused. Save the log keeps a copy. What an assistant can ask for Tool Permission What it does app_info, sheets_list Read The sets open, their sheets and how many markups each has markups_list Read The markups with type, sheet, text, comment, measurement, status, author and replies, filtered by sheet, status, type or author markup_add Edit Adds a rectangle, cloud, ellipse, text box, note, line or arrow to a sheet markup_status, markup_reply Edit Sets a markup's status (logged in its thread, signed by the assistant); adds a comment to a thread markups_export Export The Markups list's own CSV or BCF of what the list shows (its filters as you set them); in Studio it can write the file to a folder you allowed A markup an assistant adds names it as the author: the name the assistant program gives itself, followed by \"(assistant)\", or by \"(assistant for \u003Cyour name\u003E)\" once you have set your reviewer name. Its status changes and replies are signed the same way. Each is one undo step. Saving the marked-up PDF stays with you: use Save as usual. Without opening MarkupCraft, the CadCraft MCP server lists the markups of a PDF in a folder you name (markups_list), and cadcraft info Set.pdf prints them on the command line. If something doesn't work The assistant sees no MarkupCraft tools: check that the switch is on in this window, and that the window is open in Studio. \"needs the edit permission\": tick Edit under Assistants, then ask again. \"401\" or \"token\" errors: the token changed (Studio restarted, or New token). Copy the new one into the assistant's settings. See also Recipes for AI assistants: worked examples, each with the tools it calls.","lang":"en"},{"slug":"review-on-a-tablet","scope":"markupcraft","title":"Review on an iPad or touch screen","summary":"Pinch, pan and draw with your fingers or a stylus, what acts on lift, what needs a keyboard, and how to keep your work safe on a tablet.","section":"tasks","order":140,"keywords":["ipad","tablet","touch","touch screen","pinch","zoom","two fingers","apple pencil","stylus","finger","field","site","surface","gestures","mobile"],"headings":[{"id":"gestures","text":"Gestures","level":2},{"id":"what-happens-on-lift","text":"What happens on lift","level":2},{"id":"selecting-with-a-finger","text":"Selecting with a finger","level":2},{"id":"things-that-need-a-keyboard","text":"Things that need a keyboard","level":2},{"id":"stylus-and-apple-pencil","text":"Stylus and Apple Pencil","level":2},{"id":"opening-and-saving-on-an-ipad","text":"Opening and saving on an iPad","level":2},{"id":"keep-your-work-safe-on-a-tablet","text":"Keep your work safe on a tablet","level":2},{"id":"on-a-phone","text":"On a phone","level":2}],"html":"\u003Cp\u003EMarkupCraft works with touch: on an iPad (Safari or Chrome), on a touch-screen laptop, or on a Windows or Android tablet with a recent browser. In landscape a tablet shows the full layout.\u003C/p\u003E\n\u003Ch2 id=\"gestures\"\u003EGestures\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EGesture\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EOne finger\u003C/td\u003E\u003Ctd\u003EDraws with the current tool, or selects with \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETwo fingers, spread or pinch\u003C/td\u003E\u003Ctd\u003EZooms around the point between your fingers\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETwo fingers, moved together\u003C/td\u003E\u003Ctd\u003EPans; you can zoom and pan in one movement\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EA second finger while drawing\u003C/td\u003E\u003Ctd\u003ECancels what the first finger started and starts zooming instead\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDouble-tap, or touch and hold\u003C/td\u003E\u003Ctd\u003EFinishes a polyline, polygon, free cloud or area\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETouch and hold a text, callout or note, with \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EOpens its text to edit\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EOne finger with \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E on\u003C/td\u003E\u003Ctd\u003EPans\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EOn a touch screen the toolbar buttons, menus, tabs and dialog buttons are larger, so they are easy to hit with a finger.\u003C/p\u003E\n\u003Ch2 id=\"what-happens-on-lift\"\u003EWhat happens on lift\u003C/h2\u003E\n\u003Cp\u003ESo that the first finger of a pinch never leaves a mark, some tools act when you \u003Cstrong\u003Elift\u003C/strong\u003E your finger, not when you touch:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E: the dot is added on lift.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E: the note is placed on lift.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E: each point is added on lift.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E: when you tap the start and then tap the end, the end is placed on lift.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EIf your finger slides more than a little before lifting, it does not count as a tap and nothing is added. Tap cleanly; to correct, use \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003ETools you drag (\u003Cspan class=\"hui\"\u003EPen\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EText\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E) start as soon as you touch; a second finger cancels them.\u003C/p\u003E\n\u003Ch2 id=\"selecting-with-a-finger\"\u003ESelecting with a finger\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003ETap a markup to select it; drag it to move it; drag a handle to resize. After a finger touches the sheet, markups and handles take a bigger target and the handles draw larger.\u003C/li\u003E\u003Cli\u003EDrag across empty sheet to draw a selection window (left to right: fully inside; right to left: touching).\u003C/li\u003E\u003Cli\u003EIn \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E, one finger does \u003Cstrong\u003Enot\u003C/strong\u003E pan. Use two fingers, or choose \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"things-that-need-a-keyboard\"\u003EThings that need a keyboard\u003C/h2\u003E\n\u003Cp\u003EWithout a keyboard there is no \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E. Here is what to do instead:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKeyboard action\u003C/th\u003E\u003Cth scope=\"col\"\u003EWithout a keyboard\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E to cancel or go back to Select\u003C/td\u003E\u003Ctd\u003ETap \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E in the toolbar\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E for 45° lines, squares and circles\u003C/td\u003E\u003Ctd\u003EDraw carefully; adjust with the handles\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E-click to add to a selection\u003C/td\u003E\u003Ctd\u003EUse a selection window\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E-click to remove a count dot\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E right after a wrong tap\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E to finish typing\u003C/td\u003E\u003Ctd\u003ETap outside the text box\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E to finish a polyline, or to edit a markup&#039;s text\u003C/td\u003E\u003Ctd\u003ETouch and hold, or \u003Cspan class=\"hui\"\u003EEdit on the sheet\u003C/span\u003E in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EDelete\u003C/span\u003E in the toolbar or in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStarting a new count group with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ETap empty sheet with \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E, then tap \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E again\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EA keyboard case or Bluetooth keyboard brings back every shortcut; on an iPad, the ⌘ key works for \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E and the rest.\u003C/p\u003E\n\u003Cp\u003EButtons do not show their tooltips on touch. The key for each tool is listed in \u003Ca href=\"/tutorials/markupcraft/keyboard\" data-topic=\"markupcraft/keyboard\"\u003EKeyboard and mouse\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"stylus-and-apple-pencil\"\u003EStylus and Apple Pencil\u003C/h2\u003E\n\u003Cp\u003EA stylus (Apple Pencil, Surface Pen and the like) works like a mouse: it draws and selects, and acts at once on touch-down. Use your fingers for pinch and pan. Pressure does not change line width.\u003C/p\u003E\n\u003Ch2 id=\"opening-and-saving-on-an-ipad\"\u003EOpening and saving on an iPad\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EOpen\u003C/span\u003E shows the Files picker: iCloud Drive, On My iPad, and any storage app you have connected.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E asks to download; the copy lands in Files, under Downloads (or the folder set in Safari&#039;s settings).\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"keep-your-work-safe-on-a-tablet\"\u003EKeep your work safe on a tablet\u003C/h2\u003E\n\u003Caside class=\"hc hc-warning\"\u003E\u003Cp class=\"hc-label\"\u003EWarning\u003C/p\u003E\n\u003Cp\u003EiPad Safari does not warn you before leaving a page with unsaved work, and iPadOS can reload a tab in the background to free memory. MarkupCraft keeps a recovery copy in the browser and offers it back when you open it again (see \u003Ca href=\"/tutorials/basics/recover\" data-topic=\"basics/recover\"\u003ERecover your work\u003C/a\u003E), but \u003Cstrong\u003Esave after each sheet or each walk-round\u003C/strong\u003E: a private tab keeps no copy.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cul\u003E\u003Cli\u003EYour name, tool settings and tool chest are kept in that browser on that iPad, like on a computer. See \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EBefore a site visit with no signal:\u003C/strong\u003E while you are still online, open MarkupCraft in Safari (or Chrome) on the iPad and choose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E in the bar at the top. Wait until it says &quot;Offline ready&quot; (it counts &quot;Saving N of M&quot;; the PDF reader and writer are about 6 MB). On site, open the same address or a bookmark of it: opening, marking up and saving PDFs work with no connection. If it says &quot;Offline not available&quot;, you are in a private tab; use a normal one. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003ESafari removes an offline copy you have not used for some weeks. Before a trip, click &quot;Offline ready&quot; and choose &quot;Save again (get the newest version)&quot;.\u003C/li\u003E\u003Cli\u003EVery large plan sets use a lot of memory. On a tablet, open only the sheets you need for the visit.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"on-a-phone\"\u003EOn a phone\u003C/h2\u003E\n\u003Cp\u003EIt works, but the screen is small: the parts stack (toolbar, sheet, status bar, panels, then the sheets list), and the toolbar scrolls sideways. Use a phone to look and to add a quick note, and a tablet or computer for real review.\u003C/p\u003E","text":"MarkupCraft works with touch: on an iPad (Safari or Chrome), on a touch-screen laptop, or on a Windows or Android tablet with a recent browser. In landscape a tablet shows the full layout. Gestures Gesture What it does One finger Draws with the current tool, or selects with Select Two fingers, spread or pinch Zooms around the point between your fingers Two fingers, moved together Pans; you can zoom and pan in one movement A second finger while drawing Cancels what the first finger started and starts zooming instead Double-tap, or touch and hold Finishes a polyline, polygon, free cloud or area Touch and hold a text, callout or note, with Select Opens its text to edit One finger with Pan on Pans On a touch screen the toolbar buttons, menus, tabs and dialog buttons are larger, so they are easy to hit with a finger. What happens on lift So that the first finger of a pinch never leaves a mark, some tools act when you lift your finger, not when you touch: Count: the dot is added on lift. Note: the note is placed on lift. Polyline, Polygon, Free cloud and Area: each point is added on lift. Line, Arrow, Length and Calibrate: when you tap the start and then tap the end, the end is placed on lift. If your finger slides more than a little before lifting, it does not count as a tap and nothing is added. Tap cleanly; to correct, use Undo. Tools you drag (Pen, Highlight, Cloud, Rectangle, Ellipse, Callout, Text, Stamp) start as soon as you touch; a second finger cancels them. Selecting with a finger Tap a markup to select it; drag it to move it; drag a handle to resize. After a finger touches the sheet, markups and handles take a bigger target and the handles draw larger. Drag across empty sheet to draw a selection window (left to right: fully inside; right to left: touching). In Select, one finger does not pan. Use two fingers, or choose Pan. Things that need a keyboard Without a keyboard there is no Shift, Esc or Enter. Here is what to do instead: Keyboard action Without a keyboard Esc to cancel or go back to Select Tap Select in the toolbar Shift for 45° lines, squares and circles Draw carefully; adjust with the handles Shift-click to add to a selection Use a selection window Shift-click to remove a count dot Undo right after a wrong tap Ctrl+Enter to finish typing Tap outside the text box Enter to finish a polyline, or to edit a markup's text Touch and hold, or Edit on the sheet in Properties Delete Delete in the toolbar or in Properties Starting a new count group with Esc Tap empty sheet with Select, then tap Count again A keyboard case or Bluetooth keyboard brings back every shortcut; on an iPad, the ⌘ key works for Ctrl+Z and the rest. Buttons do not show their tooltips on touch. The key for each tool is listed in Keyboard and mouse. Stylus and Apple Pencil A stylus (Apple Pencil, Surface Pen and the like) works like a mouse: it draws and selects, and acts at once on touch-down. Use your fingers for pinch and pan. Pressure does not change line width. Opening and saving on an iPad Open shows the Files picker: iCloud Drive, On My iPad, and any storage app you have connected. Save asks to download; the copy lands in Files, under Downloads (or the folder set in Safari's settings). Keep your work safe on a tablet iPad Safari does not warn you before leaving a page with unsaved work, and iPadOS can reload a tab in the background to free memory. MarkupCraft keeps a recovery copy in the browser and offers it back when you open it again (see Recover your work), but save after each sheet or each walk-round: a private tab keeps no copy. Your name, tool settings and tool chest are kept in that browser on that iPad, like on a computer. See What stays in this browser. Before a site visit with no signal: while you are still online, open MarkupCraft in Safari (or Chrome) on the iPad and choose Save for offline in the bar at the top. Wait until it says \"Offline ready\" (it counts \"Saving N of M\"; the PDF reader and writer are about 6 MB). On site, open the same address or a bookmark of it: opening, marking up and saving PDFs work with no connection. If it says \"Offline not available\", you are in a private tab; use a normal one. See Working offline. Safari removes an offline copy you have not used for some weeks. Before a trip, click \"Offline ready\" and choose \"Save again (get the newest version)\". Very large plan sets use a lot of memory. On a tablet, open only the sheets you need for the visit. On a phone It works, but the screen is small: the parts stack (toolbar, sheet, status bar, panels, then the sheets list), and the toolbar scrolls sideways. Use a phone to look and to add a quick note, and a tablet or computer for real review.","lang":"en"},{"slug":"coming-from","scope":"markupcraft","title":"Coming from other markup software","summary":"How the habits of a desktop PDF markup program map to MarkupCraft, and the differences that catch people out.","section":"switching","order":10,"keywords":["switch","switching","migrate","familiar","desktop pdf markup","tool chest","markups list","overlay","sessions","profile","shortcuts","differences"],"headings":[{"id":"the-five-differences-that-matter","text":"The five differences that matter","level":2},{"id":"habit-by-habit","text":"Habit by habit","level":2},{"id":"keys-that-differ","text":"Keys that differ","level":2},{"id":"things-that-work-differently-than-you-might-expect","text":"Things that work differently than you might expect","level":2},{"id":"using-both","text":"Using both","level":2}],"html":"\u003Cp\u003EIf you review drawings in Bluebeam Revu (or comment on PDFs in another desktop PDF program), most of MarkupCraft will feel familiar: clouds, callouts, a tool chest, a markups list, statuses with replies, calibrated measurements, sheet overlays. The way files are handled is the big difference, so read the next section even if you skip the rest.\u003C/p\u003E\n\u003Ch2 id=\"the-five-differences-that-matter\"\u003EThe five differences that matter\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003E\u003Cstrong\u003ESave makes a new file.\u003C/strong\u003E MarkupCraft runs in the browser and cannot write over the PDF on your disk. \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E downloads &quot;&lt;name&gt; (marked up).pdf&quot; and the original stays as it was. Next time, open the &quot;(marked up)&quot; copy, and tidy old copies yourself.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EThe PDF is saved when you save.\u003C/strong\u003E Until then a recovery copy in this browser keeps your markups through a crash or a closed tab, and MarkupCraft offers it back next time. It is a safety net: save the PDF to keep the review.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EYour profile lives in the browser.\u003C/strong\u003E Your author name, tool settings and tool chest are kept in this browser on this computer. A different browser or computer starts fresh, and clearing site data erases them. Export your tool chest as a backup. See \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ENo shared sessions yet.\u003C/strong\u003E There is no live, shared review session and no cloud project. The review travels in the PDF: save, send the copy, the next person replies and saves.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EScale is per sheet, and only per sheet.\u003C/strong\u003E There are no viewports inside a sheet and no &quot;apply this scale to all pages&quot;. Calibrate each sheet you measure on.\u003C/li\u003E\u003C/ol\u003E\n\u003Ch2 id=\"habit-by-habit\"\u003EHabit by habit\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EYou are used to\u003C/th\u003E\u003Cth scope=\"col\"\u003EIn MarkupCraft\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EThumbnails panel, page labels\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESheets\u003C/span\u003E on the left. Names come from page labels or are read from the title block; fix them with \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EOpening several PDFs as a set\u003C/td\u003E\u003Ctd\u003EOpen them all at once; they become one list. No set file is saved: open the same PDFs next time.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETool chest with tool sets\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab: one chest per browser, saved tools with style and subject. Share by \u003Cspan class=\"hui\"\u003EExport\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EImport\u003C/span\u003E as a JSON file. Tool set files from other programs cannot be imported.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EProperties panel\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E tab: status, subject, comment, style, replies and punch item in one place.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMarkups list with columns\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab with filters for sheet, author, status and type. Export CSV or BCF. No custom columns and no PDF or workbook summary yet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStatus and review state\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E: Open, Accepted, Rejected, Completed. No custom status sets. Saved as standard review states.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EReplies on a markup\u003C/td\u003E\u003Ctd\u003EThe &quot;Replies&quot; thread in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, with status changes logged in it. A sent reply cannot be edited.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECalibrate, then length, area, count\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E), \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E, gives area and perimeter), \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E). No angle, radius, volume, polylength or cut-outs yet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EOverlay pages\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECompare\u003C/span\u003E tab: red for old, blue for new, align by two points. No automatic &quot;compare documents&quot; clouding.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStamps\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E with six built-in stamps and custom wording, signed with your name and the date. No image or signature stamps yet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPunch or issue tracking\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPunch list\u003C/span\u003E tab: numbered items with assignee, due date and status; CSV export.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELive collaboration session\u003C/td\u003E\u003Ctd\u003ENot available yet. Pass the saved PDF around.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EFlatten\u003C/td\u003E\u003Ctd\u003ENot built yet. Markups stay as comments other viewers can show and print.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELayers for markups\u003C/td\u003E\u003Ctd\u003ENot built yet. Use subjects, authors and the list filters to sort comments.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EHyperlinks between sheets\u003C/td\u003E\u003Ctd\u003ENot built yet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESpacebar to pan, wheel to zoom\u003C/td\u003E\u003Ctd\u003EThe same: hold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and drag; the wheel zooms at the pointer. The wheel never scrolls the page.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"keys-that-differ\"\u003EKeys that differ\u003C/h2\u003E\n\u003Cp\u003EMany one-letter keys are what you might expect, but check these before your fingers do it for you:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E, and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E. If you are used to Q for callouts, it will start an area here.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E is the box \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift C\"\u003E⇧C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+C\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Y\"\u003EY\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EY\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"G\"\u003EG\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EG\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"I\"\u003EI\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EI\u003C/span\u003E\u003C/kbd\u003E is \u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command D\"\u003E⌘D\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+D\u003C/span\u003E\u003C/kbd\u003E duplicates the selection (instead of the browser&#039;s bookmark).\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command +\"\u003E⌘+\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl++\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command −\"\u003E⌘−\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+−\u003C/span\u003E\u003C/kbd\u003E zoom the sheet, not the browser page.\u003C/li\u003E\u003Cli\u003EAny key can be changed: see below.\u003C/li\u003E\u003C/ul\u003E\n\u003Caside class=\"hc hc-tip\"\u003E\u003Cp class=\"hc-label\"\u003ETip\u003C/p\u003E\n\u003Cp\u003EIf your fingers know Bluebeam Revu, pick the \u003Cspan class=\"hui\"\u003EPDF review\u003C/span\u003E menu style in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMenus, keys and mouse\u003C/span\u003E: a menu bar (File, Edit, View, Document, Markup, Measure, Window) over a row of review tools, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E for a callout, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E for the highlighter, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E for a polygon, and the measurements on \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift\"\u003E⌥⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift\u003C/span\u003E\u003C/kbd\u003E with a letter. Any key can be changed there too. See \u003Ca href=\"/tutorials/markupcraft/menus-keys-and-mouse\" data-topic=\"markupcraft/menus-keys-and-mouse\"\u003EMenus, keys and mouse\u003C/a\u003E.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003EThe full list is in \u003Ca href=\"/tutorials/markupcraft/keyboard\" data-topic=\"markupcraft/keyboard\"\u003EKeyboard and mouse\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"things-that-work-differently-than-you-might-expect\"\u003EThings that work differently than you might expect\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ETools stay on.\u003C/strong\u003E After a cloud, you are still drawing clouds. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E once clears the selection, twice returns to \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EText and callouts need text.\u003C/strong\u003E Finish with nothing typed and no markup is added. Notes are kept empty.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMeasurements need a scale first.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E switch to \u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E on an uncalibrated sheet and come back after.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EComments from other programs.\u003C/strong\u003E Rectangles, ellipses, lines, polylines, polygons, ink, text boxes and sticky notes made elsewhere become editable MarkupCraft markups, and are rewritten in MarkupCraft&#039;s way when you save (their look can change slightly). Text highlights, other programs&#039; stamps and other special kinds stay read-only: you can reply to them, not change them.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECharacters outside Western European letters\u003C/strong\u003E print as &quot;?&quot; in the saved PDF. See \u003Ca href=\"/tutorials/markupcraft/save-the-marked-up-pdf\" data-topic=\"markupcraft/save-the-marked-up-pdf\"\u003ESave the marked-up PDF\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EStamp dates\u003C/strong\u003E use UTC, so a stamp made late in the evening in the Americas can show tomorrow&#039;s date.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMeasurements carry over\u003C/strong\u003E as standard measurement comments, and each calibrated sheet keeps its scale, so a program that reads PDF measurements can usually show them. Exact behavior depends on that program.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"using-both\"\u003EUsing both\u003C/h2\u003E\n\u003Cp\u003EYou can go back and forth. Comments made elsewhere open in MarkupCraft, and the &quot;(marked up)&quot; PDF opens in other PDF programs with every markup, reply and status visible. What only MarkupCraft reads back (punch assignee and due date, item status) is kept in the file for MarkupCraft.\u003C/p\u003E","text":"If you review drawings in Bluebeam Revu (or comment on PDFs in another desktop PDF program), most of MarkupCraft will feel familiar: clouds, callouts, a tool chest, a markups list, statuses with replies, calibrated measurements, sheet overlays. The way files are handled is the big difference, so read the next section even if you skip the rest. The five differences that matter Save makes a new file. MarkupCraft runs in the browser and cannot write over the PDF on your disk. Save downloads \"\u003Cname\u003E (marked up).pdf\" and the original stays as it was. Next time, open the \"(marked up)\" copy, and tidy old copies yourself. The PDF is saved when you save. Until then a recovery copy in this browser keeps your markups through a crash or a closed tab, and MarkupCraft offers it back next time. It is a safety net: save the PDF to keep the review. Your profile lives in the browser. Your author name, tool settings and tool chest are kept in this browser on this computer. A different browser or computer starts fresh, and clearing site data erases them. Export your tool chest as a backup. See What stays in this browser. No shared sessions yet. There is no live, shared review session and no cloud project. The review travels in the PDF: save, send the copy, the next person replies and saves. Scale is per sheet, and only per sheet. There are no viewports inside a sheet and no \"apply this scale to all pages\". Calibrate each sheet you measure on. Habit by habit You are used to In MarkupCraft Thumbnails panel, page labels Sheets on the left. Names come from page labels or are read from the title block; fix them with Rename sheet. Opening several PDFs as a set Open them all at once; they become one list. No set file is saved: open the same PDFs next time. Tool chest with tool sets Tools tab: one chest per browser, saved tools with style and subject. Share by Export and Import as a JSON file. Tool set files from other programs cannot be imported. Properties panel Properties tab: status, subject, comment, style, replies and punch item in one place. Markups list with columns Markups tab with filters for sheet, author, status and type. Export CSV or BCF. No custom columns and no PDF or workbook summary yet. Status and review state Status: Open, Accepted, Rejected, Completed. No custom status sets. Saved as standard review states. Replies on a markup The \"Replies\" thread in Properties, with status changes logged in it. A sent reply cannot be edited. Calibrate, then length, area, count Calibrate, Length (M), Area (Q, gives area and perimeter), Count (U). No angle, radius, volume, polylength or cut-outs yet. Overlay pages Compare tab: red for old, blue for new, align by two points. No automatic \"compare documents\" clouding. Stamps Stamp with six built-in stamps and custom wording, signed with your name and the date. No image or signature stamps yet. Punch or issue tracking Punch list tab: numbered items with assignee, due date and status; CSV export. Live collaboration session Not available yet. Pass the saved PDF around. Flatten Not built yet. Markups stay as comments other viewers can show and print. Layers for markups Not built yet. Use subjects, authors and the list filters to sort comments. Hyperlinks between sheets Not built yet. Spacebar to pan, wheel to zoom The same: hold Space and drag; the wheel zooms at the pointer. The wheel never scrolls the page. Keys that differ Many one-letter keys are what you might expect, but check these before your fingers do it for you: K is Callout, and Q is Area. If you are used to Q for callouts, it will start an area here. C is the box Cloud; Shift+C is Free cloud. M is Length, U is Count, Y is Polyline, G is Polygon, I is Highlight. Ctrl+D duplicates the selection (instead of the browser's bookmark). Ctrl++ and Ctrl+− zoom the sheet, not the browser page. Any key can be changed: see below. If your fingers know Bluebeam Revu, pick the PDF review menu style in Settings › MarkupCraft › Menus, keys and mouse: a menu bar (File, Edit, View, Document, Markup, Measure, Window) over a row of review tools, Q for a callout, H for the highlighter, N for a polygon, and the measurements on Alt+Shift with a letter. Any key can be changed there too. See Menus, keys and mouse. The full list is in Keyboard and mouse. Things that work differently than you might expect Tools stay on. After a cloud, you are still drawing clouds. Esc once clears the selection, twice returns to Select. Text and callouts need text. Finish with nothing typed and no markup is added. Notes are kept empty. Measurements need a scale first. Length and Area switch to Calibrate on an uncalibrated sheet and come back after. Comments from other programs. Rectangles, ellipses, lines, polylines, polygons, ink, text boxes and sticky notes made elsewhere become editable MarkupCraft markups, and are rewritten in MarkupCraft's way when you save (their look can change slightly). Text highlights, other programs' stamps and other special kinds stay read-only: you can reply to them, not change them. Characters outside Western European letters print as \"?\" in the saved PDF. See Save the marked-up PDF. Stamp dates use UTC, so a stamp made late in the evening in the Americas can show tomorrow's date. Measurements carry over as standard measurement comments, and each calibrated sheet keeps its scale, so a program that reads PDF measurements can usually show them. Exact behavior depends on that program. Using both You can go back and forth. Comments made elsewhere open in MarkupCraft, and the \"(marked up)\" PDF opens in other PDF programs with every markup, reply and status visible. What only MarkupCraft reads back (punch assignee and due date, item status) is kept in the file for MarkupCraft.","lang":"en"},{"slug":"keyboard","scope":"markupcraft","title":"Keyboard and mouse","summary":"Every key, mouse action and touch gesture MarkupCraft understands, grouped, plus the shortcuts the browser keeps.","section":"reference","order":10,"keywords":["keyboard","shortcuts","hotkeys","keys","mouse","wheel","right click","middle button","trackpad","touch","gestures","pinch","space pan"],"headings":[{"id":"tools","text":"Tools","level":2},{"id":"while-drawing","text":"While drawing","level":2},{"id":"selecting-and-editing","text":"Selecting and editing","level":2},{"id":"cut-copy-and-paste","text":"Cut, copy and paste","level":2},{"id":"help","text":"Help","level":2},{"id":"files-and-sheets","text":"Files and sheets","level":2},{"id":"zoom-and-pan","text":"Zoom and pan","level":2},{"id":"touch","text":"Touch","level":2},{"id":"shortcuts-the-browser-keeps","text":"Shortcuts the browser keeps","level":2},{"id":"when-a-key-does-nothing","text":"When a key does nothing","level":2}],"html":"\u003Cp\u003EShortcuts written with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E accept either ⌘ or Control on a Mac, and Ctrl on Windows and Linux. Tool letters work only when you are not typing in a box; while you type, letters are just letters. See also \u003Ca href=\"/tutorials/basics/keys\" data-topic=\"basics/keys\"\u003EKeys, mice and trackpads\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"tools\"\u003ETools\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003ETool\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"V\"\u003EV\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EV\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"B\"\u003EB\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EB\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EContent\u003C/span\u003E: the page&#039;s own lines, pictures and text (see \u003Ca href=\"/tutorials/markupcraft/page-content\" data-topic=\"markupcraft/page-content\"\u003EChange the page&#039;s own content\u003C/a\u003E)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"P\"\u003EP\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EP\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPen\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"I\"\u003EI\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EI\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"L\"\u003EL\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EL\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"A\"\u003EA\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EA\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"R\"\u003ER\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ER\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"E\"\u003EE\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EE\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Y\"\u003EY\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EY\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"G\"\u003EG\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EG\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E (drag a box)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift C\"\u003E⇧C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+C\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"T\"\u003ET\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ET\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EText\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"S\"\u003ES\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ES\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"O\"\u003EO\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EO\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArc\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"X\"\u003EX\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EX\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EAngle\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E has no key: use its toolbar button or the scale button in the status bar. Tool letters are ignored when \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option\"\u003E⌥\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt\u003C/span\u003E\u003C/kbd\u003E is held.\u003C/p\u003E\n\u003Ch2 id=\"while-drawing\"\u003EWhile drawing\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey or action\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E while drawing\u003C/td\u003E\u003Ctd\u003ELines, arrows, lengths and polyline sides at 45° steps; rectangles, ellipses and box clouds square; pen and highlighter one straight stroke\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDouble-click, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E or right-click\u003C/td\u003E\u003Ctd\u003EFinish a polyline, polygon, free cloud or area\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ERemove the last point of a polyline, polygon, free cloud or area\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECancel what you are drawing; with nothing in progress, clear the selection; with nothing selected, go back to \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EFinish typing in a text box, callout or note (or click outside it)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E while typing\u003C/td\u003E\u003Ctd\u003ECancel the text you were typing\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E-click with \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003ERemove the nearest dot of the selected count group\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"selecting-and-editing\"\u003ESelecting and editing\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey or action\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EClick\u003C/td\u003E\u003Ctd\u003ESelect a markup\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E-click\u003C/td\u003E\u003Ctd\u003EAdd or remove a markup from the selection\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag left to right on empty sheet\u003C/td\u003E\u003Ctd\u003ESelect what is fully inside the window\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag right to left on empty sheet\u003C/td\u003E\u003Ctd\u003ESelect what the window touches\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command A\"\u003E⌘A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+A\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ESelect every markup on this sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag a selected markup\u003C/td\u003E\u003Ctd\u003EMove it (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E: along 45° steps)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag a handle\u003C/td\u003E\u003Ctd\u003EResize or reshape (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E: keep proportions, or 45°)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EArrow keys\u003C/td\u003E\u003Ctd\u003ENudge the selection one screen pixel (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E: ten)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDouble-click, or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EEdit the text of a text box, callout or note; for a stamp, open \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDelete the selection\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ESelect nothing\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EUndo\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Y\"\u003E⌘Y\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Y\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command Z\"\u003E⇧⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+Z\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ERedo\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"cut-copy-and-paste\"\u003ECut, copy and paste\u003C/h2\u003E\n\u003Cp\u003EThe same commands are in the toolbar&#039;s \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E group (\u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E) and its \u003Cspan class=\"hui\"\u003EMore\u003C/span\u003E menu, each with its key. Every one is a single undo step. See \u003Ca href=\"/tutorials/markupcraft/select-and-edit#copy-paste-and-duplicate\" data-topic=\"markupcraft/select-and-edit\" data-hash=\"copy-paste-and-duplicate\"\u003ECopy, paste and duplicate\u003C/a\u003E.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command X\"\u003E⌘X\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+X\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECut: copy the selection and delete it\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECopy the selection\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPaste. With the pointer on the sheet, the copy lands centered where it points; otherwise beside the original. Settings can make it always paste beside the original.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command V\"\u003E⇧⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+V\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPaste in place: the same spot on the sheet, on this sheet or another\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command D\"\u003E⌘D\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+D\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDuplicate the selection beside it (the clipboard is left alone)\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"help\"\u003EHelp\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EOpen or close this help (a panel at the side; the sheet stays usable). Also \u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E in the bar at the top.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E in the help\u003C/td\u003E\u003Ctd\u003EClose the help\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:mac\"\u003E\u003Cp class=\"hv-label\"\u003EMac\u003C/p\u003E\n\u003Cp\u003EOn most Mac keyboards, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E with \u003Cstrong\u003Efn\u003C/strong\u003E (or the globe key), or use \u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E. See \u003Ca href=\"/tutorials/basics/keys#function-keys-on-a-mac\" data-topic=\"basics/keys\" data-hash=\"function-keys-on-a-mac\"\u003EKeys, mice and trackpads\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"files-and-sheets\"\u003EFiles and sheets\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command N\"\u003E⌘N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+N\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ENew blank pages (when the browser lets the page have the key; see \u003Ca href=\"/tutorials/markupcraft/open-a-plan-set#start-with-blank-pages\" data-topic=\"markupcraft/open-a-plan-set\" data-hash=\"start-with-blank-pages\"\u003EStart with blank pages\u003C/a\u003E)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EOpen PDFs\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command P\"\u003E⌘P\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+P\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPrint (see \u003Ca href=\"/tutorials/markupcraft/pages-and-printing\" data-topic=\"markupcraft/pages-and-printing\"\u003EPrint, and change the pages\u003C/a\u003E)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command F\"\u003E⌘F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+F\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EFind text in the drawings (see \u003Ca href=\"/tutorials/markupcraft/find-text\" data-topic=\"markupcraft/find-text\"\u003EFind text\u003C/a\u003E)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E+click a linked markup\u003C/td\u003E\u003Ctd\u003EFollow its sheet link; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option ←\"\u003E⌥←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+←\u003C/span\u003E\u003C/kbd\u003E goes back (see \u003Ca href=\"/tutorials/markupcraft/sheet-links\" data-topic=\"markupcraft/sheet-links\"\u003ESheet links\u003C/a\u003E)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ESave a marked-up copy\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↓\"\u003Efn ↓\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Down\u003C/span\u003E\u003C/kbd\u003E / \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↑\"\u003Efn ↑\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Up\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ENext / previous sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E in \u003Cspan class=\"hui\"\u003ESearch sheets\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EOpen the first matching sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Return\"\u003E⌘ Return\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Enter\u003C/span\u003E\u003C/kbd\u003E in \u003Cspan class=\"hui\"\u003EWrite a reply\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003ESend the reply\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"zoom-and-pan\"\u003EZoom and pan\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EKey or action\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EMouse wheel\u003C/td\u003E\u003Ctd\u003EZoom in or out around the pointer (the wheel never scrolls)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control\"\u003E⌃\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E + wheel\u003C/td\u003E\u003Ctd\u003EZoom faster\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"+\"\u003E+\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E+\u003C/span\u003E\u003C/kbd\u003E or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"−\"\u003E−\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E−\u003C/span\u003E\u003C/kbd\u003E (also with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E)\u003C/td\u003E\u003Ctd\u003EZoom in or out around the middle; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"=\"\u003E=\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E=\u003C/span\u003E\u003C/kbd\u003E works as plus\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 0\"\u003E⌘0\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+0\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EFit page\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 9\"\u003E⌘9\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+9\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EFit width\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag with the middle button\u003C/td\u003E\u003Ctd\u003EPan\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDrag with the right button\u003C/td\u003E\u003Ctd\u003EPan (when you are not in the middle of a polyline)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EHold \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and drag\u003C/td\u003E\u003Ctd\u003EPan\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EArrow keys with nothing selected\u003C/td\u003E\u003Ctd\u003EPan\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EScreen mode: normal, full screen, full screen with bars hidden (Control key on every computer)\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:mac\"\u003E\u003Cp class=\"hv-label\"\u003EMac\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EOn a trackpad:\u003C/strong\u003E two-finger scrolling zooms. Pinch also zooms in Chrome, Edge and Firefox. Pan with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E held while you drag, or with the \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E tool. A two-finger click is a right-click and finishes a polyline. Control-click may act as a plain click here rather than a right-click, so use a two-finger click.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Ch2 id=\"touch\"\u003ETouch\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EGesture\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat it does\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EOne finger\u003C/td\u003E\u003Ctd\u003EDraw with the current tool, or select\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETwo fingers\u003C/td\u003E\u003Ctd\u003EPinch to zoom around their middle, move to pan\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESecond finger during a stroke\u003C/td\u003E\u003Ctd\u003ECancels the stroke and zooms instead\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDouble-tap\u003C/td\u003E\u003Ctd\u003EFinish a polyline, polygon, free cloud or area\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003ECount dots, notes, polyline points and the second point of a two-point tool are placed when the finger lifts. See \u003Ca href=\"/tutorials/markupcraft/review-on-a-tablet\" data-topic=\"markupcraft/review-on-a-tablet\"\u003EReview on an iPad or touch screen\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"shortcuts-the-browser-keeps\"\u003EShortcuts the browser keeps\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command W\"\u003E⌘W\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+W\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command T\"\u003E⌘T\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+T\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command N\"\u003E⌘N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+N\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Q\"\u003E⌘Q\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Q\u003C/span\u003E\u003C/kbd\u003E belong to the browser. Closing the tab or window with unsaved markups loses them, after the browser&#039;s &quot;Leave site?&quot; question on a computer.\u003C/li\u003E\u003Cli\u003EMost browsers keep \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command N\"\u003E⌘N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+N\u003C/span\u003E\u003C/kbd\u003E for a new window, so in a browser tab use \u003Cspan class=\"hui\"\u003ENew\u003C/span\u003E in the toolbar; the desktop app and Studio pass the key to MarkupCraft.\u003C/li\u003E\u003Cli\u003EMarkupCraft takes \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command D\"\u003E⌘D\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+D\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command A\"\u003E⌘A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+A\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command V\"\u003E⇧⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+V\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 0\"\u003E⌘0\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+0\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command +\"\u003E⌘+\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl++\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command −\"\u003E⌘−\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+−\u003C/span\u003E\u003C/kbd\u003E away from the browser while the app has the keyboard, and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command X\"\u003E⌘X\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+X\u003C/span\u003E\u003C/kbd\u003E while markups are selected. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E opens \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E. To zoom the whole browser page instead, use the browser&#039;s menu.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 9\"\u003E⌘9\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+9\u003C/span\u003E\u003C/kbd\u003E jumps to the last browser tab in some browsers before MarkupCraft sees it. If that happens, use \u003Cspan class=\"hui\"\u003EFit width\u003C/span\u003E under the sheet.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E in full screen also leaves full screen.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"when-a-key-does-nothing\"\u003EWhen a key does nothing\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EYou are typing in a box.\u003C/strong\u003E Click on the sheet first. (A click with a drawing tool draws; press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E afterward or use \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E.)\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EA dialog is open.\u003C/strong\u003E Keys go to the dialog until it closes.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EYou just clicked a toolbar button\u003C/strong\u003E and the arrow keys or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E act on that button instead. Move the pointer over the sheet and use the wheel or middle button, or press a tool letter instead of clicking buttons.\u003C/li\u003E\u003C/ul\u003E","text":"Shortcuts written with Ctrl accept either ⌘ or Control on a Mac, and Ctrl on Windows and Linux. Tool letters work only when you are not typing in a box; while you type, letters are just letters. See also Keys, mice and trackpads. Tools Key Tool V Select H Pan B Content: the page's own lines, pictures and text (see Change the page's own content) P Pen I Highlight L Line A Arrow R Rectangle E Ellipse Y Polyline G Polygon C Cloud (drag a box) Shift+C Free cloud K Callout T Text N Note S Stamp M Length Q Area U Count O Arc X Angle Calibrate has no key: use its toolbar button or the scale button in the status bar. Tool letters are ignored when Alt is held. While drawing Key or action What it does Shift while drawing Lines, arrows, lengths and polyline sides at 45° steps; rectangles, ellipses and box clouds square; pen and highlighter one straight stroke Double-click, Enter or right-click Finish a polyline, polygon, free cloud or area Backspace Remove the last point of a polyline, polygon, free cloud or area Esc Cancel what you are drawing; with nothing in progress, clear the selection; with nothing selected, go back to Select Ctrl+Enter Finish typing in a text box, callout or note (or click outside it) Esc while typing Cancel the text you were typing Shift-click with Count Remove the nearest dot of the selected count group Selecting and editing Key or action What it does Click Select a markup Shift-click Add or remove a markup from the selection Drag left to right on empty sheet Select what is fully inside the window Drag right to left on empty sheet Select what the window touches Ctrl+A Select every markup on this sheet Drag a selected markup Move it (Shift: along 45° steps) Drag a handle Resize or reshape (Shift: keep proportions, or 45°) Arrow keys Nudge the selection one screen pixel (Shift: ten) Double-click, or Enter Edit the text of a text box, callout or note; for a stamp, open Properties Delete or Backspace Delete the selection Esc Select nothing Ctrl+Z Undo Ctrl+Y or Ctrl+Shift+Z Redo Cut, copy and paste The same commands are in the toolbar's Edit group (Copy, Paste) and its More menu, each with its key. Every one is a single undo step. See Copy, paste and duplicate. Key What it does Ctrl+X Cut: copy the selection and delete it Ctrl+C Copy the selection Ctrl+V Paste. With the pointer on the sheet, the copy lands centered where it points; otherwise beside the original. Settings can make it always paste beside the original. Ctrl+Shift+V Paste in place: the same spot on the sheet, on this sheet or another Ctrl+D Duplicate the selection beside it (the clipboard is left alone) Help Key What it does F1 Open or close this help (a panel at the side; the sheet stays usable). Also Help in the bar at the top. Esc in the help Close the help On most Mac keyboards, press F1 with fn (or the globe key), or use Help. See Keys, mice and trackpads. Files and sheets Key What it does Ctrl+N New blank pages (when the browser lets the page have the key; see Start with blank pages) Ctrl+O Open PDFs Ctrl+P Print (see Print, and change the pages) Ctrl+F Find text in the drawings (see Find text) Ctrl+click a linked markup Follow its sheet link; Alt+← goes back (see Sheet links) Ctrl+S Save a marked-up copy Page Down / Page Up Next / previous sheet Enter in Search sheets Open the first matching sheet Ctrl+Enter in Write a reply Send the reply Zoom and pan Key or action What it does Mouse wheel Zoom in or out around the pointer (the wheel never scrolls) Ctrl + wheel Zoom faster + or − (also with Ctrl) Zoom in or out around the middle; = works as plus Ctrl+0 Fit page Ctrl+9 Fit width Drag with the middle button Pan Drag with the right button Pan (when you are not in the middle of a polyline) Hold Space and drag Pan Arrow keys with nothing selected Pan Ctrl+Shift+F Screen mode: normal, full screen, full screen with bars hidden (Control key on every computer) On a trackpad: two-finger scrolling zooms. Pinch also zooms in Chrome, Edge and Firefox. Pan with Space held while you drag, or with the Pan tool. A two-finger click is a right-click and finishes a polyline. Control-click may act as a plain click here rather than a right-click, so use a two-finger click. Touch Gesture What it does One finger Draw with the current tool, or select Two fingers Pinch to zoom around their middle, move to pan Second finger during a stroke Cancels the stroke and zooms instead Double-tap Finish a polyline, polygon, free cloud or area Count dots, notes, polyline points and the second point of a two-point tool are placed when the finger lifts. See Review on an iPad or touch screen. Shortcuts the browser keeps Ctrl+W, Ctrl+T, Ctrl+N and Ctrl+Q belong to the browser. Closing the tab or window with unsaved markups loses them, after the browser's \"Leave site?\" question on a computer. Most browsers keep Ctrl+N for a new window, so in a browser tab use New in the toolbar; the desktop app and Studio pass the key to MarkupCraft. MarkupCraft takes Ctrl+O, Ctrl+S, Ctrl+D, Ctrl+A, Ctrl+V, Ctrl+Shift+V, Ctrl+0, Ctrl++ and Ctrl+− away from the browser while the app has the keyboard, and Ctrl+C and Ctrl+X while markups are selected. Ctrl+, opens Settings. To zoom the whole browser page instead, use the browser's menu. Ctrl+9 jumps to the last browser tab in some browsers before MarkupCraft sees it. If that happens, use Fit width under the sheet. Esc in full screen also leaves full screen. When a key does nothing You are typing in a box. Click on the sheet first. (A click with a drawing tool draws; press Esc afterward or use Ctrl+Z.) A dialog is open. Keys go to the dialog until it closes. You just clicked a toolbar button and the arrow keys or Space act on that button instead. Move the pointer over the sheet and use the wheel or middle button, or press a tool letter instead of clicking buttons.","lang":"en"},{"slug":"menus-keys-and-mouse","scope":"markupcraft","title":"Menus, keys and mouse","summary":"Pick MarkupCraft's own toolbar, a PDF review menu bar or a ribbon, give any tool your own key, move tools between menus, and set what the wheel and the mouse buttons do.","section":"reference","order":11,"keywords":["menu style","menus","menu bar","toolbar","ribbon","tabs","pdf review","keyboard shortcuts","hotkeys","keys","customize","remap","rebind","mouse","wheel","invert","zoom direction","middle button","right button","pan","export","import","switching","familiar"],"headings":[{"id":"the-three-styles","text":"The three styles","level":2},{"id":"make-it-your-own","text":"Make it your own","level":2},{"id":"mouse","text":"Mouse","level":2},{"id":"take-it-with-you","text":"Take it with you","level":2}],"html":"\u003Cp\u003EMarkupCraft&#039;s tools are the same whichever way you reach them. A \u003Cstrong\u003Emenu style\u003C/strong\u003E only decides where they sit on screen, what they are called there and which keys pick them. Choose one in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E) › \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMenus, keys and mouse\u003C/span\u003E; the change is immediate, and this browser remembers it.\u003C/p\u003E\n\u003Ch2 id=\"the-three-styles\"\u003EThe three styles\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EStyle\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat you get\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EMarkupCraft&#039;s own toolbar (File, Select, Draw, Revise, Annotate, Measure, Edit) and its one-letter keys: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"V\"\u003EV\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EV\u003C/span\u003E\u003C/kbd\u003E select, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E pan, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"P\"\u003EP\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EP\u003C/span\u003E\u003C/kbd\u003E pen, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"I\"\u003EI\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EI\u003C/span\u003E\u003C/kbd\u003E highlighter, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"L\"\u003EL\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EL\u003C/span\u003E\u003C/kbd\u003E line, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"A\"\u003EA\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EA\u003C/span\u003E\u003C/kbd\u003E arrow, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"R\"\u003ER\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ER\u003C/span\u003E\u003C/kbd\u003E rectangle, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"E\"\u003EE\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EE\u003C/span\u003E\u003C/kbd\u003E ellipse, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E cloud, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E callout, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"T\"\u003ET\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ET\u003C/span\u003E\u003C/kbd\u003E text, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E note, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"S\"\u003ES\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ES\u003C/span\u003E\u003C/kbd\u003E stamp, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E length, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E area, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E count. The start.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPDF review\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EA menu bar (\u003Cspan class=\"hui\"\u003EFile\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EView\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDocument\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EMarkup\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EMeasure\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EReview\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EWindow\u003C/span\u003E) over a row of review tools, with keys set out the way PDF review programs set theirs: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"V\"\u003EV\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EV\u003C/span\u003E\u003C/kbd\u003E select, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift V\"\u003E⇧V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+V\u003C/span\u003E\u003C/kbd\u003E pan, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"H\"\u003EH\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EH\u003C/span\u003E\u003C/kbd\u003E highlighter, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E callout, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E polygon, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift N\"\u003E⇧N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+N\u003C/span\u003E\u003C/kbd\u003E polyline, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift T\"\u003E⇧T\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+T\u003C/span\u003E\u003C/kbd\u003E note, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift A\"\u003E⇧A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+A\u003C/span\u003E\u003C/kbd\u003E arc, and the measurements on \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift\"\u003E⌥⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift\u003C/span\u003E\u003C/kbd\u003E: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift K\"\u003E⌥⇧K\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift+K\u003C/span\u003E\u003C/kbd\u003E calibrate, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift L\"\u003E⌥⇧L\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift+L\u003C/span\u003E\u003C/kbd\u003E length, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift G\"\u003E⌥⇧G\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift+G\u003C/span\u003E\u003C/kbd\u003E angle, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift A\"\u003E⌥⇧A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift+A\u003C/span\u003E\u003C/kbd\u003E area, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option Shift C\"\u003E⌥⇧C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+Shift+C\u003C/span\u003E\u003C/kbd\u003E count. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option L\"\u003E⌥L\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+L\u003C/span\u003E\u003C/kbd\u003E opens the markups list. The middle button pans; a right click does not.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ERibbon\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003ETabs named for the work: \u003Cspan class=\"hui\"\u003EMark up\u003C/span\u003E (select, draw, clouds, callouts, text, notes, stamps), \u003Cspan class=\"hui\"\u003EMeasure\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EReview\u003C/span\u003E (the markups list and its exports, BCF issues, the punch list, field records, the tool chest, compare), \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EView\u003C/span\u003E, with \u003Cspan class=\"hui\"\u003EFile\u003C/span\u003E and quick buttons for open, save, undo and redo. The tools keep MarkupCraft&#039;s own one-letter keys. A button for a panel that is not open opens that panel first.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EEvery style keeps the \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command\"\u003E⌘\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E keys: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Y\"\u003E⌘Y\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Y\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command O\"\u003E⌘O\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+O\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command P\"\u003E⌘P\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+P\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command X\"\u003E⌘X\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+X\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command D\"\u003E⌘D\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+D\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command A\"\u003E⌘A\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+A\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command F\"\u003E⌘F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+F\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 0\"\u003E⌘0\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+0\u003C/span\u003E\u003C/kbd\u003E fit page and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command 9\"\u003E⌘9\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+9\u003C/span\u003E\u003C/kbd\u003E fit width; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↑\"\u003Efn ↑\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Up\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ↓\"\u003Efn ↓\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EPage Down\u003C/span\u003E\u003C/kbd\u003E change sheet.\u003C/p\u003E\n\u003Caside class=\"hc hc-tip\"\u003E\u003Cp class=\"hc-label\"\u003ETip\u003C/p\u003E\n\u003Cp\u003EA key that belongs to MarkupCraft&#039;s own layout but not to the style you picked does nothing, and the status bar says where its tool went (&quot;In PDF review, Callout is Q&quot;). \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Tab\"\u003ETab\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ETab\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and the arrows always keep their meaning. While you type in a text box, callout or note, every key is the text&#039;s, and numbers typed while drawing still open the length box.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"make-it-your-own\"\u003EMake it your own\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EPick the style closest to what you want, then click \u003Cspan class=\"hui\"\u003ECustomize…\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EOn \u003Cspan class=\"hui\"\u003EKeys and menus\u003C/span\u003E, find a tool (the search box helps). \u003Cspan class=\"hui\"\u003EAdd a key\u003C/span\u003E and press the key, or two keys in a row for a two-letter key. Click a key to take it off.\u003C/li\u003E\u003Cli\u003EWith the menu bar, \u003Cspan class=\"hui\"\u003EWhere it sits\u003C/span\u003E moves the tool to another menu, or to \u003Cspan class=\"hui\"\u003EKeys only\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EOn \u003Cspan class=\"hui\"\u003EMouse\u003C/span\u003E, set the wheel and the buttons that pan the sheet.\u003C/li\u003E\u003Cli\u003EGive it a name and click \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ESaving a built-in style makes your own copy (&quot;My PDF review&quot;); the built-in one never changes. A key given to two tools is shown in red and has to be fixed before you can save.\u003C/p\u003E\n\u003Ch2 id=\"mouse\"\u003EMouse\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EMouse wheel\u003C/strong\u003E: \u003Cspan class=\"hui\"\u003EScroll up zooms in\u003C/span\u003E (the start) or \u003Cspan class=\"hui\"\u003EScroll up zooms out\u003C/span\u003E, and how fast. A trackpad pinch always zooms the way your fingers move.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPan the sheet with\u003C/strong\u003E: the middle button, the right button, or both. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E and drag, and the \u003Cspan class=\"hui\"\u003EPan\u003C/span\u003E tool, always pan; the left button otherwise draws and selects, so ticking it changes nothing here.\u003C/li\u003E\u003Cli\u003EMarkupCraft has no 3D view, so the 3D buttons do nothing here.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"take-it-with-you\"\u003ETake it with you\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EExport\u003C/span\u003E saves the style in use as a small \u003Ccode\u003E.ccinput.json\u003C/code\u003E file; \u003Cspan class=\"hui\"\u003EImport…\u003C/span\u003E adds one, from another computer or a colleague. An imported file can only point at MarkupCraft&#039;s own tools: anything else in it is left out and counted in the status bar. \u003Cspan class=\"hui\"\u003EDelete this style\u003C/span\u003E removes one of your own.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EThese settings stay in this browser. \u003Cspan class=\"hui\"\u003EUse this style in every app\u003C/span\u003E under the style cards makes every app open in its matching style: \u003Cspan class=\"hui\"\u003EPDF review\u003C/span\u003E goes with the other apps&#039; menu-bar styles, \u003Cspan class=\"hui\"\u003ERibbon\u003C/span\u003E with their ribbons, MarkupCraft&#039;s own toolbar with theirs. An app without a matching style keeps its own.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Caside class=\"hc hc-tip\"\u003E\u003Cp class=\"hc-label\"\u003ETip\u003C/p\u003E\n\u003Cp\u003EThe workspace layouts in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E › \u003Cspan class=\"hui\"\u003ELayout\u003C/span\u003E (\u003Cspan class=\"hui\"\u003ERibbon and project browser\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EToolbox and info box\u003C/span\u003E) build their ribbon from the \u003Cspan class=\"hui\"\u003ERibbon\u003C/span\u003E style&#039;s tabs and their toolbox from MarkupCraft&#039;s toolbar, so every tool runs the same way in them.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003ERelated: \u003Ca href=\"/tutorials/markupcraft/keyboard\" data-topic=\"markupcraft/keyboard\"\u003EKeyboard and mouse\u003C/a\u003E · \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003EMarkupCraft settings\u003C/a\u003E · \u003Ca href=\"/tutorials/markupcraft/coming-from\" data-topic=\"markupcraft/coming-from\"\u003EComing from other markup software\u003C/a\u003E\u003C/p\u003E","text":"MarkupCraft's tools are the same whichever way you reach them. A menu style only decides where they sit on screen, what they are called there and which keys pick them. Choose one in Settings (Ctrl+,) › MarkupCraft › Menus, keys and mouse; the change is immediate, and this browser remembers it. The three styles Style What you get MarkupCraft MarkupCraft's own toolbar (File, Select, Draw, Revise, Annotate, Measure, Edit) and its one-letter keys: V select, H pan, P pen, I highlighter, L line, A arrow, R rectangle, E ellipse, C cloud, K callout, T text, N note, S stamp, M length, Q area, U count. The start. PDF review A menu bar (File, Edit, View, Document, Markup, Measure, Review, Window) over a row of review tools, with keys set out the way PDF review programs set theirs: V select, Shift+V pan, H highlighter, Q callout, N polygon, Shift+N polyline, Shift+T note, Shift+A arc, and the measurements on Alt+Shift: Alt+Shift+K calibrate, Alt+Shift+L length, Alt+Shift+G angle, Alt+Shift+A area, Alt+Shift+C count. Alt+L opens the markups list. The middle button pans; a right click does not. Ribbon Tabs named for the work: Mark up (select, draw, clouds, callouts, text, notes, stamps), Measure, Edit, Review (the markups list and its exports, BCF issues, the punch list, field records, the tool chest, compare), Pages and View, with File and quick buttons for open, save, undo and redo. The tools keep MarkupCraft's own one-letter keys. A button for a panel that is not open opens that panel first. Every style keeps the Ctrl keys: Ctrl+Z, Ctrl+Y, Ctrl+S, Ctrl+O, Ctrl+P, Ctrl+C, Ctrl+X, Ctrl+V, Ctrl+D, Ctrl+A, Ctrl+F, Ctrl+0 fit page and Ctrl+9 fit width; Page Up and Page Down change sheet. A key that belongs to MarkupCraft's own layout but not to the style you picked does nothing, and the status bar says where its tool went (\"In PDF review, Callout is Q\"). Delete, Esc, Enter, Tab, Space and the arrows always keep their meaning. While you type in a text box, callout or note, every key is the text's, and numbers typed while drawing still open the length box. Make it your own Pick the style closest to what you want, then click Customize…. On Keys and menus, find a tool (the search box helps). Add a key and press the key, or two keys in a row for a two-letter key. Click a key to take it off. With the menu bar, Where it sits moves the tool to another menu, or to Keys only. On Mouse, set the wheel and the buttons that pan the sheet. Give it a name and click Save. Saving a built-in style makes your own copy (\"My PDF review\"); the built-in one never changes. A key given to two tools is shown in red and has to be fixed before you can save. Mouse Mouse wheel: Scroll up zooms in (the start) or Scroll up zooms out, and how fast. A trackpad pinch always zooms the way your fingers move. Pan the sheet with: the middle button, the right button, or both. Space and drag, and the Pan tool, always pan; the left button otherwise draws and selects, so ticking it changes nothing here. MarkupCraft has no 3D view, so the 3D buttons do nothing here. Take it with you Export saves the style in use as a small .ccinput.json file; Import… adds one, from another computer or a colleague. An imported file can only point at MarkupCraft's own tools: anything else in it is left out and counted in the status bar. Delete this style removes one of your own. These settings stay in this browser. Use this style in every app under the style cards makes every app open in its matching style: PDF review goes with the other apps' menu-bar styles, Ribbon with their ribbons, MarkupCraft's own toolbar with theirs. An app without a matching style keeps its own. The workspace layouts in Settings › Global › Layout (Ribbon and project browser, Toolbox and info box) build their ribbon from the Ribbon style's tabs and their toolbox from MarkupCraft's toolbar, so every tool runs the same way in them. Related: Keyboard and mouse · MarkupCraft settings · Coming from other markup software","lang":"en"},{"slug":"markup-types","scope":"markupcraft","title":"Every markup type","summary":"The seventeen kinds of markup, their keys, how each is drawn, its default look, and what it becomes in the saved PDF.","section":"reference","order":20,"keywords":["markup types","tools list","annotation types","cloud","callout","text","note","stamp","pen","highlighter","line","arrow","rectangle","ellipse","polyline","polygon","length","area","count"],"headings":[{"id":"the-tools","text":"The tools","level":2},{"id":"what-every-markup-carries","text":"What every markup carries","level":2},{"id":"read-only-comments","text":"Read-only comments","level":2},{"id":"not-built-yet","text":"Not built yet","level":2}],"html":"\u003Ch2 id=\"the-tools\"\u003EThe tools\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EToolbar\u003C/th\u003E\u003Cth scope=\"col\"\u003EKey\u003C/th\u003E\u003Cth scope=\"col\"\u003EHow to draw\u003C/th\u003E\u003Cth scope=\"col\"\u003EDefault look\u003C/th\u003E\u003Cth scope=\"col\"\u003EIn the saved PDF\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPen\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"P\"\u003EP\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EP\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag\u003C/td\u003E\u003Ctd\u003ERed, 1.5 pt\u003C/td\u003E\u003Ctd\u003EInk\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EHighlight\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"I\"\u003EI\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EI\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag\u003C/td\u003E\u003Ctd\u003EYellow, 14 pt wide, see-through, tints what is under it\u003C/td\u003E\u003Ctd\u003EInk (marked as a highlighter stroke)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ELine\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"L\"\u003EL\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EL\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag, or click start and end\u003C/td\u003E\u003Ctd\u003ERed, 2 pt\u003C/td\u003E\u003Ctd\u003ELine\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArrow\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"A\"\u003EA\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EA\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag, or click start and end\u003C/td\u003E\u003Ctd\u003ERed, 2 pt, closed arrowhead at the end\u003C/td\u003E\u003Ctd\u003ELine with an arrowhead\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArc\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"O\"\u003EO\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EO\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick the start, a point on the arc, then the end\u003C/td\u003E\u003Ctd\u003ERed, 2 pt\u003C/td\u003E\u003Ctd\u003EPolyline along the arc\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"R\"\u003ER\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ER\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag a box\u003C/td\u003E\u003Ctd\u003ERed, 2 pt, no fill\u003C/td\u003E\u003Ctd\u003ESquare\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"E\"\u003EE\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EE\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag a box\u003C/td\u003E\u003Ctd\u003ERed, 2 pt, no fill\u003C/td\u003E\u003Ctd\u003ECircle\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Y\"\u003EY\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EY\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick points, double-click to finish\u003C/td\u003E\u003Ctd\u003ERed, 2 pt\u003C/td\u003E\u003Ctd\u003EPolyline\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"G\"\u003EG\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EG\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick points, double-click to finish\u003C/td\u003E\u003Ctd\u003ERed, 2 pt, no fill\u003C/td\u003E\u003Ctd\u003EPolygon\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"C\"\u003EC\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EC\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EDrag a box\u003C/td\u003E\u003Ctd\u003ERed, 1.5 pt scallops\u003C/td\u003E\u003Ctd\u003ESquare with a cloudy border\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift C\"\u003E⇧C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+C\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick points, double-click to finish\u003C/td\u003E\u003Ctd\u003ERed, 1.5 pt scallops\u003C/td\u003E\u003Ctd\u003EPolygon with a cloudy border\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECallout\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"K\"\u003EK\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EK\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPress on the point, drag to the text, type\u003C/td\u003E\u003Ctd\u003ERed text and leader, 1 pt, 12 pt text\u003C/td\u003E\u003Ctd\u003EText box with a callout leader\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EText\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"T\"\u003ET\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ET\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick or drag a box, type\u003C/td\u003E\u003Ctd\u003ERed 12 pt text, no border\u003C/td\u003E\u003Ctd\u003EText box\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ENote\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"N\"\u003EN\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EN\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick, type\u003C/td\u003E\u003Ctd\u003EYellow note icon\u003C/td\u003E\u003Ctd\u003ESticky note\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"S\"\u003ES\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ES\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EPick a stamp, click or drag\u003C/td\u003E\u003Ctd\u003EFramed capitals plus &quot;By &lt;name&gt;, &lt;date&gt;&quot;; colored by meaning\u003C/td\u003E\u003Ctd\u003EStamp\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"M\"\u003EM\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EM\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick start and end (needs a scale)\u003C/td\u003E\u003Ctd\u003EBlue dimension line with ticks and the length\u003C/td\u003E\u003Ctd\u003ELine marked as a dimension, with a measurement\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EAngle\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"X\"\u003EX\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EX\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick one arm&#039;s end, the corner, then the other arm&#039;s end\u003C/td\u003E\u003Ctd\u003EBlue arms, a small arc at the corner and the angle in degrees\u003C/td\u003E\u003Ctd\u003EPolyline with the angle as its text\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Q\"\u003EQ\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EQ\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick corners, double-click to finish (needs a scale)\u003C/td\u003E\u003Ctd\u003EBlue outline, light blue fill, area and perimeter\u003C/td\u003E\u003Ctd\u003EPolygon marked as an area, with a measurement\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"U\"\u003EU\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EU\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EClick each item\u003C/td\u003E\u003Ctd\u003EOrange numbered dots and a &quot;group: n&quot; tag\u003C/td\u003E\u003Ctd\u003EOne ink comment per group, a ring per item\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EOn touch, &quot;double-click to finish&quot; is a double-tap, and &quot;click&quot; is a tap that acts when you lift (for points, notes and counts).\u003C/p\u003E\n\u003Ch2 id=\"what-every-markup-carries\"\u003EWhat every markup carries\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EField\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhere you see it\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EAuthor\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, the list, the stamp&#039;s second line, other PDF viewers\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECreated and modified\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E (your time zone), the list, the CSV\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStatus\u003C/td\u003E\u003Ctd\u003EOpen, Accepted, Rejected or Completed\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESubject\u003C/td\u003E\u003Ctd\u003EA short label; defaults to the kind (&quot;Cloud&quot;, &quot;Text box&quot;, &quot;Length measurement&quot;)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EComment\u003C/td\u003E\u003Ctd\u003ELonger notes. For a note, its text is its comment.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EText\u003C/td\u003E\u003Ctd\u003EText boxes and callouts only\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EReplies\u003C/td\u003E\u003Ctd\u003EThe thread, with status changes\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPunch item\u003C/td\u003E\u003Ctd\u003ENumber, assignee, due date, item status, when added to the punch list\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStyle\u003C/td\u003E\u003Ctd\u003EColor, line width, fill and fill opacity (closed shapes, text and callouts), opacity, text size (text, callouts and measurements)\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"read-only-comments\"\u003ERead-only comments\u003C/h2\u003E\n\u003Cp\u003EComments that came with the file and that MarkupCraft cannot edit (text highlights, other programs&#039; stamps and other special kinds) are listed with the type &quot;Other&quot; and the status chip &quot;Read-only&quot;. They keep exactly the look the file gives them. You can select them, see their author, subject and comment, and reply to them.\u003C/p\u003E\n\u003Ch2 id=\"not-built-yet\"\u003ENot built yet\u003C/h2\u003E\n\u003Cp\u003EFile attachments are not built yet. Any markup can link to a sheet; see \u003Ca href=\"/tutorials/markupcraft/sheet-links\" data-topic=\"markupcraft/sheet-links\"\u003ESheet links\u003C/a\u003E. Pictures and signatures are placed with the \u003Cspan class=\"hui\"\u003EStamp\u003C/span\u003E tool; see \u003Ca href=\"/tutorials/markupcraft/stamps-and-notes\" data-topic=\"markupcraft/stamps-and-notes\"\u003EStamps and notes\u003C/a\u003E. See \u003Ca href=\"/tutorials/markupcraft/not-built-yet\" data-topic=\"markupcraft/not-built-yet\"\u003EWhat is not built yet\u003C/a\u003E.\u003C/p\u003E","text":"The tools Toolbar Key How to draw Default look In the saved PDF Pen P Drag Red, 1.5 pt Ink Highlight I Drag Yellow, 14 pt wide, see-through, tints what is under it Ink (marked as a highlighter stroke) Line L Drag, or click start and end Red, 2 pt Line Arrow A Drag, or click start and end Red, 2 pt, closed arrowhead at the end Line with an arrowhead Arc O Click the start, a point on the arc, then the end Red, 2 pt Polyline along the arc Rectangle R Drag a box Red, 2 pt, no fill Square Ellipse E Drag a box Red, 2 pt, no fill Circle Polyline Y Click points, double-click to finish Red, 2 pt Polyline Polygon G Click points, double-click to finish Red, 2 pt, no fill Polygon Cloud C Drag a box Red, 1.5 pt scallops Square with a cloudy border Free cloud Shift+C Click points, double-click to finish Red, 1.5 pt scallops Polygon with a cloudy border Callout K Press on the point, drag to the text, type Red text and leader, 1 pt, 12 pt text Text box with a callout leader Text T Click or drag a box, type Red 12 pt text, no border Text box Note N Click, type Yellow note icon Sticky note Stamp S Pick a stamp, click or drag Framed capitals plus \"By \u003Cname\u003E, \u003Cdate\u003E\"; colored by meaning Stamp Length M Click start and end (needs a scale) Blue dimension line with ticks and the length Line marked as a dimension, with a measurement Angle X Click one arm's end, the corner, then the other arm's end Blue arms, a small arc at the corner and the angle in degrees Polyline with the angle as its text Area Q Click corners, double-click to finish (needs a scale) Blue outline, light blue fill, area and perimeter Polygon marked as an area, with a measurement Count U Click each item Orange numbered dots and a \"group: n\" tag One ink comment per group, a ring per item On touch, \"double-click to finish\" is a double-tap, and \"click\" is a tap that acts when you lift (for points, notes and counts). What every markup carries Field Where you see it Author Properties, the list, the stamp's second line, other PDF viewers Created and modified Properties (your time zone), the list, the CSV Status Open, Accepted, Rejected or Completed Subject A short label; defaults to the kind (\"Cloud\", \"Text box\", \"Length measurement\") Comment Longer notes. For a note, its text is its comment. Text Text boxes and callouts only Replies The thread, with status changes Punch item Number, assignee, due date, item status, when added to the punch list Style Color, line width, fill and fill opacity (closed shapes, text and callouts), opacity, text size (text, callouts and measurements) Read-only comments Comments that came with the file and that MarkupCraft cannot edit (text highlights, other programs' stamps and other special kinds) are listed with the type \"Other\" and the status chip \"Read-only\". They keep exactly the look the file gives them. You can select them, see their author, subject and comment, and reply to them. Not built yet File attachments are not built yet. Any markup can link to a sheet; see Sheet links. Pictures and signatures are placed with the Stamp tool; see Stamps and notes. See What is not built yet.","lang":"en"},{"slug":"units-and-scales","scope":"markupcraft","title":"Units, lengths and scales","summary":"Every way to type a length, the units lengths and areas are shown in, rounding, and the list of preset scales.","section":"reference","order":30,"keywords":["units","feet","inches","feet and inches","metric","meters","millimeters","centimeters","scale","preset","architectural scale","engineering scale","ratio","square feet","rounding","fractions"],"headings":[{"id":"typing-a-length","text":"Typing a length","level":2},{"id":"how-lengths-and-areas-are-shown","text":"How lengths and areas are shown","level":2},{"id":"preset-scales","text":"Preset scales","level":2},{"id":"scales-other-programs-saved","text":"Scales other programs saved","level":2},{"id":"paper-positions","text":"Paper positions","level":2},{"id":"accuracy","text":"Accuracy","level":2}],"html":"\u003Ch2 id=\"typing-a-length\"\u003ETyping a length\u003C/h2\u003E\n\u003Cp\u003EWhen you calibrate from two points, you type the real distance. MarkupCraft reads all of these:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EYou type\u003C/th\u003E\u003Cth scope=\"col\"\u003EIt means\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E24&#039;-0&quot;\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003E24 feet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E12&#039; 6 1/2&quot;\u003C/code\u003E or \u003Ccode\u003E12&#039;-6 1/2&quot;\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003E12 feet 6½ inches\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E12&#039; 6\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003E12 feet 6 inches (inch mark left off)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E6&quot;\u003C/code\u003E or \u003Ccode\u003E1/2&quot;\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Einches\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E12.5&#039;\u003C/code\u003E or \u003Ccode\u003E12.5 ft\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003E12½ feet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E3 ft 6 in\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003E3 feet 6 inches (also feet, foot, inch, inches)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E3.5 m\u003C/code\u003E, \u003Ccode\u003E90 cm\u003C/code\u003E, \u003Ccode\u003E900 mm\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Emetric (also meter, metre, millimeter, centimetre…)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E24\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Ea bare number, in the unit chosen under \u003Cspan class=\"hui\"\u003EShow lengths in\u003C/span\u003E\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003ECurly quotes (’ ”) and two apostrophes (&#039;&#039;) for inches work too. Zero and negative lengths are refused.\u003C/p\u003E\n\u003Caside class=\"hc hc-warning\"\u003E\u003Cp class=\"hc-label\"\u003EWarning\u003C/p\u003E\n\u003Cp\u003EA comma is read as a decimal point: \u003Ccode\u003E1,5 m\u003C/code\u003E is 1.5 meters. Do not type thousands separators: \u003Ccode\u003E1,200 mm\u003C/code\u003E is read as 1.2 millimeters. Type \u003Ccode\u003E1200 mm\u003C/code\u003E.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"how-lengths-and-areas-are-shown\"\u003EHow lengths and areas are shown\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003E\u003Cspan class=\"hui\"\u003EShow lengths in\u003C/span\u003E\u003C/th\u003E\u003Cth scope=\"col\"\u003EA length shows as\u003C/th\u003E\u003Cth scope=\"col\"\u003EAn area shows as\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EFeet and inches\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ccode\u003E12&#039;-6 1/2&quot;\u003C/code\u003E, rounded to 1/16&quot;\u003C/td\u003E\u003Ctd\u003Esquare feet, two decimals\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EDecimal feet\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ccode\u003E12.54&#039;\u003C/code\u003E, two decimals\u003C/td\u003E\u003Ctd\u003Esquare feet, two decimals\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EInches\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ccode\u003E150.5&quot;\u003C/code\u003E, up to two decimals\u003C/td\u003E\u003Ctd\u003Esquare inches, one decimal\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMeters\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ccode\u003E3.820 m\u003C/code\u003E, three decimals\u003C/td\u003E\u003Ctd\u003Esquare meters, three decimals\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EMillimeters\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003E\u003Ccode\u003E3820 mm\u003C/code\u003E, whole millimeters\u003C/td\u003E\u003Ctd\u003Esquare millimeters, whole\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EThe perimeter of an area uses the length format.\u003C/p\u003E\n\u003Ch2 id=\"preset-scales\"\u003EPreset scales\u003C/h2\u003E\n\u003Cp\u003EThe presets assume the PDF is at its full printed size: 72 PDF points to the inch, as a CAD program plots it.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EGroup\u003C/th\u003E\u003Cth scope=\"col\"\u003EScales\u003C/th\u003E\u003Cth scope=\"col\"\u003ELengths shown in\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EArchitectural\u003C/td\u003E\u003Ctd\u003E1/32&quot; = 1&#039;-0&quot;, 1/16&quot;, 3/32&quot;, 1/8&quot;, 3/16&quot;, 1/4&quot;, 3/8&quot;, 1/2&quot;, 3/4&quot;, 1&quot;, 1 1/2&quot;, 3&quot; = 1&#039;-0&quot;\u003C/td\u003E\u003Ctd\u003EFeet and inches\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEngineering\u003C/td\u003E\u003Ctd\u003E1&quot; = 10&#039;, 20&#039;, 30&#039;, 40&#039;, 50&#039;, 60&#039;, 100&#039;\u003C/td\u003E\u003Ctd\u003EDecimal feet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMetric\u003C/td\u003E\u003Ctd\u003E1:1, 1:5, 1:10, 1:20, 1:25, 1:50\u003C/td\u003E\u003Ctd\u003EMillimeters\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMetric\u003C/td\u003E\u003Ctd\u003E1:100, 1:200, 1:250, 1:500, 1:1000\u003C/td\u003E\u003Ctd\u003EMeters\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003ETo use a preset scale but see lengths in another unit, calibrate from two points instead and pick the unit there.\u003C/p\u003E\n\u003Ch2 id=\"scales-other-programs-saved\"\u003EScales other programs saved\u003C/h2\u003E\n\u003Cp\u003EWhen a PDF already carries a scale for a page from another program (a measurement scale stored on the page), MarkupCraft uses it if it is in feet, inches, meters, centimeters or millimeters. Its label is shown as the file states it.\u003C/p\u003E\n\u003Ch2 id=\"paper-positions\"\u003EPaper positions\u003C/h2\u003E\n\u003Cp\u003EThe status bar shows where the pointer is on the paper, in inches from the sheet&#039;s top-left corner, whatever the sheet&#039;s scale. Compare&#039;s nudge steps are in points (72 points to an inch).\u003C/p\u003E\n\u003Ch2 id=\"accuracy\"\u003EAccuracy\u003C/h2\u003E\n\u003Cp\u003EA measurement is as good as the calibration and your clicks. Calibrate over the longest known dimension you can find, zoom in to click its ends, then check one other dimension. A PDF that was scaled when it was made (a &quot;fit to page&quot; plot or a half-size set) is still accurate after calibrating from a dimension, but not with a preset.\u003C/p\u003E","text":"Typing a length When you calibrate from two points, you type the real distance. MarkupCraft reads all of these: You type It means 24'-0\" 24 feet 12' 6 1/2\" or 12'-6 1/2\" 12 feet 6½ inches 12' 6 12 feet 6 inches (inch mark left off) 6\" or 1/2\" inches 12.5' or 12.5 ft 12½ feet 3 ft 6 in 3 feet 6 inches (also feet, foot, inch, inches) 3.5 m, 90 cm, 900 mm metric (also meter, metre, millimeter, centimetre…) 24 a bare number, in the unit chosen under Show lengths in Curly quotes (’ ”) and two apostrophes ('') for inches work too. Zero and negative lengths are refused. A comma is read as a decimal point: 1,5 m is 1.5 meters. Do not type thousands separators: 1,200 mm is read as 1.2 millimeters. Type 1200 mm. How lengths and areas are shown Show lengths in A length shows as An area shows as Feet and inches 12'-6 1/2\", rounded to 1/16\" square feet, two decimals Decimal feet 12.54', two decimals square feet, two decimals Inches 150.5\", up to two decimals square inches, one decimal Meters 3.820 m, three decimals square meters, three decimals Millimeters 3820 mm, whole millimeters square millimeters, whole The perimeter of an area uses the length format. Preset scales The presets assume the PDF is at its full printed size: 72 PDF points to the inch, as a CAD program plots it. Group Scales Lengths shown in Architectural 1/32\" = 1'-0\", 1/16\", 3/32\", 1/8\", 3/16\", 1/4\", 3/8\", 1/2\", 3/4\", 1\", 1 1/2\", 3\" = 1'-0\" Feet and inches Engineering 1\" = 10', 20', 30', 40', 50', 60', 100' Decimal feet Metric 1:1, 1:5, 1:10, 1:20, 1:25, 1:50 Millimeters Metric 1:100, 1:200, 1:250, 1:500, 1:1000 Meters To use a preset scale but see lengths in another unit, calibrate from two points instead and pick the unit there. Scales other programs saved When a PDF already carries a scale for a page from another program (a measurement scale stored on the page), MarkupCraft uses it if it is in feet, inches, meters, centimeters or millimeters. Its label is shown as the file states it. Paper positions The status bar shows where the pointer is on the paper, in inches from the sheet's top-left corner, whatever the sheet's scale. Compare's nudge steps are in points (72 points to an inch). Accuracy A measurement is as good as the calibration and your clicks. Calibrate over the longest known dimension you can find, zoom in to click its ends, then check one other dimension. A PDF that was scaled when it was made (a \"fit to page\" plot or a half-size set) is still accurate after calibrating from a dimension, but not with a preset.","lang":"en"},{"slug":"what-the-pdf-keeps","scope":"markupcraft","title":"What is saved in the PDF","summary":"Exactly what the marked-up copy contains, what other PDF programs see, and what is read back when you open a file.","section":"reference","order":40,"keywords":["pdf annotations","comments","saved data","round trip","page labels","measurement","review state","replies","interoperability","compatibility","reopen","private data"],"headings":[{"id":"each-markup","text":"Each markup","level":2},{"id":"threads-and-statuses","text":"Threads and statuses","level":2},{"id":"each-sheet","text":"Each sheet","level":2},{"id":"text-and-characters","text":"Text and characters","level":2},{"id":"what-happens-to-comments-that-were-already-there","text":"What happens to comments that were already there","level":2},{"id":"what-is-not-changed","text":"What is not changed","level":2}],"html":"\u003Cp\u003EThe marked-up copy is the original PDF with comments (PDF annotations) added. The pages themselves, their drawings, text, bookmarks and links are copied as they were.\u003C/p\u003E\n\u003Ch2 id=\"each-markup\"\u003EEach markup\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EMarkupCraft\u003C/th\u003E\u003Cth scope=\"col\"\u003ESaved as\u003C/th\u003E\u003Cth scope=\"col\"\u003EOther PDF viewers show\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003ERectangle, box cloud\u003C/td\u003E\u003Ctd\u003ESquare annotation (cloud: cloudy border)\u003C/td\u003E\u003Ctd\u003EA rectangle or cloud comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEllipse\u003C/td\u003E\u003Ctd\u003ECircle annotation\u003C/td\u003E\u003Ctd\u003EAn ellipse comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPolygon, free cloud\u003C/td\u003E\u003Ctd\u003EPolygon annotation (cloud: cloudy border)\u003C/td\u003E\u003Ctd\u003EA polygon or cloud comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPolyline\u003C/td\u003E\u003Ctd\u003EPolyLine annotation\u003C/td\u003E\u003Ctd\u003EA polyline comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELine, arrow\u003C/td\u003E\u003Ctd\u003ELine annotation (arrow: closed arrowhead)\u003C/td\u003E\u003Ctd\u003EA line or arrow comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELength\u003C/td\u003E\u003Ctd\u003ELine annotation marked as a dimension, with a measurement\u003C/td\u003E\u003Ctd\u003EA length measurement, where the viewer supports them\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EArea\u003C/td\u003E\u003Ctd\u003EPolygon annotation marked as an area, with a measurement\u003C/td\u003E\u003Ctd\u003EAn area measurement, where supported; otherwise a polygon\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECount group\u003C/td\u003E\u003Ctd\u003EOne ink annotation, a ring per item; its text is &quot;group: n&quot;\u003C/td\u003E\u003Ctd\u003EAn ink comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPen, highlighter\u003C/td\u003E\u003Ctd\u003EInk annotation (highlighter marked as such)\u003C/td\u003E\u003Ctd\u003EAn ink comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EText\u003C/td\u003E\u003Ctd\u003EFreeText annotation\u003C/td\u003E\u003Ctd\u003EA text box comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECallout\u003C/td\u003E\u003Ctd\u003EFreeText annotation with a callout leader\u003C/td\u003E\u003Ctd\u003EA callout comment\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ENote\u003C/td\u003E\u003Ctd\u003EText annotation\u003C/td\u003E\u003Ctd\u003EA sticky note that opens to its text\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStamp\u003C/td\u003E\u003Ctd\u003EStamp annotation\u003C/td\u003E\u003Ctd\u003EA stamp comment\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EEvery one is saved with:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003Eits own appearance\u003C/strong\u003E, drawn exactly as MarkupCraft draws it on screen, so it looks the same in any viewer and prints the same, punch number badge included;\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003Ethe author\u003C/strong\u003E, \u003Cstrong\u003Ethe created and modified dates\u003C/strong\u003E, \u003Cstrong\u003Ethe subject\u003C/strong\u003E, \u003Cstrong\u003Ethe comment text\u003C/strong\u003E (for text boxes and callouts, the text and the comment), \u003Cstrong\u003Ethe color\u003C/strong\u003E and \u003Cstrong\u003Ethe opacity\u003C/strong\u003E;\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003Eits MarkupCraft details\u003C/strong\u003E in a private entry that other programs ignore: status, punch item, style and type, so it reopens exactly.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"threads-and-statuses\"\u003EThreads and statuses\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EEach reply is saved as a reply comment linked to its markup, with its author, date and text. Replies have no icon of their own on the sheet.\u003C/li\u003E\u003Cli\u003EEach status change is saved as a reply carrying a review state. Other review tools show it as Accepted, Rejected or Completed; Open is saved as no state.\u003C/li\u003E\u003Cli\u003EA markup with a status other than Open but no logged status change gets one review-state reply, so other programs see the status too.\u003C/li\u003E\u003Cli\u003EReplies on read-only comments from the original file are saved the same way, linked to that comment.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"each-sheet\"\u003EEach sheet\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EScale:\u003C/strong\u003E a calibrated sheet gets a measurement viewport covering the page (the standard way to store a page scale) and MarkupCraft&#039;s own copy of the calibration.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESheet number:\u003C/strong\u003E a number typed with \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E becomes the page label. When any page of a file has one, every page of that file gets a label: its typed number, else its old label, else its page number.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESheet title:\u003C/strong\u003E a typed title is saved for MarkupCraft only; other viewers do not show it.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"text-and-characters\"\u003EText and characters\u003C/h2\u003E\n\u003Cp\u003EText is written in Helvetica, which every PDF viewer has. Letters outside the Western European set (Windows-1252) print as &quot;?&quot; in the copy; the save message counts them.\u003C/p\u003E\n\u003Ch2 id=\"what-happens-to-comments-that-were-already-there\"\u003EWhat happens to comments that were already there\u003C/h2\u003E\n\u003Cp\u003EWhen you open a PDF that already has comments:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EMarkupCraft&#039;s own comments are read back exactly. If another program moved or resized one, its new position wins.\u003C/li\u003E\u003Cli\u003ERectangles, ellipses, lines, polylines, polygons, ink, text boxes and sticky notes from other programs become editable markups. \u003Cstrong\u003EWhen you save, MarkupCraft removes the originals and writes them again its own way\u003C/strong\u003E, with their pop-ups and replies. Their look can change slightly.\u003C/li\u003E\u003Cli\u003EReview states from other programs set the status; the newest wins.\u003C/li\u003E\u003Cli\u003EEverything else (text highlights, other programs&#039; stamps and special kinds) is \u003Cstrong\u003Ekept untouched\u003C/strong\u003E in the copy, read-only.\u003C/li\u003E\u003Cli\u003ELinks and form fields are kept untouched and are not listed.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ESaving the same file again never doubles anything: the markups MarkupCraft read are replaced, not added again.\u003C/p\u003E\n\u003Ch2 id=\"what-is-not-changed\"\u003EWhat is not changed\u003C/h2\u003E\n\u003Cp\u003EYour original file on disk is never changed. The copy is not optimized for size, so it can be somewhat larger than the original. Protected (encrypted) PDFs cannot be saved.\u003C/p\u003E","text":"The marked-up copy is the original PDF with comments (PDF annotations) added. The pages themselves, their drawings, text, bookmarks and links are copied as they were. Each markup MarkupCraft Saved as Other PDF viewers show Rectangle, box cloud Square annotation (cloud: cloudy border) A rectangle or cloud comment Ellipse Circle annotation An ellipse comment Polygon, free cloud Polygon annotation (cloud: cloudy border) A polygon or cloud comment Polyline PolyLine annotation A polyline comment Line, arrow Line annotation (arrow: closed arrowhead) A line or arrow comment Length Line annotation marked as a dimension, with a measurement A length measurement, where the viewer supports them Area Polygon annotation marked as an area, with a measurement An area measurement, where supported; otherwise a polygon Count group One ink annotation, a ring per item; its text is \"group: n\" An ink comment Pen, highlighter Ink annotation (highlighter marked as such) An ink comment Text FreeText annotation A text box comment Callout FreeText annotation with a callout leader A callout comment Note Text annotation A sticky note that opens to its text Stamp Stamp annotation A stamp comment Every one is saved with: its own appearance, drawn exactly as MarkupCraft draws it on screen, so it looks the same in any viewer and prints the same, punch number badge included; the author, the created and modified dates, the subject, the comment text (for text boxes and callouts, the text and the comment), the color and the opacity; its MarkupCraft details in a private entry that other programs ignore: status, punch item, style and type, so it reopens exactly. Threads and statuses Each reply is saved as a reply comment linked to its markup, with its author, date and text. Replies have no icon of their own on the sheet. Each status change is saved as a reply carrying a review state. Other review tools show it as Accepted, Rejected or Completed; Open is saved as no state. A markup with a status other than Open but no logged status change gets one review-state reply, so other programs see the status too. Replies on read-only comments from the original file are saved the same way, linked to that comment. Each sheet Scale: a calibrated sheet gets a measurement viewport covering the page (the standard way to store a page scale) and MarkupCraft's own copy of the calibration. Sheet number: a number typed with Rename sheet becomes the page label. When any page of a file has one, every page of that file gets a label: its typed number, else its old label, else its page number. Sheet title: a typed title is saved for MarkupCraft only; other viewers do not show it. Text and characters Text is written in Helvetica, which every PDF viewer has. Letters outside the Western European set (Windows-1252) print as \"?\" in the copy; the save message counts them. What happens to comments that were already there When you open a PDF that already has comments: MarkupCraft's own comments are read back exactly. If another program moved or resized one, its new position wins. Rectangles, ellipses, lines, polylines, polygons, ink, text boxes and sticky notes from other programs become editable markups. When you save, MarkupCraft removes the originals and writes them again its own way, with their pop-ups and replies. Their look can change slightly. Review states from other programs set the status; the newest wins. Everything else (text highlights, other programs' stamps and special kinds) is kept untouched in the copy, read-only. Links and form fields are kept untouched and are not listed. Saving the same file again never doubles anything: the markups MarkupCraft read are replaced, not added again. What is not changed Your original file on disk is never changed. The copy is not optimized for size, so it can be somewhat larger than the original. Protected (encrypted) PDFs cannot be saved.","lang":"en"},{"slug":"bcf-basics","scope":"markupcraft","title":"BCF basics","summary":"What a BCF export from MarkupCraft contains, how to use it with BIM coordination tools, and its limits.","section":"reference","order":50,"keywords":["bcf","bcfzip","bim collaboration format","issues","coordination","clash","topics","viewpoint","snapshot","openbim","buildingsmart","export issues"],"headings":[{"id":"make-one","text":"Make one","level":2},{"id":"what-is-in-it","text":"What is in it","level":2},{"id":"limits-to-know","text":"Limits to know","level":2}],"html":"\u003Cp\u003EBCF (BIM Collaboration Format) is an open file format for passing issues between BIM tools. Many model coordination and authoring programs can import a \u003Ccode\u003E.bcfzip\u003C/code\u003E file as a list of issues. MarkupCraft writes \u003Cstrong\u003EBCF 2.1\u003C/strong\u003E.\u003C/p\u003E\n\u003Ch2 id=\"make-one\"\u003EMake one\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the \u003Cspan class=\"hui\"\u003EMarkups\u003C/span\u003E tab.\u003C/li\u003E\u003Cli\u003EFilter the list to what you want to send, for example \u003Cspan class=\"hui\"\u003EStatus\u003C/span\u003E &quot;Open&quot;. Only the listed markups are exported.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EBCF\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EWait while it makes a snapshot of each markup (&quot;Making snapshots for BCF (5 of 20)…&quot;).\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EResult: &quot;&lt;name&gt; markups.bcfzip&quot; downloads, and the status bar says how many topics it holds and the file size.\u003C/p\u003E\n\u003Ch2 id=\"what-is-in-it\"\u003EWhat is in it\u003C/h2\u003E\n\u003Cp\u003EEach markup becomes one \u003Cstrong\u003Etopic\u003C/strong\u003E:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ETopic field\u003C/th\u003E\u003Cth scope=\"col\"\u003EFilled with\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003ETitle\u003C/td\u003E\u003Ctd\u003EPunch number, subject and sheet, for example &quot;#4 Cloud on A-101 — Floor plan&quot;\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EType\u003C/td\u003E\u003Ctd\u003EThe markup kind (Cloud, Callout, Length…)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStatus\u003C/td\u003E\u003Ctd\u003EOpen, Accepted, Rejected or Completed\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELabels\u003C/td\u003E\u003Ctd\u003EThe markup kind and the sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EAuthor and dates\u003C/td\u003E\u003Ctd\u003EThe markup&#039;s author, created and modified dates\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EAssigned to, due date\u003C/td\u003E\u003Ctd\u003EFrom its punch item, when it has one\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EDescription\u003C/td\u003E\u003Ctd\u003EIts text or stamp wording, measured value, comment, and the sheet and file\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EComments\u003C/td\u003E\u003Ctd\u003EOne per reply, with author and date\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESnapshot\u003C/td\u003E\u003Ctd\u003EA picture of the markup on its part of the sheet\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EViewpoint\u003C/td\u003E\u003Ctd\u003EA top-down view of the markup&#039;s place on the sheet\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EExporting the same markup again gives the same topic ID, so a tool that imports BCF can recognize it as the same issue.\u003C/p\u003E\n\u003Ch2 id=\"limits-to-know\"\u003ELimits to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EA sheet is not a model.\u003C/strong\u003E The viewpoint points at the markup&#039;s position on the paper, measured in meters of paper. It does not take a BIM tool to a place in the model. Use the snapshot and the sheet name to find the spot.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EStatuses and types are MarkupCraft&#039;s own\u003C/strong\u003E (Open, Accepted, Rejected, Completed; Cloud, Callout…). The file declares them, as BCF allows, but a tool with fixed lists of its own may map or ignore them.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EImporting brings comments, not model views.\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EImport BCF\u003C/span\u003E adds replies and statuses to the markups you exported, and makes notes of other issues; it cannot show a model camera. See \u003Ca href=\"/tutorials/markupcraft/markups-list-and-export#import-bcf\" data-topic=\"markupcraft/markups-list-and-export\" data-hash=\"import-bcf\"\u003EMarkups list and export\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003ESending markups back as a PDF is often simpler for drawing reviews. BCF is for getting drawing comments into a model coordination workflow.\u003C/li\u003E\u003C/ul\u003E","text":"BCF (BIM Collaboration Format) is an open file format for passing issues between BIM tools. Many model coordination and authoring programs can import a .bcfzip file as a list of issues. MarkupCraft writes BCF 2.1. Make one Open the Markups tab. Filter the list to what you want to send, for example Status \"Open\". Only the listed markups are exported. Choose BCF. Wait while it makes a snapshot of each markup (\"Making snapshots for BCF (5 of 20)…\"). Result: \"\u003Cname\u003E markups.bcfzip\" downloads, and the status bar says how many topics it holds and the file size. What is in it Each markup becomes one topic: Topic field Filled with Title Punch number, subject and sheet, for example \"#4 Cloud on A-101 — Floor plan\" Type The markup kind (Cloud, Callout, Length…) Status Open, Accepted, Rejected or Completed Labels The markup kind and the sheet Author and dates The markup's author, created and modified dates Assigned to, due date From its punch item, when it has one Description Its text or stamp wording, measured value, comment, and the sheet and file Comments One per reply, with author and date Snapshot A picture of the markup on its part of the sheet Viewpoint A top-down view of the markup's place on the sheet Exporting the same markup again gives the same topic ID, so a tool that imports BCF can recognize it as the same issue. Limits to know A sheet is not a model. The viewpoint points at the markup's position on the paper, measured in meters of paper. It does not take a BIM tool to a place in the model. Use the snapshot and the sheet name to find the spot. Statuses and types are MarkupCraft's own (Open, Accepted, Rejected, Completed; Cloud, Callout…). The file declares them, as BCF allows, but a tool with fixed lists of its own may map or ignore them. Importing brings comments, not model views. Import BCF adds replies and statuses to the markups you exported, and makes notes of other issues; it cannot show a model camera. See Markups list and export. Sending markups back as a PDF is often simpler for drawing reviews. BCF is for getting drawing comments into a model coordination workflow.","lang":"en"},{"slug":"browser-storage","scope":"markupcraft","title":"What stays in this browser","summary":"Your name, settings, tool chest and the last markups you copied are kept in this browser on this computer; your markups are kept only in the PDFs you save.","section":"reference","order":60,"keywords":["local storage","browser storage","settings","preferences","profile","clear data","private window","incognito","backup","another computer","sync","reset"],"headings":[{"id":"what-is-kept-in-the-browser","text":"What is kept in the browser","level":2},{"id":"what-that-means","text":"What that means","level":2},{"id":"what-is-not-kept-in-the-browser","text":"What is not kept in the browser","level":2},{"id":"back-up-and-move-your-setup","text":"Back up and move your setup","level":2},{"id":"start-fresh","text":"Start fresh","level":2},{"id":"the-offline-copy","text":"The offline copy","level":2}],"html":"\u003Cp\u003EMarkupCraft has no account and no server storage. A few small things are kept in your browser&#039;s storage for this website, and everything else lives in your files.\u003C/p\u003E\n\u003Ch2 id=\"what-is-kept-in-the-browser\"\u003EWhat is kept in the browser\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EWhat\u003C/th\u003E\u003Cth scope=\"col\"\u003ESet where\u003C/th\u003E\u003Cth scope=\"col\"\u003EKept as\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EYour author name\u003C/td\u003E\u003Ctd\u003EThe name button in the status bar, or \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EOne name\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMarkupCraft settings\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E tab: color and line weight of new markups, where paste puts copies, units (see \u003Ca href=\"/tutorials/markupcraft/settings\" data-topic=\"markupcraft/settings\"\u003EMarkupCraft settings\u003C/a\u003E)\u003C/td\u003E\u003Ctd\u003EOne set\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETool settings\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E while a drawing tool is on: color, line, fill, opacity and text size per tool, the chosen stamp, the count group name\u003C/td\u003E\u003Ctd\u003EOne set\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETool chest\u003C/td\u003E\u003Ctd\u003EThe \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E tab\u003C/td\u003E\u003Ctd\u003EUp to 500 tools\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EWhat you last copied\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003ECopy\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ECut\u003C/span\u003E\u003C/td\u003E\u003Ctd\u003EThe copied markups, so another tab can paste them; replaced by the next copy\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EStamp picture and signature\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EPicture…\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EMy signature…\u003C/span\u003E in the stamp list\u003C/td\u003E\u003Ctd\u003EThe last picture and your signature\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ERecovery copies\u003C/td\u003E\u003Ctd\u003EKept for you while a PDF has unsaved markups\u003C/td\u003E\u003Ctd\u003EThe PDF and its markups, removed when you save, close or discard it; kept up to 30 days\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"what-that-means\"\u003EWhat that means\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EPer browser, per computer.\u003C/strong\u003E Chrome and Firefox on the same computer each have their own. Your laptop and the office desktop each have their own. Nothing syncs between them, even if you sign in to the browser.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPrivate and incognito windows\u003C/strong\u003E start empty and forget everything when they close.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EClearing site data erases it.\u003C/strong\u003E Clearing cookies and site data for this website, or for all sites, in the browser&#039;s settings removes your name, settings and chest. Some cleanup tools and some company policies do this automatically.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ENothing is uploaded.\u003C/strong\u003E These values never leave the computer, except your name inside the PDFs you save. Recovery copies stay in this browser too.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003ESafari can delete a website&#039;s stored data after some weeks without a visit. Open MarkupCraft now and then, and keep an exported tool chest.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"what-is-not-kept-in-the-browser\"\u003EWhat is not kept in the browser\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EYour markups, for good.\u003C/strong\u003E They belong in the &quot;(marked up)&quot; PDF you save. The recovery copy is a safety net for a crash or a closed tab, not a place to keep work: it goes when you save, and clearing site data removes it. See \u003Ca href=\"/tutorials/basics/recover\" data-topic=\"basics/recover\"\u003ERecover your work\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EYour open files.\u003C/strong\u003E Each time you open MarkupCraft, open the PDFs again.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EThe sheet you were on, zoom, filters and undo history.\u003C/strong\u003E These last until you close the set or the tab.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"back-up-and-move-your-setup\"\u003EBack up and move your setup\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ETool chest:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EExport\u003C/span\u003E. On the other browser or computer, \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E, then \u003Cspan class=\"hui\"\u003EImport\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EName:\u003C/strong\u003E type it again on the other browser (click the name button in the status bar).\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ETool settings:\u003C/strong\u003E set them again, or save each styled markup as a tool so it travels with the chest.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"start-fresh\"\u003EStart fresh\u003C/h2\u003E\n\u003Cp\u003ETo reset everything, clear this website&#039;s data in your browser&#039;s settings. Your name, settings and chest go; the six default tools come back.\u003C/p\u003E\n\u003Ch2 id=\"the-offline-copy\"\u003EThe offline copy\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E in the bar at the top stores the app&#039;s own files (with the PDF reader and writer, about 6 MB) in the browser too, separately from these settings. Clearing site data removes that copy as well; click &quot;Offline ready&quot; and choose &quot;Remove the offline copy&quot; to remove only it. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003ECloud saving and sync between computers are not available yet.\u003C/p\u003E","text":"MarkupCraft has no account and no server storage. A few small things are kept in your browser's storage for this website, and everything else lives in your files. What is kept in the browser What Set where Kept as Your author name The name button in the status bar, or Settings One name MarkupCraft settings Settings, MarkupCraft tab: color and line weight of new markups, where paste puts copies, units (see MarkupCraft settings) One set Tool settings Properties while a drawing tool is on: color, line, fill, opacity and text size per tool, the chosen stamp, the count group name One set Tool chest The Tools tab Up to 500 tools What you last copied Copy or Cut The copied markups, so another tab can paste them; replaced by the next copy Stamp picture and signature Picture… and My signature… in the stamp list The last picture and your signature Recovery copies Kept for you while a PDF has unsaved markups The PDF and its markups, removed when you save, close or discard it; kept up to 30 days What that means Per browser, per computer. Chrome and Firefox on the same computer each have their own. Your laptop and the office desktop each have their own. Nothing syncs between them, even if you sign in to the browser. Private and incognito windows start empty and forget everything when they close. Clearing site data erases it. Clearing cookies and site data for this website, or for all sites, in the browser's settings removes your name, settings and chest. Some cleanup tools and some company policies do this automatically. Nothing is uploaded. These values never leave the computer, except your name inside the PDFs you save. Recovery copies stay in this browser too. Safari can delete a website's stored data after some weeks without a visit. Open MarkupCraft now and then, and keep an exported tool chest. What is not kept in the browser Your markups, for good. They belong in the \"(marked up)\" PDF you save. The recovery copy is a safety net for a crash or a closed tab, not a place to keep work: it goes when you save, and clearing site data removes it. See Recover your work. Your open files. Each time you open MarkupCraft, open the PDFs again. The sheet you were on, zoom, filters and undo history. These last until you close the set or the tab. Back up and move your setup Tool chest: Tools, then Export. On the other browser or computer, Tools, then Import. Name: type it again on the other browser (click the name button in the status bar). Tool settings: set them again, or save each styled markup as a tool so it travels with the chest. Start fresh To reset everything, clear this website's data in your browser's settings. Your name, settings and chest go; the six default tools come back. The offline copy Save for offline in the bar at the top stores the app's own files (with the PDF reader and writer, about 6 MB) in the browser too, separately from these settings. Clearing site data removes that copy as well; click \"Offline ready\" and choose \"Remove the offline copy\" to remove only it. See Working offline. Cloud saving and sync between computers are not available yet.","lang":"en"},{"slug":"settings","scope":"markupcraft","title":"MarkupCraft settings","summary":"Change your name, the color and line weight of new markups, where paste puts copies, and the units for lengths and the sheet position.","section":"reference","order":65,"keywords":["settings","preferences","options","name","author","color","colour","default color","line weight","line width","thick","thin","paste","paste at pointer","offset","units","metric","millimeters","inches","feet","reset"],"headings":[{"id":"your-name","text":"Your name","level":2},{"id":"new-markups","text":"New markups","level":2},{"id":"paste","text":"Paste","level":2},{"id":"measurements","text":"Measurements","level":2},{"id":"reset","text":"Reset","level":2}],"html":"\u003Cp\u003EOpen \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E with the gear in the bar at the top, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E. The first tab, \u003Cspan class=\"hui\"\u003EMarkupCraft\u003C/span\u003E, holds the settings that belong to this app; \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E holds the ones every CadCraft app shares (theme, toolbar, panels). MarkupCraft&#039;s settings exist only in the app: you change them here, and this browser remembers them (see \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E). A change takes effect at once; there is nothing to save.\u003C/p\u003E\n\u003Ch2 id=\"your-name\"\u003EYour name\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EName on markups\u003C/span\u003E is the name every new markup and reply carries, and that saved PDFs show as the comment&#039;s author. It is the same name as the button at the right end of the status bar; change it in either place. Markups already drawn keep the name they were made with. See \u003Ca href=\"/tutorials/markupcraft/set-your-name\" data-topic=\"markupcraft/set-your-name\"\u003ESet your author name\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"new-markups\"\u003ENew markups\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EMarkup color\u003C/span\u003E\u003C/strong\u003E is the color new pens, lines, arrows, rectangles, ellipses, polylines, polygons, clouds, callouts and text start with (red at the start). Highlighters, notes, stamps, lengths, areas and counts keep their own colors, because their colors say what they are.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EThin lines\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ENormal\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EHeavy lines\u003C/span\u003E\u003C/strong\u003E make the lines of those same markups half as wide, as they are, or half again as wide.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EA color or line width you choose for one tool in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E (with that tool on and nothing selected) wins over these. Tools from the \u003Ca href=\"/tutorials/markupcraft/tool-chest\" data-topic=\"markupcraft/tool-chest\"\u003Etool chest\u003C/a\u003E keep their own style. Markups already drawn do not change: select them and change them in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"paste\"\u003EPaste\u003C/h2\u003E\n\u003Cp\u003EWhere \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E puts what you copied:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EAt the pointer\u003C/span\u003E\u003C/strong\u003E (the start): with the pointer on the sheet, the copy lands centered where it points. With the pointer elsewhere, it lands beside the original.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EBeside the copy\u003C/span\u003E\u003C/strong\u003E: always a little down and to the right of the original, a step further with each paste.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe \u003Cspan class=\"hui\"\u003EPaste\u003C/span\u003E button and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift Command V\"\u003E⇧⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+V\u003C/span\u003E\u003C/kbd\u003E (\u003Cspan class=\"hui\"\u003EPaste in place\u003C/span\u003E) work the same with either choice. See \u003Ca href=\"/tutorials/markupcraft/select-and-edit#copy-paste-and-duplicate\" data-topic=\"markupcraft/select-and-edit\" data-hash=\"copy-paste-and-duplicate\"\u003ECopy, paste and duplicate\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"measurements\"\u003EMeasurements\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EShow lengths in\u003C/span\u003E\u003C/strong\u003E is the unit the sheet scale dialog offers first when you calibrate from two points: feet and inches, decimal feet, inches, meters or millimeters. Sheets you already calibrated keep their unit. See \u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure\" data-topic=\"markupcraft/calibrate-and-measure\"\u003ECalibrate a sheet and measure\u003C/a\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003E\u003Cspan class=\"hui\"\u003EPosition on the sheet\u003C/span\u003E\u003C/strong\u003E chooses inches or millimeters for the pointer position at the bottom left of the screen. It is a position on the paper, not a real-world distance.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"reset\"\u003EReset\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003EReset MarkupCraft settings\u003C/span\u003E at the bottom of the dialog puts these settings, and the panel and toolbar settings on \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E, back to how they start. It keeps your name, since that says who you are rather than how you like to work, and it keeps the colors you picked in each tool&#039;s own panel.\u003C/p\u003E","text":"Open Settings with the gear in the bar at the top, or press Ctrl+,. The first tab, MarkupCraft, holds the settings that belong to this app; General holds the ones every CadCraft app shares (theme, toolbar, panels). MarkupCraft's settings exist only in the app: you change them here, and this browser remembers them (see What stays in this browser). A change takes effect at once; there is nothing to save. Your name Name on markups is the name every new markup and reply carries, and that saved PDFs show as the comment's author. It is the same name as the button at the right end of the status bar; change it in either place. Markups already drawn keep the name they were made with. See Set your author name. New markups Markup color is the color new pens, lines, arrows, rectangles, ellipses, polylines, polygons, clouds, callouts and text start with (red at the start). Highlighters, notes, stamps, lengths, areas and counts keep their own colors, because their colors say what they are. Thin lines, Normal, Heavy lines make the lines of those same markups half as wide, as they are, or half again as wide. A color or line width you choose for one tool in Properties (with that tool on and nothing selected) wins over these. Tools from the tool chest keep their own style. Markups already drawn do not change: select them and change them in Properties. Paste Where Ctrl+V puts what you copied: At the pointer (the start): with the pointer on the sheet, the copy lands centered where it points. With the pointer elsewhere, it lands beside the original. Beside the copy: always a little down and to the right of the original, a step further with each paste. The Paste button and Ctrl+Shift+V (Paste in place) work the same with either choice. See Copy, paste and duplicate. Measurements Show lengths in is the unit the sheet scale dialog offers first when you calibrate from two points: feet and inches, decimal feet, inches, meters or millimeters. Sheets you already calibrated keep their unit. See Calibrate a sheet and measure. Position on the sheet chooses inches or millimeters for the pointer position at the bottom left of the screen. It is a position on the paper, not a real-world distance. Reset Reset MarkupCraft settings at the bottom of the dialog puts these settings, and the panel and toolbar settings on General, back to how they start. It keeps your name, since that says who you are rather than how you like to work, and it keeps the colors you picked in each tool's own panel.","lang":"en"},{"slug":"troubleshooting","scope":"markupcraft","title":"Troubleshooting","summary":"Messages MarkupCraft shows and what to do about them, plus fixes for things that seem not to work.","section":"trouble","order":10,"keywords":["problem","error","not working","help","message","wont open","cannot save","password","protected","measure refused","calibrate","offline","blank","slow","lost markups","question marks"],"headings":[{"id":"opening-files","text":"Opening files","level":2},{"id":"drawing-and-selecting","text":"Drawing and selecting","level":2},{"id":"measuring","text":"Measuring","level":2},{"id":"saving","text":"Saving","level":2},{"id":"working-offline","text":"Working offline","level":2},{"id":"lost-things","text":"Lost things","level":2},{"id":"display-and-speed","text":"Display and speed","level":2}],"html":"\u003Cp\u003EMost problems are explained in the status bar at the bottom of the screen. Read it first.\u003C/p\u003E\n\u003Ch2 id=\"opening-files\"\u003EOpening files\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;MarkupCraft opens PDF files. &quot;x&quot; is not a PDF.&quot;\u003C/strong\u003E You picked or dropped something else. Only PDFs open. Export drawings from your CAD program as PDF first.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&#039;&quot;name&quot; needs a password to open. Open an unprotected copy.&#039;\u003C/strong\u003E The PDF is password-protected. Ask the sender for an unprotected copy, or open it in a PDF program where you know the password and save a copy without the password.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&#039;&quot;name&quot; could not be read as a PDF (…)&#039;\u003C/strong\u003E The file is damaged or is not really a PDF (an incomplete download, an email attachment cut off). Download it again. If other PDF programs can open it, use their &quot;save as&quot; to make a clean copy and open that.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Some files did not open&quot;\u003C/strong\u003E When you open several at once, this box lists the files that failed and why. The others are open.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;The PDF reader could not load: …&quot;\u003C/strong\u003E The PDF engine could not be fetched. Online: reload the page and try again; check that a firewall or content blocker is not blocking the site. Offline: MarkupCraft was not saved for offline use in this browser (the bar at the top does not say &quot;Offline ready&quot;). Get online, choose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E, and wait for &quot;Offline ready&quot;. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Some annotations may show twice on screen&quot; or &quot;Extra annotation details could not be read&quot;\u003C/strong\u003E The file&#039;s existing comments are unusual. They are still opened as well as MarkupCraft can; check them before relying on them. Saving still works.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe sheet has the wrong name, or &quot;page 3&quot;\u003C/strong\u003E See \u003Ca href=\"/tutorials/markupcraft/open-a-plan-set#how-sheets-get-their-names\" data-topic=\"markupcraft/open-a-plan-set\" data-hash=\"how-sheets-get-their-names\"\u003EHow sheets get their names\u003C/a\u003E. Scanned sheets have no text to read; use \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe same sheets appear twice\u003C/strong\u003E The same file was opened twice. Choose \u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E (save first if needed) and open the set again.\u003C/p\u003E\n\u003Ch2 id=\"drawing-and-selecting\"\u003EDrawing and selecting\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003ENothing happens when I click on the sheet\u003C/strong\u003E Check which tool is pressed in the toolbar, and read the status bar. With \u003Cspan class=\"hui\"\u003ERectangle\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EEllipse\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ECloud\u003C/span\u003E, a click without dragging draws nothing: drag. With \u003Cspan class=\"hui\"\u003EPolyline\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPolygon\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFree cloud\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E, points are being added: finish with a double-click or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;A polygon needs at least 3 points.&quot; (or 2 for a polyline)\u003C/strong\u003E Click more points before finishing.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Nothing typed, so no text was added.&quot;\u003C/strong\u003E Text boxes and callouts are kept only when they have text. Draw it again and type before clicking away.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;The two points are the same. Click two different points.&quot;\u003C/strong\u003E For lines, arrows, lengths and calibration, the two ends must be apart. Drag, or click twice in different places.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EI cannot move or delete a markup; it has a gray dashed box\u003C/strong\u003E It is a read-only comment that came with the file (for example a text highlight). MarkupCraft keeps it as it is: you can only reply to it. The status bar says &quot;read-only markup(s) are kept as in the file&quot;.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EMy keys type letters into a box instead of choosing tools\u003C/strong\u003E The cursor is in a text box (a reply, a field in \u003Cspan class=\"hui\"\u003EProperties\u003C/span\u003E, the sheet search). Click on an empty part of the sheet area first, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E if you are editing markup text.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003ESpace does not pan, or arrow keys do nothing\u003C/strong\u003E You just clicked a toolbar button, so it still has the keyboard. Drag with the middle mouse button instead, or click the sheet once with \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E on, then try again. See also \u003Ca href=\"/tutorials/markupcraft/keyboard#when-a-key-does-nothing\" data-topic=\"markupcraft/keyboard\" data-hash=\"when-a-key-does-nothing\"\u003EKeyboard and mouse\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EA pinch on the touch screen left a mark\u003C/strong\u003E A drag tool (pen, cloud, rectangle) started before the second finger arrived and finished before it was canceled. Press \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E. Put both fingers down together when you mean to zoom.\u003C/p\u003E\n\u003Ch2 id=\"measuring\"\u003EMeasuring\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Calibrate this sheet first: pick two points a known distance apart, or choose its scale. Then measure.&quot;\u003C/strong\u003E Each sheet needs its own scale before \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E. MarkupCraft has switched to \u003Cspan class=\"hui\"\u003ECalibrate\u003C/span\u003E: click the two ends of a known dimension and type its length, or click the scale button in the status bar and pick a scale. See \u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure\" data-topic=\"markupcraft/calibrate-and-measure\"\u003ECalibrate a sheet and measure\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&#039;That is not a length MarkupCraft understands.&#039;\u003C/strong\u003E Type it like \u003Ccode\u003E24&#039;-0&quot;\u003C/code\u003E, \u003Ccode\u003E12&#039; 6 1/2&quot;\u003C/code\u003E, \u003Ccode\u003E7.2 m\u003C/code\u003E or \u003Ccode\u003E900 mm\u003C/code\u003E. See \u003Ca href=\"/tutorials/markupcraft/units-and-scales\" data-topic=\"markupcraft/units-and-scales\"\u003EUnits, lengths and scales\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EMeasurements are a bit off, or wildly off\u003C/strong\u003E\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EA preset scale on a PDF that is not full size measures wrong. Calibrate from a long known dimension instead.\u003C/li\u003E\u003Cli\u003EA thousands separator was read as a decimal point: \u003Ccode\u003E1,200 mm\u003C/code\u003E means 1.2 mm. Type \u003Ccode\u003E1200 mm\u003C/code\u003E.\u003C/li\u003E\u003Cli\u003EZoom in when you click the ends.\u003C/li\u003E\u003Cli\u003EThe drawing may not be to scale (&quot;NTS&quot;).\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Select a count group first, then Shift+click a mark to remove it.&quot;\u003C/strong\u003E Choose \u003Cspan class=\"hui\"\u003ESelect\u003C/span\u003E, click the count group, then choose \u003Cspan class=\"hui\"\u003ECount\u003C/span\u003E again and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E-click the dot.\u003C/p\u003E\n\u003Ch2 id=\"saving\"\u003ESaving\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;This PDF is protected (encrypted), so a marked-up copy cannot be written.&quot;\u003C/strong\u003E The file forbids changes. Ask for an unprotected copy. Meanwhile you can still export the markups list as CSV or BCF.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;The PDF writer could not load: …&quot;\u003C/strong\u003E Usually you are offline and the app was not saved for offline use (no &quot;Offline ready&quot; in the bar at the top). Your markups are still in the tab: keep it open, get online, and choose \u003Cspan class=\"hui\"\u003ESave\u003C/span\u003E again. Then choose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E so it works offline next time; the saved copy includes the PDF writer.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;Could not save &lt;file&gt;&quot;\u003C/strong\u003E The box shows why. Your markups are still in the tab. Try again; if it repeats, export the CSV so the comments are not lost, and report the message.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EI chose Save but only one file arrived\u003C/strong\u003E Your browser blocked the extra downloads. Look for a notice in the address bar and allow this site to download multiple files, then save again.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EI cannot find the saved file\u003C/strong\u003E It went to your browser&#039;s downloads folder. Open the browser&#039;s downloads list (in Chrome and Edge, \u003Cspan class=\"hp\"\u003E\u003Cspan class=\"hpv\" data-v=\"os:mac\" title=\"Mac\"\u003EOption-Command-L\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:windows,linux\" title=\"Windows or Linux\"\u003ECtrl+J\u003C/span\u003E\u003C/span\u003E; in Firefox and Safari, the downloads button in the toolbar) to see where. See \u003Ca href=\"/tutorials/basics/browsers\" data-topic=\"basics/browsers\"\u003EBrowsers and computers\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003ESome text shows &quot;?&quot; in other PDF viewers\u003C/strong\u003E Characters outside the Western European set print as &quot;?&quot; in the copy. The save message counts them. See \u003Ca href=\"/tutorials/markupcraft/save-the-marked-up-pdf\" data-topic=\"markupcraft/save-the-marked-up-pdf\"\u003ESave the marked-up PDF\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe stamp shows tomorrow&#039;s (or yesterday&#039;s) date\u003C/strong\u003E Stamp dates are in UTC. See \u003Ca href=\"/tutorials/markupcraft/stamps-and-notes\" data-topic=\"markupcraft/stamps-and-notes\"\u003EStamps and sticky notes\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"working-offline\"\u003EWorking offline\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe offline button says &quot;Could not save&quot;\u003C/strong\u003E Some of the app&#039;s files did not download. Check the connection and click the button again; it counts &quot;Saving N of M&quot; until &quot;Offline ready&quot;.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe offline button says &quot;Offline not available&quot;\u003C/strong\u003E This browser window cannot keep an offline copy: a private window, or a computer whose policy blocks it. Open MarkupCraft in a normal window and try again.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EOffline, the app is an older version\u003C/strong\u003E The offline copy is the version you saved. When you are online, click &quot;Offline ready&quot; and choose &quot;Save again (get the newest version)&quot;. To free the space, choose &quot;Remove the offline copy&quot;. See \u003Ca href=\"/tutorials/basics/offline\" data-topic=\"basics/offline\"\u003EWorking offline\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe help will not open\u003C/strong\u003E Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E (on a Mac, with \u003Cstrong\u003Efn\u003C/strong\u003E), or choose \u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E in the bar at the top. It works offline too.\u003C/p\u003E\n\u003Ch2 id=\"lost-things\"\u003ELost things\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003EMy markups are gone after closing or reloading the tab\u003C/strong\u003E Open MarkupCraft again in the same browser: it offers the unsaved work back with &quot;Recover your work?&quot;. Choose \u003Cspan class=\"hui\"\u003ERecover\u003C/span\u003E and save the PDF. Copies are kept up to 30 days; a private window, or clearing site data, leaves none. See \u003Ca href=\"/tutorials/basics/recover\" data-topic=\"basics/recover\"\u003ERecover your work\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EMy name, tool settings or tool chest are gone\u003C/strong\u003E They are kept in this browser only and were cleared (site data cleared, a private window, another browser or computer, or Safari&#039;s cleanup of sites not visited for a while). Set the name again and import your exported chest. See \u003Ca href=\"/tutorials/markupcraft/browser-storage\" data-topic=\"markupcraft/browser-storage\"\u003EWhat stays in this browser\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003E&quot;The tool chest could not be kept in this browser (storage is off or full). Export it to keep it.&quot;\u003C/strong\u003E The browser refuses to store data for this site (private mode, storage blocked by a setting or policy, or full). Export the chest after changing it, and import it next time.\u003C/p\u003E\n\u003Ch2 id=\"display-and-speed\"\u003EDisplay and speed\u003C/h2\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe sheet looks blurry for a moment\u003C/strong\u003E MarkupCraft shows a quick, rough rendering while you zoom or pan, and redraws it sharp a moment after you stop.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EEverything is slow with a big set\u003C/strong\u003E Close other heavy tabs, open fewer files at once, and avoid zooming to the maximum on huge sheets. See \u003Ca href=\"/tutorials/markupcraft/several-files#big-sets\" data-topic=\"markupcraft/several-files\" data-hash=\"big-sets\"\u003EWork with several files at once\u003C/a\u003E.\u003C/p\u003E\n\u003Cp\u003E\u003Cstrong\u003EThe sheet is dark with light lines\u003C/strong\u003E You are in the \u003Cspan class=\"hui\"\u003EModel\u003C/span\u003E theme. Choose \u003Cspan class=\"hui\"\u003EPaper\u003C/span\u003E in the bar at the top for dark lines on white. Your markups and the saved PDF are not affected.\u003C/p\u003E","text":"Most problems are explained in the status bar at the bottom of the screen. Read it first. Opening files \"MarkupCraft opens PDF files. \"x\" is not a PDF.\" You picked or dropped something else. Only PDFs open. Export drawings from your CAD program as PDF first. '\"name\" needs a password to open. Open an unprotected copy.' The PDF is password-protected. Ask the sender for an unprotected copy, or open it in a PDF program where you know the password and save a copy without the password. '\"name\" could not be read as a PDF (…)' The file is damaged or is not really a PDF (an incomplete download, an email attachment cut off). Download it again. If other PDF programs can open it, use their \"save as\" to make a clean copy and open that. \"Some files did not open\" When you open several at once, this box lists the files that failed and why. The others are open. \"The PDF reader could not load: …\" The PDF engine could not be fetched. Online: reload the page and try again; check that a firewall or content blocker is not blocking the site. Offline: MarkupCraft was not saved for offline use in this browser (the bar at the top does not say \"Offline ready\"). Get online, choose Save for offline, and wait for \"Offline ready\". See Working offline. \"Some annotations may show twice on screen\" or \"Extra annotation details could not be read\" The file's existing comments are unusual. They are still opened as well as MarkupCraft can; check them before relying on them. Saving still works. The sheet has the wrong name, or \"page 3\" See How sheets get their names. Scanned sheets have no text to read; use Rename sheet. The same sheets appear twice The same file was opened twice. Choose Close (save first if needed) and open the set again. Drawing and selecting Nothing happens when I click on the sheet Check which tool is pressed in the toolbar, and read the status bar. With Rectangle, Ellipse and Cloud, a click without dragging draws nothing: drag. With Polyline, Polygon, Free cloud and Area, points are being added: finish with a double-click or Enter. \"A polygon needs at least 3 points.\" (or 2 for a polyline) Click more points before finishing. \"Nothing typed, so no text was added.\" Text boxes and callouts are kept only when they have text. Draw it again and type before clicking away. \"The two points are the same. Click two different points.\" For lines, arrows, lengths and calibration, the two ends must be apart. Drag, or click twice in different places. I cannot move or delete a markup; it has a gray dashed box It is a read-only comment that came with the file (for example a text highlight). MarkupCraft keeps it as it is: you can only reply to it. The status bar says \"read-only markup(s) are kept as in the file\". My keys type letters into a box instead of choosing tools The cursor is in a text box (a reply, a field in Properties, the sheet search). Click on an empty part of the sheet area first, or press Esc if you are editing markup text. Space does not pan, or arrow keys do nothing You just clicked a toolbar button, so it still has the keyboard. Drag with the middle mouse button instead, or click the sheet once with Select on, then try again. See also Keyboard and mouse. A pinch on the touch screen left a mark A drag tool (pen, cloud, rectangle) started before the second finger arrived and finished before it was canceled. Press Undo. Put both fingers down together when you mean to zoom. Measuring \"Calibrate this sheet first: pick two points a known distance apart, or choose its scale. Then measure.\" Each sheet needs its own scale before Length or Area. MarkupCraft has switched to Calibrate: click the two ends of a known dimension and type its length, or click the scale button in the status bar and pick a scale. See Calibrate a sheet and measure. 'That is not a length MarkupCraft understands.' Type it like 24'-0\", 12' 6 1/2\", 7.2 m or 900 mm. See Units, lengths and scales. Measurements are a bit off, or wildly off A preset scale on a PDF that is not full size measures wrong. Calibrate from a long known dimension instead. A thousands separator was read as a decimal point: 1,200 mm means 1.2 mm. Type 1200 mm. Zoom in when you click the ends. The drawing may not be to scale (\"NTS\"). \"Select a count group first, then Shift+click a mark to remove it.\" Choose Select, click the count group, then choose Count again and Shift-click the dot. Saving \"This PDF is protected (encrypted), so a marked-up copy cannot be written.\" The file forbids changes. Ask for an unprotected copy. Meanwhile you can still export the markups list as CSV or BCF. \"The PDF writer could not load: …\" Usually you are offline and the app was not saved for offline use (no \"Offline ready\" in the bar at the top). Your markups are still in the tab: keep it open, get online, and choose Save again. Then choose Save for offline so it works offline next time; the saved copy includes the PDF writer. \"Could not save \u003Cfile\u003E\" The box shows why. Your markups are still in the tab. Try again; if it repeats, export the CSV so the comments are not lost, and report the message. I chose Save but only one file arrived Your browser blocked the extra downloads. Look for a notice in the address bar and allow this site to download multiple files, then save again. I cannot find the saved file It went to your browser's downloads folder. Open the browser's downloads list (in Chrome and Edge, Option-Command-L / Ctrl+J; in Firefox and Safari, the downloads button in the toolbar) to see where. See Browsers and computers. Some text shows \"?\" in other PDF viewers Characters outside the Western European set print as \"?\" in the copy. The save message counts them. See Save the marked-up PDF. The stamp shows tomorrow's (or yesterday's) date Stamp dates are in UTC. See Stamps and sticky notes. Working offline The offline button says \"Could not save\" Some of the app's files did not download. Check the connection and click the button again; it counts \"Saving N of M\" until \"Offline ready\". The offline button says \"Offline not available\" This browser window cannot keep an offline copy: a private window, or a computer whose policy blocks it. Open MarkupCraft in a normal window and try again. Offline, the app is an older version The offline copy is the version you saved. When you are online, click \"Offline ready\" and choose \"Save again (get the newest version)\". To free the space, choose \"Remove the offline copy\". See Working offline. The help will not open Press F1 (on a Mac, with fn), or choose Help in the bar at the top. It works offline too. Lost things My markups are gone after closing or reloading the tab Open MarkupCraft again in the same browser: it offers the unsaved work back with \"Recover your work?\". Choose Recover and save the PDF. Copies are kept up to 30 days; a private window, or clearing site data, leaves none. See Recover your work. My name, tool settings or tool chest are gone They are kept in this browser only and were cleared (site data cleared, a private window, another browser or computer, or Safari's cleanup of sites not visited for a while). Set the name again and import your exported chest. See What stays in this browser. \"The tool chest could not be kept in this browser (storage is off or full). Export it to keep it.\" The browser refuses to store data for this site (private mode, storage blocked by a setting or policy, or full). Export the chest after changing it, and import it next time. Display and speed The sheet looks blurry for a moment MarkupCraft shows a quick, rough rendering while you zoom or pan, and redraws it sharp a moment after you stop. Everything is slow with a big set Close other heavy tabs, open fewer files at once, and avoid zooming to the maximum on huge sheets. See Work with several files at once. The sheet is dark with light lines You are in the Model theme. Choose Paper in the bar at the top for dark lines on white. Your markups and the saved PDF are not affected.","lang":"en"},{"slug":"not-built-yet","scope":"markupcraft","title":"What is not built yet","summary":"What this build of MarkupCraft does not do yet, and what to do instead today.","section":"trouble","order":20,"keywords":["missing","roadmap","planned","limitation","not supported","coming","feature request","sessions","cloud","digital signature","ocr","web links"],"headings":[{"id":"working-with-other-people","text":"Working with other people","level":2},{"id":"markups","text":"Markups","level":2},{"id":"the-page-s-own-content","text":"The page's own content","level":2},{"id":"measuring","text":"Measuring","level":2},{"id":"sheets-and-files","text":"Sheets and files","level":2},{"id":"lists-and-exports","text":"Lists and exports","level":2},{"id":"compare","text":"Compare","level":2},{"id":"panels","text":"Panels","level":2},{"id":"platforms","text":"Platforms","level":2}],"html":"\u003Cp\u003EMarkupCraft is in development. This is what the current build does \u003Cstrong\u003Enot\u003C/strong\u003E do, so you can plan around it. It describes today&#039;s build, not promises.\u003C/p\u003E\n\u003Ch2 id=\"working-with-other-people\"\u003EWorking with other people\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EShared review sessions over the internet (invite links are not open yet)\u003C/td\u003E\u003Ctd\u003EReview live on your own network in CadCraft Studio with a short code, which is free: see \u003Ca href=\"/tutorials/markupcraft/work-live\" data-topic=\"markupcraft/work-live\"\u003EReview one plan set together, live\u003C/a\u003E. Or save the marked-up PDF and pass it on; each person replies and saves.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECloud saving and sync between computers\u003C/td\u003E\u003Ctd\u003EKeep the PDFs with your project files. Cloud saving is not available yet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMerging two people&#039;s copies of the markups\u003C/td\u003E\u003Ctd\u003EDivide the sheets between reviewers, or copy a few markups across with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command C\"\u003E⌘C\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+C\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command V\"\u003E⌘V\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+V\u003C/span\u003E\u003C/kbd\u003E. RFIs, submittals and daily logs do merge: see \u003Ca href=\"/tutorials/markupcraft/field-records\" data-topic=\"markupcraft/field-records\"\u003ETrack RFIs, submittals and daily logs\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETeams, notifications and cloud projects for RFIs and submittals\u003C/td\u003E\u003Ctd\u003EPass the PDF on and use Merge to bring copies together.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ERFIs, submittals and daily logs in a live session\u003C/td\u003E\u003Ctd\u003EEach person works on their own copy; bring the copies together with \u003Cspan class=\"hui\"\u003EMerge\u003C/span\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMerging two people&#039;s changes to different fields of one record\u003C/td\u003E\u003Ctd\u003EThe copy changed last wins that record as a whole (its thread and attachment names are joined). Agree who edits which record.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EAssistant tools for RFIs, submittals and daily logs\u003C/td\u003E\u003Ctd\u003EWork with them in the \u003Cspan class=\"hui\"\u003EField\u003C/span\u003E tab. Assistants can work with markups: see \u003Ca href=\"/tutorials/markupcraft/use-with-ai-assistants\" data-topic=\"markupcraft/use-with-ai-assistants\"\u003EUse MarkupCraft with an AI assistant\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEditing or deleting a reply once sent\u003C/td\u003E\u003Ctd\u003EUndo right away, or add a correcting reply.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EChanging who a markup is by\u003C/td\u003E\u003Ctd\u003ESet your name before you start.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"markups\"\u003EMarkups\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EStamps with fill-in fields, certified digital signatures\u003C/td\u003E\u003Ctd\u003EUse a custom text stamp, which carries your name and the date, or a picture of your signature.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EAttaching files other than photos (documents, videos)\u003C/td\u003E\u003Ctd\u003EKeep them alongside the PDF and refer to them in the comment.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELinks to websites or to files that are not open\u003C/td\u003E\u003Ctd\u003EWrite the address or file name in the comment.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECustom status sets\u003C/td\u003E\u003Ctd\u003EUse the four statuses, and the subject for anything more.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEditing comments that came with the file as read-only (text highlights, other programs&#039; stamps)\u003C/td\u003E\u003Ctd\u003EReply to them, or draw a MarkupCraft markup next to them.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPressure-sensitive pen strokes\u003C/td\u003E\u003Ctd\u003ESet the line width.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"the-page-s-own-content\"\u003EThe page&#039;s own content\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EDrawing new shapes straight into the page\u003C/td\u003E\u003Ctd\u003EDraw them as markups, then \u003Cspan class=\"hui\"\u003EPut into the page\u003C/span\u003E. See \u003Ca href=\"/tutorials/markupcraft/page-content\" data-topic=\"markupcraft/page-content\"\u003EChange the page&#039;s own content\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETurning page objects to any angle\u003C/td\u003E\u003Ctd\u003EMove and resize them; turn the whole page with \u003Cspan class=\"hui\"\u003EPages\u003C/span\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EChanging a line of text&#039;s font or size, or text that flows over several lines\u003C/td\u003E\u003Ctd\u003EChange the words one line at a time; for new wording in another font, add a text markup.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEditing what is inside a scanned picture\u003C/td\u003E\u003Ctd\u003EReplace the picture, or mark it up.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEditing encrypted or signed PDFs\u003C/td\u003E\u003Ctd\u003EAsk for an unsigned copy; markups work on any PDF.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"measuring\"\u003EMeasuring\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003ERadius measurements\u003C/td\u003E\u003Ctd\u003EDraw an \u003Cspan class=\"hui\"\u003EArc\u003C/span\u003E along it, or measure the \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E across and halve it.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EEditing a cut-out&#039;s corners\u003C/td\u003E\u003Ctd\u003ERemove the cut-outs and draw them again.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EApplying one scale to many sheets at once\u003C/td\u003E\u003Ctd\u003ECalibrate each sheet; picking a preset takes a few seconds per sheet.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESeveral scales on one sheet (viewports)\u003C/td\u003E\u003Ctd\u003ECalibrate to the drawing you measure most. Changing a sheet&#039;s scale re-measures everything on it, so write down detail values before you recalibrate for them.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESnapping to lines in the drawing\u003C/td\u003E\u003Ctd\u003EZoom in before clicking, or type lengths and angles (see \u003Ca href=\"/tutorials/markupcraft/calibrate-and-measure#sketch-to-scale\" data-topic=\"markupcraft/calibrate-and-measure\" data-hash=\"sketch-to-scale\"\u003ESketch to scale\u003C/a\u003E).\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EA full takeoff with items, assemblies and prices\u003C/td\u003E\u003Ctd\u003EUse TakeoffCraft, the CadCraft family&#039;s takeoff app.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"sheets-and-files\"\u003ESheets and files\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EReading text from scanned sheets (OCR)\u003C/td\u003E\u003Ctd\u003EScans are named by file and page; use \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E. A test found sheet numbers in plotter fonts misread, so it is not built.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EUndoing a page change (rotate, move, insert, delete)\u003C/td\u003E\u003Ctd\u003EClose without saving and open the original PDF again. See \u003Ca href=\"/tutorials/markupcraft/pages-and-printing\" data-topic=\"markupcraft/pages-and-printing\"\u003EPrint, and change the pages\u003C/a\u003E.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EClosing one file of a set\u003C/td\u003E\u003Ctd\u003E\u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E closes the whole set; reopen the files you need.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESaving a set as a project to reopen in one step\u003C/td\u003E\u003Ctd\u003EOpen the same PDFs again.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESearching scanned sheets (no text in the PDF)\u003C/td\u003E\u003Ctd\u003EName the sheets with \u003Cspan class=\"hui\"\u003ERename sheet\u003C/span\u003E; \u003Cspan class=\"hui\"\u003EFind text\u003C/span\u003E searches only sheets with text.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EPrinting to a chosen scale, or several sheets per paper\u003C/td\u003E\u003Ctd\u003EUse your browser&#039;s printer dialog, or print the saved copy from another PDF viewer.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"lists-and-exports\"\u003ELists and exports\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EPlacing imported BCF issues at their model position\u003C/td\u003E\u003Ctd\u003EImported issues tied to no sheet are stacked at the top left: move them.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EImporting tool sets from other markup programs\u003C/td\u003E\u003Ctd\u003ERebuild the tools you need and save them to the chest; export it for the office.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"compare\"\u003ECompare\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EComparing text set in a font, or a list of what changed\u003C/td\u003E\u003Ctd\u003EUse the overlay and the slider, or \u003Cspan class=\"hui\"\u003EChanged lines\u003C/span\u003E for drawn lines.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EComparing scanned sheets by their lines\u003C/td\u003E\u003Ctd\u003EUse the picture overlay.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ELining up every pair automatically when comparing a whole set\u003C/td\u003E\u003Ctd\u003ECompare a shifted pair on its own and use \u003Cspan class=\"hui\"\u003EAlign by two points\u003C/span\u003E.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"panels\"\u003EPanels\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003ENot built yet\u003C/th\u003E\u003Cth scope=\"col\"\u003EDo this today\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EMoving the toolbar or the status bar\u003C/td\u003E\u003Ctd\u003EOnly the two side panels move.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Ch2 id=\"platforms\"\u003EPlatforms\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EDesktop:\u003C/strong\u003E MarkupCraft runs in the browser on Mac, Windows, Linux and iPad, and in CadCraft Studio, the desktop app with all eight apps in one install.\u003C/li\u003E\u003Cli\u003EMarkupCraft is in development. Labels and behavior may still change, and this help changes with them.\u003C/li\u003E\u003C/ul\u003E","text":"MarkupCraft is in development. This is what the current build does not do, so you can plan around it. It describes today's build, not promises. Working with other people Not built yet Do this today Shared review sessions over the internet (invite links are not open yet) Review live on your own network in CadCraft Studio with a short code, which is free: see Review one plan set together, live. Or save the marked-up PDF and pass it on; each person replies and saves. Cloud saving and sync between computers Keep the PDFs with your project files. Cloud saving is not available yet. Merging two people's copies of the markups Divide the sheets between reviewers, or copy a few markups across with Ctrl+C and Ctrl+V. RFIs, submittals and daily logs do merge: see Track RFIs, submittals and daily logs. Teams, notifications and cloud projects for RFIs and submittals Pass the PDF on and use Merge to bring copies together. RFIs, submittals and daily logs in a live session Each person works on their own copy; bring the copies together with Merge. Merging two people's changes to different fields of one record The copy changed last wins that record as a whole (its thread and attachment names are joined). Agree who edits which record. Assistant tools for RFIs, submittals and daily logs Work with them in the Field tab. Assistants can work with markups: see Use MarkupCraft with an AI assistant. Editing or deleting a reply once sent Undo right away, or add a correcting reply. Changing who a markup is by Set your name before you start. Markups Not built yet Do this today Stamps with fill-in fields, certified digital signatures Use a custom text stamp, which carries your name and the date, or a picture of your signature. Attaching files other than photos (documents, videos) Keep them alongside the PDF and refer to them in the comment. Links to websites or to files that are not open Write the address or file name in the comment. Custom status sets Use the four statuses, and the subject for anything more. Editing comments that came with the file as read-only (text highlights, other programs' stamps) Reply to them, or draw a MarkupCraft markup next to them. Pressure-sensitive pen strokes Set the line width. The page's own content Not built yet Do this today Drawing new shapes straight into the page Draw them as markups, then Put into the page. See Change the page's own content. Turning page objects to any angle Move and resize them; turn the whole page with Pages. Changing a line of text's font or size, or text that flows over several lines Change the words one line at a time; for new wording in another font, add a text markup. Editing what is inside a scanned picture Replace the picture, or mark it up. Editing encrypted or signed PDFs Ask for an unsigned copy; markups work on any PDF. Measuring Not built yet Do this today Radius measurements Draw an Arc along it, or measure the Length across and halve it. Editing a cut-out's corners Remove the cut-outs and draw them again. Applying one scale to many sheets at once Calibrate each sheet; picking a preset takes a few seconds per sheet. Several scales on one sheet (viewports) Calibrate to the drawing you measure most. Changing a sheet's scale re-measures everything on it, so write down detail values before you recalibrate for them. Snapping to lines in the drawing Zoom in before clicking, or type lengths and angles (see Sketch to scale). A full takeoff with items, assemblies and prices Use TakeoffCraft, the CadCraft family's takeoff app. Sheets and files Not built yet Do this today Reading text from scanned sheets (OCR) Scans are named by file and page; use Rename sheet. A test found sheet numbers in plotter fonts misread, so it is not built. Undoing a page change (rotate, move, insert, delete) Close without saving and open the original PDF again. See Print, and change the pages. Closing one file of a set Close closes the whole set; reopen the files you need. Saving a set as a project to reopen in one step Open the same PDFs again. Searching scanned sheets (no text in the PDF) Name the sheets with Rename sheet; Find text searches only sheets with text. Printing to a chosen scale, or several sheets per paper Use your browser's printer dialog, or print the saved copy from another PDF viewer. Lists and exports Not built yet Do this today Placing imported BCF issues at their model position Imported issues tied to no sheet are stacked at the top left: move them. Importing tool sets from other markup programs Rebuild the tools you need and save them to the chest; export it for the office. Compare Not built yet Do this today Comparing text set in a font, or a list of what changed Use the overlay and the slider, or Changed lines for drawn lines. Comparing scanned sheets by their lines Use the picture overlay. Lining up every pair automatically when comparing a whole set Compare a shifted pair on its own and use Align by two points. Panels Not built yet Do this today Moving the toolbar or the status bar Only the two side panels move. Platforms Desktop: MarkupCraft runs in the browser on Mac, Windows, Linux and iPad, and in CadCraft Studio, the desktop app with all eight apps in one install. MarkupCraft is in development. Labels and behavior may still change, and this help changes with them.","lang":"en"},{"slug":"help","scope":"basics","title":"Using this help","summary":"Open the help, search it, and see the steps for your computer.","section":"start","order":10,"keywords":["help","f1","search","tutorials","manual"],"headings":[{"id":"open-the-help","text":"Open the help","level":2},{"id":"find-a-topic","text":"Find a topic","level":2},{"id":"steps-for-your-computer","text":"Steps for your computer","level":2},{"id":"the-same-help-on-the-website","text":"The same help on the website","level":2}],"html":"\u003Cp\u003EEvery app carries its own help. It is part of the app, so it opens with no connection and always describes the version you are running.\u003C/p\u003E\n\u003Ch2 id=\"open-the-help\"\u003EOpen the help\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E in the bar at the top of the app.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E or choose \u003Cspan class=\"hui\"\u003EClose\u003C/span\u003E to put it away. Your drawing stays as it was.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:mac\"\u003E\u003Cp class=\"hv-label\"\u003EMac\u003C/p\u003E\n\u003Cp\u003EOn most Mac keyboards the top row controls brightness and sound. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"F1\"\u003EF1\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EF1\u003C/span\u003E\u003C/kbd\u003E together with the \u003Cstrong\u003Efn\u003C/strong\u003E key (or the globe key), or use the \u003Cspan class=\"hui\"\u003EHelp\u003C/span\u003E button. See \u003Ca href=\"/tutorials/basics/keys#function-keys-on-a-mac\" data-topic=\"basics/keys\" data-hash=\"function-keys-on-a-mac\"\u003EKeys on a Mac\u003C/a\u003E.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"find-a-topic\"\u003EFind a topic\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EType in the search box at the top of the help. Results update as you type and include other programs&#039; command names, so typing what you would have typed elsewhere usually finds the right page.\u003C/li\u003E\u003Cli\u003ETopics are grouped the same way in every app: getting started, walkthroughs, coming from other software, reference, and troubleshooting.\u003C/li\u003E\u003Cli\u003ELinks inside a topic open the next topic in the same panel. \u003Cspan class=\"hui\"\u003EBack\u003C/span\u003E returns to where you were.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"steps-for-your-computer\"\u003ESteps for your computer\u003C/h2\u003E\n\u003Cp\u003ESome steps differ between Mac, Windows and Linux, between browsers, and between being online and offline. The help works out which applies to you and shows those steps. The line at the top of a topic says what it chose, for example &quot;Showing steps for Mac, Chrome or Edge, online&quot;.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EChange\u003C/span\u003E on that line to pick another computer or browser, for example to help a colleague.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EShow all\u003C/span\u003E to see every version of every step, each labeled.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EKeyboard shortcuts are written the way your keyboard labels them: \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E reads as ⌘S on a Mac and Ctrl+S on Windows and Linux.\u003C/p\u003E\n\u003Ch2 id=\"the-same-help-on-the-website\"\u003EThe same help on the website\u003C/h2\u003E\n\u003Cp\u003EThe website shows the same topics at getcadcraft.com/tutorials, with every platform&#039;s steps. In the app, \u003Cspan class=\"hui\"\u003EOpen on the website\u003C/span\u003E at the bottom of a topic opens that page when you are online.\u003C/p\u003E","text":"Every app carries its own help. It is part of the app, so it opens with no connection and always describes the version you are running. Open the help Press F1, or choose Help in the bar at the top of the app. Press Esc or choose Close to put it away. Your drawing stays as it was. On most Mac keyboards the top row controls brightness and sound. Press F1 together with the fn key (or the globe key), or use the Help button. See Keys on a Mac. Find a topic Type in the search box at the top of the help. Results update as you type and include other programs' command names, so typing what you would have typed elsewhere usually finds the right page. Topics are grouped the same way in every app: getting started, walkthroughs, coming from other software, reference, and troubleshooting. Links inside a topic open the next topic in the same panel. Back returns to where you were. Steps for your computer Some steps differ between Mac, Windows and Linux, between browsers, and between being online and offline. The help works out which applies to you and shows those steps. The line at the top of a topic says what it chose, for example \"Showing steps for Mac, Chrome or Edge, online\". Choose Change on that line to pick another computer or browser, for example to help a colleague. Choose Show all to see every version of every step, each labeled. Keyboard shortcuts are written the way your keyboard labels them: Ctrl+S reads as ⌘S on a Mac and Ctrl+S on Windows and Linux. The same help on the website The website shows the same topics at getcadcraft.com/tutorials, with every platform's steps. In the app, Open on the website at the bottom of a topic opens that page when you are online.","lang":"en"},{"slug":"browsers","scope":"basics","title":"Browsers and computers","summary":"Which browsers the apps run in, what differs between them, and what your computer needs.","section":"start","order":20,"keywords":["chrome","edge","firefox","safari","brave","browser","mac","windows","linux","ipad","tablet","webgl","requirements","memory"],"headings":[{"id":"which-browser","text":"Which browser","level":2},{"id":"what-differs-between-browsers","text":"What differs between browsers","level":2},{"id":"mac-windows-and-linux","text":"Mac, Windows and Linux","level":2},{"id":"tablets-and-touch-screens","text":"Tablets and touch screens","level":2},{"id":"what-your-computer-needs","text":"What your computer needs","level":2}],"html":"\u003Cp\u003EThe apps run inside a web browser. They do the work on your own computer: your files are opened there and never sent to us (see \u003Ca href=\"/tutorials/basics/your-files\" data-topic=\"basics/your-files\"\u003EWhere your files go\u003C/a\u003E).\u003C/p\u003E\n\u003Ch2 id=\"which-browser\"\u003EWhich browser\u003C/h2\u003E\n\u003Cp\u003EUse an up-to-date version of one of these:\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EBrowser\u003C/th\u003E\u003Cth scope=\"col\"\u003EEngine\u003C/th\u003E\u003Cth scope=\"col\"\u003ENotes\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003EChrome, Edge, Brave, Opera, Vivaldi\u003C/td\u003E\u003Ctd\u003EChromium\u003C/td\u003E\u003Ctd\u003EThe most complete: folder picking, saving for offline use, file handling.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EFirefox\u003C/td\u003E\u003Ctd\u003EGecko\u003C/td\u003E\u003Ctd\u003EWorks. Opening a whole folder uses a simpler picker. Offline saving may not work in private windows.\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ESafari\u003C/td\u003E\u003Ctd\u003EWebKit\u003C/td\u003E\u003Ctd\u003EWorks on Mac and iPad. Opening a whole folder uses a simpler picker. Safari may delete an offline copy you have not used for a few weeks.\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EAll three engines are fine for everyday work. Where an app does something differently in one of them, its help shows the steps for your browser.\u003C/p\u003E\n\u003Ch2 id=\"what-differs-between-browsers\"\u003EWhat differs between browsers\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EOpening a folder.\u003C/strong\u003E Chromium browsers show a real folder picker and can read the folder directly. Firefox and Safari ask you to choose a folder and then read every file in it, which takes longer for big project folders; dragging the folder onto the app works in all three.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ESaving.\u003C/strong\u003E The apps save by downloading a file. Your browser decides where downloads go and whether it asks first.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:chromium\"\u003E\u003Cp class=\"hv-label\"\u003EChrome or Edge\u003C/p\u003E\n\u003Cp\u003EIn Chrome or Edge, turn on &quot;Ask where to save each file before downloading&quot; (in Settings, under Downloads) to choose a folder every time.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:firefox\"\u003E\u003Cp class=\"hv-label\"\u003EFirefox\u003C/p\u003E\n\u003Cp\u003EIn Firefox, open Settings, then General, then Downloads, and choose &quot;Always ask you where to save files&quot; to pick a folder every time.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003EIn Safari, open Settings, then General, and set &quot;File download location&quot; to &quot;Ask for each download&quot; to pick a folder every time.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"mac-windows-and-linux\"\u003EMac, Windows and Linux\u003C/h2\u003E\n\u003Cp\u003EThe apps are the same on every computer. What changes is the keyboard: shortcuts are written for your computer automatically. See \u003Ca href=\"/tutorials/basics/keys\" data-topic=\"basics/keys\"\u003EKeys, mice and trackpads\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"tablets-and-touch-screens\"\u003ETablets and touch screens\u003C/h2\u003E\n\u003Cp\u003ESome apps accept touch (one finger draws or selects, two fingers pinch to zoom and pan). Each app&#039;s help says whether it does. On an iPad, use Safari or Chrome. A keyboard helps with apps that use typed commands.\u003C/p\u003E\n\u003Ch2 id=\"what-your-computer-needs\"\u003EWhat your computer needs\u003C/h2\u003E\n\u003Cp\u003EThese are planned minimums for the apps, not measured requirements:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E8 GB of memory (16 GB is recommended for large federated models).\u003C/li\u003E\u003Cli\u003EA graphics chip with WebGL 2 for the 3D apps. If a 3D view stays blank, check that hardware acceleration is on in your browser&#039;s settings.\u003C/li\u003E\u003Cli\u003EA screen at least 1280 pixels wide for the full toolbars; smaller screens wrap them.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EVery large files (big plan sets, big models) use a lot of memory in a browser tab. Close other heavy tabs if an app slows down.\u003C/p\u003E","text":"The apps run inside a web browser. They do the work on your own computer: your files are opened there and never sent to us (see Where your files go). Which browser Use an up-to-date version of one of these: Browser Engine Notes Chrome, Edge, Brave, Opera, Vivaldi Chromium The most complete: folder picking, saving for offline use, file handling. Firefox Gecko Works. Opening a whole folder uses a simpler picker. Offline saving may not work in private windows. Safari WebKit Works on Mac and iPad. Opening a whole folder uses a simpler picker. Safari may delete an offline copy you have not used for a few weeks. All three engines are fine for everyday work. Where an app does something differently in one of them, its help shows the steps for your browser. What differs between browsers Opening a folder. Chromium browsers show a real folder picker and can read the folder directly. Firefox and Safari ask you to choose a folder and then read every file in it, which takes longer for big project folders; dragging the folder onto the app works in all three. Saving. The apps save by downloading a file. Your browser decides where downloads go and whether it asks first. In Chrome or Edge, turn on \"Ask where to save each file before downloading\" (in Settings, under Downloads) to choose a folder every time. In Firefox, open Settings, then General, then Downloads, and choose \"Always ask you where to save files\" to pick a folder every time. In Safari, open Settings, then General, and set \"File download location\" to \"Ask for each download\" to pick a folder every time. Mac, Windows and Linux The apps are the same on every computer. What changes is the keyboard: shortcuts are written for your computer automatically. See Keys, mice and trackpads. Tablets and touch screens Some apps accept touch (one finger draws or selects, two fingers pinch to zoom and pan). Each app's help says whether it does. On an iPad, use Safari or Chrome. A keyboard helps with apps that use typed commands. What your computer needs These are planned minimums for the apps, not measured requirements: 8 GB of memory (16 GB is recommended for large federated models). A graphics chip with WebGL 2 for the 3D apps. If a 3D view stays blank, check that hardware acceleration is on in your browser's settings. A screen at least 1280 pixels wide for the full toolbars; smaller screens wrap them. Very large files (big plan sets, big models) use a lot of memory in a browser tab. Close other heavy tabs if an app slows down.","lang":"en"},{"slug":"keys","scope":"basics","title":"Keys, mice and trackpads","summary":"How shortcuts are written, function keys on a Mac, right-clicking and panning without a mouse.","section":"start","order":30,"keywords":["keyboard","shortcut","ctrl","command","cmd","option","fn","function keys","trackpad","right click","middle button","magic mouse"],"headings":[{"id":"how-shortcuts-are-written","text":"How shortcuts are written","level":2},{"id":"function-keys-on-a-mac","text":"Function keys on a Mac","level":2},{"id":"shortcuts-the-browser-keeps","text":"Shortcuts the browser keeps","level":2},{"id":"mouse-buttons-on-a-trackpad","text":"Mouse buttons on a trackpad","level":2},{"id":"typing-in-a-text-box","text":"Typing in a text box","level":2}],"html":"\u003Ch2 id=\"how-shortcuts-are-written\"\u003EHow shortcuts are written\u003C/h2\u003E\n\u003Cp\u003EThe help writes each shortcut the way your keyboard labels it.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EWritten\u003C/th\u003E\u003Cth scope=\"col\"\u003EOn a Mac\u003C/th\u003E\u003Cth scope=\"col\"\u003EOn Windows and Linux\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command S\"\u003E⌘S\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+S\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003ECommand (⌘) and S\u003C/td\u003E\u003Ctd\u003ECtrl and S\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EControl (⌃), Shift (⇧) and F\u003C/td\u003E\u003Ctd\u003ECtrl, Shift and F\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option ←\"\u003E⌥←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+←\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EOption (⌥) and ←\u003C/td\u003E\u003Ctd\u003EAlt and ←\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Delete\"\u003EDelete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EBackspace\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003Ethe Delete key\u003C/td\u003E\u003Ctd\u003EBackspace\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn Delete\"\u003Efn Delete\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EDelete\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003Efn and Delete (forward delete)\u003C/td\u003E\u003Ctd\u003EDelete\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E\u003C/td\u003E\u003Ctd\u003EReturn\u003C/td\u003E\u003Ctd\u003EEnter\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EA plus sign means hold the keys together. &quot;Then&quot; means press one after the other.\u003C/p\u003E\n\u003Cp\u003EMost app shortcuts accept either Command or Control on a Mac, so \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E works both ways. A few, such as full screen (\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E), use the Control key on every computer; the help says so where that applies.\u003C/p\u003E\n\u003Ch2 id=\"function-keys-on-a-mac\"\u003EFunction keys on a Mac\u003C/h2\u003E\n\u003Cp\u003EOn most Mac keyboards the top row changes brightness, volume and media. To send F1 to F12:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003Ehold \u003Cstrong\u003Efn\u003C/strong\u003E (or the globe key) while you press the key, or\u003C/li\u003E\u003Cli\u003Eopen \u003Cstrong\u003ESystem Settings\u003C/strong\u003E, then \u003Cstrong\u003EKeyboard\u003C/strong\u003E, then \u003Cstrong\u003EKeyboard Shortcuts\u003C/strong\u003E, then \u003Cstrong\u003EFunction Keys\u003C/strong\u003E, and turn on &quot;Use F1, F2, etc. keys as standard function keys&quot;.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ESome F-keys are also claimed by macOS itself (for example Mission Control). If a key does nothing in the app, try it with fn, or use the toolbar button instead.\u003C/p\u003E\n\u003Ch2 id=\"shortcuts-the-browser-keeps\"\u003EShortcuts the browser keeps\u003C/h2\u003E\n\u003Cp\u003EA web page cannot take some shortcuts from the browser, whatever it does. In every app:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command N\"\u003E⌘N\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+N\u003C/span\u003E\u003C/kbd\u003E, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command T\"\u003E⌘T\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+T\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command W\"\u003E⌘W\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+W\u003C/span\u003E\u003C/kbd\u003E always open or close browser windows and tabs. The apps use buttons for New and Close instead.\u003C/li\u003E\u003Cli\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Q\"\u003E⌘Q\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Q\u003C/span\u003E\u003C/kbd\u003E on a Mac and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option F4\"\u003E⌥ F4\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt+F4\u003C/span\u003E\u003C/kbd\u003E on Windows quit the browser. If you have unsaved work, the browser asks first (&quot;Leave site?&quot;); choose to stay, then save.\u003C/li\u003E\u003Cli\u003EThe browser&#039;s own full screen (\u003Cspan class=\"hp\"\u003E\u003Cspan class=\"hpv\" data-v=\"os:mac\" title=\"Mac\"\u003EControl-Command-F, or the green button on the window\u003C/span\u003E\u003Cspan class=\"hp-sep\"\u003E / \u003C/span\u003E\u003Cspan class=\"hpv\" data-v=\"os:windows,linux\" title=\"Windows or Linux\"\u003EF11\u003C/span\u003E\u003C/span\u003E) still works. The apps also have their own screen modes on \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E, which can hide the app&#039;s bars too.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"mouse-buttons-on-a-trackpad\"\u003EMouse buttons on a trackpad\u003C/h2\u003E\n\u003Cp\u003EThe apps use the right button and the middle button. Without a three-button mouse:\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:mac\"\u003E\u003Cp class=\"hv-label\"\u003EMac\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ERight-click:\u003C/strong\u003E click with two fingers. Turn on &quot;Secondary click&quot; in \u003Cstrong\u003ESystem Settings\u003C/strong\u003E, then \u003Cstrong\u003ETrackpad\u003C/strong\u003E, if two-finger click does nothing. Holding \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control\"\u003E⌃\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E while you click opens the browser&#039;s menu, but inside a drawing some apps read it as an ordinary click (with Control held), so prefer the two-finger click.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMiddle-button drag (pan):\u003C/strong\u003E each app offers another way to pan, such as holding \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E while you drag or dragging with the right button. The app&#039;s keyboard page says which.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EWheel zoom:\u003C/strong\u003E two-finger scroll on the trackpad zooms in most apps. Pinch also zooms where the app supports it.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"os:windows,linux\"\u003E\u003Cp class=\"hv-label\"\u003EWindows or Linux\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ERight-click:\u003C/strong\u003E click with two fingers, or click the lower-right corner of the touchpad. This depends on your touchpad settings.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMiddle-button drag (pan):\u003C/strong\u003E each app offers another way to pan, such as holding \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Space\"\u003ESpace\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ESpace\u003C/span\u003E\u003C/kbd\u003E while you drag or dragging with the right button. The app&#039;s keyboard page says which.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EWheel zoom:\u003C/strong\u003E two-finger scroll on the touchpad zooms in most apps.\u003C/li\u003E\u003C/ul\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"typing-in-a-text-box\"\u003ETyping in a text box\u003C/h2\u003E\n\u003Cp\u003EWhile you type in a box (a name, a note, a search), the app&#039;s one-letter shortcuts are off, so typing &quot;L&quot; types an L. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E or click on the drawing to give the keys back to the app.\u003C/p\u003E","text":"How shortcuts are written The help writes each shortcut the way your keyboard labels it. Written On a Mac On Windows and Linux Ctrl+S Command (⌘) and S Ctrl and S Ctrl+Shift+F Control (⌃), Shift (⇧) and F Ctrl, Shift and F Alt+← Option (⌥) and ← Alt and ← Backspace the Delete key Backspace Delete fn and Delete (forward delete) Delete Enter Return Enter A plus sign means hold the keys together. \"Then\" means press one after the other. Most app shortcuts accept either Command or Control on a Mac, so Ctrl+Z works both ways. A few, such as full screen (Ctrl+Shift+F), use the Control key on every computer; the help says so where that applies. Function keys on a Mac On most Mac keyboards the top row changes brightness, volume and media. To send F1 to F12: hold fn (or the globe key) while you press the key, or open System Settings, then Keyboard, then Keyboard Shortcuts, then Function Keys, and turn on \"Use F1, F2, etc. keys as standard function keys\". Some F-keys are also claimed by macOS itself (for example Mission Control). If a key does nothing in the app, try it with fn, or use the toolbar button instead. Shortcuts the browser keeps A web page cannot take some shortcuts from the browser, whatever it does. In every app: Ctrl+N, Ctrl+T and Ctrl+W always open or close browser windows and tabs. The apps use buttons for New and Close instead. Ctrl+Q on a Mac and Alt+F4 on Windows quit the browser. If you have unsaved work, the browser asks first (\"Leave site?\"); choose to stay, then save. The browser's own full screen (Control-Command-F, or the green button on the window / F11) still works. The apps also have their own screen modes on Ctrl+Shift+F, which can hide the app's bars too. Mouse buttons on a trackpad The apps use the right button and the middle button. Without a three-button mouse: Right-click: click with two fingers. Turn on \"Secondary click\" in System Settings, then Trackpad, if two-finger click does nothing. Holding Ctrl while you click opens the browser's menu, but inside a drawing some apps read it as an ordinary click (with Control held), so prefer the two-finger click. Middle-button drag (pan): each app offers another way to pan, such as holding Space while you drag or dragging with the right button. The app's keyboard page says which. Wheel zoom: two-finger scroll on the trackpad zooms in most apps. Pinch also zooms where the app supports it. Right-click: click with two fingers, or click the lower-right corner of the touchpad. This depends on your touchpad settings. Middle-button drag (pan): each app offers another way to pan, such as holding Space while you drag or dragging with the right button. The app's keyboard page says which. Wheel zoom: two-finger scroll on the touchpad zooms in most apps. Typing in a text box While you type in a box (a name, a note, a search), the app's one-letter shortcuts are off, so typing \"L\" types an L. Press Esc or click on the drawing to give the keys back to the app.","lang":"en"},{"slug":"find-tools","scope":"basics","title":"Find a tool or setting","summary":"Press Ctrl+K and type a few letters to run any tool, change a setting or open a help topic.","section":"start","order":32,"keywords":["find","search","command palette","quick open","run command","ctrl k","cmd k","tool","setting","shortcut"],"headings":[{"id":"find-and-run","text":"Find and run","level":2},{"id":"things-to-know","text":"Things to know","level":2}],"html":"\u003Cp\u003EEvery app has a search box for its tools, its settings and this help. You don&#039;t need to know where a tool sits in the toolbar.\u003C/p\u003E\n\u003Ch2 id=\"find-and-run\"\u003EFind and run\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command K\"\u003E⌘K\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+K\u003C/span\u003E\u003C/kbd\u003E, or choose \u003Cspan class=\"hui\"\u003EFind\u003C/span\u003E in the bar at the top.\u003C/li\u003E\u003Cli\u003EType a few letters of what you want: &quot;fillet&quot;, &quot;panel text&quot;, &quot;units&quot;. Every word you type has to match, so add a second word to narrow the list.\u003C/li\u003E\u003Cli\u003EPress \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E to run the first match, or move with the arrow keys first. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E closes the box.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EA tool runs as if you had clicked it in the toolbar. A setting opens \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E at that setting. A help topic opens here, in the help panel.\u003C/p\u003E\n\u003Ch2 id=\"things-to-know\"\u003EThings to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EWhat you used last comes first the next time, so a tool you use often is one key press away.\u003C/li\u003E\u003Cli\u003ETools that can&#039;t run right now, for example before a file is open, are listed but greyed out.\u003C/li\u003E\u003Cli\u003EAdd-ons&#039; tools are in the list too, once the add-on is switched on.\u003C/li\u003E\u003C/ul\u003E","text":"Every app has a search box for its tools, its settings and this help. You don't need to know where a tool sits in the toolbar. Find and run Press Ctrl+K, or choose Find in the bar at the top. Type a few letters of what you want: \"fillet\", \"panel text\", \"units\". Every word you type has to match, so add a second word to narrow the list. Press Enter to run the first match, or move with the arrow keys first. Esc closes the box. A tool runs as if you had clicked it in the toolbar. A setting opens Settings at that setting. A help topic opens here, in the help panel. Things to know What you used last comes first the next time, so a tool you use often is one key press away. Tools that can't run right now, for example before a file is open, are listed but greyed out. Add-ons' tools are in the list too, once the add-on is switched on.","lang":"en"},{"slug":"arrange-panels","scope":"basics","title":"Arrange the panels and use a second monitor","summary":"Dock the side panels left, right or at the bottom, stack them, group them as tabs, pin or hide them, float them over the drawing, make the layout denser, or move them to their own window on another screen.","section":"start","order":35,"keywords":["panels","dock","float","move panel","drag","layout","tabs","tab group","stack","pin","auto-hide","hide panel","close panel","compact","layout density","dense","second monitor","two screens","dual monitor","multiple monitors","window","pop-up","reset layout"],"headings":[{"id":"move-a-panel-in-the-window","text":"Move a panel in the window","level":2},{"id":"group-panels-as-tabs","text":"Group panels as tabs","level":2},{"id":"pin-hide-and-bring-back","text":"Pin, hide and bring back","level":2},{"id":"make-the-layout-denser","text":"Make the layout denser","level":2},{"id":"use-the-keyboard","text":"Use the keyboard","level":2},{"id":"put-the-panels-on-a-second-monitor","text":"Put the panels on a second monitor","level":2},{"id":"more-than-one-panels-window","text":"More than one panels window","level":2},{"id":"move-a-dialog","text":"Move a dialog","level":2},{"id":"put-the-panels-back","text":"Put the panels back","level":2}],"html":"\u003Cp\u003EThe panels beside the drawing can move. Put them where they suit you, or give them a window of their own on a second monitor so the drawing gets the whole of the first one.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EEach panel has a title bar: a slim bar with the panel&#039;s name, a \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu, a pin and a close button at the top of the panel. Versions before 0.7 have the name and the \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu only.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"move-a-panel-in-the-window\"\u003EMove a panel in the window\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EDrag the panel by its name at the top.\u003C/li\u003E\u003Cli\u003EWhile you drag, outlined areas appear on the left, the right and the bottom of the drawing. Drop the panel on one to dock it there. The area you are over darkens.\u003C/li\u003E\u003Cli\u003EDrop it anywhere else over the drawing to make it float.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EPanels can share one side: they stack, and each line between two of them drags to share the space (with a line focused, the arrow keys move it, and double-clicking it shares the space equally). Drag the inner edge of a docked side to make it wider or narrower; double-click the edge to put it back.\u003C/p\u003E\n\u003Cp\u003EA floating panel stays over the drawing. Move it by its name, and resize it by dragging its lower-right corner (or tab to the corner and use the arrow keys). Double-click its name to dock it again where it was.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Cp\u003EDrag with one finger on the panel&#039;s name. Drag the lower-right corner of a floating panel with one finger to resize it, and the edges between docked panels the same way. To float or dock with no dragging, use the \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"group-panels-as-tabs\"\u003EGroup panels as tabs\u003C/h2\u003E\n\u003Cp\u003ETwo panels can share one frame and show one at a time. Drag a panel by its name onto another panel&#039;s title bar (the bar is outlined while you are over it) and let go: the frame now has a tab for each panel, in its title bar. Click a tab to show that panel. With a tab focused, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"←\"\u003E←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E←\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"→\"\u003E→\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E→\u003C/span\u003E\u003C/kbd\u003E switch tabs, and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ←\"\u003Efn ←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EHome\u003C/span\u003E\u003C/kbd\u003E and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn →\"\u003Efn →\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnd\u003C/span\u003E\u003C/kbd\u003E go to the first and last.\u003C/p\u003E\n\u003Cp\u003ETo take a panel out of the group, choose \u003Cspan class=\"hui\"\u003EMove out of the tab group\u003C/span\u003E in its \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu, or drag it somewhere else. Choose \u003Cspan class=\"hui\"\u003ETab with\u003C/span\u003E and a panel&#039;s name to group them without dragging.\u003C/p\u003E\n\u003Ch2 id=\"pin-hide-and-bring-back\"\u003EPin, hide and bring back\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EThe pin in a panel&#039;s title bar makes it \u003Cstrong\u003Eauto-hide\u003C/strong\u003E: the panel leaves its dock and becomes a small tab at that edge. Point at the tab, focus it or click it and the panel slides out over the drawing; move away (or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E) and it slides back. Press the pin again, or choose \u003Cspan class=\"hui\"\u003EUnpin\u003C/span\u003E, to dock it for good.\u003C/li\u003E\u003Cli\u003EThe close button, or \u003Cspan class=\"hui\"\u003EHide this panel\u003C/span\u003E in the menu, hides the panel and closes up its dock. A dashed tab at the edge brings it back: click it, or focus it and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"make-the-layout-denser\"\u003EMake the layout denser\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003ELayout density\u003C/span\u003E has two choices. \u003Cspan class=\"hui\"\u003EComfortable\u003C/span\u003E is the default. \u003Cspan class=\"hui\"\u003ECompact\u003C/span\u003E tightens the row heights, panel padding, toolbar buttons and panel text of that app so more fits on the screen. It is kept for each app. A touch screen keeps its large buttons in both, and a phone keeps its own layout. \u003Cspan class=\"hui\"\u003EReset layout\u003C/span\u003E leaves the density as you set it.\u003C/p\u003E\n\u003Ch2 id=\"use-the-keyboard\"\u003EUse the keyboard\u003C/h2\u003E\n\u003Cp\u003EEvery panel&#039;s \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E button opens a menu: \u003Cspan class=\"hui\"\u003EDock on the left\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDock on the right\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EDock at the bottom\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EFloat over the drawing\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EPin to the edge\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EHide this panel\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ETab with\u003C/span\u003E another panel, \u003Cspan class=\"hui\"\u003EMove to a new window\u003C/span\u003E and \u003Cspan class=\"hui\"\u003EPut it back\u003C/span\u003E. Tab to the button, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E, move with the arrow keys and press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E again. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E closes the menu.\u003C/p\u003E\n\u003Ch2 id=\"put-the-panels-on-a-second-monitor\"\u003EPut the panels on a second monitor\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E on a panel, then \u003Cspan class=\"hui\"\u003EMove all panels to a new window\u003C/span\u003E. You can also choose \u003Cspan class=\"hui\"\u003EMove panels to a new window\u003C/span\u003E in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EA small window opens with the panels in it. Drag it to your other monitor and make it as big as you like.\u003C/li\u003E\u003Cli\u003EKeep working: the panels act on the drawing as before, and the drawing fills the main window.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EShortcuts keep working while the panels window is in front: keys you press there, other than typing in a box, go to the drawing. Questions and dialogs the app asks still open in the main window, so look there when one appears. The theme and the panel text size follow the main window.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:chromium\"\u003E\u003Cp class=\"hv-label\"\u003EChrome or Edge\u003C/p\u003E\n\u003Cp\u003EChrome and Edge can place the window on the other screen for you. With a second screen connected, choose \u003Cspan class=\"hui\"\u003EPut it on my other screen\u003C/span\u003E in the panels window (or \u003Cspan class=\"hui\"\u003EPut the panels on my other screen\u003C/span\u003E in a panel&#039;s \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu). The browser asks once whether this site may see your screens; after you allow it, the panels window opens on that screen every time.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:firefox,safari\"\u003E\u003Cp class=\"hv-label\"\u003EFirefox or Safari\u003C/p\u003E\n\u003Cp\u003EDrag the panels window to the other monitor yourself. It opens in the same place and at the same size next time.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"more-than-one-panels-window\"\u003EMore than one panels window\u003C/h2\u003E\n\u003Cp\u003EEach panel can have a window of its own: up to four panels windows, for example one per monitor.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EIn a panel&#039;s \u003Cspan class=\"hui\"\u003E⋯\u003C/span\u003E menu, \u003Cspan class=\"hui\"\u003EMove to a new window\u003C/span\u003E opens another window for that panel, and \u003Cspan class=\"hui\"\u003EMove to panels window 2\u003C/span\u003E (and so on) moves it into one that is open. The second window is called &quot;panels 2&quot;.\u003C/li\u003E\u003Cli\u003EDrag a panel by its name from one window to another: let go over the main window to dock it there (the outlined areas show while you are over it) or to float it, and over another panels window to move it in. Let go anywhere else and it stays where it was.\u003C/li\u003E\u003Cli\u003EA panels window that has no panels left closes by itself.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EAfter a reload the app offers your panels windows again. Browsers open one window per click, so choose \u003Cspan class=\"hui\"\u003EOpen the next one\u003C/span\u003E once for each window.\u003C/p\u003E\n\u003Ch2 id=\"move-a-dialog\"\u003EMove a dialog\u003C/h2\u003E\n\u003Cp\u003EEvery dialog can be moved out of the way of the drawing: press and drag its title bar. The dialog remembers where you left it, each dialog on its own, and comes back to that place the next time it opens. Double-click the title bar to centre it again.\u003C/p\u003E\n\u003Cp\u003EFrom the keyboard, press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Option\"\u003E⌥\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EAlt\u003C/span\u003E\u003C/kbd\u003E+\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift\"\u003E⇧\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift\u003C/span\u003E\u003C/kbd\u003E+an arrow key with the focus inside the dialog to move it 16 pixels at a time; add \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control\"\u003E⌃\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl\u003C/span\u003E\u003C/kbd\u003E for 64. A dialog that ends up off the screen (after a smaller window or screen) is brought back.\u003C/p\u003E\n\u003Cp\u003EOn a phone, dialogs stay full-width sheets and are not moved.\u003C/p\u003E\n\u003Cp\u003EIn CadCraft Studio, CadCraft&#039;s \u003Cspan class=\"hui\"\u003EPlot to PDF\u003C/span\u003E dialog, which you may keep open while you work, has a button in its title bar, \u003Cspan class=\"hui\"\u003EOpen in its own window\u003C/span\u003E. The dialog moves into a window of its own that you can put on another monitor. Closing the dialog closes the window, and closing the window closes the dialog.\u003C/p\u003E\n\u003Ch2 id=\"put-the-panels-back\"\u003EPut the panels back\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003EPut the panels back\u003C/span\u003E in the panels window, or simply close it. The panels go back where they were.\u003C/li\u003E\u003Cli\u003EClosing or reloading the main window closes the panels window too. When the app opens again it says your panels were in their own window; choose \u003Cspan class=\"hui\"\u003EOpen it\u003C/span\u003E to bring the window back, or \u003Cspan class=\"hui\"\u003EKeep them here\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EReset layout\u003C/span\u003E puts every panel back where it started.\u003C/li\u003E\u003C/ul\u003E\n\u003Caside class=\"hc hc-tip\"\u003E\u003Cp class=\"hc-label\"\u003ETip\u003C/p\u003E\n\u003Cp\u003EIf nothing opens when you move panels to a new window, the browser blocked the pop-up. The app says so and keeps the panels where they were. Allow pop-ups for getcadcraft.com, then try again.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003EThe layout is kept for each app in this browser, along with your other settings.\u003C/p\u003E","text":"The panels beside the drawing can move. Put them where they suit you, or give them a window of their own on a second monitor so the drawing gets the whole of the first one. Each panel has a title bar: a slim bar with the panel's name, a ⋯ menu, a pin and a close button at the top of the panel. Versions before 0.7 have the name and the ⋯ menu only. Move a panel in the window Drag the panel by its name at the top. While you drag, outlined areas appear on the left, the right and the bottom of the drawing. Drop the panel on one to dock it there. The area you are over darkens. Drop it anywhere else over the drawing to make it float. Panels can share one side: they stack, and each line between two of them drags to share the space (with a line focused, the arrow keys move it, and double-clicking it shares the space equally). Drag the inner edge of a docked side to make it wider or narrower; double-click the edge to put it back. A floating panel stays over the drawing. Move it by its name, and resize it by dragging its lower-right corner (or tab to the corner and use the arrow keys). Double-click its name to dock it again where it was. Drag with one finger on the panel's name. Drag the lower-right corner of a floating panel with one finger to resize it, and the edges between docked panels the same way. To float or dock with no dragging, use the ⋯ menu. Group panels as tabs Two panels can share one frame and show one at a time. Drag a panel by its name onto another panel's title bar (the bar is outlined while you are over it) and let go: the frame now has a tab for each panel, in its title bar. Click a tab to show that panel. With a tab focused, ← and → switch tabs, and Home and End go to the first and last. To take a panel out of the group, choose Move out of the tab group in its ⋯ menu, or drag it somewhere else. Choose Tab with and a panel's name to group them without dragging. Pin, hide and bring back The pin in a panel's title bar makes it auto-hide: the panel leaves its dock and becomes a small tab at that edge. Point at the tab, focus it or click it and the panel slides out over the drawing; move away (or press Esc) and it slides back. Press the pin again, or choose Unpin, to dock it for good. The close button, or Hide this panel in the menu, hides the panel and closes up its dock. A dashed tab at the edge brings it back: click it, or focus it and press Enter. Make the layout denser Settings › General › Layout density has two choices. Comfortable is the default. Compact tightens the row heights, panel padding, toolbar buttons and panel text of that app so more fits on the screen. It is kept for each app. A touch screen keeps its large buttons in both, and a phone keeps its own layout. Reset layout leaves the density as you set it. Use the keyboard Every panel's ⋯ button opens a menu: Dock on the left, Dock on the right, Dock at the bottom, Float over the drawing, Pin to the edge, Hide this panel, Tab with another panel, Move to a new window and Put it back. Tab to the button, press Enter, move with the arrow keys and press Enter again. Esc closes the menu. Put the panels on a second monitor Choose ⋯ on a panel, then Move all panels to a new window. You can also choose Move panels to a new window in Settings. A small window opens with the panels in it. Drag it to your other monitor and make it as big as you like. Keep working: the panels act on the drawing as before, and the drawing fills the main window. Shortcuts keep working while the panels window is in front: keys you press there, other than typing in a box, go to the drawing. Questions and dialogs the app asks still open in the main window, so look there when one appears. The theme and the panel text size follow the main window. Chrome and Edge can place the window on the other screen for you. With a second screen connected, choose Put it on my other screen in the panels window (or Put the panels on my other screen in a panel's ⋯ menu). The browser asks once whether this site may see your screens; after you allow it, the panels window opens on that screen every time. Drag the panels window to the other monitor yourself. It opens in the same place and at the same size next time. More than one panels window Each panel can have a window of its own: up to four panels windows, for example one per monitor. In a panel's ⋯ menu, Move to a new window opens another window for that panel, and Move to panels window 2 (and so on) moves it into one that is open. The second window is called \"panels 2\". Drag a panel by its name from one window to another: let go over the main window to dock it there (the outlined areas show while you are over it) or to float it, and over another panels window to move it in. Let go anywhere else and it stays where it was. A panels window that has no panels left closes by itself. After a reload the app offers your panels windows again. Browsers open one window per click, so choose Open the next one once for each window. Move a dialog Every dialog can be moved out of the way of the drawing: press and drag its title bar. The dialog remembers where you left it, each dialog on its own, and comes back to that place the next time it opens. Double-click the title bar to centre it again. From the keyboard, press Alt+Shift+an arrow key with the focus inside the dialog to move it 16 pixels at a time; add Ctrl for 64. A dialog that ends up off the screen (after a smaller window or screen) is brought back. On a phone, dialogs stay full-width sheets and are not moved. In CadCraft Studio, CadCraft's Plot to PDF dialog, which you may keep open while you work, has a button in its title bar, Open in its own window. The dialog moves into a window of its own that you can put on another monitor. Closing the dialog closes the window, and closing the window closes the dialog. Put the panels back Choose Put the panels back in the panels window, or simply close it. The panels go back where they were. Closing or reloading the main window closes the panels window too. When the app opens again it says your panels were in their own window; choose Open it to bring the window back, or Keep them here. Settings › General › Reset layout puts every panel back where it started. If nothing opens when you move panels to a new window, the browser blocked the pop-up. The app says so and keeps the panels where they were. Allow pop-ups for getcadcraft.com, then try again. The layout is kept for each app in this browser, along with your other settings.","lang":"en"},{"slug":"layout-ribbon","scope":"basics","title":"Trabajar con el diseño de cinta y navegador de proyecto","summary":"Cambie la aplicación a una cinta de pestañas sobre el dibujo, con Propiedades y un navegador de proyecto a la izquierda y una pestaña por cada vista abierta, y vuelva al diseño clásico cuando quiera.","section":"start","order":36,"keywords":["diseño","espacio de trabajo","cinta","pestañas de la cinta","navegador de proyecto","navegador","paletas","paleta de propiedades","pestañas de vista","barra de estado","acceso rápido","contraer la cinta","minimizar la cinta","ventana de la cinta","diseño clásico","cambiar de diseño"],"headings":[{"id":"elegirlo","text":"Elegirlo","level":2},{"id":"qu-hay-en-cada-lugar","text":"Qué hay en cada lugar","level":2},{"id":"usar-la-cinta-con-el-teclado","text":"Usar la cinta con el teclado","level":2},{"id":"contraer-la-cinta-o-darle-su-propia-ventana","text":"Contraer la cinta o darle su propia ventana","level":2},{"id":"sus-paneles-siguen-siendo-suyos","text":"Sus paneles siguen siendo suyos","level":2},{"id":"volver-al-dise-o-cl-sico","text":"Volver al diseño clásico","level":2}],"html":"\u003Cp\u003E\u003Cstrong\u003ECinta y navegador de proyecto\u003C/strong\u003E es uno de los tres diseños de espacio de trabajo de la aplicación. Una cinta de pestañas recorre la parte de arriba, Propiedades y un navegador de proyecto comparten el panel izquierdo, cada vista que abre tiene su pestaña sobre el dibujo y abajo hay una barra de estado. Las herramientas son las de la aplicación: todo lo que puede hacer en el diseño clásico funciona aquí también, y su dibujo, su estilo de menú y sus teclas siguen igual.\u003C/p\u003E\n\u003Ch2 id=\"elegirlo\"\u003EElegirlo\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EAbra \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E (el engrane, o \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EElija la pestaña \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E y vaya a \u003Cspan class=\"hui\"\u003EDiseño\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EEspacio de trabajo\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EElija \u003Cspan class=\"hui\"\u003ECinta y navegador de proyecto\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EEl diseño cambia de inmediato. La elección vale para todas las aplicaciones en este navegador: cada una abre con él desde entonces, y está listo antes de que se dibuje la página, así que nunca verá primero el diseño clásico.\u003C/p\u003E\n\u003Ch2 id=\"qu-hay-en-cada-lugar\"\u003EQué hay en cada lugar\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EBarra de título:\u003C/strong\u003E el nombre de la aplicación, botones de acceso rápido (abrir, guardar, deshacer, rehacer), el nombre del archivo abierto, \u003Cspan class=\"hui\"\u003EQué hace aquí cada herramienta\u003C/span\u003E (una lista de todas las herramientas con un cuadro de búsqueda, que dice cuáles están listas y por qué las demás no), pantalla completa, \u003Cspan class=\"hui\"\u003EAyuda\u003C/span\u003E y \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E. En este diseño la barra de título ocupa el lugar de la barra de la aplicación.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECinta:\u003C/strong\u003E las herramientas de la aplicación en pestañas, cada pestaña en grupos. \u003Cspan class=\"hui\"\u003EArchivo\u003C/span\u003E, a la izquierda, abre, guarda y lo demás. Algunas aplicaciones agregan una pestaña propia mientras trabaja en un modo o espacio de trabajo; se ilumina mientras aplica y desaparece después.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EBarra de opciones:\u003C/strong\u003E debajo de la cinta, lo que la herramienta en curso le pide, o lo que está seleccionado.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPanel izquierdo:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EPropiedades\u003C/span\u003E arriba y, debajo, las paletas (el navegador de proyecto y el contenido propio del panel) como pestañas. Arrastre la línea entre ellas para repartir el espacio.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPestañas de vista:\u003C/strong\u003E una pestaña por cada vista que abrió (una hoja, una planta, una escena…). Cierre una con su botón de cerrar; el archivo sigue abierto.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EBarra de vista y barra de estado:\u003C/strong\u003E debajo del dibujo, los controles de la vista (escala, zoom); abajo del todo, los mensajes de la aplicación.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EUna herramienta que no puede usarse ahora aparece en gris, y su información emergente dice por qué (por ejemplo, &quot;Abra primero un archivo&quot;, o que la aplicación aún no tiene esa herramienta). Haga clic en ella, o pulse \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E sobre ella, para leer el motivo en un cuadro.\u003C/p\u003E\n\u003Ch2 id=\"usar-la-cinta-con-el-teclado\"\u003EUsar la cinta con el teclado\u003C/h2\u003E\n\u003Cp\u003ECon una pestaña de la cinta enfocada, \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"←\"\u003E←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E←\u003C/span\u003E\u003C/kbd\u003E y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"→\"\u003E→\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003E→\u003C/span\u003E\u003C/kbd\u003E pasan de una pestaña a otra, y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn ←\"\u003Efn ←\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EHome\u003C/span\u003E\u003C/kbd\u003E y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"fn →\"\u003Efn →\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnd\u003C/span\u003E\u003C/kbd\u003E van a la primera y a la última. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E termina primero la herramienta en curso, como en el diseño clásico, y todos los atajos y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E (modos de pantalla) funcionan como antes.\u003C/p\u003E\n\u003Ch2 id=\"contraer-la-cinta-o-darle-su-propia-ventana\"\u003EContraer la cinta o darle su propia ventana\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EHaga doble clic en una pestaña de la cinta para contraerla a sus pestañas; entonces un clic en una pestaña muestra sus herramientas hasta que siga con otra cosa. Haga doble clic otra vez para mantenerla abierta. El botón \u003Cspan class=\"hui\"\u003EMover la cinta\u003C/span\u003E, en el extremo derecho de la cinta, también tiene \u003Cspan class=\"hui\"\u003EContraer la cinta\u003C/span\u003E y \u003Cspan class=\"hui\"\u003EMantener la cinta abierta\u003C/span\u003E. Cada aplicación lo recuerda.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EMover la cinta\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EMover a una ventana nueva\u003C/span\u003E pone la cinta en una ventana propia, por ejemplo en un segundo monitor. Las teclas que pulse ahí llegan a la aplicación. \u003Cspan class=\"hui\"\u003ERegresar la cinta\u003C/span\u003E, o cerrar esa ventana, la devuelve a su lugar.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ELa configuración de la barra de herramientas se aplica a la cinta: \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EBarra de herramientas\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EIconos y etiquetas\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESolo iconos\u003C/span\u003E (la cinta muestra entonces dos filas de iconos pequeños por grupo) o \u003Cspan class=\"hui\"\u003ESolo etiquetas\u003C/span\u003E, y \u003Cspan class=\"hui\"\u003EMostrar nombres de grupo (Archivo, Dibujo, …)\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"sus-paneles-siguen-siendo-suyos\"\u003ESus paneles siguen siendo suyos\u003C/h2\u003E\n\u003Cp\u003ELos paneles izquierdo y derecho conservan todo lo que se describe en \u003Ca href=\"/tutorials/basics/arrange-panels\" data-topic=\"basics/arrange-panels\"\u003EOrganizar los paneles\u003C/a\u003E: acoplar, flotar, fijar, ocultar, pestañas, \u003Cspan class=\"hui\"\u003EMover a una ventana nueva\u003C/span\u003E y \u003Cspan class=\"hui\"\u003ERestablecer diseño\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"volver-al-dise-o-cl-sico\"\u003EVolver al diseño clásico\u003C/h2\u003E\n\u003Cp\u003EAbra \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EDiseño\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EEspacio de trabajo\u003C/span\u003E y elija \u003Cspan class=\"hui\"\u003ECadCraft clásico\u003C/span\u003E. Cada barra de herramientas, pestaña y panel vuelve a su lugar.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EEn un teléfono, o en una ventana de 760 píxeles de ancho o menos, la aplicación usa su diseño para teléfono sin importar lo que haya elegido. Una ventana más ancha devuelve su diseño.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003EPara probar otra disposición, vea \u003Ca href=\"/tutorials/basics/layout-toolbox\" data-topic=\"basics/layout-toolbox\"\u003Eel diseño de caja de herramientas y cuadro de información\u003C/a\u003E.\u003C/p\u003E","text":"Cinta y navegador de proyecto es uno de los tres diseños de espacio de trabajo de la aplicación. Una cinta de pestañas recorre la parte de arriba, Propiedades y un navegador de proyecto comparten el panel izquierdo, cada vista que abre tiene su pestaña sobre el dibujo y abajo hay una barra de estado. Las herramientas son las de la aplicación: todo lo que puede hacer en el diseño clásico funciona aquí también, y su dibujo, su estilo de menú y sus teclas siguen igual. Elegirlo Abra Configuración (el engrane, o Ctrl+,). Elija la pestaña Global y vaya a Diseño › Espacio de trabajo. Elija Cinta y navegador de proyecto. El diseño cambia de inmediato. La elección vale para todas las aplicaciones en este navegador: cada una abre con él desde entonces, y está listo antes de que se dibuje la página, así que nunca verá primero el diseño clásico. Qué hay en cada lugar Barra de título: el nombre de la aplicación, botones de acceso rápido (abrir, guardar, deshacer, rehacer), el nombre del archivo abierto, Qué hace aquí cada herramienta (una lista de todas las herramientas con un cuadro de búsqueda, que dice cuáles están listas y por qué las demás no), pantalla completa, Ayuda y Configuración. En este diseño la barra de título ocupa el lugar de la barra de la aplicación. Cinta: las herramientas de la aplicación en pestañas, cada pestaña en grupos. Archivo, a la izquierda, abre, guarda y lo demás. Algunas aplicaciones agregan una pestaña propia mientras trabaja en un modo o espacio de trabajo; se ilumina mientras aplica y desaparece después. Barra de opciones: debajo de la cinta, lo que la herramienta en curso le pide, o lo que está seleccionado. Panel izquierdo: Propiedades arriba y, debajo, las paletas (el navegador de proyecto y el contenido propio del panel) como pestañas. Arrastre la línea entre ellas para repartir el espacio. Pestañas de vista: una pestaña por cada vista que abrió (una hoja, una planta, una escena…). Cierre una con su botón de cerrar; el archivo sigue abierto. Barra de vista y barra de estado: debajo del dibujo, los controles de la vista (escala, zoom); abajo del todo, los mensajes de la aplicación. Una herramienta que no puede usarse ahora aparece en gris, y su información emergente dice por qué (por ejemplo, \"Abra primero un archivo\", o que la aplicación aún no tiene esa herramienta). Haga clic en ella, o pulse Enter sobre ella, para leer el motivo en un cuadro. Usar la cinta con el teclado Con una pestaña de la cinta enfocada, ← y → pasan de una pestaña a otra, y Home y End van a la primera y a la última. Esc termina primero la herramienta en curso, como en el diseño clásico, y todos los atajos y Ctrl+Shift+F (modos de pantalla) funcionan como antes. Contraer la cinta o darle su propia ventana Haga doble clic en una pestaña de la cinta para contraerla a sus pestañas; entonces un clic en una pestaña muestra sus herramientas hasta que siga con otra cosa. Haga doble clic otra vez para mantenerla abierta. El botón Mover la cinta, en el extremo derecho de la cinta, también tiene Contraer la cinta y Mantener la cinta abierta. Cada aplicación lo recuerda. Mover la cinta › Mover a una ventana nueva pone la cinta en una ventana propia, por ejemplo en un segundo monitor. Las teclas que pulse ahí llegan a la aplicación. Regresar la cinta, o cerrar esa ventana, la devuelve a su lugar. La configuración de la barra de herramientas se aplica a la cinta: Configuración › Global › Barra de herramientas › Iconos y etiquetas, Solo iconos (la cinta muestra entonces dos filas de iconos pequeños por grupo) o Solo etiquetas, y Mostrar nombres de grupo (Archivo, Dibujo, …). Sus paneles siguen siendo suyos Los paneles izquierdo y derecho conservan todo lo que se describe en Organizar los paneles: acoplar, flotar, fijar, ocultar, pestañas, Mover a una ventana nueva y Restablecer diseño. Volver al diseño clásico Abra Configuración › Global › Diseño › Espacio de trabajo y elija CadCraft clásico. Cada barra de herramientas, pestaña y panel vuelve a su lugar. En un teléfono, o en una ventana de 760 píxeles de ancho o menos, la aplicación usa su diseño para teléfono sin importar lo que haya elegido. Una ventana más ancha devuelve su diseño. Para probar otra disposición, vea el diseño de caja de herramientas y cuadro de información.","lang":"es-MX"},{"slug":"layout-toolbox","scope":"basics","title":"Trabajar con el diseño de caja de herramientas y cuadro de información","summary":"Cambie la aplicación a una columna de herramientas a la izquierda con espacios para las suyas, un cuadro de información arriba que sigue a la herramienta en curso o a lo que eligió, un navegador a la derecha, una pestaña por cada vista, opciones rápidas y una paleta de edición, y vuelva al diseño clásico cuando quiera.","section":"start","order":37,"keywords":["diseño","espacio de trabajo","caja de herramientas","columna de herramientas","cuadro de información","barra de información","navegador","mapa del proyecto","barra rápida","opciones rápidas","paleta de edición","mis herramientas","herramientas favoritas","pestañas de vista","ventana de la caja de herramientas","diseño clásico","cambiar de diseño"],"headings":[{"id":"elegirlo","text":"Elegirlo","level":2},{"id":"qu-hay-en-cada-lugar","text":"Qué hay en cada lugar","level":2},{"id":"darle-a-la-caja-de-herramientas-su-propia-ventana","text":"Darle a la caja de herramientas su propia ventana","level":2},{"id":"sus-paneles-siguen-siendo-suyos","text":"Sus paneles siguen siendo suyos","level":2},{"id":"volver-al-dise-o-cl-sico","text":"Volver al diseño clásico","level":2}],"html":"\u003Cp\u003E\u003Cstrong\u003ECaja de herramientas y cuadro de información\u003C/strong\u003E es uno de los tres diseños de espacio de trabajo de la aplicación. Las herramientas de dibujo están en una columna a la izquierda, un cuadro de información arriba muestra lo que pide la herramienta en curso o lo que tiene seleccionado, cada vista tiene su pestaña y una barra rápida debajo del dibujo reúne algunas opciones de uso diario. Las herramientas son las de la aplicación: todo lo que puede hacer en el diseño clásico funciona aquí también, y su dibujo, su estilo de menú y sus teclas siguen igual.\u003C/p\u003E\n\u003Ch2 id=\"elegirlo\"\u003EElegirlo\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EAbra \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E (el engrane, o \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E).\u003C/li\u003E\u003Cli\u003EElija la pestaña \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E y vaya a \u003Cspan class=\"hui\"\u003EDiseño\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EEspacio de trabajo\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EElija \u003Cspan class=\"hui\"\u003ECaja de herramientas y cuadro de información\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EEl diseño cambia de inmediato. La elección vale para todas las aplicaciones en este navegador: cada una abre con él desde entonces, y está listo antes de que se dibuje la página, así que nunca verá primero el diseño clásico.\u003C/p\u003E\n\u003Ch2 id=\"qu-hay-en-cada-lugar\"\u003EQué hay en cada lugar\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EBarra de herramientas:\u003C/strong\u003E la barra de herramientas de la aplicación sigue arriba del área de dibujo, con sus menús.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECuadro de información:\u003C/strong\u003E debajo de la barra de herramientas. Mientras una herramienta está en curso muestra la herramienta y lo que pide. Cuando elige algo muestra sus ajustes principales (para un muro: su tipo, espesor, longitud, línea de ubicación y altura), y puede cambiarlos ahí mismo: un cambio ahí es igual que en Propiedades, y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command Z\"\u003E⌘Z\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Z\u003C/span\u003E\u003C/kbd\u003E lo deshace. Si no hay nada elegido dice &quot;Nada seleccionado&quot;. Cada aplicación agrega aquí sus propios cuadros, como la capa o el nivel actual, o el documento abierto.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECaja de herramientas:\u003C/strong\u003E la columna de la izquierda, las herramientas de la aplicación en grupos. Haga clic en el nombre de un grupo para contraerlo o abrirlo de nuevo. La herramienta en curso aparece iluminada.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMis herramientas:\u003C/strong\u003E el primer grupo de la caja de herramientas, ocho espacios vacíos para las herramientas que más usa. Haga clic en un espacio vacío para elegir cualquier herramienta o comando de la aplicación; o haga clic derecho en una herramienta de la caja y elija \u003Cspan class=\"hui\"\u003EAgregar a Mis herramientas\u003C/span\u003E; o arrastre una herramienta a un espacio. Haga clic derecho en un espacio para cambiarlo o vaciarlo. Sus espacios se guardan para cada aplicación en este navegador.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ENavegador:\u003C/strong\u003E el panel derecho. Arriba está el explorador del proyecto de la aplicación (plantas, cortes, alzados, vistas 3D, tablas, hojas, según las tenga la aplicación): haga clic en una para abrirla. Debajo, \u003Cspan class=\"hui\"\u003EPropiedades\u003C/span\u003E y una pestaña con el resto del panel derecho.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPestañas de vista:\u003C/strong\u003E una pestaña por cada vista del archivo abierto (una hoja, una planta, una escena…), sobre el dibujo.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EBarra rápida:\u003C/strong\u003E debajo del dibujo, los ajustes de vista y las opciones de uso diario que tenga la aplicación, como la escala, el nivel de detalle, el rango de vista, ajustar, planta, dividida o 3D, referencias y unidades.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EPaleta de edición:\u003C/strong\u003E haga clic en algo del dibujo y aparece junto al puntero una pequeña paleta con los comandos de edición de la aplicación para eso, como mover, copiar, girar, reflejar, duplicar o eliminar, y \u003Cspan class=\"hui\"\u003EPropiedades\u003C/span\u003E. \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E, la rueda del ratón, otro clic o su botón de cerrar la quitan.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EUna herramienta que no puede usarse ahora aparece en gris, y su información emergente dice por qué. Haga clic en ella, o pulse \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Return\"\u003EReturn\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEnter\u003C/span\u003E\u003C/kbd\u003E sobre ella, para leer el motivo en un cuadro.\u003C/p\u003E\n\u003Cp\u003E\u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E termina primero la herramienta en curso, como en el diseño clásico, y todos los atajos y \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E (modos de pantalla) funcionan como antes.\u003C/p\u003E\n\u003Ch2 id=\"darle-a-la-caja-de-herramientas-su-propia-ventana\"\u003EDarle a la caja de herramientas su propia ventana\u003C/h2\u003E\n\u003Cp\u003EEl botón \u003Cspan class=\"hui\"\u003EMover la caja de herramientas\u003C/span\u003E, arriba de la caja de herramientas, tiene \u003Cspan class=\"hui\"\u003EMover a una ventana nueva\u003C/span\u003E: la caja de herramientas se abre en una ventana angosta propia que puede poner junto a la aplicación o en un segundo monitor. Las teclas que pulse ahí llegan a la aplicación. \u003Cspan class=\"hui\"\u003ERegresar la caja de herramientas\u003C/span\u003E, o cerrar esa ventana, la devuelve a su lugar.\u003C/p\u003E\n\u003Cp\u003ELa configuración de la barra de herramientas también se aplica a la caja de herramientas: \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EBarra de herramientas\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EIconos y etiquetas\u003C/span\u003E, \u003Cspan class=\"hui\"\u003ESolo iconos\u003C/span\u003E o \u003Cspan class=\"hui\"\u003ESolo etiquetas\u003C/span\u003E, y \u003Cspan class=\"hui\"\u003EMostrar nombres de grupo (Archivo, Dibujo, …)\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"sus-paneles-siguen-siendo-suyos\"\u003ESus paneles siguen siendo suyos\u003C/h2\u003E\n\u003Cp\u003ELos paneles izquierdo y derecho conservan todo lo que se describe en \u003Ca href=\"/tutorials/basics/arrange-panels\" data-topic=\"basics/arrange-panels\"\u003EOrganizar los paneles\u003C/a\u003E: acoplar, flotar, fijar, ocultar, pestañas, \u003Cspan class=\"hui\"\u003EMover a una ventana nueva\u003C/span\u003E y \u003Cspan class=\"hui\"\u003ERestablecer diseño\u003C/span\u003E.\u003C/p\u003E\n\u003Ch2 id=\"volver-al-dise-o-cl-sico\"\u003EVolver al diseño clásico\u003C/h2\u003E\n\u003Cp\u003EAbra \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EDiseño\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EEspacio de trabajo\u003C/span\u003E y elija \u003Cspan class=\"hui\"\u003ECadCraft clásico\u003C/span\u003E. Cada barra de herramientas, pestaña y panel vuelve a su lugar.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EEn un teléfono, o en una ventana de 760 píxeles de ancho o menos, la aplicación usa su diseño para teléfono sin importar lo que haya elegido. Una ventana más ancha devuelve su diseño.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Cp\u003EPara probar otra disposición, vea \u003Ca href=\"/tutorials/basics/layout-ribbon\" data-topic=\"basics/layout-ribbon\"\u003Eel diseño de cinta y navegador de proyecto\u003C/a\u003E.\u003C/p\u003E","text":"Caja de herramientas y cuadro de información es uno de los tres diseños de espacio de trabajo de la aplicación. Las herramientas de dibujo están en una columna a la izquierda, un cuadro de información arriba muestra lo que pide la herramienta en curso o lo que tiene seleccionado, cada vista tiene su pestaña y una barra rápida debajo del dibujo reúne algunas opciones de uso diario. Las herramientas son las de la aplicación: todo lo que puede hacer en el diseño clásico funciona aquí también, y su dibujo, su estilo de menú y sus teclas siguen igual. Elegirlo Abra Configuración (el engrane, o Ctrl+,). Elija la pestaña Global y vaya a Diseño › Espacio de trabajo. Elija Caja de herramientas y cuadro de información. El diseño cambia de inmediato. La elección vale para todas las aplicaciones en este navegador: cada una abre con él desde entonces, y está listo antes de que se dibuje la página, así que nunca verá primero el diseño clásico. Qué hay en cada lugar Barra de herramientas: la barra de herramientas de la aplicación sigue arriba del área de dibujo, con sus menús. Cuadro de información: debajo de la barra de herramientas. Mientras una herramienta está en curso muestra la herramienta y lo que pide. Cuando elige algo muestra sus ajustes principales (para un muro: su tipo, espesor, longitud, línea de ubicación y altura), y puede cambiarlos ahí mismo: un cambio ahí es igual que en Propiedades, y Ctrl+Z lo deshace. Si no hay nada elegido dice \"Nada seleccionado\". Cada aplicación agrega aquí sus propios cuadros, como la capa o el nivel actual, o el documento abierto. Caja de herramientas: la columna de la izquierda, las herramientas de la aplicación en grupos. Haga clic en el nombre de un grupo para contraerlo o abrirlo de nuevo. La herramienta en curso aparece iluminada. Mis herramientas: el primer grupo de la caja de herramientas, ocho espacios vacíos para las herramientas que más usa. Haga clic en un espacio vacío para elegir cualquier herramienta o comando de la aplicación; o haga clic derecho en una herramienta de la caja y elija Agregar a Mis herramientas; o arrastre una herramienta a un espacio. Haga clic derecho en un espacio para cambiarlo o vaciarlo. Sus espacios se guardan para cada aplicación en este navegador. Navegador: el panel derecho. Arriba está el explorador del proyecto de la aplicación (plantas, cortes, alzados, vistas 3D, tablas, hojas, según las tenga la aplicación): haga clic en una para abrirla. Debajo, Propiedades y una pestaña con el resto del panel derecho. Pestañas de vista: una pestaña por cada vista del archivo abierto (una hoja, una planta, una escena…), sobre el dibujo. Barra rápida: debajo del dibujo, los ajustes de vista y las opciones de uso diario que tenga la aplicación, como la escala, el nivel de detalle, el rango de vista, ajustar, planta, dividida o 3D, referencias y unidades. Paleta de edición: haga clic en algo del dibujo y aparece junto al puntero una pequeña paleta con los comandos de edición de la aplicación para eso, como mover, copiar, girar, reflejar, duplicar o eliminar, y Propiedades. Esc, la rueda del ratón, otro clic o su botón de cerrar la quitan. Una herramienta que no puede usarse ahora aparece en gris, y su información emergente dice por qué. Haga clic en ella, o pulse Enter sobre ella, para leer el motivo en un cuadro. Esc termina primero la herramienta en curso, como en el diseño clásico, y todos los atajos y Ctrl+Shift+F (modos de pantalla) funcionan como antes. Darle a la caja de herramientas su propia ventana El botón Mover la caja de herramientas, arriba de la caja de herramientas, tiene Mover a una ventana nueva: la caja de herramientas se abre en una ventana angosta propia que puede poner junto a la aplicación o en un segundo monitor. Las teclas que pulse ahí llegan a la aplicación. Regresar la caja de herramientas, o cerrar esa ventana, la devuelve a su lugar. La configuración de la barra de herramientas también se aplica a la caja de herramientas: Configuración › Global › Barra de herramientas › Iconos y etiquetas, Solo iconos o Solo etiquetas, y Mostrar nombres de grupo (Archivo, Dibujo, …). Sus paneles siguen siendo suyos Los paneles izquierdo y derecho conservan todo lo que se describe en Organizar los paneles: acoplar, flotar, fijar, ocultar, pestañas, Mover a una ventana nueva y Restablecer diseño. Volver al diseño clásico Abra Configuración › Global › Diseño › Espacio de trabajo y elija CadCraft clásico. Cada barra de herramientas, pestaña y panel vuelve a su lugar. En un teléfono, o en una ventana de 760 píxeles de ancho o menos, la aplicación usa su diseño para teléfono sin importar lo que haya elegido. Una ventana más ancha devuelve su diseño. Para probar otra disposición, vea el diseño de cinta y navegador de proyecto.","lang":"es-MX"},{"slug":"layout-own","scope":"basics","title":"Organizar su propio diseño y guardar sus configuraciones","summary":"Elija qué panel muestra el explorador del proyecto, Propiedades o el contenido propio del panel, dónde va la caja de herramientas y qué llevan las barras, guárdelo como su propio diseño, y guarde configuraciones completas con un nombre para cambiar entre ellas.","section":"start","order":39,"keywords":["diseño","espacio de trabajo","organizar","personalizar","mi diseño","diseño propio","paneles","editores","explorador del proyecto","propiedades","caja de herramientas","barra rápida","cuadro de información","entorno de trabajo","configuración","perfil","guardar configuración","cambiar de configuración","exportar configuración","importar configuración","ccenv"],"headings":[{"id":"organizar-su-propio-dise-o","text":"Organizar su propio diseño","level":2},{"id":"guardar-su-configuraci-n-como-entorno-de-trabajo","text":"Guardar su configuración como entorno de trabajo","level":2}],"html":"\u003Cp\u003EAdemás de los tres diseños incluidos, puede organizar uno propio y guardar toda su configuración con un nombre para volver a ella en un solo paso.\u003C/p\u003E\n\u003Ch2 id=\"organizar-su-propio-dise-o\"\u003EOrganizar su propio diseño\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EAbra \u003Cspan class=\"hui\"\u003EConfiguración\u003C/span\u003E (el engrane, o \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E), elija \u003Cspan class=\"hui\"\u003EGlobal\u003C/span\u003E y luego \u003Cspan class=\"hui\"\u003EDiseño\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EElija \u003Cspan class=\"hui\"\u003EOrganizar su propio diseño…\u003C/span\u003E. El cuadro parte del diseño que usa ahora.\u003C/li\u003E\u003Cli\u003EDele un nombre y elija:\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ESobre el dibujo:\u003C/strong\u003E la barra de herramientas de la aplicación, una cinta o ninguna; una barra de título; un cuadro de información y qué controles lleva.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EJunto al dibujo:\u003C/strong\u003E la caja de herramientas a la izquierda, a la derecha o sin ella, con o sin \u003Cspan class=\"hui\"\u003EMis herramientas\u003C/span\u003E; qué panel lleva las paletas, cuál va arriba (el explorador del proyecto o Propiedades, por ejemplo) y cuáles son pestañas debajo.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EEl área de dibujo:\u003C/strong\u003E pestañas de vista, una barra rápida y una barra de vista con los controles que marque, la paleta de edición, una barra de estado.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EAspecto:\u003C/strong\u003E tamaño, contorno de los botones y estilo de las pestañas.\u003C/li\u003E\u003C/ul\u003E\u003C/li\u003E\u003Cli\u003EElija \u003Cspan class=\"hui\"\u003EUsar este diseño\u003C/span\u003E. La aplicación cambia a él de inmediato, y todas las aplicaciones que tienen diseños también lo usan.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003ESolo se ofrece lo que tiene esta aplicación. Su diseño aparece en \u003Cspan class=\"hui\"\u003EDe complementos y archivos\u003C/span\u003E; \u003Cspan class=\"hui\"\u003EExportar este diseño\u003C/span\u003E lo guarda como un archivo que puede pasar a un colega, y el botón de quitar lo elimina. Los paneles que llena se siguen acoplando, flotando y pasando a su propia ventana, como en \u003Ca href=\"/tutorials/basics/arrange-panels\" data-topic=\"basics/arrange-panels\"\u003EOrganizar los paneles\u003C/a\u003E.\u003C/p\u003E\n\u003Ch2 id=\"guardar-su-configuraci-n-como-entorno-de-trabajo\"\u003EGuardar su configuración como entorno de trabajo\u003C/h2\u003E\n\u003Cp\u003EUn entorno de trabajo es toda su configuración para todas las aplicaciones en este navegador: el diseño, el estilo de menú y sus teclas, el estilo de la barra de herramientas, los paneles y sus tamaños, y \u003Cspan class=\"hui\"\u003EMis herramientas\u003C/span\u003E. El tema y el idioma no forman parte de él.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003EGuardar:\u003C/strong\u003E escriba un nombre en \u003Cspan class=\"hui\"\u003EEntornos de trabajo\u003C/span\u003E y elija \u003Cspan class=\"hui\"\u003EGuardar mi configuración\u003C/span\u003E. Guardar con un nombre que ya existe reemplaza esa configuración.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECambiar:\u003C/strong\u003E elija una configuración en la lista y luego \u003Cspan class=\"hui\"\u003ECambiar a esta\u003C/span\u003E. La aplicación se vuelve a cargar con esa configuración; si tiene trabajo sin guardar, la aplicación pregunta antes, como en cualquier recarga.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ECompartir:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EExportar\u003C/span\u003E guarda la configuración elegida como un archivo \u003Ccode\u003E.ccenv.json\u003C/code\u003E; \u003Cspan class=\"hui\"\u003EImportar una configuración…\u003C/span\u003E agrega una desde un archivo. Un archivo solo fija estas opciones, nada más.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EQuitar:\u003C/strong\u003E elija una configuración y luego \u003Cspan class=\"hui\"\u003EQuitar\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EPuede guardar hasta doce configuraciones.\u003C/p\u003E\n\u003Cp\u003EPara probar primero los diseños incluidos, vea \u003Ca href=\"/tutorials/basics/layout-toolbox\" data-topic=\"basics/layout-toolbox\"\u003Eel diseño de caja de herramientas y cuadro de información\u003C/a\u003E y \u003Ca href=\"/tutorials/basics/layout-ribbon\" data-topic=\"basics/layout-ribbon\"\u003Eel diseño de cinta y explorador del proyecto\u003C/a\u003E.\u003C/p\u003E","text":"Además de los tres diseños incluidos, puede organizar uno propio y guardar toda su configuración con un nombre para volver a ella en un solo paso. Organizar su propio diseño Abra Configuración (el engrane, o Ctrl+,), elija Global y luego Diseño. Elija Organizar su propio diseño…. El cuadro parte del diseño que usa ahora. Dele un nombre y elija: Sobre el dibujo: la barra de herramientas de la aplicación, una cinta o ninguna; una barra de título; un cuadro de información y qué controles lleva. Junto al dibujo: la caja de herramientas a la izquierda, a la derecha o sin ella, con o sin Mis herramientas; qué panel lleva las paletas, cuál va arriba (el explorador del proyecto o Propiedades, por ejemplo) y cuáles son pestañas debajo. El área de dibujo: pestañas de vista, una barra rápida y una barra de vista con los controles que marque, la paleta de edición, una barra de estado. Aspecto: tamaño, contorno de los botones y estilo de las pestañas. Elija Usar este diseño. La aplicación cambia a él de inmediato, y todas las aplicaciones que tienen diseños también lo usan. Solo se ofrece lo que tiene esta aplicación. Su diseño aparece en De complementos y archivos; Exportar este diseño lo guarda como un archivo que puede pasar a un colega, y el botón de quitar lo elimina. Los paneles que llena se siguen acoplando, flotando y pasando a su propia ventana, como en Organizar los paneles. Guardar su configuración como entorno de trabajo Un entorno de trabajo es toda su configuración para todas las aplicaciones en este navegador: el diseño, el estilo de menú y sus teclas, el estilo de la barra de herramientas, los paneles y sus tamaños, y Mis herramientas. El tema y el idioma no forman parte de él. Guardar: escriba un nombre en Entornos de trabajo y elija Guardar mi configuración. Guardar con un nombre que ya existe reemplaza esa configuración. Cambiar: elija una configuración en la lista y luego Cambiar a esta. La aplicación se vuelve a cargar con esa configuración; si tiene trabajo sin guardar, la aplicación pregunta antes, como en cualquier recarga. Compartir: Exportar guarda la configuración elegida como un archivo .ccenv.json; Importar una configuración… agrega una desde un archivo. Un archivo solo fija estas opciones, nada más. Quitar: elija una configuración y luego Quitar. Puede guardar hasta doce configuraciones. Para probar primero los diseños incluidos, vea el diseño de caja de herramientas y cuadro de información y el diseño de cinta y explorador del proyecto.","lang":"es-MX"},{"slug":"offline","scope":"basics","title":"Working offline","summary":"Save an app for offline use, what works with no connection, and what needs one.","section":"start","order":40,"keywords":["offline","no internet","airplane","site visit","cache","service worker","install","download","connection"],"headings":[{"id":"save-an-app-for-offline-use","text":"Save an app for offline use","level":2},{"id":"what-works-offline","text":"What works offline","level":2},{"id":"what-needs-a-connection","text":"What needs a connection","level":2},{"id":"things-to-know","text":"Things to know","level":2}],"html":"\u003Cp\u003EThe apps do their work on your computer, so most of it works with no connection. The browser only needs to have the app&#039;s files saved first.\u003C/p\u003E\n\u003Ch2 id=\"save-an-app-for-offline-use\"\u003ESave an app for offline use\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the app while you are online.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E in the bar at the top.\u003C/li\u003E\u003Cli\u003EWait for &quot;Offline ready&quot;. The app&#039;s files, its file readers and this help are now saved in your browser. Apps that read DWG or PDF files save their readers too, so this can take a minute the first time.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EDo this once per app, in each browser you use. To go back to the app later with no connection, open the same address you used before, or a bookmark of it.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"net:offline\"\u003E\u003Cp class=\"hv-label\"\u003EOffline\u003C/p\u003E\n\u003Cp\u003EYou are offline now. If this app was saved for offline use, everything below works. If it was not, you can still use what has already loaded in this tab, but don&#039;t reload it until you are online again.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"what-works-offline\"\u003EWhat works offline\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EOpening files from your computer, drawing, editing, measuring and checking.\u003C/li\u003E\u003Cli\u003ESaving and exporting: every save is a download to your computer.\u003C/li\u003E\u003Cli\u003EThis help, including search.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"what-needs-a-connection\"\u003EWhat needs a connection\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EOpening the app for the first time, and saving it for offline use.\u003C/li\u003E\u003Cli\u003EGetting a newer version of the app. When you are online, the app picks up the newest version the next time it opens, and \u003Cspan class=\"hui\"\u003ESave for offline\u003C/span\u003E refreshes the saved copy.\u003C/li\u003E\u003Cli\u003ELinks to the website, such as \u003Cspan class=\"hui\"\u003EOpen on the website\u003C/span\u003E and links to other pages.\u003C/li\u003E\u003Cli\u003ECloud saving and sync between computers, which are not available yet.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"things-to-know\"\u003EThings to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EA saved copy belongs to one browser on one computer. Clearing your browser&#039;s site data removes it.\u003C/li\u003E\u003Cli\u003EPrivate windows in some browsers, and some locked-down work computers, do not allow offline saving. The button tells you when it cannot save.\u003C/li\u003E\u003C/ul\u003E\n\u003Cdiv class=\"hv\" data-v=\"browser:safari\"\u003E\u003Cp class=\"hv-label\"\u003ESafari\u003C/p\u003E\n\u003Cp\u003ESafari removes saved site data from sites you have not visited for several weeks. Open the app now and then while online, or save it again before a trip.\u003C/p\u003E\n\u003C/div\u003E\n\u003Cul\u003E\u003Cli\u003ECadCraft Studio, the desktop app with all eight apps in one install, is on getcadcraft.com/download.\u003C/li\u003E\u003C/ul\u003E","text":"The apps do their work on your computer, so most of it works with no connection. The browser only needs to have the app's files saved first. Save an app for offline use Open the app while you are online. Choose Save for offline in the bar at the top. Wait for \"Offline ready\". The app's files, its file readers and this help are now saved in your browser. Apps that read DWG or PDF files save their readers too, so this can take a minute the first time. Do this once per app, in each browser you use. To go back to the app later with no connection, open the same address you used before, or a bookmark of it. You are offline now. If this app was saved for offline use, everything below works. If it was not, you can still use what has already loaded in this tab, but don't reload it until you are online again. What works offline Opening files from your computer, drawing, editing, measuring and checking. Saving and exporting: every save is a download to your computer. This help, including search. What needs a connection Opening the app for the first time, and saving it for offline use. Getting a newer version of the app. When you are online, the app picks up the newest version the next time it opens, and Save for offline refreshes the saved copy. Links to the website, such as Open on the website and links to other pages. Cloud saving and sync between computers, which are not available yet. Things to know A saved copy belongs to one browser on one computer. Clearing your browser's site data removes it. Private windows in some browsers, and some locked-down work computers, do not allow offline saving. The button tells you when it cannot save. Safari removes saved site data from sites you have not visited for several weeks. Open the app now and then while online, or save it again before a trip. CadCraft Studio, the desktop app with all eight apps in one install, is on getcadcraft.com/download.","lang":"en"},{"slug":"your-files","scope":"basics","title":"Where your files go","summary":"Files stay on your computer, how saving works, and what the browser remembers.","section":"start","order":50,"keywords":["privacy","upload","cloud","save","download","storage","local","security","confidential"],"headings":[{"id":"your-files-stay-on-your-computer","text":"Your files stay on your computer","level":2},{"id":"how-saving-works","text":"How saving works","level":2},{"id":"what-the-browser-remembers","text":"What the browser remembers","level":2},{"id":"cloud-saving","text":"Cloud saving","level":2}],"html":"\u003Ch2 id=\"your-files-stay-on-your-computer\"\u003EYour files stay on your computer\u003C/h2\u003E\n\u003Cp\u003EWhen you open a drawing, model or PDF, the app reads it inside your browser. \u003Cstrong\u003EThe file is not uploaded.\u003C/strong\u003E We never see it, and it works the same with no connection.\u003C/p\u003E\n\u003Ch2 id=\"how-saving-works\"\u003EHow saving works\u003C/h2\u003E\n\u003Cp\u003EA browser page cannot overwrite files on your computer by itself, so the apps save by \u003Cstrong\u003Edownloading\u003C/strong\u003E a new file:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EThe download goes where your browser puts downloads, usually your Downloads folder, unless you have set the browser to ask each time (see \u003Ca href=\"/tutorials/basics/browsers#what-differs-between-browsers\" data-topic=\"basics/browsers\" data-hash=\"what-differs-between-browsers\"\u003EBrowsers and computers\u003C/a\u003E).\u003C/li\u003E\u003Cli\u003EApps that change a file save a copy with a new name, such as &quot;(edited)&quot; or &quot;(marked up)&quot;, so your original stays untouched.\u003C/li\u003E\u003Cli\u003EIf you close the tab with unsaved work, the browser asks first (&quot;Leave site?&quot;).\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"what-the-browser-remembers\"\u003EWhat the browser remembers\u003C/h2\u003E\n\u003Cp\u003ESome apps remember small settings in your browser, such as your author name or tool styles. They stay in that browser on that computer, and clearing site data removes them. Each app&#039;s help says what it keeps.\u003C/p\u003E\n\u003Ch2 id=\"cloud-saving\"\u003ECloud saving\u003C/h2\u003E\n\u003Cp\u003ECloud saving and sync between computers are part of the commercial license. They are not available yet. Until then, keep your files where you keep your other project files and back them up the usual way.\u003C/p\u003E","text":"Your files stay on your computer When you open a drawing, model or PDF, the app reads it inside your browser. The file is not uploaded. We never see it, and it works the same with no connection. How saving works A browser page cannot overwrite files on your computer by itself, so the apps save by downloading a new file: The download goes where your browser puts downloads, usually your Downloads folder, unless you have set the browser to ask each time (see Browsers and computers). Apps that change a file save a copy with a new name, such as \"(edited)\" or \"(marked up)\", so your original stays untouched. If you close the tab with unsaved work, the browser asks first (\"Leave site?\"). What the browser remembers Some apps remember small settings in your browser, such as your author name or tool styles. They stay in that browser on that computer, and clearing site data removes them. Each app's help says what it keeps. Cloud saving Cloud saving and sync between computers are part of the commercial license. They are not available yet. Until then, keep your files where you keep your other project files and back them up the usual way.","lang":"en"},{"slug":"assistants-recipes","scope":"basics","title":"Recipes for AI assistants","summary":"Worked examples for using your own AI assistant with the CadCraft apps: what to ask, the tools it calls, and the permissions each needs. Every recipe here is run by our tests with the same calls.","section":"tasks","order":62,"keywords":["ai","assistant","mcp","recipes","examples","prompts","automation","batch","convert","plot","check","takeoff","cut","fill","parameters","script"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"recipes","text":"Recipes","level":2},{"id":"tidy-a-drawing","text":"Tidy a drawing","level":3},{"id":"plot-a-set-of-sheets","text":"Plot a set of sheets","level":3},{"id":"convert-drawings-for-a-consultant","text":"Convert drawings for a consultant","level":3},{"id":"check-drawings-before-sending-them","text":"Check drawings before sending them","level":3},{"id":"ask-a-building-model-questions","text":"Ask a building model questions","level":3},{"id":"draw-a-room-in-bimcraft","text":"Draw a room in BimCraft","level":3},{"id":"total-a-takeoff","text":"Total a takeoff","level":3},{"id":"site-numbers","text":"Site numbers","level":3},{"id":"try-a-part-variant","text":"Try a part variant","level":3},{"id":"fill-in-a-title-block","text":"Fill in a title block","level":3},{"id":"your-files-and-your-assistant","text":"Your files and your assistant","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EReady-made requests for your own AI assistant, and what it does with them. The apps contain no AI: your assistant reads the files and calls the apps&#039; tools, and you decide which permissions it has. Each recipe names the tools it calls, so you can check its work in the activity log, and each one is run by our tests with exactly these calls, so they keep working.\u003C/p\u003E\n\u003Cp\u003EThere are two ways in. In \u003Cstrong\u003ECadCraft Studio\u003C/strong\u003E, an assistant works with the apps you have open (Settings › Assistants in each app). \u003Cstrong\u003EWithout a window\u003C/strong\u003E, the CadCraft file server for assistants (\u003Ccode\u003Enpx @getcadcraft/mcp --root &lt;folder&gt;\u003C/code\u003E) works on files in folders you name; the \u003Ccode\u003Ecadcraft\u003C/code\u003E command line does the same jobs for your own scripts. The recipes say which way they use; most work both ways.\u003C/p\u003E\n\u003Caside class=\"hc hc-tip\"\u003E\u003Cp class=\"hc-label\"\u003ETip\u003C/p\u003E\n\u003Cp\u003EStart read-only. Ask the assistant to describe a file before it changes anything; its answers are better when it has looked first, and Read is the only permission that is on to begin with.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"recipes\"\u003ERecipes\u003C/h2\u003E\n\u003Ch3 id=\"tidy-a-drawing\"\u003ETidy a drawing\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;List the layers with nothing on them and the blocks nobody uses, then purge the unused blocks.&quot;\u003C/p\u003E\n\u003Cp\u003EThe assistant opens the drawing and reads it, then runs PURGE:\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Edrawing_open {path: &quot;Kitchen/kitchen-equipment.dwg&quot;}            → d1\ndrawing_describe {doc: &quot;d1&quot;}                                    layers with 0 objects, blocks with 0 uses\ncommand_run {doc: &quot;d1&quot;, input: &quot;PURGE&quot;}                         one undo step: &quot;Assistant: PURGE&quot;\ndrawing_save {doc: &quot;d1&quot;, path: &quot;Kitchen/kitchen-tidy.dwg&quot;}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read and Edit, and Save to write the result. Dimension arrowheads count as used, so they stay.\u003C/p\u003E\n\u003Ch3 id=\"plot-a-set-of-sheets\"\u003EPlot a set of sheets\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Plot every sheet of every drawing in the Kitchen folder to PDF.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Efiles_list {folder: &quot;Kitchen&quot;, extensions: [&quot;dwg&quot;, &quot;dxf&quot;]}\ndrawing_open {path: …}  ·  drawing_describe {doc}                the sheets of each drawing\ndrawing_plot {doc, layout: &quot;&lt;sheet&gt;&quot;, out: &quot;Plots/&lt;drawing&gt; &lt;sheet&gt;.pdf&quot;}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read and Export. From the command line, one PDF per drawing with all its sheets: \u003Ccode\u003Ecadcraft plot Kitchen/*.dwg Plots --all\u003C/code\u003E.\u003C/p\u003E\n\u003Ch3 id=\"convert-drawings-for-a-consultant\"\u003EConvert drawings for a consultant\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Save copies of the drawings in Kitchen as AutoCAD 2013 DWG in the Out folder.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Efiles_list {folder: &quot;Kitchen&quot;, extensions: [&quot;dwg&quot;, &quot;dxf&quot;]}\ndrawing_convert {path: &quot;Kitchen/&lt;file&gt;&quot;, out: &quot;Out/&lt;file&gt;.dwg&quot;, version: &quot;2013&quot;}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read and Export; the originals are not changed. From the command line: \u003Ccode\u003Ecadcraft convert Kitchen/*.dwg Kitchen/*.dxf Out --to dwg --version 2013\u003C/code\u003E.\u003C/p\u003E\n\u003Ch3 id=\"check-drawings-before-sending-them\"\u003ECheck drawings before sending them\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Check the drawings in Kitchen: nothing on layer 0, colours by layer, no unused blocks. Give me a table of what fails.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Edrawing_check {doc, rules: {layers: {noObjectsOn: [&quot;0&quot;]}, objects: {colorByLayer: true}, blocks: {noUnused: true}}}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read. Keep your office&#039;s rules in a file and the command line checks a whole folder: \u003Ccode\u003Ecadcraft check Kitchen/*.dwg --rules office-standards.json\u003C/code\u003E (exit code 1 when something fails, so it fits in a script).\u003C/p\u003E\n\u003Ch3 id=\"ask-a-building-model-questions\"\u003EAsk a building model questions\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;How many doors does the house have on each level, and which are external?&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Eifc_open {path: &quot;house.ifc&quot;}                                    → d1\nifc_query {doc: &quot;d1&quot;, class: &quot;IfcDoor&quot;}                         each door with its level\nifc_properties {doc: &quot;d1&quot;, id: &lt;door&gt;}                          Pset_DoorCommon.IsExternal\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read. In Studio, BimCraft&#039;s own tools answer the same about the model you have open.\u003C/p\u003E\n\u003Ch3 id=\"draw-a-room-in-bimcraft\"\u003EDraw a room in BimCraft\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Draw a 6 by 4 metre room on Level 1 with a single door in the south wall.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Ewalls_add {points: [[0, 0], [6000, 0], [6000, 4000], [0, 4000]], closed: true}     one undo step\nopening_add {wall: &quot;&lt;the first wall&#039;s GlobalId&gt;&quot;, kind: &quot;door&quot;}                    one undo step\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Edit. Walls join and the room follows, as with the Draw tools. Without a window, \u003Ccode\u003Eifc_new\u003C/code\u003E starts a building first and \u003Ccode\u003Eifc_save\u003C/code\u003E writes it.\u003C/p\u003E\n\u003Ch3 id=\"total-a-takeoff\"\u003ETotal a takeoff\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Give me the estimate by item and export it to XLSX.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Etakeoff_open {path: &quot;job.takeoff.json&quot;}  ·  takeoff_estimate {doc}  ·  takeoff_export {doc, out: &quot;job.xlsx&quot;}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read, and Export for the file. Marks on sheets with no scale are listed and never counted as zero, so an incomplete estimate says so.\u003C/p\u003E\n\u003Ch3 id=\"site-numbers\"\u003ESite numbers\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;How much cut and fill does the pad need?&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Esite_open {path: &quot;site.civilcraft.json&quot;}  ·  surface_volume {doc}       cut, fill and net, per pad\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read. With a level instead of a design: \u003Ccode\u003Esurface_volume {doc, datum: 100}\u003C/code\u003E.\u003C/p\u003E\n\u003Ch3 id=\"try-a-part-variant\"\u003ETry a part variant\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Set the length to 40 mm, rebuild, and give me the mass.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Epart_open {path: &quot;screw.partcraft.json&quot;}  ·  params_list {doc}\nparam_set {doc, name: &quot;l&quot;, value: 40}                           one undo step, the part rebuilt\nmass_properties {doc}                                            volume, mass from the material, centre, inertia\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Read and Edit; Save (\u003Ccode\u003Epart_save\u003C/code\u003E) to keep it.\u003C/p\u003E\n\u003Ch3 id=\"fill-in-a-title-block\"\u003EFill in a title block\u003C/h3\u003E\n\u003Cp\u003E\u003Cstrong\u003EAsk:\u003C/strong\u003E &quot;Insert the title block at 0,0 with sheet number A-101 and the title Kitchen plan.&quot;\u003C/p\u003E\n\u003Cpre class=\"hcode\"\u003E\u003Ccode\u003Eblock_insert {doc, block: &quot;TITLEBLOCK-ARCHD&quot;, at: [0, 0], attributes: {&quot;SHEET-NO&quot;: &quot;A-101&quot;, &quot;SHEET-TITLE&quot;: &quot;Kitchen plan&quot;}}\u003C/code\u003E\u003C/pre\u003E\n\u003Cp\u003ENeeds Edit. One undo step; the attributes it does not name keep their defaults.\u003C/p\u003E\n\u003Ch2 id=\"your-files-and-your-assistant\"\u003EYour files and your assistant\u003C/h2\u003E\n\u003Cp\u003EThe apps never send your files anywhere. \u003Cstrong\u003EBut what your assistant reads goes to whoever runs that assistant:\u003C/strong\u003E a cloud assistant&#039;s maker sees the parts of the drawing it is shown. If that matters for a job, use an assistant that runs on your own computer, or keep that job&#039;s folders out of the ones you allow.\u003C/p\u003E","text":"What you will learn Ready-made requests for your own AI assistant, and what it does with them. The apps contain no AI: your assistant reads the files and calls the apps' tools, and you decide which permissions it has. Each recipe names the tools it calls, so you can check its work in the activity log, and each one is run by our tests with exactly these calls, so they keep working. There are two ways in. In CadCraft Studio, an assistant works with the apps you have open (Settings › Assistants in each app). Without a window, the CadCraft file server for assistants (npx @getcadcraft/mcp --root \u003Cfolder\u003E) works on files in folders you name; the cadcraft command line does the same jobs for your own scripts. The recipes say which way they use; most work both ways. Start read-only. Ask the assistant to describe a file before it changes anything; its answers are better when it has looked first, and Read is the only permission that is on to begin with. Recipes Tidy a drawing Ask: \"List the layers with nothing on them and the blocks nobody uses, then purge the unused blocks.\" The assistant opens the drawing and reads it, then runs PURGE: drawing_open {path: \"Kitchen/kitchen-equipment.dwg\"} → d1 drawing_describe {doc: \"d1\"} layers with 0 objects, blocks with 0 uses command_run {doc: \"d1\", input: \"PURGE\"} one undo step: \"Assistant: PURGE\" drawing_save {doc: \"d1\", path: \"Kitchen/kitchen-tidy.dwg\"} Needs Read and Edit, and Save to write the result. Dimension arrowheads count as used, so they stay. Plot a set of sheets Ask: \"Plot every sheet of every drawing in the Kitchen folder to PDF.\" files_list {folder: \"Kitchen\", extensions: [\"dwg\", \"dxf\"]} drawing_open {path: …} · drawing_describe {doc} the sheets of each drawing drawing_plot {doc, layout: \"\u003Csheet\u003E\", out: \"Plots/\u003Cdrawing\u003E \u003Csheet\u003E.pdf\"} Needs Read and Export. From the command line, one PDF per drawing with all its sheets: cadcraft plot Kitchen/*.dwg Plots --all. Convert drawings for a consultant Ask: \"Save copies of the drawings in Kitchen as AutoCAD 2013 DWG in the Out folder.\" files_list {folder: \"Kitchen\", extensions: [\"dwg\", \"dxf\"]} drawing_convert {path: \"Kitchen/\u003Cfile\u003E\", out: \"Out/\u003Cfile\u003E.dwg\", version: \"2013\"} Needs Read and Export; the originals are not changed. From the command line: cadcraft convert Kitchen/*.dwg Kitchen/*.dxf Out --to dwg --version 2013. Check drawings before sending them Ask: \"Check the drawings in Kitchen: nothing on layer 0, colours by layer, no unused blocks. Give me a table of what fails.\" drawing_check {doc, rules: {layers: {noObjectsOn: [\"0\"]}, objects: {colorByLayer: true}, blocks: {noUnused: true}}} Needs Read. Keep your office's rules in a file and the command line checks a whole folder: cadcraft check Kitchen/*.dwg --rules office-standards.json (exit code 1 when something fails, so it fits in a script). Ask a building model questions Ask: \"How many doors does the house have on each level, and which are external?\" ifc_open {path: \"house.ifc\"} → d1 ifc_query {doc: \"d1\", class: \"IfcDoor\"} each door with its level ifc_properties {doc: \"d1\", id: \u003Cdoor\u003E} Pset_DoorCommon.IsExternal Needs Read. In Studio, BimCraft's own tools answer the same about the model you have open. Draw a room in BimCraft Ask: \"Draw a 6 by 4 metre room on Level 1 with a single door in the south wall.\" walls_add {points: [[0, 0], [6000, 0], [6000, 4000], [0, 4000]], closed: true} one undo step opening_add {wall: \"\u003Cthe first wall's GlobalId\u003E\", kind: \"door\"} one undo step Needs Edit. Walls join and the room follows, as with the Draw tools. Without a window, ifc_new starts a building first and ifc_save writes it. Total a takeoff Ask: \"Give me the estimate by item and export it to XLSX.\" takeoff_open {path: \"job.takeoff.json\"} · takeoff_estimate {doc} · takeoff_export {doc, out: \"job.xlsx\"} Needs Read, and Export for the file. Marks on sheets with no scale are listed and never counted as zero, so an incomplete estimate says so. Site numbers Ask: \"How much cut and fill does the pad need?\" site_open {path: \"site.civilcraft.json\"} · surface_volume {doc} cut, fill and net, per pad Needs Read. With a level instead of a design: surface_volume {doc, datum: 100}. Try a part variant Ask: \"Set the length to 40 mm, rebuild, and give me the mass.\" part_open {path: \"screw.partcraft.json\"} · params_list {doc} param_set {doc, name: \"l\", value: 40} one undo step, the part rebuilt mass_properties {doc} volume, mass from the material, centre, inertia Needs Read and Edit; Save (part_save) to keep it. Fill in a title block Ask: \"Insert the title block at 0,0 with sheet number A-101 and the title Kitchen plan.\" block_insert {doc, block: \"TITLEBLOCK-ARCHD\", at: [0, 0], attributes: {\"SHEET-NO\": \"A-101\", \"SHEET-TITLE\": \"Kitchen plan\"}} Needs Edit. One undo step; the attributes it does not name keep their defaults. Your files and your assistant The apps never send your files anywhere. But what your assistant reads goes to whoever runs that assistant: a cloud assistant's maker sees the parts of the drawing it is shown. If that matters for a job, use an assistant that runs on your own computer, or keep that job's folders out of the ones you allow.","lang":"en"},{"slug":"work-together-live","scope":"basics","title":"Work together live","summary":"Share the file open in an app so teammates edit it with you on your own network with a short code, and join someone else's session. Invite links over the internet are not open yet.","section":"tasks","order":90,"keywords":["live","studio live","work together","collaborate","share live","join","code","qr","invite link","link","host","approve","guest","network","relay","license","many people","limit","allow anyway","slow","recent edits","edit log","who changed","history"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"share-the-file-you-have-open","text":"Share the file you have open","level":2},{"id":"let-people-in","text":"Let people in","level":2},{"id":"when-many-people-join","text":"When many people join","level":2},{"id":"codes-on-your-own-network","text":"Codes on your own network","level":2},{"id":"invite-links-over-the-internet-not-open-yet","text":"Invite links over the internet: not open yet","level":2},{"id":"join-someone-else-s-session","text":"Join someone else's session","level":2},{"id":"who-changed-what-recent-edits","text":"Who changed what: Recent edits","level":2},{"id":"assistants-in-a-session","text":"Assistants in a session","level":2},{"id":"when-the-session-ends","text":"When the session ends","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EHow to share a file live from CadCraft Studio, let people in, and join a session someone else shares. What you see in the drawing itself while you work together is on the app&#039;s own page about live sessions.\u003C/p\u003E\n\u003Ch2 id=\"share-the-file-you-have-open\"\u003EShare the file you have open\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the file in its app inside CadCraft Studio on a computer.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ELive\u003C/span\u003E in the app&#039;s bar, type the name others should see, then choose \u003Cspan class=\"hui\"\u003EShare live\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EStudio shows a code like \u003Ccode\u003EK7-Q4M2X\u003C/code\u003E with a picture to scan and the computer&#039;s address. Give the code to the people you want to invite.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EYour file stays on your computer. Only you save it, and everyone sees your saves.\u003C/p\u003E\n\u003Ch2 id=\"let-people-in\"\u003ELet people in\u003C/h2\u003E\n\u003Cp\u003ENobody gets in without you. When someone knocks, a card shows their name and device and whether they came on this network or through the internet:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E lets them change the file with you.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EView only\u003C/span\u003E lets them watch; anything they try to change is taken back.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EDeny\u003C/span\u003E turns them away.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe list under \u003Cspan class=\"hui\"\u003EIn the session\u003C/span\u003E shows everyone. Change a person&#039;s role there, or \u003Cspan class=\"hui\"\u003ERemove\u003C/span\u003E them: they keep a copy of what they had, and they can&#039;t come back without a new invitation.\u003C/p\u003E\n\u003Ch2 id=\"when-many-people-join\"\u003EWhen many people join\u003C/h2\u003E\n\u003Cp\u003EA session&#039;s usual size is up to 20 people besides you. It is not a hard limit: how many people can work well together depends on their computers, the file and the network, so Studio asks you before a session grows past it instead of deciding for you.\u003C/p\u003E\n\u003Cp\u003EWhen someone knocks and would make more than 20, their card says so, and Studio explains what to expect: every change goes to everyone, so with many people each change takes longer to reach each person, and slower laptops and connections fall behind first. Then you choose:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EAllow anyway\u003C/span\u003E lets more people in for this session. Each person still waits for your \u003Cspan class=\"hui\"\u003EEdit\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EView only\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EDeny\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EKeep it at 20\u003C/span\u003E turns away the people waiting over the limit; they are told you are keeping the session small.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ETo allow more before anyone knocks, choose \u003Cspan class=\"hui\"\u003EAllow more people…\u003C/span\u003E under \u003Cspan class=\"hui\"\u003EIn the session\u003C/span\u003E. \u003Cspan class=\"hui\"\u003EBack to 20\u003C/span\u003E puts the usual size back. Your choice lasts for this session only; the next one starts at 20 again.\u003C/p\u003E\n\u003Cp\u003EIf things slow down, fewer people, a quieter file (fewer people changing it at the same moment) or a better connection (a cable instead of Wi-Fi) helps.\u003C/p\u003E\n\u003Ch2 id=\"codes-on-your-own-network\"\u003ECodes on your own network\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EA code works for 10 minutes. \u003Cspan class=\"hui\"\u003ENew code\u003C/span\u003E makes another; \u003Cspan class=\"hui\"\u003EStop inviting\u003C/span\u003E closes it. People already in stay.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EOne-time code\u003C/span\u003E lets one person in per code.\u003C/li\u003E\u003Cli\u003EAfter 3 wrong codes in a row, Studio closes the code and makes a new one, and tells you.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003ESessions on your own network are free, for everyone.\u003C/p\u003E\n\u003Ch2 id=\"invite-links-over-the-internet-not-open-yet\"\u003EInvite links over the internet: not open yet\u003C/h2\u003E\n\u003Cp\u003EInvite links aren&#039;t open yet. Sessions on your own network are free. Today the \u003Cspan class=\"hui\"\u003EOver the internet\u003C/span\u003E part of the \u003Cspan class=\"hui\"\u003ELive\u003C/span\u003E panel says so in a plain sentence instead of offering a link.\u003C/p\u003E\n\u003Cp\u003EWhen invite links open, this is how they will work:\u003C/p\u003E\n\u003Col\u003E\u003Cli\u003EUnder \u003Cspan class=\"hui\"\u003EOver the internet\u003C/span\u003E, choose how long the link works (1 hour, 8 hours, or until you end the session), then \u003Cspan class=\"hui\"\u003EInvite by link\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003ECopy the link and send it like a meeting link.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EThe link&#039;s secret part (after \u003Ccode\u003E#\u003C/code\u003E) never reaches getcadcraft.com: the site only passes on encrypted messages it can&#039;t read, and you still approve each person. \u003Cspan class=\"hui\"\u003ENew link\u003C/span\u003E makes the old one stop working at once; \u003Cspan class=\"hui\"\u003EStop the link\u003C/span\u003E ends it.\u003C/p\u003E\n\u003Cp\u003EMaking an invite link will need you signed in, with a commercial license in force for the app. Guests will need nothing: no account, no license.\u003C/p\u003E\n\u003Ch2 id=\"join-someone-else-s-session\"\u003EJoin someone else&#039;s session\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EIn CadCraft Studio&#039;s home screen, find \u003Cspan class=\"hui\"\u003EJoin a live session\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003EType the code the host gave you, or type the address shown under their code followed by the code. (Once invite links open, you will paste the host&#039;s link here too.)\u003C/li\u003E\u003Cli\u003EType your name and choose \u003Cspan class=\"hui\"\u003EJoin\u003C/span\u003E. Studio opens the right app; it fills with the host&#039;s file once the host lets you in.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EWithout Studio, scan the picture under the host&#039;s code with a device on the same network: the app opens in the browser.\u003C/p\u003E\n\u003Cp\u003EIn CadCraft, if you already have the same file open in a Studio window, you can join from that window instead: choose \u003Cspan class=\"hui\"\u003ELive\u003C/span\u003E, then under \u003Cspan class=\"hui\"\u003EJoin with the drawing open here\u003C/span\u003E type the code or the address and code, and choose \u003Cspan class=\"hui\"\u003EJoin here\u003C/span\u003E. Only the changes made since the file was opened travel. If the host&#039;s drawing is a different one, it replaces the one in that window; your file on disk stays as it is.\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EGuest, hotel and school Wi-Fi often keep devices apart, so a code can&#039;t find the host there. Use a network that lets devices see each other, such as the office network. Invite links, for when you are not on the same network, are not open yet.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"who-changed-what-recent-edits\"\u003EWho changed what: Recent edits\u003C/h2\u003E\n\u003Cp\u003EThe Live panel lists \u003Cstrong\u003ERecent edits\u003C/strong\u003E: who made each change and what it was (the step&#039;s name, such as Line or Move), newest first, with how long ago. \u003Cspan class=\"hui\"\u003EShow more\u003C/span\u003E lists more of them. With something selected in CadCraft or MarkupCraft, the panel also says who changed it last, and \u003Cspan class=\"hui\"\u003EOnly what is selected\u003C/span\u003E keeps just the edits that touched it.\u003C/p\u003E\n\u003Cp\u003EThe list is made in your own window from the session&#039;s edits while the session runs. It is gone when the session ends: it is never saved in the file or sent anywhere. Everyone in the session can see who made each change. If you joined after people had started, or were away for a while, the edits from before are not in your list, and the panel says so.\u003C/p\u003E\n\u003Ch2 id=\"assistants-in-a-session\"\u003EAssistants in a session\u003C/h2\u003E\n\u003Cp\u003EIf someone turned on assistants in their app&#039;s settings, their AI assistant can ask to work in the session too. The host&#039;s own assistant joins at once; anyone else&#039;s waits for the host, with a card saying whose assistant it is: \u003Cspan class=\"hui\"\u003EAllow\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EDeny\u003C/span\u003E. An assistant edits like its person, with its own undo, and leaves the session when its person leaves.\u003C/p\u003E\n\u003Ch2 id=\"when-the-session-ends\"\u003EWhen the session ends\u003C/h2\u003E\n\u003Cp\u003EThe host chooses \u003Cspan class=\"hui\"\u003EEnd the session\u003C/span\u003E, or closes the file. Everyone else keeps an unsaved copy of the file as it was: save it if you want to keep it. \u003Cspan class=\"hui\"\u003ELeave\u003C/span\u003E does the same for you alone.\u003C/p\u003E","text":"What you will learn How to share a file live from CadCraft Studio, let people in, and join a session someone else shares. What you see in the drawing itself while you work together is on the app's own page about live sessions. Share the file you have open Open the file in its app inside CadCraft Studio on a computer. Choose Live in the app's bar, type the name others should see, then choose Share live. Studio shows a code like K7-Q4M2X with a picture to scan and the computer's address. Give the code to the people you want to invite. Your file stays on your computer. Only you save it, and everyone sees your saves. Let people in Nobody gets in without you. When someone knocks, a card shows their name and device and whether they came on this network or through the internet: Edit lets them change the file with you. View only lets them watch; anything they try to change is taken back. Deny turns them away. The list under In the session shows everyone. Change a person's role there, or Remove them: they keep a copy of what they had, and they can't come back without a new invitation. When many people join A session's usual size is up to 20 people besides you. It is not a hard limit: how many people can work well together depends on their computers, the file and the network, so Studio asks you before a session grows past it instead of deciding for you. When someone knocks and would make more than 20, their card says so, and Studio explains what to expect: every change goes to everyone, so with many people each change takes longer to reach each person, and slower laptops and connections fall behind first. Then you choose: Allow anyway lets more people in for this session. Each person still waits for your Edit, View only or Deny. Keep it at 20 turns away the people waiting over the limit; they are told you are keeping the session small. To allow more before anyone knocks, choose Allow more people… under In the session. Back to 20 puts the usual size back. Your choice lasts for this session only; the next one starts at 20 again. If things slow down, fewer people, a quieter file (fewer people changing it at the same moment) or a better connection (a cable instead of Wi-Fi) helps. Codes on your own network A code works for 10 minutes. New code makes another; Stop inviting closes it. People already in stay. One-time code lets one person in per code. After 3 wrong codes in a row, Studio closes the code and makes a new one, and tells you. Sessions on your own network are free, for everyone. Invite links over the internet: not open yet Invite links aren't open yet. Sessions on your own network are free. Today the Over the internet part of the Live panel says so in a plain sentence instead of offering a link. When invite links open, this is how they will work: Under Over the internet, choose how long the link works (1 hour, 8 hours, or until you end the session), then Invite by link. Copy the link and send it like a meeting link. The link's secret part (after #) never reaches getcadcraft.com: the site only passes on encrypted messages it can't read, and you still approve each person. New link makes the old one stop working at once; Stop the link ends it. Making an invite link will need you signed in, with a commercial license in force for the app. Guests will need nothing: no account, no license. Join someone else's session In CadCraft Studio's home screen, find Join a live session. Type the code the host gave you, or type the address shown under their code followed by the code. (Once invite links open, you will paste the host's link here too.) Type your name and choose Join. Studio opens the right app; it fills with the host's file once the host lets you in. Without Studio, scan the picture under the host's code with a device on the same network: the app opens in the browser. In CadCraft, if you already have the same file open in a Studio window, you can join from that window instead: choose Live, then under Join with the drawing open here type the code or the address and code, and choose Join here. Only the changes made since the file was opened travel. If the host's drawing is a different one, it replaces the one in that window; your file on disk stays as it is. Guest, hotel and school Wi-Fi often keep devices apart, so a code can't find the host there. Use a network that lets devices see each other, such as the office network. Invite links, for when you are not on the same network, are not open yet. Who changed what: Recent edits The Live panel lists Recent edits: who made each change and what it was (the step's name, such as Line or Move), newest first, with how long ago. Show more lists more of them. With something selected in CadCraft or MarkupCraft, the panel also says who changed it last, and Only what is selected keeps just the edits that touched it. The list is made in your own window from the session's edits while the session runs. It is gone when the session ends: it is never saved in the file or sent anywhere. Everyone in the session can see who made each change. If you joined after people had started, or were away for a while, the edits from before are not in your list, and the panel says so. Assistants in a session If someone turned on assistants in their app's settings, their AI assistant can ask to work in the session too. The host's own assistant joins at once; anyone else's waits for the host, with a card saying whose assistant it is: Allow or Deny. An assistant edits like its person, with its own undo, and leaves the session when its person leaves. When the session ends The host chooses End the session, or closes the file. Everyone else keeps an unsaved copy of the file as it was: save it if you want to keep it. Leave does the same for you alone.","lang":"en"},{"slug":"pen-and-touch","scope":"basics","title":"Draw with a pen on a tablet","summary":"What the app does when you draw with a pen on a touch screen: it ignores your palm, can leave the drawing to the pen while your fingers move the view, and lets the pen's buttons and a two-finger tap undo.","section":"tasks","order":94,"keywords":["pen","stylus","tablet","touch","palm","palm rejection","finger","fingers","two fingers","tap","undo","redo","side button","barrel button","eraser","pressure","hover","phone"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"a-pen-is-noticed-the-first-time","text":"A pen is noticed the first time","level":2},{"id":"your-palm-is-ignored","text":"Your palm is ignored","level":2},{"id":"let-the-pen-draw-and-your-fingers-move-the-view","text":"Let the pen draw and your fingers move the view","level":2},{"id":"undo-with-a-tap","text":"Undo with a tap","level":2},{"id":"the-pen-s-buttons","text":"The pen's buttons","level":2},{"id":"these-are-the-device-s-settings","text":"These are the device's settings","level":2},{"id":"not-built-yet","text":"Not built yet","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EHow the app works with a pen on a tablet or a touch-screen laptop, and the settings that change it. They are in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EPen and touch\u003C/span\u003E, which shows on a touch screen, or once you have used a pen.\u003C/p\u003E\n\u003Ch2 id=\"a-pen-is-noticed-the-first-time\"\u003EA pen is noticed the first time\u003C/h2\u003E\n\u003Cp\u003ENothing changes until you touch the drawing with a pen. From then on the app remembers, on this device, that you draw with one, and the choices below start to apply. Before that, your fingers draw and select as usual.\u003C/p\u003E\n\u003Ch2 id=\"your-palm-is-ignored\"\u003EYour palm is ignored\u003C/h2\u003E\n\u003Cp\u003EWith \u003Cspan class=\"hui\"\u003EIgnore my palm while I use a pen\u003C/span\u003E on (it starts on), a touch on the drawing is ignored while the pen touches the screen, for a moment after you lift it or while it hovers just above the screen, and whenever the contact is as big as a palm. Rest your hand on the screen and draw.\u003C/p\u003E\n\u003Cp\u003EIf a quick finger right after the pen does nothing, wait a moment: that moment is the palm rule at work.\u003C/p\u003E\n\u003Ch2 id=\"let-the-pen-draw-and-your-fingers-move-the-view\"\u003ELet the pen draw and your fingers move the view\u003C/h2\u003E\n\u003Cp\u003EUnder \u003Cspan class=\"hui\"\u003EFingers on the drawing, once you use a pen here\u003C/span\u003E:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EDraw and select\u003C/span\u003E (the start): a finger does what the pen does.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EOnly move the view\u003C/span\u003E: one finger on the drawing does nothing, so a stray touch never draws or picks. Two fingers still move and zoom the view as usual.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe toolbars, panels and dialogs work with your fingers either way.\u003C/p\u003E\n\u003Ch2 id=\"undo-with-a-tap\"\u003EUndo with a tap\u003C/h2\u003E\n\u003Cp\u003EWith \u003Cspan class=\"hui\"\u003ETap with two fingers to undo, three to redo\u003C/span\u003E on (it starts on), tap the drawing with two fingers together to undo your last step, and with three to redo it. It works with or without a pen. Moving the fingers is a pan or a zoom, never a tap.\u003C/p\u003E\n\u003Ch2 id=\"the-pen-s-buttons\"\u003EThe pen&#039;s buttons\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPen side button\u003C/span\u003E: \u003Cspan class=\"hui\"\u003EWhat the app does (a right click)\u003C/span\u003E at the start, or \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ERedo\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EPen eraser end\u003C/span\u003E (on pens that have one): \u003Cspan class=\"hui\"\u003EWhat the app does\u003C/span\u003E at the start, or \u003Cspan class=\"hui\"\u003EUndo\u003C/span\u003E or \u003Cspan class=\"hui\"\u003ERedo\u003C/span\u003E. In ModelCraft, what the app does is to erase while the eraser end touches.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"these-are-the-device-s-settings\"\u003EThese are the device&#039;s settings\u003C/h2\u003E\n\u003Cp\u003EThe pen and touch choices are kept for this device and apply in every app on it, so you set them once. \u003Cspan class=\"hui\"\u003EReset the layout\u003C/span\u003E and resetting an app&#039;s settings leave them as they are.\u003C/p\u003E\n\u003Ch2 id=\"not-built-yet\"\u003ENot built yet\u003C/h2\u003E\n\u003Cp\u003EPen pressure and tilt don&#039;t change line weights yet, and no app has a handwriting or sketch-to-shape tool. The app reads the pen&#039;s pressure, tilt and hover, so these can come later per app.\u003C/p\u003E","text":"What you will learn How the app works with a pen on a tablet or a touch-screen laptop, and the settings that change it. They are in Settings › General › Pen and touch, which shows on a touch screen, or once you have used a pen. A pen is noticed the first time Nothing changes until you touch the drawing with a pen. From then on the app remembers, on this device, that you draw with one, and the choices below start to apply. Before that, your fingers draw and select as usual. Your palm is ignored With Ignore my palm while I use a pen on (it starts on), a touch on the drawing is ignored while the pen touches the screen, for a moment after you lift it or while it hovers just above the screen, and whenever the contact is as big as a palm. Rest your hand on the screen and draw. If a quick finger right after the pen does nothing, wait a moment: that moment is the palm rule at work. Let the pen draw and your fingers move the view Under Fingers on the drawing, once you use a pen here: Draw and select (the start): a finger does what the pen does. Only move the view: one finger on the drawing does nothing, so a stray touch never draws or picks. Two fingers still move and zoom the view as usual. The toolbars, panels and dialogs work with your fingers either way. Undo with a tap With Tap with two fingers to undo, three to redo on (it starts on), tap the drawing with two fingers together to undo your last step, and with three to redo it. It works with or without a pen. Moving the fingers is a pan or a zoom, never a tap. The pen's buttons Pen side button: What the app does (a right click) at the start, or Undo or Redo. Pen eraser end (on pens that have one): What the app does at the start, or Undo or Redo. In ModelCraft, what the app does is to erase while the eraser end touches. These are the device's settings The pen and touch choices are kept for this device and apply in every app on it, so you set them once. Reset the layout and resetting an app's settings leave them as they are. Not built yet Pen pressure and tilt don't change line weights yet, and no app has a handwriting or sketch-to-shape tool. The app reads the pen's pressure, tilt and hover, so these can come later per app.","lang":"en"},{"slug":"unit-lists","scope":"basics","title":"Units, typed values and the unit lists","summary":"Type a length in any unit with its mark, choose which units the unit lists show, and star the unit new work starts in. A file always keeps its own unit.","section":"reference","order":60,"keywords":["units","unit list","metric","imperial","feet","inches","feet and inches","meters","millimeters","US survey foot","survey feet","international foot","yards","miles","nautical mile","chain","rod","link","furlong","fathom","point","pica","acre","hectare","square","roofing square","acre-foot","board foot","gallon","gon","grad","radian","degrees minutes seconds","slope","percent","H:V","rise run","default unit","star","INSUNITS"],"headings":[{"id":"what-you-will-learn","text":"What you will learn","level":2},{"id":"type-a-length-in-any-unit","text":"Type a length in any unit","level":2},{"id":"choose-the-units-the-lists-show","text":"Choose the units the lists show","level":2},{"id":"where-the-lists-and-the-star-are-used","text":"Where the lists and the star are used","level":2},{"id":"a-file-keeps-its-own-unit","text":"A file keeps its own unit","level":2}],"html":"\u003Ch2 id=\"what-you-will-learn\"\u003EWhat you will learn\u003C/h2\u003E\n\u003Cp\u003EHow to type a value in any unit, and how to choose which units the unit lists in the apps show and which one new work starts in. Every app shares one table of units, with the exact sizes their legal definitions give.\u003C/p\u003E\n\u003Ch2 id=\"type-a-length-in-any-unit\"\u003EType a length in any unit\u003C/h2\u003E\n\u003Cp\u003EIn a box that takes a length, type the number and the unit&#039;s mark after it. The app turns it into the unit the box is in.\u003C/p\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EType\u003C/th\u003E\u003Cth scope=\"col\"\u003EMeans\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E12&#039;6&quot;\u003C/code\u003E, \u003Ccode\u003E12&#039; 6 1/2&quot;\u003C/code\u003E, \u003Ccode\u003E12&#039;-6&quot;\u003C/code\u003E, \u003Ccode\u003E3 ft 6 in\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Efeet and inches\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E450 mm\u003C/code\u003E, \u003Ccode\u003E3.2 m\u003C/code\u003E, \u003Ccode\u003E1.5 km\u003C/code\u003E, \u003Ccode\u003E2 dm\u003C/code\u003E, \u003Ccode\u003E400 nm\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Emetric lengths (\u003Ccode\u003Enm\u003C/code\u003E is the nanometer)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E3 yd\u003C/code\u003E, \u003Ccode\u003E2.5 mi\u003C/code\u003E, \u003Ccode\u003E250 mil\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Eyards, miles, thousandths of an inch\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E10 US ft\u003C/code\u003E, \u003Ccode\u003E1 US mi\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Ethe US survey foot and mile\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E2 rd\u003C/code\u003E, \u003Ccode\u003E100 li\u003C/code\u003E, \u003Ccode\u003E3 ch\u003C/code\u003E, \u003Ccode\u003E1 fur\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Erods, links, chains, furlongs\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E1 nmi\u003C/code\u003E or \u003Ccode\u003E1 NM\u003C/code\u003E, \u003Ccode\u003E6 ftm\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Enautical miles, fathoms\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003E\u003Ccode\u003E12 pt\u003C/code\u003E, \u003Ccode\u003E3 pc\u003C/code\u003E\u003C/td\u003E\u003Ctd\u003Epoints and picas (1/72 and 1/6 of an inch)\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Ccode\u003Enm\u003C/code\u003E is always the nanometer. For the nautical mile type \u003Ccode\u003Enmi\u003C/code\u003E or \u003Ccode\u003ENM\u003C/code\u003E. \u003Ccode\u003ENm\u003C/code\u003E is refused, because it could be either.\u003C/li\u003E\u003Cli\u003E\u003Ccode\u003Eft\u003C/code\u003E is the international foot (0.3048 m). The US survey foot (1200/3937 m) is a different unit: type \u003Ccode\u003EUS ft\u003C/code\u003E, \u003Ccode\u003Eusft\u003C/code\u003E or \u003Ccode\u003Esurvey ft\u003C/code\u003E. Rods, links, chains, furlongs and acres are the international-foot ones.\u003C/li\u003E\u003Cli\u003ESums work as before where the app takes them, with any of these marks: \u003Ccode\u003E2*3 yd\u003C/code\u003E, \u003Ccode\u003E12&#039;6&quot; + 3 ch\u003C/code\u003E.\u003C/li\u003E\u003Cli\u003EIn CadCraft a mark is read when the drawing has units (its $INSUNITS). A drawing with no units reads one only when its length format is Engineering or Architectural, where one drawing unit is an inch.\u003C/li\u003E\u003Cli\u003EIn CivilCraft a project in feet is in US survey feet, as it always was, so \u003Ccode\u003E10 US ft\u003C/code\u003E is 10 and \u003Ccode\u003E10 ft\u003C/code\u003E is 10 project feet.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"choose-the-units-the-lists-show\"\u003EChoose the units the lists show\u003C/h2\u003E\n\u003Cp\u003EOpen \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E (the gear on the app bar, or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E), choose \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E, and find \u003Cspan class=\"hui\"\u003EUnits\u003C/span\u003E. There is one list for each kind: \u003Cspan class=\"hui\"\u003ELength\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EArea\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EVolume\u003C/span\u003E, \u003Cspan class=\"hui\"\u003EAngle\u003C/span\u003E and \u003Cspan class=\"hui\"\u003ESlope\u003C/span\u003E.\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003EEach unit has a switch. A unit that is off is left out of the unit lists in the apps.\u003C/li\u003E\u003Cli\u003EClick the star beside a unit to make it the default for new work. Click it again to take the star away. With no star, each app keeps its own default (the file&#039;s unit, or the one for your region).\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EReset the unit lists\u003C/span\u003E puts the starting lists back, with no stars.\u003C/li\u003E\u003Cli\u003EThe choices are the same in every app in this browser, and they are saved as you make them.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"where-the-lists-and-the-star-are-used\"\u003EWhere the lists and the star are used\u003C/h2\u003E\n\u003Cdiv class=\"ht-wrap\"\u003E\u003Ctable class=\"ht\"\u003E\u003Cthead\u003E\u003Ctr\u003E\u003Cth scope=\"col\"\u003EApp\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat follows the switches\u003C/th\u003E\u003Cth scope=\"col\"\u003EWhat the star sets\u003C/th\u003E\u003C/tr\u003E\u003C/thead\u003E\u003Ctbody\u003E\u003Ctr\u003E\u003Ctd\u003ECadCraft\u003C/td\u003E\u003Ctd\u003E\u003C/td\u003E\u003Ctd\u003EThe units ($INSUNITS) of a new drawing, when it is a unit a drawing can carry\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ECivilCraft\u003C/td\u003E\u003Ctd\u003EThe project&#039;s units list\u003C/td\u003E\u003Ctd\u003ELength: a new project in meters (a metric star) or feet. Area and volume: the unit areas and volumes are reported in\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EModelCraft\u003C/td\u003E\u003Ctd\u003EThe units list beside the value box\u003C/td\u003E\u003Ctd\u003EThe unit of a new model\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EBimCraft\u003C/td\u003E\u003Ctd\u003EThe units list on the plan toolbar\u003C/td\u003E\u003Ctd\u003EThe display units, until you pick them on the toolbar (your earlier pick is kept)\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003EMarkupCraft\u003C/td\u003E\u003Ctd\u003EThe measuring and position units in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E, and the unit in the calibrate dialog\u003C/td\u003E\u003Ctd\u003EThe measuring unit, until MarkupCraft&#039;s own settings have been saved\u003C/td\u003E\u003C/tr\u003E\u003Ctr\u003E\u003Ctd\u003ETakeoffCraft\u003C/td\u003E\u003Ctd\u003EThe unit lists of an item\u003C/td\u003E\u003Ctd\u003ELength and area: the unit of a new item\u003C/td\u003E\u003C/tr\u003E\u003C/tbody\u003E\u003C/table\u003E\u003C/div\u003E\n\u003Cp\u003EThe angle and slope lists are saved, but no app&#039;s box follows them yet.\u003C/p\u003E\n\u003Ch2 id=\"a-file-keeps-its-own-unit\"\u003EA file keeps its own unit\u003C/h2\u003E\n\u003Cp\u003EThe settings never change a file. A drawing keeps its units, a CivilCraft project its feet or meters, a model its unit. The unit a file uses is always in its list, even when it is turned off in \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E.\u003C/p\u003E","text":"What you will learn How to type a value in any unit, and how to choose which units the unit lists in the apps show and which one new work starts in. Every app shares one table of units, with the exact sizes their legal definitions give. Type a length in any unit In a box that takes a length, type the number and the unit's mark after it. The app turns it into the unit the box is in. Type Means 12'6\", 12' 6 1/2\", 12'-6\", 3 ft 6 in feet and inches 450 mm, 3.2 m, 1.5 km, 2 dm, 400 nm metric lengths (nm is the nanometer) 3 yd, 2.5 mi, 250 mil yards, miles, thousandths of an inch 10 US ft, 1 US mi the US survey foot and mile 2 rd, 100 li, 3 ch, 1 fur rods, links, chains, furlongs 1 nmi or 1 NM, 6 ftm nautical miles, fathoms 12 pt, 3 pc points and picas (1/72 and 1/6 of an inch) nm is always the nanometer. For the nautical mile type nmi or NM. Nm is refused, because it could be either. ft is the international foot (0.3048 m). The US survey foot (1200/3937 m) is a different unit: type US ft, usft or survey ft. Rods, links, chains, furlongs and acres are the international-foot ones. Sums work as before where the app takes them, with any of these marks: 2*3 yd, 12'6\" + 3 ch. In CadCraft a mark is read when the drawing has units (its $INSUNITS). A drawing with no units reads one only when its length format is Engineering or Architectural, where one drawing unit is an inch. In CivilCraft a project in feet is in US survey feet, as it always was, so 10 US ft is 10 and 10 ft is 10 project feet. Choose the units the lists show Open Settings (the gear on the app bar, or Ctrl+,), choose General, and find Units. There is one list for each kind: Length, Area, Volume, Angle and Slope. Each unit has a switch. A unit that is off is left out of the unit lists in the apps. Click the star beside a unit to make it the default for new work. Click it again to take the star away. With no star, each app keeps its own default (the file's unit, or the one for your region). Reset the unit lists puts the starting lists back, with no stars. The choices are the same in every app in this browser, and they are saved as you make them. Where the lists and the star are used App What follows the switches What the star sets CadCraft The units ($INSUNITS) of a new drawing, when it is a unit a drawing can carry CivilCraft The project's units list Length: a new project in meters (a metric star) or feet. Area and volume: the unit areas and volumes are reported in ModelCraft The units list beside the value box The unit of a new model BimCraft The units list on the plan toolbar The display units, until you pick them on the toolbar (your earlier pick is kept) MarkupCraft The measuring and position units in Settings, and the unit in the calibrate dialog The measuring unit, until MarkupCraft's own settings have been saved TakeoffCraft The unit lists of an item Length and area: the unit of a new item The angle and slope lists are saved, but no app's box follows them yet. A file keeps its own unit The settings never change a file. A drawing keeps its units, a CivilCraft project its feet or meters, a model its unit. The unit a file uses is always in its list, even when it is turned off in Settings.","lang":"en"},{"slug":"lost-toolbar","scope":"basics","title":"Where did my toolbar go?","summary":"The bars, menus or panels went missing. Here is what hides them on purpose, the keys that bring them back, and one button that puts the whole layout back.","section":"trouble","order":5,"keywords":["toolbar gone","toolbar missing","lost toolbar","lost menu","menu disappeared","ribbon disappeared","bars hidden","show bars","full screen","panels gone","reset layout","layout","ribbon","collapsed","locked toolbar"],"headings":[{"id":"the-quickest-fix-reset-the-layout","text":"The quickest fix: reset the layout","level":2},{"id":"the-bars-are-hidden-full-screen","text":"The bars are hidden (full screen)","level":2},{"id":"the-toolbar-looks-different","text":"The toolbar looks different","level":2},{"id":"the-toolbar-s-own-menu","text":"The toolbar's own menu","level":2},{"id":"everything-is-too-big-or-too-small","text":"Everything is too big or too small","level":2},{"id":"the-panels-are-gone","text":"The panels are gone","level":2},{"id":"on-a-phone","text":"On a phone","level":2},{"id":"still-missing","text":"Still missing?","level":2}],"html":"\u003Cp\u003ENothing is deleted when a bar or a panel goes away: the app only hides or moves it. Each of these ways is on purpose, and each has a way back.\u003C/p\u003E\n\u003Ch2 id=\"the-quickest-fix-reset-the-layout\"\u003EThe quickest fix: reset the layout\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E with the gear button in the app bar, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command ,\"\u003E⌘,\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+,\u003C/span\u003E\u003C/kbd\u003E.\u003C/li\u003E\u003Cli\u003EChoose the \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E tab.\u003C/li\u003E\u003Cli\u003EUnder \u003Cspan class=\"hui\"\u003ELayout\u003C/span\u003E, choose \u003Cspan class=\"hui\"\u003EReset the layout\u003C/span\u003E.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003EThe toolbar goes back to its first order and buttons, the panels go back to their sides, the screen mode goes back to the normal view and the menu style goes back to the one the app starts with. Your theme, language, sizes and the app&#039;s own settings stay as they are, and so do any menu styles you made yourself (choose them again under \u003Cspan class=\"hui\"\u003EMenus, keys and mouse\u003C/span\u003E).\u003C/p\u003E\n\u003Caside class=\"hc hc-note\"\u003E\u003Cp class=\"hc-label\"\u003ENote\u003C/p\u003E\n\u003Cp\u003EIn CadCraft Studio, \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E in Studio&#039;s own window also has \u003Cspan class=\"hui\"\u003EReset the layout in every app\u003C/span\u003E. Each app&#039;s windows follow at once, and an app you open later starts from its first layout.\u003C/p\u003E\n\u003C/aside\u003E\n\u003Ch2 id=\"the-bars-are-hidden-full-screen\"\u003EThe bars are hidden (full screen)\u003C/h2\u003E\n\u003Cp\u003EThe screen-mode button in the app bar, and \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E, go from the normal view to full screen, then to full screen with the bars hidden, then back.\u003C/p\u003E\n\u003Cp\u003EWhile the bars are hidden, a small \u003Cspan class=\"hui\"\u003EShow bars\u003C/span\u003E tab stays at the top middle of the window. Choose it, or point at the top edge of the window, and the bars slide down; they hide again a moment after you move away. Press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Control Shift F\"\u003E⌃⇧F\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+Shift+F\u003C/span\u003E\u003C/kbd\u003E to leave this mode, or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E to leave full screen.\u003C/p\u003E\n\u003Cp\u003EIf the app opens with its bars hidden every time, look at \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EScreen\u003C/span\u003E: the app does what is chosen there when it opens.\u003C/p\u003E\n\u003Cdiv class=\"hv\" data-v=\"input:touch\"\u003E\u003Cp class=\"hv-label\"\u003ETouch\u003C/p\u003E\n\u003Cp\u003ETap the \u003Cspan class=\"hui\"\u003EShow bars\u003C/span\u003E tab, or tap the top edge of the screen.\u003C/p\u003E\n\u003C/div\u003E\n\u003Ch2 id=\"the-toolbar-looks-different\"\u003EThe toolbar looks different\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003ETools in another order, or tools you can&#039;t find:\u003C/strong\u003E someone arranged the toolbar. Choose \u003Cspan class=\"hui\"\u003EOriginal order\u003C/span\u003E under \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EToolbar\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EOnly icons, or only words:\u003C/strong\u003E \u003Cspan class=\"hui\"\u003EToolbar buttons\u003C/span\u003E in the same place picks icons and labels, icons only or labels only. Hold the pointer over an icon to see its name.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003ETools won&#039;t move:\u003C/strong\u003E the toolbar is locked. Right-click the toolbar (or press and hold it) and choose \u003Cspan class=\"hui\"\u003EUnlock the toolbar\u003C/span\u003E, or clear \u003Cspan class=\"hui\"\u003ELock the toolbar\u003C/span\u003E under \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EToolbar\u003C/span\u003E.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EA ribbon that shows only its tab names:\u003C/strong\u003E it is collapsed. Choose a tab name to open its tools for one command, or double-click a tab name (or choose the pin at the end of the tab row) to keep the ribbon open.\u003C/li\u003E\u003Cli\u003E\u003Cstrong\u003EMenus or a ribbon instead of the toolbar:\u003C/strong\u003E a menu style is on. Pick the app&#039;s own style under \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › the app&#039;s tab › \u003Cspan class=\"hui\"\u003EMenus, keys and mouse\u003C/span\u003E. Every command is in every style; \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command K\"\u003E⌘K\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+K\u003C/span\u003E\u003C/kbd\u003E finds any of them by name.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"the-toolbar-s-own-menu\"\u003EThe toolbar&#039;s own menu\u003C/h2\u003E\n\u003Cp\u003ERight-click the toolbar, or press and hold it on a touch screen, for a short menu:\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EArrange the toolbar\u003C/span\u003E: drag tools within their group and groups by their name, or move the focused one with the arrow keys. Choose \u003Cspan class=\"hui\"\u003EDone arranging\u003C/span\u003E in the same menu, or press \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Esc\"\u003EEsc\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EEsc\u003C/span\u003E\u003C/kbd\u003E, when it looks right.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003ELock the toolbar\u003C/span\u003E / \u003Cspan class=\"hui\"\u003EUnlock the toolbar\u003C/span\u003E: a locked toolbar can&#039;t be arranged or reset by accident.\u003C/li\u003E\u003Cli\u003E\u003Cspan class=\"hui\"\u003EReset the toolbar\u003C/span\u003E: tools back in their first order.\u003C/li\u003E\u003Cli\u003EWith a ribbon menu style: \u003Cspan class=\"hui\"\u003ECollapse the ribbon\u003C/span\u003E or \u003Cspan class=\"hui\"\u003EPin the ribbon open\u003C/span\u003E.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EOn a keyboard, the menu key (or \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Shift F10\"\u003E⇧ F10\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003EShift+F10\u003C/span\u003E\u003C/kbd\u003E) opens it for the tool that has the focus.\u003C/p\u003E\n\u003Ch2 id=\"everything-is-too-big-or-too-small\"\u003EEverything is too big or too small\u003C/h2\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EInterface size\u003C/span\u003E makes the bars, toolbars, panels and dialogs of this app bigger or smaller, from 80 % to 140 %. The drawing keeps its own zoom, so a smaller interface leaves more room for it, for example with two apps side by side on one monitor. \u003Cspan class=\"hui\"\u003EPanel text size\u003C/span\u003E beside it changes only the text in the side panels, on top of the interface size. Each app keeps its own size; CadCraft Studio&#039;s own window has one in its \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E too.\u003C/p\u003E\n\u003Ch2 id=\"the-panels-are-gone\"\u003EThe panels are gone\u003C/h2\u003E\n\u003Cp\u003EPanels can float over the drawing, dock on another side, or move to a window of their own (often on a second monitor, or behind this window).\u003C/p\u003E\n\u003Cul\u003E\u003Cli\u003ELook for a second window called after the app with &quot;panels&quot;, and choose \u003Cspan class=\"hui\"\u003EPut the panels back\u003C/span\u003E in it.\u003C/li\u003E\u003Cli\u003EOr choose \u003Cspan class=\"hui\"\u003EReset layout\u003C/span\u003E under \u003Cspan class=\"hui\"\u003ESettings\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EGeneral\u003C/span\u003E › \u003Cspan class=\"hui\"\u003EPanels\u003C/span\u003E, which brings every panel home.\u003C/li\u003E\u003C/ul\u003E\n\u003Ch2 id=\"on-a-phone\"\u003EOn a phone\u003C/h2\u003E\n\u003Cp\u003EOn a phone the panels are sheets: open one from the bar at the bottom of the screen. The \u003Cspan class=\"hui\"\u003ETools\u003C/span\u003E button in that bar hides and shows the toolbar, and \u003Cspan class=\"hui\"\u003EMove\u003C/span\u003E puts it at the top or the bottom of the screen.\u003C/p\u003E\n\u003Ch2 id=\"still-missing\"\u003EStill missing?\u003C/h2\u003E\n\u003Cp\u003EFind any tool by name with \u003Ckbd class=\"hk\"\u003E\u003Cspan class=\"k-mac\" title=\"Command K\"\u003E⌘K\u003C/span\u003E\u003Cspan class=\"k-pc\"\u003ECtrl+K\u003C/span\u003E\u003C/kbd\u003E, even while its bar is hidden. If something is still not where it should be after resetting the layout, tell us on the support page with the app&#039;s name and what you were doing.\u003C/p\u003E","text":"Nothing is deleted when a bar or a panel goes away: the app only hides or moves it. Each of these ways is on purpose, and each has a way back. The quickest fix: reset the layout Open Settings with the gear button in the app bar, or press Ctrl+,. Choose the General tab. Under Layout, choose Reset the layout. The toolbar goes back to its first order and buttons, the panels go back to their sides, the screen mode goes back to the normal view and the menu style goes back to the one the app starts with. Your theme, language, sizes and the app's own settings stay as they are, and so do any menu styles you made yourself (choose them again under Menus, keys and mouse). In CadCraft Studio, Settings in Studio's own window also has Reset the layout in every app. Each app's windows follow at once, and an app you open later starts from its first layout. The bars are hidden (full screen) The screen-mode button in the app bar, and Ctrl+Shift+F, go from the normal view to full screen, then to full screen with the bars hidden, then back. While the bars are hidden, a small Show bars tab stays at the top middle of the window. Choose it, or point at the top edge of the window, and the bars slide down; they hide again a moment after you move away. Press Ctrl+Shift+F to leave this mode, or Esc to leave full screen. If the app opens with its bars hidden every time, look at Settings › General › Screen: the app does what is chosen there when it opens. Tap the Show bars tab, or tap the top edge of the screen. The toolbar looks different Tools in another order, or tools you can't find: someone arranged the toolbar. Choose Original order under Settings › General › Toolbar. Only icons, or only words: Toolbar buttons in the same place picks icons and labels, icons only or labels only. Hold the pointer over an icon to see its name. Tools won't move: the toolbar is locked. Right-click the toolbar (or press and hold it) and choose Unlock the toolbar, or clear Lock the toolbar under Settings › General › Toolbar. A ribbon that shows only its tab names: it is collapsed. Choose a tab name to open its tools for one command, or double-click a tab name (or choose the pin at the end of the tab row) to keep the ribbon open. Menus or a ribbon instead of the toolbar: a menu style is on. Pick the app's own style under Settings › the app's tab › Menus, keys and mouse. Every command is in every style; Ctrl+K finds any of them by name. The toolbar's own menu Right-click the toolbar, or press and hold it on a touch screen, for a short menu: Arrange the toolbar: drag tools within their group and groups by their name, or move the focused one with the arrow keys. Choose Done arranging in the same menu, or press Esc, when it looks right. Lock the toolbar / Unlock the toolbar: a locked toolbar can't be arranged or reset by accident. Reset the toolbar: tools back in their first order. With a ribbon menu style: Collapse the ribbon or Pin the ribbon open. On a keyboard, the menu key (or Shift+F10) opens it for the tool that has the focus. Everything is too big or too small Settings › General › Interface size makes the bars, toolbars, panels and dialogs of this app bigger or smaller, from 80 % to 140 %. The drawing keeps its own zoom, so a smaller interface leaves more room for it, for example with two apps side by side on one monitor. Panel text size beside it changes only the text in the side panels, on top of the interface size. Each app keeps its own size; CadCraft Studio's own window has one in its Settings too. The panels are gone Panels can float over the drawing, dock on another side, or move to a window of their own (often on a second monitor, or behind this window). Look for a second window called after the app with \"panels\", and choose Put the panels back in it. Or choose Reset layout under Settings › General › Panels, which brings every panel home. On a phone On a phone the panels are sheets: open one from the bar at the bottom of the screen. The Tools button in that bar hides and shows the toolbar, and Move puts it at the top or the bottom of the screen. Still missing? Find any tool by name with Ctrl+K, even while its bar is hidden. If something is still not where it should be after resetting the layout, tell us on the support page with the app's name and what you were doing.","lang":"en"},{"slug":"recover","scope":"basics","title":"Recover unsaved work","summary":"How the apps keep a recovery copy while you work, and how to get your work back after a crash or a closed tab.","section":"trouble","order":55,"keywords":["autosave","recover","recovery","crash","lost work","closed tab","unsaved","restore","backup"],"headings":[{"id":"when-the-copy-is-kept","text":"When the copy is kept","level":2},{"id":"get-your-work-back","text":"Get your work back","level":2},{"id":"things-to-know","text":"Things to know","level":2}],"html":"\u003Cp\u003EWhile you work, each app keeps a recovery copy of what you have not saved yet. It is not a save: your file on your computer only changes when you save it. The copy is there so a crash, a closed tab or a computer that turns off does not cost you your work.\u003C/p\u003E\n\u003Ch2 id=\"when-the-copy-is-kept\"\u003EWhen the copy is kept\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EA few seconds after you stop editing, and at least every 30 seconds while you keep going.\u003C/li\u003E\u003Cli\u003EWhen you switch to another tab or window.\u003C/li\u003E\u003C/ul\u003E\n\u003Cp\u003EThe copy stays in this browser, on this computer. Nothing is uploaded.\u003C/p\u003E\n\u003Ch2 id=\"get-your-work-back\"\u003EGet your work back\u003C/h2\u003E\n\u003Col\u003E\u003Cli\u003EOpen the same app again, in the same browser.\u003C/li\u003E\u003Cli\u003EIf it closed before your work was saved, it asks \u003Cspan class=\"hui\"\u003ERecover your work?\u003C/span\u003E and lists what it kept, with the time of the last copy.\u003C/li\u003E\u003Cli\u003EChoose \u003Cspan class=\"hui\"\u003ERecover\u003C/span\u003E to open it, or \u003Cspan class=\"hui\"\u003EDiscard\u003C/span\u003E to throw it away.\u003C/li\u003E\u003Cli\u003ESave it to a file as soon as it opens.\u003C/li\u003E\u003C/ol\u003E\n\u003Cp\u003E\u003Cspan class=\"hui\"\u003ENot now\u003C/span\u003E keeps the copies for 30 days, and the app asks again the next time it opens. A reload counts too: reload a tab with unsaved work and the app offers it back.\u003C/p\u003E\n\u003Ch2 id=\"things-to-know\"\u003EThings to know\u003C/h2\u003E\n\u003Cul\u003E\u003Cli\u003EWhen you save, or close a file on purpose, its recovery copy is removed.\u003C/li\u003E\u003Cli\u003EAnother tab of the same app that is still open never offers your copies. It only offers work from a tab that has gone.\u003C/li\u003E\u003Cli\u003EPrivate windows in some browsers, and a browser with no space left, cannot keep a copy. The app tells you when that happens, so save to a file more often.\u003C/li\u003E\u003Cli\u003EClearing your browser&#039;s site data removes the copies.\u003C/li\u003E\u003Cli\u003ENot every app keeps a recovery copy yet. Each app&#039;s own help says whether it does.\u003C/li\u003E\u003C/ul\u003E","text":"While you work, each app keeps a recovery copy of what you have not saved yet. It is not a save: your file on your computer only changes when you save it. The copy is there so a crash, a closed tab or a computer that turns off does not cost you your work. When the copy is kept A few seconds after you stop editing, and at least every 30 seconds while you keep going. When you switch to another tab or window. The copy stays in this browser, on this computer. Nothing is uploaded. Get your work back Open the same app again, in the same browser. If it closed before your work was saved, it asks Recover your work? and lists what it kept, with the time of the last copy. Choose Recover to open it, or Discard to throw it away. Save it to a file as soon as it opens. Not now keeps the copies for 30 days, and the app asks again the next time it opens. A reload counts too: reload a tab with unsaved work and the app offers it back. Things to know When you save, or close a file on purpose, its recovery copy is removed. Another tab of the same app that is still open never offers your copies. It only offers work from a tab that has gone. Private windows in some browsers, and a browser with no space left, cannot keep a copy. The app tells you when that happens, so save to a file more often. Clearing your browser's site data removes the copies. Not every app keeps a recovery copy yet. Each app's own help says whether it does.","lang":"en"}],"locale":"es-MX","chain":["es-MX","es","en"]};
